const e=JSON.parse(`[{"id":"studio.lang.shots.t01","legacyId":"tya9ztb","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Далечен план (Extreme long shot)","bg":"Далечен план","en":"Extreme long shot","alts":["далечен","extreme long shot","els"],"def":"Човекът е малка част от пространството или изобщо не се вижда; дава мащаб, самота, епичност.","ex":"„Лорънс Арабски“ (1962) е пълен с далечни планове на пустинята: хората са точки сред пясъка и зрителят усеща колко огромно и безмилостно е мястото."}},{"id":"studio.lang.shots.t02","legacyId":"t1a1ida8","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Общ план (Long shot)","bg":"Общ план","en":"Long shot","alts":["общ","long shot","full shot","ls"],"def":"Човекът се вижда целият — от главата до петите — и е достатъчно едър, за да се четат позата и движението му; около него остава част от мястото.","ex":"Фред Астер настоявал танците му да се снимат в цял ръст и с възможно най-малко срязвания, за да не се губят стъпките. Общият план е за всичко, в което говори цялото тяло."}},{"id":"studio.lang.shots.t03","legacyId":"tln6x26","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Американски план (Cowboy shot)","bg":"Американски план","en":"Cowboy shot","alts":["американски","cowboy shot"],"def":"От средата на бедрото или от коленете нагоре; идва от уестърна, за да се вижда кобурът.","ex":"Удобен е, когато героите стоят прави и действат с ръцете — вадят нещо от джоба или държат инструмент. Не режи точно в коляното: ставата на ръба на кадъра изглежда като отрязана."}},{"id":"studio.lang.shots.t04","legacyId":"twmqq5x","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Среден план (Medium shot)","bg":"Среден план","en":"Medium shot","alts":["среден","medium shot","ms"],"def":"От кръста нагоре; основният план за действие и разговор.","ex":"Средният план е „неутралната скорост“ на филма: от него монтажът може да отиде по-близо за емоция или по-широко за ориентация. Затова сцените често се връщат към него."}},{"id":"studio.lang.shots.t05","legacyId":"tmyxmki","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Близък план (Medium close-up)","bg":"Близък план","en":"Medium close-up","alts":["близък","medium close-up","mcu"],"def":"От гърдите нагоре; вниманието отива към лицето, а жестът още се вижда.","ex":"Така обикновено са кадрирани водещите на новините и хората в интервю: лицето се вижда ясно, а под него остава място за надпис с името."}},{"id":"studio.lang.shots.t06","legacyId":"t1w74wnk","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Крупен план (Close-up)","bg":"Крупен план","en":"Close-up","alts":["крупен","едър план","едър","close-up","cu"],"def":"Лицето изпълва кадъра; емоцията става главното събитие.","ex":"От близкия план го различаваш по раменете: при крупния те почти изчезват и долният ръб минава около шията. В диалог крупните планове обикновено се пазят за най-силните реплики и реакции."}},{"id":"studio.lang.shots.t07","legacyId":"tkqs4h0","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Детайл (Extreme close-up)","bg":"Детайл","en":"Extreme close-up","alts":["много едър план","extreme close-up","ecu"],"def":"Кадър само на част от лицето (очите, устните) или на малък предмет; насочва вниманието към улика или усещане.","ex":"В „Психо“ сцената под душа завършва с детайл на неподвижното око на героинята, от който камерата бавно се отдалечава."}},{"id":"studio.lang.shots.t08","legacyId":"tk31tsh","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Засечка през рамо (Over-the-shoulder shot)","bg":"Засечка през рамо","en":"Over-the-shoulder shot","alts":["през рамо","over the shoulder","ots"],"def":"Камерата е зад единия събеседник: тилът и част от тялото му са в преден план, а в дълбочина е лицето на другия; свързва двамата в диалога.","ex":"Засечките идват по двойки — над рамото на единия, после над рамото на другия. Така се снима класическият диалог кадър – контракадър (Shot/reverse shot)."}},{"id":"studio.lang.shots.t09","legacyId":"tykf0he","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Установяващ план (Establishing shot)","bg":"Установяващ план","en":"Establishing shot","alts":["установяващ","establishing shot","ориентиращ план"],"def":"План в началото на сцената, който показва мястото и разположението на героите.","ex":"В ситкомите като „Приятели“ преди нова сцена често се вижда сградата отвън — зрителят знае къде сме, още преди да влезем в стаята."}},{"id":"studio.lang.angle.t01","legacyId":"td8nbj9","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Нормален ъгъл (Eye-level shot)","bg":"Нормален ъгъл","en":"Eye-level shot","alts":["на нивото на очите","eye level","нормален"],"def":"Камерата е на височината на очите на героя; неутрално, равноправно виждане.","ex":"Повечето диалози се снимат от нивото на очите, затова зрителят изобщо не забелязва ъгъла. Точно затова всяко отклонение нагоре или надолу веднага се усеща."}},{"id":"studio.lang.angle.t02","legacyId":"t320rkx","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Горен ракурс (High angle)","bg":"Горен ракурс","en":"High angle","alts":["горен","горен ъгъл","high angle"],"def":"Камерата е над нивото на очите и гледа надолу под наклон; героят изглежда по-малък и уязвим.","ex":"За горен ракурс не ти трябва кран: качи се на стол или на стълбище и насочи телефона надолу към човек, седнал на пода. Сравни снимката с една от нивото на очите му."}},{"id":"studio.lang.angle.t03","legacyId":"t15xbpm7","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Долен ракурс (Low angle)","bg":"Долен ракурс","en":"Low angle","alts":["долен","долен ъгъл","low angle"],"def":"Камерата е под нивото на очите и гледа нагоре под наклон; героят изглежда силен, заплашителен или монументален.","ex":"Първият кадър на „Междузвездни войни“ (1977) гледа отдолу огромен кораб, който минава над камерата и сякаш няма край — ниската гледна точка показва мощта на Империята."}},{"id":"studio.lang.angle.t04","legacyId":"t11a0b0t","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Птичи поглед (Bird’s-eye view)","bg":"Птичи поглед","en":"Bird’s-eye view","alts":["отгоре","overhead","bird’s eye","птичи"],"def":"Камерата е точно над действието; сцената се превръща в карта или шаблон.","ex":"Бъзби Бъркли снима танцьорките в мюзикълите си от 30-те години точно отгоре — телата им образуват цветя и калейдоскопи."}},{"id":"studio.lang.angle.t05","legacyId":"tjp2roc","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Холандски ъгъл (Dutch angle)","bg":"Холандски ъгъл","en":"Dutch angle","alts":["наклонен кадър","dutch angle","холандски"],"def":"Камерата е завъртяна около оста на обектива и хоризонтът е накриво; внушава тревога, нестабилност, объркване.","ex":"Според едно от обясненията името идва от „Deutsch“ (немски): наклонените кадри се свързват с немския експресионизъм от 20-те години на XX век. Наричат го и canted angle."}},{"id":"studio.lang.angle.t06","legacyId":"tft3pt","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Кадър от нивото на земята (Ground level shot)","bg":"Кадър от нивото на земята","en":"Ground level shot","alts":["ground level","ground level shot","от земята","ниво на земята"],"def":"Камерата е само на няколко сантиметра над пода или тревата; близките предмети изглеждат огромни, а гледната точка е необичайна — на дете, животно или предмет.","ex":"В „Играта на играчките“ камерата често е ниско, на височината на играчките — затова стаята, мебелите и хората изглеждат огромни."}},{"id":"studio.lang.angle.t07","legacyId":"tm1lvoh","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Въздушен кадър (Aerial shot)","bg":"Въздушен кадър","en":"Aerial shot","alts":["aerial","aerial shot","въздушен","от дрон"],"def":"Камерата лети високо над мястото — на дрон, хеликоптер или самолет; показва мащаба на град, битка или пейзаж.","ex":"Днес дронът прави за минути кадри, за които преди бяха нужни хеликоптер и цял екип. Преди полет обаче провери правилата: над хора, летища и в градовете има ограничения."}},{"id":"studio.lang.comp.t01","legacyId":"t1m72d0o","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Правило на третините (Rule of thirds)","bg":"Правило на третините","en":"Rule of thirds","alts":["третини","rule of thirds"],"def":"Кадърът се дели на 3 × 3; важното се поставя по линиите или в пресечните точки, а не в центъра.","ex":"Изразът „правило на третините“ е записан за първи път през 1797 г. от английския художник и гравьор Джон Томас Смит в книга за рисуването на пейзажи."}},{"id":"studio.lang.comp.t02","legacyId":"t1p41ufz","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Пространство за поглед (Lead room)","bg":"Пространство за поглед","en":"Lead room","alts":["lead room","nose room","въздух пред лицето"],"def":"Свободното място в кадъра пред лицето на героя — откъм страната, към която е обърнат.","ex":"Същото важи и за движение: на героя, който тича надясно, се оставя повече място пред него. Иначе изглежда, че всеки миг ще се удари в ръба на кадъра."}},{"id":"studio.lang.comp.t03","legacyId":"t6vha1u","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Въздух над главата (Headroom)","bg":"Въздух над главата","en":"Headroom","alts":["headroom","въздух"],"def":"Разстоянието между темето и горния ръб: твърде много смачква героя надолу, твърде малко го реже.","ex":"Колкото по-близък е планът, толкова по-малко въздух се оставя: в крупен план рамката често реже темето. По-добре да изчезне темето, отколкото брадичката."}},{"id":"studio.lang.comp.t04","legacyId":"t1pdwihn","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Преден, среден и заден план (Foreground, midground, background)","bg":"Преден, среден и заден план","en":"Foreground, midground, background","alts":["планове на дълбочината","преден план","fg mg bg"],"def":"Трите слоя на дълбочината; когато погледът минава през тях, кадърът добива обем.","ex":"В „Гражданинът Кейн“ малкият Чарлз играе в снега, видян през прозореца в дълбочина, докато възрастните в преден план решават съдбата му — трите слоя разказват едновременно."}},{"id":"studio.lang.comp.t05","legacyId":"t5upb8a","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Водещи линии (Leading lines)","bg":"Водещи линии","en":"Leading lines","alts":["водещи линии","leading lines"],"def":"Пътища, парапети, ръбове или погледи в кадъра, които насочват окото към главното.","ex":"В „Тайната вечеря“ на Леонардо да Винчи линиите на тавана и стените се събират в главата на Христос — класически пример как линиите водят окото."}},{"id":"studio.lang.comp.t06","legacyId":"t2eubl7","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Рамка в рамката (Frame within a frame)","bg":"Рамка в рамката","en":"Frame within a frame","alts":["рамка в рамката","frame within a frame"],"def":"Врата, прозорец или огледало в кадъра, които обграждат героя и насочват вниманието.","ex":"Рамката може да е и естествена — клони, арка, пролука между хора. Работи най-добре, когато е по-тъмна или по-размазана от героя: тогава го подчертава, вместо да го скрива."}},{"id":"studio.lang.comp.t07","legacyId":"t1m9o2dh","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Силует (Silhouette)","bg":"Силует","en":"Silhouette","alts":["силует","silhouette"],"def":"Плътната външна форма; ако позата не се чете като черно петно, няма да се чете и на екрана.","ex":"В кадъра силует се получава с контражур (Backlight): героят застава пред ярък прозорец или залез и остава тъмна форма. Така се пази тайна или се подчертава позата."}},{"id":"studio.lang.comp.t08","legacyId":"t1f5k150","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Златно сечение (Golden ratio)","bg":"Златно сечение","en":"Golden ratio","alts":["golden ratio","златна пропорция","божествена пропорция","phi grid"],"def":"Пропорция около 1 : 1,618; линиите на силата в кадъра са малко по-близо до центъра, отколкото при третините.","ex":"Много твърдения в интернет за златното сечение в известни сгради и картини са спорни. Ползвай го като ориентир за композиция, а не като закон."}},{"id":"studio.lang.comp.t09","legacyId":"tvyljip","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Спирала на Фибоначи (Fibonacci spiral)","bg":"Спирала на Фибоначи","en":"Fibonacci spiral","alts":["fibonacci","фибоначи","fibonacci spiral","златна спирала"],"def":"Извита линия от четвъртинки окръжности, вписани в квадрати със страни 1, 1, 2, 3, 5, 8…; окото следва извивката към най-важното в кадъра.","ex":"Наречена е на Леонардо от Пиза (Фибоначи), който описва числовата редица в „Liber Abaci“ (1202). В кадъра центърът на спиралата е мястото за най-важното — очите, ръката, предмета."}},{"id":"studio.lang.comp.t10","legacyId":"t1jswe9a","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Симетрия (Symmetry)","bg":"Симетрия","en":"Symmetry","alts":["symmetry","симетричен кадър"],"def":"Двете половини на кадъра се отразяват; внушава ред, контрол или тържественост, а без причина прави кадъра статичен.","ex":"Малко нарушение на симетрията привлича окото: в идеално подреден кадър един предмет или човек не на място веднага става главното."}},{"id":"studio.lang.comp.t11","legacyId":"t1cgtmi4","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Негативно пространство (Negative space)","bg":"Негативно пространство","en":"Negative space","alts":["negative space","празно пространство"],"def":"Незаетата част от кадъра около героя; когато е голяма, внушава самота, изолация или очакване.","ex":"В логата негативното пространство често крие втора форма — например стрелката между буквите E и x в логото на FedEx."}},{"id":"studio.lang.pov.t01","legacyId":"tj3qlkt","hall":"studio","domain":"lang","topic":"lang.pov","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Обективна камера (Objective camera)","bg":"Обективна камера","en":"Objective camera","alts":["обективна","objective camera"],"def":"Разказ като в трето лице: зрителят гледа събитията отстрани, като невидим свидетел, а не през очите на някой герой.","ex":"Така са разказани повечето филми: актьорите не гледат в обектива. Ако герой погледне право в камерата и заговори на зрителя, това е „чупене на четвъртата стена“."}},{"id":"studio.lang.pov.t02","legacyId":"t1dxqubg","hall":"studio","domain":"lang","topic":"lang.pov","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Субективна камера (Subjective camera)","bg":"Субективна камера","en":"Subjective camera","alts":["субективна","subjective camera"],"def":"Образът предава преживяването на героя (замайване, страх), а не само мястото, откъдето гледа.","ex":"Началото на „Скафандърът и пеперудата“ (2007) е видяно през замъгленото око на парализирания герой: образът е размит, лекарите се навеждат към обектива, а ние чуваме мислите му."}},{"id":"studio.lang.pov.t03","legacyId":"txpd1fr","hall":"studio","domain":"lang","topic":"lang.pov","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Кадър от гледна точка (POV shot)","bg":"Кадър от гледна точка","en":"POV shot","alts":["pov","гледна точка","point of view"],"def":"Зрителят вижда света през очите на героя — точно това, което е пред него; обикновено се монтира след план на лицето му.","ex":"„Grandma’s Reading Glass“ (1900) на Джордж Албърт Смит от Брайтънската школа (Brighton School) е сред първите филми с такъв монтаж: момче гледа през лупа, а ние виждаме предметите отблизо в кръгла рамка."}},{"id":"studio.lang.pov.t04","legacyId":"tu673ib","hall":"studio","domain":"lang","topic":"lang.pov","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Разкриване (Reveal)","bg":"Разкриване","en":"Reveal","alts":["reveal","разкриване"],"def":"Кадър или движение на камерата, което в точно избран момент показва на зрителя нещо невидимо дотогава и така променя смисъла на сцената.","ex":"В „Джурасик парк“ първо виждаме смаяните лица на учените и едва после динозавъра. Разкриването е по-силно, защото реакцията идва преди самия обект."}},{"id":"studio.lang.pov.t05","legacyId":"t2sxks7","hall":"studio","domain":"lang","topic":"lang.pov","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Поява на героя (Entrance)","bg":"Поява на героя","en":"Entrance","alts":["entrance","поява","въвеждане на героя"],"def":"Първият момент, в който зрителят вижда даден персонаж; начинът, по който е показан, подсказва кой е той и колко е важен за историята.","ex":"В началото на „Цар Лъв“ Рафики вдига малкия Симба над скалата пред всички животни — първата поява го представя като бъдещия цар."}},{"id":"studio.edit.space.t01","legacyId":"t1tjnpqv","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Правило 180° (180-degree rule)","bg":"Правило 180°","en":"180-degree rule","alts":["180","180 градуса","правилото на оста","ос"],"def":"Въображаема линия минава през двамата герои; камерата остава от едната ѝ страна, за да се пазят посоките на погледите.","ex":"В телевизионните предавания на футбол основните камери са от една страна на терена. Иначе при смяна на камерата отборите изведнъж ще атакуват в обратната посока."}},{"id":"studio.edit.space.t02","legacyId":"tmq0jwr","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Правило 30° (30-degree rule)","bg":"Правило 30°","en":"30-degree rule","alts":["30","30 градуса"],"def":"Ако два поредни кадъра на един и същ обект са снимани от почти същата позиция, образът подскача; затова ъгълът на камерата трябва да се смени отчетливо.","ex":"При интервю с една камера операторът сменя плана между въпросите — така монтажистът има къде да реже. Ориентир за смяната: поне 30° встрани или отчетливо различен план."}},{"id":"studio.edit.space.t03","legacyId":"t7fycud","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Монтажна посока (Screen direction)","bg":"Монтажна посока","en":"Screen direction","alts":["посока на екрана","посока на движението"],"def":"Героят, излязъл вдясно, влиза в следващия кадър отляво, ако продължава нататък.","ex":"В гонитба преследвачът и преследваният тичат в една и съща посока на екрана. Ако единият тича наляво, а другият надясно, изглежда, че ще се сблъскат."}},{"id":"studio.edit.space.t04","legacyId":"t19z86th","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Линия на погледа (Eyeline)","bg":"Линия на погледа","en":"Eyeline","alts":["eyeline","съвпадение на погледите"],"def":"Накъде са обърнати очите на героя; при монтажа очите на събеседниците трябва да се срещат.","ex":"При близък план актьорът гледа малко встрани от обектива — от страната, където стои партньорът му. Ако погледне право в обектива, ще изглежда, че говори на зрителя."}},{"id":"studio.edit.space.t05","legacyId":"tuncsix","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Прескачане на оста (Crossing the line)","bg":"Прескачане на оста","en":"Crossing the line","alts":["прекосяване на оста"],"def":"Минаване на камерата от другата страна на линията на действието; оправдано е, ако зрителят види как камерата минава, след кадър точно по линията или при силен драматичен удар.","ex":"Честа грешка при снимане с два телефона: единият застава от другата страна на линията между събеседниците. В монтажа двамата гледат в една и съща посока и изглеждат така, сякаш говорят с някой трети."}},{"id":"studio.edit.space.t06","legacyId":"tjmi9z","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Неутрален кадър (Neutral shot)","bg":"Неутрален кадър","en":"Neutral shot","alts":["neutral shot","неутрален","кадър по оста","on-axis shot"],"def":"Изглед точно по линията на действието: героят гледа или се движи право към камерата или от нея; след него може да се мине от другата страна.","ex":"Лесно го разпознаваш: героят расте или се смалява в рамката, вместо да я пресича. Монтажистите го пазят като резерв, за да сменят посоката, когато сцената го изисква."}},{"id":"studio.edit.cuts.t01","legacyId":"t17293d9","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Съвпадение по действие (Match on action)","bg":"Съвпадение по действие","en":"Match on action","alts":["match on action","монтаж по действие","рязане в движение"],"def":"Срязване в средата на движение, продължено в следващия кадър; монтажът става невидим.","ex":"Удар, хвърляне на топка, сядане — всяко ясно движение е удобно място за срязване. Често първият кадър е по-общ, а вторият — по-близък, и движението „пренася“ зрителя напред."}},{"id":"studio.edit.cuts.t02","legacyId":"tzd84kr","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Прескачащ монтаж (Jump cut)","bg":"Прескачащ монтаж","en":"Jump cut","alts":["jump cut","джъмп кът"],"def":"Срязване в едно продължаващо действие с видимо прекъсване; привлича вниманието към себе си.","ex":"Може да покаже как времето се влачи в една стая: героят е на леглото, после до прозореца, после на пода — все от една и съща позиция на камерата."}},{"id":"studio.edit.cuts.t03","legacyId":"tf9qaph","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Паралелен монтаж (Cross-cutting)","bg":"Паралелен монтаж","en":"Cross-cutting","alts":["паралелен","cross-cutting","кръстосан монтаж"],"def":"Редуване на две действия, които се случват едновременно на различни места.","ex":"В „Кръстникът“ (1972) кръщенето в църквата се редува с убийствата, поръчани от Майкъл — паралелният монтаж прави молитвата и насилието части от една сцена."}},{"id":"studio.edit.cuts.t04","legacyId":"tyzl0gc","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Вмъкнат кадър (Cutaway)","bg":"Вмъкнат кадър","en":"Cutaway","alts":["cutaway","вмъкване","вмъкнат"],"def":"Кратко отклонение към нещо извън основното действие — реакция, наблюдател, околност; прекъсва действието и често скрива склейка.","ex":"В спортен филм кадърът на напрегнатия треньор на пейката е вмъкнат кадър: той не е част от играта, но показва колко много зависи от нея."}},{"id":"studio.edit.cuts.t05","legacyId":"twlscvd","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Преливане (Dissolve)","bg":"Преливане","en":"Dissolve","alts":["дисолв","dissolve","наплив"],"def":"Единият кадър избледнява, докато другият се появява; обикновено внушава изминало време.","ex":"Когато преливането е бавно, за миг двата образа съжителстват — лице и пейзаж, настояще и спомен. Затова често въвежда сън или спомен, а бързото преливане е почти като срязване."}},{"id":"studio.edit.cuts.t06","legacyId":"t16la3eo","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Затъмнение (Fade)","bg":"Затъмнение","en":"Fade","alts":["fade","фейд","изтъмняване"],"def":"Образът потъва в черно или изплува от черно; начало или край на епизод.","ex":"Сценариите на английски традиционно започват с „FADE IN:“ и завършват с „FADE OUT.“ — затъмнението отваря и затваря целия филм."}},{"id":"studio.edit.cuts.t07","legacyId":"tumvmn0","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"J- и L-срязване (J-cut, L-cut)","bg":"J- и L-срязване","en":"J-cut, L-cut","alts":["j cut","l cut","j-cut","l-cut","split edit"],"def":"Звукът и образът сменят кадъра в различен момент: звукът изпреварва образа (J) или остава след него (L).","ex":"В диалог L-срязването е навсякъде: краят на репликата още се чува, а вече виждаме лицето на слушащия и реакцията му."}},{"id":"studio.edit.cuts.t08","legacyId":"tpgk9su","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Графично съвпадение (Match cut)","bg":"Графично съвпадение","en":"Match cut","alts":["match cut","мач кът"],"def":"Срязване между две различни неща с еднаква форма или движение (костта и спътникът в „2001: Космическа одисея“).","ex":"В „Лорънс Арабски“ (1962) героят духва клечка кибрит и кадърът рязко става изгрев над пустинята — малкото пламъче и огромното слънце се свързват."}},{"id":"studio.edit.cuts.t09","legacyId":"t1lamlli","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Кадър – контракадър (Shot/reverse shot)","bg":"Кадър – контракадър","en":"Shot/reverse shot","alts":["кадър контракадър","контракадър","shot reverse shot","shot/reverse shot","засечка"],"def":"Редуване на кадрите на двамата събеседници, често през рамо; основата на монтажа на диалога.","ex":"На снимки диалогът обикновено се заснема изцяло от едната страна, а след това от другата. В монтажа се решава кога да се вижда говорещият и кога — слушащият."}},{"id":"studio.edit.cuts.t10","legacyId":"t80z91j","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy","fixes":["S60","S61","S62"]},"kind":"term","term":{"label":"Вмъкнат детайл (Insert shot)","bg":"Вмъкнат детайл","en":"Insert shot","alts":["insert","инсерт","cut-in","insert shot","вмъкнат детайл"],"def":"Кадър отблизо на подробност от самото действие — бележка, часовник, ключ — за да я забележи зрителят.","ex":"В трилърите Insert shot на часовник или на писмо дава на зрителя информация, която героят още не е видял — и така поражда напрежение."}},{"id":"studio.edit.cuts.t11","legacyId":"t1a63zrd","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Wipe","en":"Wipe","alts":["wipe","уайп","завеса"],"def":"Новият кадър избутва стария с линия или форма, която минава през екрана („Междузвездни войни“).","ex":"В телевизионните спортни предавания повторенията често започват и свършват с wipe — логото на предаването минава през екрана и сменя кадъра."}},{"id":"studio.edit.cuts.t12","legacyId":"t1a5tey3","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Iris","en":"Iris","alts":["iris","ирис"],"def":"Кръг, който се свива или разширява, за да затвори или отвори кадъра; типичен за нямото кино.","ex":"Много класически анимационни филмчета завършват с кръг, който се затваря около героя — понякога той го спира с ръце или надниква, за да каже последна реплика."}},{"id":"studio.edit.cuts.t13","legacyId":"t1tfu5cs","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Smash cut","en":"Smash cut","alts":["smash cut","смаш кът"],"def":"Рязък, неочакван скок между контрастни кадри — от тишина към шум, от обещание към опровержението му.","ex":"Smash cut е обратното на плавния преход: никакво затъмнение или преливане, а рязък удар, често в средата на звук или движение, който стряска зрителя."}},{"id":"studio.edit.time.t01","legacyId":"tl5m8uv","hall":"studio","domain":"edit","topic":"edit.time","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Компресия (Compression)","bg":"Компресия","en":"Compression","alts":["компресия","сгъстяване"],"def":"Съкращаване на времето в сцената, без зрителят да го усети.","ex":"Героят слиза от колата — срязване — вече чука на вратата на третия етаж. Изкачването по стълбите е изрязано, но зрителят не усеща липсата."}},{"id":"studio.edit.time.t02","legacyId":"t1vkx8r6","hall":"studio","domain":"edit","topic":"edit.time","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Елипса (Ellipsis)","bg":"Елипса","en":"Ellipsis","alts":["елипса","прескачане"],"def":"Явен скок във времето, който зрителят разпознава.","ex":"Скокът от костта към спътника в „2001: Космическа одисея“ е и графично съвпадение, и елипса: с едно срязване филмът прескача цялата човешка история."}},{"id":"studio.edit.time.t03","legacyId":"t1ux373r","hall":"studio","domain":"edit","topic":"edit.time","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Разтягане на времето (Elaboration)","bg":"Разтягане на времето","en":"Elaboration","alts":["елаборация"],"def":"Удължаване на важен момент чрез много кадри, повторения или забавен каданс, така че на екрана да трае повече от реалното.","ex":"Класически пример е вдигането на моста в „Октомври“ (1928) на Айзенщайн: движението е показано отново и отново, от различни ъгли, и кратък миг става цяла сцена."}},{"id":"studio.edit.time.t04","legacyId":"t1tt3ohn","hall":"studio","domain":"edit","topic":"edit.time","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Реално време (Real time)","bg":"Реално време","en":"Real time","alts":["реално време","real time"],"def":"Сцената на екрана трае точно толкова, колкото и действието в историята — без пропуски и без удължаване.","ex":"Във „Въжето“ (1948) Хичкок крие част от срязванията в тъмни гърбове и предмети, така че филмът изглежда като почти непрекъснато действие, което трае колкото прожекцията."}},{"id":"studio.edit.time.t05","legacyId":"t6yqipq","hall":"studio","domain":"edit","topic":"edit.time","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Темпо (Pace)","bg":"Темпо","en":"Pace","alts":["темпо","pace","ритъм"],"def":"Скоростта, с която се сменят кадрите и се развива действието — колко бързо или бавно усещаме, че върви филмът.","ex":"Темпото не зависи само от броя на срязванията: дълъг кадър с бързо движение вътре може да е по-напрегнат от поредица кратки, но спокойни кадри."}},{"id":"studio.edit.time.t06","legacyId":"t1ip2an4","hall":"studio","domain":"edit","topic":"edit.time","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Монтажна поредица (Montage)","bg":"Монтажна поредица","en":"Montage","alts":["montage","монтажна поредица","montage sequence"],"def":"Кратки кадри, често под музика, които сгъстяват дълъг процес — тренировка, пътуване, ремонт — в минута.","ex":"В „Роки“ (1976) тренировъчната поредица завършва с изкачването по стълбите на музея във Филаделфия — седмици подготовка в няколко минути."}},{"id":"studio.edit.sound.t01","legacyId":"tlvybmq","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Синхрон (Sync)","bg":"Синхрон","en":"Sync","alts":["синхрон","sync"],"def":"Звукът съвпада точно с образа, от който идва — устни, стъпки, удар.","ex":"Затова на снимки се използва клапа: ударът ѝ се вижда в образа и се чува в звука, а в монтажа двата записа се подравняват точно по него."}},{"id":"studio.edit.sound.t02","legacyId":"t1c4iosr","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Звуков контрапункт (Contrapuntal sound)","bg":"Звуков контрапункт","en":"Contrapuntal sound","alts":["контрапункт","асинхрон"],"def":"Звукът противоречи на образа или го коментира и така ражда нов смисъл.","ex":"Честа форма е нежна или весела музика над жестока сцена: колкото по-спокойна е мелодията, толкова по-страшно изглежда случващото се. Обратното също работи — тревожна музика над съвсем обикновен кадър."}},{"id":"studio.edit.sound.t03","legacyId":"t1rlj5i0","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Диегетичен звук (Diegetic sound)","bg":"Диегетичен звук","en":"Diegetic sound","alts":["диегетичен","diegetic","вътрешнокадров звук"],"def":"Звук от света на филма, който и героите чуват.","ex":"Проверка: би ли могъл героят да изключи звука, да го заглуши или да реагира на него — радио, гръм, песен на парти? Ако да, звукът е диегетичен. Думата идва от гръцкото „диегезис“ — разказ."}},{"id":"studio.edit.sound.t04","legacyId":"tlzodia","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Недиегетичен звук (Non-diegetic sound)","bg":"Недиегетичен звук","en":"Non-diegetic sound","alts":["недиегетичен","non-diegetic","извънкадров"],"def":"Звук извън света на историята — музика зад кадър, глас на разказвача.","ex":"Класически пример е музиката в „Челюсти“: двете ниски ноти предупреждават зрителя за акулата, но плувците във водата не ги чуват."}},{"id":"studio.edit.sound.t05","legacyId":"t5malbu","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Шумове (Foley)","bg":"Шумове","en":"Foley","alts":["фоли"],"def":"Звуците на стъпки, дрехи и предмети, изпълнени и записани отделно в студио синхронно с образа.","ex":"Името идва от Джак Фоли, който в студиото Universal започва да прави шумове на живо върху образа още в първите години на звуковото кино. Счупени кости често се озвучават с прекършена целина."}},{"id":"studio.edit.sound.t06","legacyId":"tvfiibo","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Фон на помещението (Room tone)","bg":"Фон на помещението","en":"Room tone","alts":["room tone","рум тон","фон"],"def":"Записан „празен“ звук на локацията, с който се запълват паузите при монтажа.","ex":"На снимки екипът замръзва за половин минута, докато се записва само „тишината“ на мястото. Всяко помещение звучи различно — хладилник, улица, ехо, — затова фон се записва на всяка локация."}},{"id":"studio.edit.sound.t07","legacyId":"ti6qfcs","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Постсинхрон (ADR)","bg":"Постсинхрон","en":"ADR","alts":["дублаж"],"def":"Презаписване на реплики в студио, когато звукът от снимките е негоден.","ex":"ADR означава Automated Dialogue Replacement. Актьорът гледа сцената на екран и повтаря репликите, докато думите му съвпаднат с движението на устните. По-старото име е looping — сцената се е въртяла в кръг."}},{"id":"studio.edit.theory.t01","legacyId":"t140x00r","hall":"studio","domain":"edit","topic":"edit.theory","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Ефект на Кулешов (Kuleshov effect)","bg":"Ефект на Кулешов","en":"Kuleshov effect","alts":["кулешов","kuleshov"],"def":"Едно и също неутрално лице изглежда гладно, тъжно или влюбено според кадъра до него.","ex":"В реалити предаванията реакция на участник, сложена след чужда реплика, изглежда като отговор на нея — дори да е заснета в съвсем друг момент. Така монтажът може да промени как възприемаме човека."}},{"id":"studio.edit.theory.t02","legacyId":"t6nyqql","hall":"studio","domain":"edit","topic":"edit.theory","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Монтаж на атракционите (Montage of attractions)","bg":"Монтаж на атракционите","en":"Montage of attractions","alts":["атракциони","монтаж на атракциони"],"def":"Поредица от силни, шокиращи образи, подредени така, че да разтърсят зрителя емоционално (Айзенщайн).","ex":"Айзенщайн заимства думата от цирка и панаира, където „атракцион“ е силен номер, който разтърсва публиката. Статията му от 1923 г. е за театъра, а във филма „Стачка“ той пренася идеята на екрана."}},{"id":"studio.edit.theory.t03","legacyId":"ti3j04p","hall":"studio","domain":"edit","topic":"edit.theory","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Интелектуален монтаж (Intellectual montage)","bg":"Интелектуален монтаж","en":"Intellectual montage","alts":["интелектуален","монтажна метафора"],"def":"Два образа, съпоставени така, че раждат понятие, каквото няма в нито един от тях.","ex":"В „Октомври“ (1928) Айзенщайн редува кадри на Керенски с механичен златен паун: зрителят „прочита“ суетност, без тя да бъде казана с думи."}},{"id":"studio.edit.theory.t04","legacyId":"t1fz8sxq","hall":"studio","domain":"edit","topic":"edit.theory","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Невидим монтаж (Continuity editing)","bg":"Невидим монтаж","en":"Continuity editing","alts":["непрекъснат монтаж","continuity editing","класически монтаж"],"def":"Холивудският стил, при който срязванията следват погледа и действието така, че зрителят не ги забелязва.","ex":"Правило 180°, правило 30°, съвпадение по действие и линия на погледа са негови инструменти. Целта е зрителят да следи историята, а не срязванията."}},{"id":"studio.edit.theory.t05","legacyId":"t1bqommr","hall":"studio","domain":"edit","topic":"edit.theory","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Метричен монтаж (Metric montage)","bg":"Метричен монтаж","en":"Metric montage","alts":["metric montage","метричен"],"def":"Методът на Айзенщайн, при който кадрите се режат по предварително зададена дължина, независимо от съдържанието им; скъсяването на кадрите ускорява темпото.","ex":"Опитай: нарежи десет кадъра от разходка, като всеки следващ е малко по-кратък от предишния. Дори без музика ще усетиш как напрежението расте, каквото и да показват кадрите."}},{"id":"studio.edit.theory.t06","legacyId":"t1dxy4ai","hall":"studio","domain":"edit","topic":"edit.theory","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Ритмичен монтаж (Rhythmic montage)","bg":"Ритмичен монтаж","en":"Rhythmic montage","alts":["rhythmic montage","ритмичен"],"def":"Срязването следва движението в самите кадри — стъпки, удари, машини (Одеските стъпала в „Броненосецът Потьомкин“).","ex":"Айзенщайн пише, че на Одеските стъпала тропотът на войнишките ботуши нарушава всяка равномерна дължина на кадрите. Напрежението расте още, когато стъпките отстъпват място на търкалящата се количка."}},{"id":"studio.edit.theory.t07","legacyId":"tszgywz","hall":"studio","domain":"edit","topic":"edit.theory","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Тонален монтаж (Tonal montage)","bg":"Тонален монтаж","en":"Tonal montage","alts":["tonal montage","тонален"],"def":"Кадрите се свързват по емоционалното си звучене — светлина, форма, настроение; например мъгла и вода, за да се внуши скръб.","ex":"Айзенщайн дава за пример мъглата над пристанището в Одеса в „Броненосецът Потьомкин“ преди траура по убития моряк: кадрите се свързват по светлината, не по действието."}},{"id":"studio.cam.lens.t01","legacyId":"t1o24j0m","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Фокусно разстояние (Focal length)","bg":"Фокусно разстояние","en":"Focal length","alts":["фокусно","focal length"],"def":"Отстоянието в милиметри от оптичния център на обектива до сензора, когато обективът е настроен на безкрайност; определя ъгъла на видимост — колкото е по-малко, толкова по-широко вижда.","ex":"Числото е изписано на всеки обектив — например „50 mm“ или „24–70 mm“ при вариообектив. Едно и също фокусно разстояние вижда по-тясно на по-малък сензор, затова уточняваме „при пълен кадър“."}},{"id":"studio.cam.lens.t02","legacyId":"t8it0jq","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Широкоъгълен обектив (Wide-angle lens)","bg":"Широкоъгълен обектив","en":"Wide-angle lens","alts":["широкоъгълен","wide","широк обектив"],"def":"Късо фокусно разстояние (под около 35 mm при пълен кадър): събира в кадъра много пространство, раздалечава плановете и подсилва движението към камерата.","ex":"В тесни помещения — кола, асансьор, малка стая — често е единственият начин всичко да влезе в кадъра. Внимавай с лицата по краищата на кадъра: там се разтягат най-силно."}},{"id":"studio.cam.lens.t03","legacyId":"t1k1e3q4","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Нормален обектив (Normal lens)","bg":"Нормален обектив","en":"Normal lens","alts":["нормален","стандартен","standard lens","50 mm"],"def":"Около 35–55 mm при пълен кадър; перспектива, близка до човешкото зрение.","ex":"Удобен е за диалог и наблюдение: не разтяга и не сгъстява пространството, затова зрителят не усеща обектива. Ако не знаеш какъв обектив да избереш, започни от нормалния и търси причина да се отклониш."}},{"id":"studio.cam.lens.t04","legacyId":"t1d5878a","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Телеобектив (Telephoto lens)","bg":"Телеобектив","en":"Telephoto lens","alts":["теле","дълъг обектив","telephoto","long lens"],"def":"Дълго фокусно разстояние (над около 70 mm): тесен ъгъл, сгъстено пространство, героят се отделя от фона.","ex":"В „Абсолвентът“ (1967) Бенджамин тича към църквата, заснет с телеобектив, и сякаш почти не напредва: дългият обектив сгъстява разстоянието, което трябва да пробяга."}},{"id":"studio.cam.lens.t05","legacyId":"tinplee","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Рибешко око (Fisheye lens)","bg":"Рибешко око","en":"Fisheye lens","alts":["fisheye","фишай","рибешко"],"def":"Изключително широк обектив, който извива правите линии; стилизация, шпионка, изменено съзнание.","ex":"За разлика от обикновения широкоъгълен обектив, който пази правите линии прави, рибешкото око ги огъва в дъги, особено по краищата. Класическо е за скейтборд видеа, заснети съвсем отблизо."}},{"id":"studio.cam.lens.t06","legacyId":"t1gluyrg","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Вариообектив (Zoom lens)","bg":"Вариообектив","en":"Zoom lens","alts":["трансфокатор","варио","зум"],"def":"Обектив с променливо фокусно разстояние: без да го сменяш, можеш да разшириш или стесниш кадъра; фикс обективът има само едно.","ex":"Удобен е в репортажа и документалното кино: минаваш от общ към крупен план, без да сменяш обектива. Цената обикновено е по-голямо тегло и по-малък максимален отвор от този на фикса."}},{"id":"studio.cam.lens.t07","legacyId":"t1uqzo26","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Анаморфен обектив (Anamorphic lens)","bg":"Анаморфен обектив","en":"Anamorphic lens","alts":["анаморфен"],"def":"Свива широкия кадър по хоризонтала, за да се побере върху сензора; дава формат около 2,39:1, овално bokeh и хоризонтални отблясъци.","ex":"Записаният образ е свит и хората в него изглеждат тесни и издължени, докато мониторът или монтажната програма не го разпънат обратно. Днес има анаморфни приставки дори за телефон."}},{"id":"studio.cam.lens.t08","legacyId":"t1ljldir","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Фикс обектив (Prime lens)","bg":"Фикс обектив","en":"Prime lens","alts":["prime","prime lens","фикс","фиксобектив"],"def":"Обектив с едно фокусно разстояние; обикновено е по-светъл, по-рязък и по-лек от вариообектива.","ex":"Разпознаваш го по едно число на обектива — например „35 mm“, а не диапазон като „24–70 mm“. В киното операторите често работят с комплект фиксове, например 25, 35, 50 и 85 mm."}},{"id":"studio.cam.lens.t09","legacyId":"tt3rrjj","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Парфокален обектив (Parfocal lens)","bg":"Парфокален обектив","en":"Parfocal lens","alts":["parfocal","parfocal lens","парфокален"],"def":"Вариообектив, който остава на фокус, докато се променя фокусното разстояние; при варифокалния фокусът се губи.","ex":"Кино вариообективите са парфокални, а много фото вариообективи — не. Ако при видео рязкостта „плува“, докато правиш трансфокация, обективът ти най-вероятно е варифокален."}},{"id":"studio.cam.lens.t10","legacyId":"tou78qd","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Макро обектив (Macro lens)","bg":"Макро обектив","en":"Macro lens","alts":["macro","macro lens","макро"],"def":"Фокусира от много малко разстояние и дава мащаб 1:1 — малкият предмет изпълва кадъра.","ex":"Освен за насекоми и капки, в киното служи за детайли: зеница, механизъм на часовник, хартия, която гори. Често е 90–105 mm: така остава повече място до предмета и не го засенчваш."}},{"id":"studio.cam.lens.t11","legacyId":"t5i12bp","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Обектив с наклон и отместване (Tilt-shift lens)","bg":"Обектив с наклон и отместване","en":"Tilt-shift lens","alts":["tilt-shift","tilt shift","тилт шифт"],"def":"Оптиката може да се завърта под ъгъл спрямо сензора и да се плъзга успоредно на него: изправя вертикалите на сградите или оставя рязка само тясна ивица — ефект на миниатюра.","ex":"Наклонът и отместването се настройват с копчета по самия обектив, а фокусът почти винаги е ръчен. Затова се ползва при спокойна работа: архитектура, предметна фотография и стилизирани кадри."}},{"id":"studio.cam.lens.t12","legacyId":"te1w1yr","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Разделена диоптрична леща (Split diopter)","bg":"Разделена диоптрична леща","en":"Split diopter","alts":["split diopter","сплит диоптър","диоптър"],"def":"Приставка пред обектива, която покрива само половината кадър: едновременно рязко са предмет съвсем близо и друг — далеч в дъното.","ex":"За разлика от дълбокия фокус, където рязкостта е непрекъсната от предния до задния план, тук средната зона между двата плана остава размита."}},{"id":"studio.cam.expo.t01","legacyId":"tz2kkwn","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Бленда (Aperture)","bg":"Бленда","en":"Aperture","alts":["диафрагма","апертура","aperture","f-число"],"def":"Регулируемият отвор в обектива, който определя колко светлина стига до сензора; от него зависи и дълбочината на рязкост.","ex":"Отбелязва се с f-число (f/1,4; f/2,8; f/8): колкото по-голямо е числото, толкова по-малък е отворът. Наричат я още диафрагма — отворът се образува от метални ламели в обектива."}},{"id":"studio.cam.expo.t02","legacyId":"t1vfq3bx","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Скорост на затвора (Shutter speed)","bg":"Скорост на затвора","en":"Shutter speed","alts":["затвор","shutter speed","експонация"],"def":"Времето, за което сензорът приема светлина за един кадър; определя размазването на движението.","ex":"Правило за снимане от ръка: времето на затвора да не е по-дълго от 1 ÷ фокусното разстояние — при 200 mm на пълен кадър най-много 1/200 s. Иначе, без стабилизация, трептенето на ръцете размазва снимката."}},{"id":"studio.cam.expo.t03","legacyId":"t1l9hp1j","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"ISO","en":"ISO","alts":["iso","gain","усилване","чувствителност"],"def":"Настройката (100, 400, 3200…), която показва колко камерата засилва сигнала от сензора: по-високата стойност дава по-светъл образ, но и повече шум; при видеокамерите същата настройка се дава в dB.","ex":"Във видеокамерите вместо ISO често има gain (усилване): +6 dB е около една степен — колкото ISO 400 → 800. Шумът личи най-много в тъмните части на кадъра."}},{"id":"studio.cam.expo.t04","legacyId":"t19ov89w","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Степен на експозицията (Stop)","bg":"Степен на експозицията","en":"Stop","alts":["стоп","степен","стъпка"],"def":"Удвояване или намаляване наполовина на светлината: f/2,8 → f/4 пропуска половината.","ex":"Степента е обща мярка за трите настройки: f/4 → f/5,6; 1/60 → 1/125 s и ISO 800 → 400 са по една степен по-тъмно. Затова можеш да „размениш“ степен от блендата срещу степен от затвора."}},{"id":"studio.cam.expo.t05","legacyId":"tgw0hzy","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Правилото за 180° на затвора (180-degree shutter rule)","bg":"Правилото за 180° на затвора","en":"180-degree shutter rule","alts":["180 градуса затвор","shutter angle","правилото на затвора"],"def":"Препоръка времето на експонация да е около 1 ÷ (2 × кадровата честота): при 25 кадъра в секунда — 1/50 s. Така движението се размазва естествено, както сме свикнали в киното.","ex":"Смениш ли кадровата честота, сменяш и затвора: при 50 кадъра в секунда правилото иска 1/100 s, при 60 — 1/120 s. Във фотографията то не важи — там затворът се избира свободно."}},{"id":"studio.cam.expo.t06","legacyId":"t1xxqcgr","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Ъгъл на затвора (Shutter angle)","bg":"Ъгъл на затвора","en":"Shutter angle","alts":["shutter angle"],"def":"Мярка в градуси за това каква част от времето на всеки кадър трае експонацията: пълен оборот (360°) е цялото време, а 90° — една четвърт. Идва от въртящия се диск на филмовата камера.","ex":"Цифровите кинокамери позволяват затворът да се задава направо в градуси, а фотоапаратите — като време (1/50 s). Над 180° движението става по-размазано и „сънливо“, под 180° — по-рязко и накъсано."}},{"id":"studio.cam.expo.t07","legacyId":"to6yy82","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy","fixes":["S63","S64","S65"]},"kind":"term","term":{"label":"Ефект на плъзгащия затвор (Rolling shutter)","bg":"Ефект на плъзгащия затвор","en":"Rolling shutter","alts":["rolling shutter","ролинг шътър","желе ефект","ефект на плъзгащия затвор"],"def":"Сензорът се прочита ред по ред отгоре надолу, а не целият наведнъж; при бързо движение вертикалите се накланят и образът се „люлее“.","ex":"Global shutter записва целия кадър наведнъж и няма този дефект. Rolling shutter се издава и от „извитите“ перки на вентилатор, и от светкавица, която осветява само ивица от кадъра."}},{"id":"studio.cam.settings.t01","legacyId":"t1kg6t9","hall":"studio","domain":"cam","topic":"cam.settings","level":11,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Хистограма (Histogram)","bg":"Хистограма","en":"Histogram","alts":["histogram","хистограма"],"def":"Графика на яркостите в кадъра — от черно вляво до бяло вдясно; показва прегорели или „запушени“ в тъмното места.","ex":"Няма „правилна“ форма: хистограмата на снимка в сняг естествено е натрупана вдясно, а на нощна улица — вляво. Тревожен знак е само стълб, опрял в някой от краищата."}},{"id":"studio.cam.settings.t02","legacyId":"t14acvyb","hall":"studio","domain":"cam","topic":"cam.settings","level":11,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Зебра (Zebra)","bg":"Зебра","en":"Zebra","alts":["zebra","zebras","зебра"],"def":"Раирани ивици на екрана върху местата над зададена яркост; предупреждават, че ще прегорят.","ex":"Ивиците се виждат само на екрана и не влизат в записа. Освен на 100% (прегаряне) зебрата често се настройва и на около 70%, за да се провери експозицията на лицето."}},{"id":"studio.cam.settings.t03","legacyId":"tzs1lyo","hall":"studio","domain":"cam","topic":"cam.settings","level":11,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Focus peaking","en":"Focus peaking","alts":["focus peaking","peaking","пийкинг"],"def":"Цветно очертаване на най-рязките контури в образа на екрана; помага да нагласиш рязкостта на ръка.","ex":"Peaking реагира на контраста, а не на самия фокус: по шарен плат свети и при леко размазване, а по гладка кожа — почти никак. Затова при лица не му се доверявай напълно."}},{"id":"studio.cam.settings.t04","legacyId":"ttby7vq","hall":"studio","domain":"cam","topic":"cam.settings","level":11,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Плосък профил (Log profile)","bg":"Плосък профил","en":"Log profile","alts":["log","log profile","лог","flat profile","s-log","c-log","v-log"],"def":"Запис с нисък контраст и наситеност, който пази най-много детайл в светлото и тъмното за цветовата корекция.","ex":"На екрана Log изглежда сив, затова операторът гледа през LUT (Look-Up Table) — таблица, която показва образа с нормален контраст. Самият запис остава плосък за колориста."}},{"id":"studio.cam.settings.t05","legacyId":"tvn4bqw","hall":"studio","domain":"cam","topic":"cam.settings","level":11,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"ND филтър (Neutral density filter)","bg":"ND филтър","en":"Neutral density filter","alts":["nd","nd filter","neutral density","сив филтър"],"def":"Затъмняващо стъкло пред обектива, което намалява светлината, без да променя цветовете; позволява широка бленда и правилен затвор на силно слънце.","ex":"Означава се с плътност (0,3; 0,6; 0,9) или с кратност (ND2, ND4, ND8): ND8 намалява светлината 8 пъти, тоест с 3 степени — колкото плътност 0,9."}},{"id":"studio.cam.settings.t06","legacyId":"t1vjh00r","hall":"studio","domain":"cam","topic":"cam.settings","level":11,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Кодек (Codec)","bg":"Кодек","en":"Codec","alts":["codec","кодек","h.264","h264","prores"],"def":"Методът, по който видеото се компресира при запис и се разкомпресира при гледане; от него зависят качеството, размерът на файла и колко лесно се монтира.","ex":"Името е от „кодер + декодер“. H.264 и H.265 дават малки файлове за мрежата, ProRes — големи, но удобни за монтаж. Не бъркай кодека с контейнера: .mov и .mp4 са „кутии“ за различни кодеци."}},{"id":"studio.cam.settings.t07","legacyId":"t10aj8p4","hall":"studio","domain":"cam","topic":"cam.settings","level":11,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Битрейт (Bitrate)","bg":"Битрейт","en":"Bitrate","alts":["bitrate","битрейт","mbps","скорост на данните"],"def":"Колко данни в секунда се записват; по-високата стойност пази повече детайл, но файлът е по-голям.","ex":"Измерва се в Mbps — мегабита в секунда. 100 Mbps са 12,5 MB в секунда (100 ÷ 8), тоест около 750 MB за минута запис. Сметни го, преди да избереш карта памет."}},{"id":"studio.cam.focus.t01","legacyId":"t1gayogx","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Дълбочина на рязкост (Depth of field)","bg":"Дълбочина на рязкост","en":"Depth of field","alts":["depth of field","dof","дълбочина"],"def":"Зоната пред и зад точката на фокуса, в която предметите изглеждат ясни, а не размити.","ex":"Зависи главно от блендата, фокусното разстояние и разстоянието до обекта. Зоната не е симетрична: при средни разстояния около една трета от нея е пред точката на фокуса и две трети — зад нея."}},{"id":"studio.cam.focus.t02","legacyId":"tv5iszd","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Плитка дълбочина на рязкост (Shallow depth of field)","bg":"Плитка дълбочина на рязкост","en":"Shallow depth of field","alts":["плитка","shallow depth of field"],"def":"Само малка част от пространството е ясна: фонът се превръща в меко петно и героят се откроява от него.","ex":"Кадърът с плитка рязкост изглежда „кинематографично“, но не прекалявай: ако всеки кадър е такъв, зрителят губи представа къде се намират героите и какво има около тях."}},{"id":"studio.cam.focus.t03","legacyId":"t2mlicg","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Прехвърляне на фокуса (Rack focus)","bg":"Прехвърляне на фокуса","en":"Rack focus","alts":["rack focus","прехвърляне"],"def":"По време на кадъра рязкостта се премества от един обект към друг, който е на различно разстояние; така вниманието на зрителя минава от единия към другия.","ex":"Скоростта на прехвърлянето също разказва: бавното е като плавно отместване на мисълта, а бързото — като внезапно стряскане."}},{"id":"studio.cam.focus.t04","legacyId":"t1unxou6","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Следящ фокус (Continuous autofocus)","bg":"Следящ фокус","en":"Continuous autofocus","alts":["следящ","af-c","continuous focus"],"def":"Автоматичен режим, при който камерата непрекъснато пренастройва рязкостта, докато обектът се приближава или отдалечава.","ex":"Разпознаваш го на дисплея: рамката на фокуса се мести заедно с обекта. В менюто се казва AF-C при Nikon, Sony и Fujifilm и Servo (AI Servo) при Canon."}},{"id":"studio.cam.focus.t05","legacyId":"t1sunica","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Заключен фокус (Single-shot autofocus)","bg":"Заключен фокус","en":"Single-shot autofocus","alts":["заключен","af-s","single focus"],"def":"Автоматичен режим, при който камерата намира рязкостта веднъж и я задържа, докато снимаш — удобно при неподвижен обект.","ex":"Удобен е за портрет и пейзаж: фокусираш, задържаш спусъка наполовина натиснат и прекадрираш, без рязкостта да се мени. При Canon режимът се казва One-Shot AF."}},{"id":"studio.cam.focus.t06","legacyId":"tfa409e","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Асистент по фокуса (Focus puller)","bg":"Асистент по фокуса","en":"Focus puller","alts":["фокус-пулер","първи асистент-оператор"],"def":"Член на операторския екип, който по време на дубъла върти пръстена за рязкост на обектива и следи разстоянието до актьорите.","ex":"Работата му е една от най-трудните в екипа: при отворена бленда грешка от няколко сантиметра разваля дубъла. Обикновено не гледа през визьора, а следи действието с очи или на отделен монитор."}},{"id":"studio.cam.focus.t07","legacyId":"tfvr14h","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Дълбок фокус (Deep focus)","bg":"Дълбок фокус","en":"Deep focus","alts":["deep focus","дълбок"],"def":"Всичко — от предмета отпред до дъното — е рязко; действието се подрежда на няколко плана („Гражданинът Кейн“).","ex":"В 3D анимацията всичко е рязко по подразбиране — като при дълбок фокус. Размитият фон се добавя нарочно чрез настройка на виртуалната камера."}},{"id":"studio.cam.focus.t08","legacyId":"t1emjr94","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Мек фокус (Soft focus)","bg":"Мек фокус","en":"Soft focus","alts":["soft focus","мек"],"def":"Целият образ е леко замъглен и мечтателен, контурите са нежни, а светлите места сякаш сияят — за спомен, романтика или ласкав портрет.","ex":"Не е същото като грешен фокус: при мекия фокус има рязка основа, а около нея светлината се разлива. Постига се със специален обектив или с дифузионен филтър."}},{"id":"studio.cam.move.t01","legacyId":"tb4yqh9","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Панорама (Pan)","bg":"Панорама","en":"Pan","alts":["pan","пан"],"def":"Камерата се върти хоризонтално около своята ос, без да се мести.","ex":"Започни и завърши панорамата с неподвижен, добре композиран кадър. При 24 кадъра в секунда твърде бързата панорама кара образа да трепти и да се накъсва."}},{"id":"studio.cam.move.t02","legacyId":"t13m1ztq","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Вертикална панорама (Tilt)","bg":"Вертикална панорама","en":"Tilt","alts":["тилт","tilt"],"def":"Камерата се накланя нагоре или надолу от едно и също място.","ex":"Нагоре по човек или сграда подчертава ръста и силата; надолу може да „свали“ погледа ни към нещо важно на земята — следи, ключ, писмо."}},{"id":"studio.cam.move.t03","legacyId":"t1fjf04x","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Шарийо (Dolly shot)","bg":"Шарийо","en":"Dolly shot","alts":["dolly","тракинг","проезд","количка","travelling"],"def":"Камерата е на подвижна платформа и се движи плавно по релси или по гладък под: приближава, отдалечава или следва героя.","ex":"Думата идва от френското chariot — количка. При малък бюджет го заменят инвалидна количка, скейтборд или маса на колелца."}},{"id":"studio.cam.move.t04","legacyId":"t1bdteae","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Кран (Crane shot)","bg":"Кран","en":"Crane shot","alts":["crane","jib","стрела"],"def":"Камерата е на дълго подвижно рамо и се издига или спуска над действието; разкрива мащаб или завършва сцена.","ex":"Един от най-известните е в „Отнесени от вихъра“ (1939): камерата се издига над гарата в Атланта, докато ранените войници изпълнят целия кадър."}},{"id":"studio.cam.move.t05","legacyId":"t165uuq","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Ръчна камера (Handheld camera)","bg":"Ръчна камера","en":"Handheld camera","alts":["handheld","от ръка","ръчна"],"def":"Операторът държи апарата на рамо или пред себе си, без статив, релси или стабилизатор: кадърът леко трепти — нестабилност, присъствие, документалност.","ex":"Ръчната камера трябва да изглежда умишлено. Дръж лактите до тялото, дишай равно и снимай с по-широк обектив — при него треперенето се вижда по-малко."}},{"id":"studio.cam.move.t06","legacyId":"tq8s2u9","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Стабилизатор (Steadicam, gimbal)","bg":"Стабилизатор","en":"Steadicam, gimbal","alts":["steadicam","gimbal","стедикам","гимбал"],"def":"Носена от оператора система, която гаси трусовете: плавно движение без релси.","ex":"Steadicam е изобретен от Гарет Браун и е представен през 1975 г.; сред първите филми с него е „Роки“ (1976). Гимбалът е по-лекият, електронен вариант: моторчета държат камерата стабилна и хоризонтална."}},{"id":"studio.cam.move.t07","legacyId":"tvhd0ye","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Трансфокация (Zoom)","bg":"Трансфокация","en":"Zoom","alts":["зуумване","zoom","зум"],"def":"Промяна на фокусното разстояние по време на кадъра: образът се уголемява или смалява, без перспективата да се мени.","ex":"В „Бари Линдън“ (1975) Стенли Кубрик често започва от детайл и бавно отдалечава с трансфокация, докато кадърът заприлича на картина от XVIII век."}},{"id":"studio.cam.move.t08","legacyId":"tecbxfx","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Вертиго ефект (Dolly zoom)","bg":"Вертиго ефект","en":"Dolly zoom","alts":["вертиго","vertigo effect"],"def":"Камерата се отдалечава, докато обективът приближава с трансфокация (или обратно): героят остава еднакъв, а фонът се разтяга или свива.","ex":"Името идва от „Световъртеж“ (Vertigo, 1958) на Хичкок: там ефектът показва страха от височина на героя, който гледа надолу по стълбището на камбанарията."}},{"id":"studio.cam.move.t09","legacyId":"t1f8kkqm","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Приближаване на камерата (Push in)","bg":"Приближаване на камерата","en":"Push in","alts":["push in","push-in","приближаване"],"def":"Камерата бавно се движи към героя и кадърът постепенно се стеснява около лицето му; засилва вниманието към вътрешния момент — осъзнаване, решение, страх.","ex":"За разлика от трансфокацията, тук камерата наистина се движи, затова фонът леко се мени и движението се усеща живо. Колкото е по-бавно, толкова по-малко го забелязваме — но го усещаме."}},{"id":"studio.cam.move.t10","legacyId":"t1coc59i","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Отдалечаване на камерата (Pull out)","bg":"Отдалечаване на камерата","en":"Pull out","alts":["pull out","pull back","отдалечаване"],"def":"Камерата се движи назад от героя и кадърът постепенно се разширява; изолира героя или разкрива какво има около него.","ex":"Често завършва филми: камерата се оттегля и оставя героите малки в техния свят — зрителят буквално се сбогува с тях."}},{"id":"studio.cam.move.t11","legacyId":"t89nsic","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Кръгово движение (Arc shot)","bg":"Кръгово движение","en":"Arc shot","alts":["arc","arc shot","кръгово","дъга"],"def":"Камерата обикаля около героя, като пази разстоянието до него; издига момента и показва героя от различни страни.","ex":"За гладко движение се ползват извити релси или стабилизатор. С телефона върви в кръг около приятел, като пазиш еднакво разстояние и той остава в центъра на кадъра."}},{"id":"studio.cam.move.t12","legacyId":"t1413i45","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Рязка панорама (Whip pan)","bg":"Рязка панорама","en":"Whip pan","alts":["whip pan","swish pan"],"def":"Толкова бързо хоризонтално завъртане на камерата, че образът се размазва в ивици; често служи и за преход между сцени.","ex":"Освен като преход, може да свързва двама герои в спор: камерата „прескача“ от единия към другия като погледа на зрител на тенис мач."}},{"id":"studio.cam.move.t13","legacyId":"txlw1wd","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Проследяващ кадър (Tracking shot)","bg":"Проследяващ кадър","en":"Tracking shot","alts":["tracking","tracking shot","тракинг","проследяване"],"def":"Камерата се движи заедно с героя — до него, пред него или зад него — и зрителят сякаш върви с него.","ex":"Шарийото описва техниката — количка и релси, а проследяващият кадър описва какво прави камерата: върви с героя. Може да се снима и с ръчна камера, стабилизатор или от кола."}},{"id":"studio.cam.format.t01","legacyId":"tndk7ry","hall":"studio","domain":"cam","topic":"cam.format","level":10,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Кадрова честота (Frame rate)","bg":"Кадрова честота","en":"Frame rate","alts":["fps","кадри в секунда","frame rate"],"def":"Брой изображения за една секунда филм или видео: 24 — кино, 25 — телевизията в Европа, 30 — телевизията в САЩ и много видеа в мрежата.","ex":"Точните телевизионни стойности в САЩ са 29,97 и 59,94 кадъра в секунда — „дробни“ честоти, останали от въвеждането на цветната телевизия."}},{"id":"studio.cam.format.t02","legacyId":"tdvie42","hall":"studio","domain":"cam","topic":"cam.format","level":10,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Съотношение на страните (Aspect ratio)","bg":"Съотношение на страните","en":"Aspect ratio","alts":["аспектно съотношение","формат на кадъра"],"def":"Пропорцията между ширината и височината на кадъра: 4:3; 16:9; 1,85:1; 2,39:1.","ex":"В „Гранд хотел Будапеща“ Уес Андерсън сменя съотношението на страните според епохата на действието — така самият кадър подсказва в кое време сме."}},{"id":"studio.cam.format.t03","legacyId":"t9vqpfy","hall":"studio","domain":"cam","topic":"cam.format","level":10,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Резолюция (Resolution)","bg":"Резолюция","en":"Resolution","alts":["resolution"],"def":"Брой пиксели по ширина и височина: Full HD 1920 × 1080, 4K UHD 3840 × 2160.","ex":"4K UHD има точно 4 пъти повече пиксели от Full HD — двойно по ширина и двойно по височина. Затова от 4K кадър можеш да изрежеш средната четвърт и пак да имаш Full HD."}},{"id":"studio.cam.format.t04","legacyId":"tmjah75","hall":"studio","domain":"cam","topic":"cam.format","level":10,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Пълнокадров и по-малък сензор (Full frame vs crop sensor)","bg":"Пълнокадров и по-малък сензор","en":"Full frame vs crop sensor","alts":["full frame","crop sensor","crop factor","пълен кадър","кроп"],"def":"Сравнение между светочувствителна площ 36 × 24 mm (колкото кадър от 35-милиметровата фотолента) и по-компактните формати, които изрязват средата на образа и сякаш удължават обектива — най-често с коефициент 1,5–1,6.","ex":"При коефициент 1,5 обектив 50 mm дава зрителен ъгъл като 75 mm на пълен кадър. Класическият кинокадър Super 35 е близък по размер до тези сензори (APS-C)."}},{"id":"studio.cam.format.t05","legacyId":"t1ow6k6l","hall":"studio","domain":"cam","topic":"cam.format","level":10,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Забавен каданс (Slow motion)","bg":"Забавен каданс","en":"Slow motion","alts":["slow motion","забавено движение","забавяне"],"def":"Снимаш с повече кадри в секунда и пускаш с нормалната честота, така че движението на екрана трае по-дълго, отколкото в действителност.","ex":"В режим за забавен каданс телефоните снимат със 120 или 240 кадъра в секунда; пуснат с 30, такъв запис дава 4 или 8 пъти по-бавно движение. Обратното — по-малко кадри при снимане — ускорява движението."}},{"id":"studio.cam.genres.t01","legacyId":"t1oq0tpc","hall":"studio","domain":"cam","topic":"cam.genres","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Портрет (Portrait)","bg":"Портрет","en":"Portrait","alts":["portrait","портрет"],"def":"Снимка, която разкрива характера на човека; обективът, светлината и фонът служат на личността.","ex":"Класически портретен обектив е около 85 mm на пълен кадър: от разстоянието, от което снимаш с него, лицето не се „издува“ като при широкоъгълен обектив отблизо, а фонът се размива."}},{"id":"studio.cam.genres.t02","legacyId":"t1wyqycq","hall":"studio","domain":"cam","topic":"cam.genres","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Пейзаж (Landscape)","bg":"Пейзаж","en":"Landscape","alts":["landscape","пейзаж"],"def":"Природна или градска среда; често с голяма дълбочина на рязкост и с внимание към светлината в часа на снимане.","ex":"Внимавай с думите: в менюта и програми landscape значи и хоризонтална ориентация на кадъра, а portrait — вертикална. Пейзажистите често снимат на статив с бленда f/8–f/11, за да е рязко от близо до далеч."}},{"id":"studio.cam.genres.t03","legacyId":"t14uo72y","hall":"studio","domain":"cam","topic":"cam.genres","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Репортажна фотография (Photojournalism)","bg":"Репортажна фотография","en":"Photojournalism","alts":["photojournalism","репортаж","репортажна"],"def":"Документира реални събития за медиите; истината е по-важна от красотата и нищо не се постановява.","ex":"Разлика с документалната фотография: репортажът следва новината и трябва да е бърз, а документалната фотография проследява една тема дълго — понякога с години."}},{"id":"studio.cam.genres.t04","legacyId":"tqtr3si","hall":"studio","domain":"cam","topic":"cam.genres","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Спортна фотография (Sports photography)","bg":"Спортна фотография","en":"Sports photography","alts":["sports photography","спортна","спорт"],"def":"Бързо движение в решаващия момент: кратък затвор, следящ фокус, дълги обективи, серийни снимки.","ex":"Освен замразяване има и прием панорамиране: следиш бегача с камерата при по-дълъг затвор, например 1/30 s. Той остава рязък, а фонът се размазва в линии и подсказва скоростта."}},{"id":"studio.cam.genres.t05","legacyId":"thkn1x9","hall":"studio","domain":"cam","topic":"cam.genres","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Модна фотография (Fashion photography)","bg":"Модна фотография","en":"Fashion photography","alts":["fashion photography","модна","мода"],"def":"Представя дрехи и стил; постановъчна, с внимателно подбрани модели, грим, светлина и локация.","ex":"Модната снимка продава настроение, не само дреха, затова често прилича на кадър от филм — с локация, персонаж и история. В каталожната снимка, обратно, дрехата трябва да се вижда ясно и точно."}},{"id":"studio.cam.genres.t06","legacyId":"t1qhug1c","hall":"studio","domain":"cam","topic":"cam.genres","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Макрофотография (Macro photography)","bg":"Макрофотография","en":"Macro photography","alts":["macro photography","макрофотография"],"def":"Много малки обекти в мащаб 1:1 или по-голям — насекоми, капки, текстури; дълбочината на рязкост е много плитка.","ex":"Мащаб 1:1 значи, че образът върху сензора е в естествена големина: мравка от 1 cm заема 1 cm от сензора. Заради плитката рязкост макрофотографите често сглобяват няколко кадъра с различен фокус (focus stacking)."}},{"id":"studio.cam.genres.t07","legacyId":"t1wry26u","hall":"studio","domain":"cam","topic":"cam.genres","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Натюрморт (Still life)","bg":"Натюрморт","en":"Still life","alts":["still life","натюрморт","кулинарна"],"def":"Композиция от неодушевени предмети, подредена и осветена от фотографа; към жанра спадат и снимките на храна и на продукти.","ex":"Името идва от френското nature morte („мъртва природа“), а жанрът — от живописта, например холандските натюрморти от XVII век. Днес по същите правила се снимат реклами на продукти."}},{"id":"studio.cam.genres.t08","legacyId":"tmh5r4y","hall":"studio","domain":"cam","topic":"cam.genres","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Фотоистория (Photo story)","bg":"Фотоистория","en":"Photo story","alts":["photo story","фотоистория","фотоесе","photo essay"],"def":"Поредица от снимки, подредени така, че да разказват за човек или събитие с начало, развитие и край.","ex":"Обикновено съчетава различни планове — общ кадър на мястото, портрет на героя, детайли и решаващ момент — подобно на смяната на планове във филмова сцена."}},{"id":"studio.light.3pt.t01","legacyId":"tvpo1ld","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Рисуваща светлина (Key light)","bg":"Рисуваща светлина","en":"Key light","alts":["рисуваща","key light","основна светлина","кий"],"def":"Основният и най-силен източник; моделира лицето и задава посоката на светлината.","ex":"Поставя се първа, а всички останали светлини се нагласят спрямо нея. В натура рисуващата често е самото слънце или голям прозорец."}},{"id":"studio.light.3pt.t02","legacyId":"t1s1fkfy","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Запълваща светлина (Fill light)","bg":"Запълваща светлина","en":"Fill light","alts":["запълваща","fill light","пълнеж"],"def":"По-слаба светлина от другата страна; омекотява сенките от рисуващата.","ex":"Не бива да създава втора видима сянка, затова често е мека и стои близо до камерата. Може да е лампа, отражател или просто светла стена."}},{"id":"studio.light.3pt.t03","legacyId":"t1l8u6t4","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Контражур (Backlight)","bg":"Контражур","en":"Backlight","alts":["back light","задна светлина","hair light"],"def":"Светлина отзад и отгоре; очертава контура и отделя героя от фона.","ex":"Думата идва от френското contre-jour — „срещу светлината“. Личи като светъл ореол по косата и раменете; в натура ролята му често играе ниското слънце зад героя."}},{"id":"studio.light.3pt.t04","legacyId":"tspi29z","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Съотношение на светлините (Lighting ratio)","bg":"Съотношение на светлините","en":"Lighting ratio","alts":["lighting ratio","съотношение"],"def":"Колко по-силна е рисуващата от запълващата: 2:1 — меко, 8:1 — драматично.","ex":"Всяка степен разлика удвоява съотношението: 1 степен — 2:1, 2 степени — 4:1, 3 степени — 8:1. Ниските съотношения са типични за рекламата и комедията, високите — за ноара."}},{"id":"studio.light.3pt.t05","legacyId":"t1ko0v19","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Отражател (Reflector)","bg":"Отражател","en":"Reflector","alts":["reflector","рефлектор"],"def":"Бяла или сребриста повърхност, която връща светлина в сенките — често като запълваща.","ex":"Сгъваемите отражатели имат няколко лица: сребристото връща повече и по-контрастна светлина, златистото затопля кожата. Черната страна прави обратното: поглъща светлина и задълбочава сенките."}},{"id":"studio.light.3pt.t06","legacyId":"tsflyud","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Рембрантово осветление (Rembrandt lighting)","bg":"Рембрантово осветление","en":"Rembrandt lighting","alts":["rembrandt","rembrandt lighting","рембрант","рембрантова светлина"],"def":"Рисуващата светлина е високо и встрани; на сенчестата буза остава малък светъл триъгълник под окото.","ex":"Името идва от портретите на холандския художник Рембранд, в които светлината пада високо отстрани. Постига се само с една лампа и е добро начало за драматичен портрет."}},{"id":"studio.light.3pt.t07","legacyId":"t152in5m","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Късо осветление (Short lighting)","bg":"Късо осветление","en":"Short lighting","alts":["short lighting","късо","smart side"],"def":"Рисуващата пада върху страната на лицето, която е по-далеч от камерата; към камерата остава сянка и лицето изглежда по-тясно и драматично.","ex":"Подчертава скулите и обема, затова е често в драмата и ноара. Обратното е широкото осветление (Broad lighting), при което светлата страна е обърната към камерата."}},{"id":"studio.light.3pt.t08","legacyId":"tn13jwl","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Широко осветление (Broad lighting)","bg":"Широко осветление","en":"Broad lighting","alts":["broad lighting","широко","dumb side"],"def":"Рисуващата пада върху страната на лицето, която е по-близо до камерата; лицето изглежда по-пълно, открито и по-плоско.","ex":"Подходящо е за открит, приветлив образ — интервю, реклама, комедия, — но прави пълното лице още по-пълно. Обратното е късото осветление (Short lighting)."}},{"id":"studio.light.quality.t01","legacyId":"t19d4i6c","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Твърда светлина (Hard light)","bg":"Твърда светлина","en":"Hard light","alts":["твърда","hard light"],"def":"Малък или далечен източник: сенки с остър ръб, силен контраст.","ex":"Пример: пладнешко слънце в ясен ден или гола крушка. Познаваш я по рязката граница между светло и сянка, например под носа; подходяща е за жега, напрежение и ноар."}},{"id":"studio.light.quality.t02","legacyId":"t19wgqxm","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Мека светлина (Soft light)","bg":"Мека светлина","en":"Soft light","alts":["мека","soft light","разсеяна светлина"],"def":"Голям или близък източник (или лампа през плат): плавни преходи и сенки с размит ръб.","ex":"Меката светлина ласкае лицето и скрива неравностите на кожата, затова е честа в рекламата и в романтичните сцени. Голям прозорец без пряко слънце е най-лесният ѝ източник."}},{"id":"studio.light.quality.t03","legacyId":"tj7wh0y","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Светла тоналност (High-key)","bg":"Светла тоналност","en":"High-key","alts":["high key","хай кий"],"def":"Ярка, равномерно осветена картина с малко сенки и нисък контраст: комедия, мюзикъл, реклама.","ex":"Не е просто преекспониран кадър: сенките са светли и меки, но детайлът в лицето се пази. Типична е за рекламите на козметика и за много телевизионни комедии."}},{"id":"studio.light.quality.t04","legacyId":"tukljz8","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Тъмна тоналност (Low-key)","bg":"Тъмна тоналност","en":"Low-key","alts":["low key","лоу кий"],"def":"Почти целият кадър тъне в мрак, а огрени са само отделни участъци: ноар, трилър, драма.","ex":"Не е просто тъмен кадър: светлината е малко, но точно поставена, за да покаже само важното. Ако всичко е еднакво тъмно, кадърът е просто недоекспониран."}},{"id":"studio.light.quality.t05","legacyId":"t1urtn9n","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Мотивирана светлина (Motivated light)","bg":"Мотивирана светлина","en":"Motivated light","alts":["мотивирана","motivated light"],"def":"Светлината изглежда, сякаш идва от реален източник в сцената — прозорец, лампа, огън.","ex":"Пример: героят чете до прозорец, а светлината идва от прожектор отвън — зрителят вярва, че е слънцето. Без такъв видим или подразбиращ се източник светлината изглежда театрална."}},{"id":"studio.light.quality.t06","legacyId":"t1hpxsv5","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Практична лампа (Practical)","bg":"Практична лампа","en":"Practical","alts":["practical light","практична"],"def":"Източник, който е част от декора: вижда се в кадъра и наистина свети в сцената — например свещ, телевизор или полилей.","ex":"Името е от английското practical — реквизит, който наистина работи. Често крушката се сменя с по-слаба или се пуска през димер, за да не прегаря в кадъра."}},{"id":"studio.light.quality.t07","legacyId":"t1iiktgd","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Светлосянка (Chiaroscuro)","bg":"Светлосянка","en":"Chiaroscuro","alts":["chiaroscuro","кяроскуро"],"def":"Рязко противопоставяне на ярки и почти черни петна, което моделира обема на лицата и предметите; похват, дошъл в киното от живописта.","ex":"Произнася се „кяроскуро“. В живописта е типична за Караваджо и Рембранд, а в киното — за ноара и за сцените с една силна лампа в тъмна стая."}},{"id":"studio.light.quality.t08","legacyId":"t1gj0uc7","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Отблясък от обектива (Lens flare)","bg":"Отблясък от обектива","en":"Lens flare","alts":["lens flare","флеър","отблясък"],"def":"Ярък източник, насочен към камерата, оставя в кадъра петна, кръгове и ивици от разсейването в стъклата; често е нарочен ефект.","ex":"Нежелания отблясък махаш със сенник на обектива или като засенчиш предната леща с ръка или картон извън кадъра. Нарочният засилва усещането за ярко слънце, жега или мечтателност."}},{"id":"studio.light.quality.t09","legacyId":"tiocmso","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Отразена светлина (Bounce light)","bg":"Отразена светлина","en":"Bounce light","alts":["bounce","bounce light","отразена"],"def":"Лампата не сочи към героя, а към таван или бяла стена, и до него стига само непряката светлина.","ex":"Отразената светлина взема цвета на повърхността: от зелена стена лицето позеленява. Затова на снимачната площадка носят бели платна и листове стиропор."}},{"id":"studio.light.temp.t01","legacyId":"tgu9bk3","hall":"studio","domain":"light","topic":"light.temp","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy","fixes":["B001","B002","B003"]},"kind":"term","term":{"label":"Цветна температура (Colour temperature)","bg":"Цветна температура","en":"Colour temperature","alts":["келвини","kelvin","color temperature","colour temperature"],"def":"Цветът на светлината, изразен по скала в K: ниските стойности са топли и оранжеви, високите — студени и сини.","ex":"Келвините идват от физиката: нагрят метал свети първо червено, после жълто и бяло, а най-горещите звезди са синкави. Затова „топлата“ на цвят светлина е с ниска температура."}},{"id":"studio.light.temp.t02","legacyId":"tljj6ud","hall":"studio","domain":"light","topic":"light.temp","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Баланс на бялото (White balance)","bg":"Баланс на бялото","en":"White balance","alts":["white balance","wb"],"def":"Настройка на камерата спрямо цвета на осветлението, така че неутралните предмети да излязат без цветен оттенък.","ex":"Ръчният баланс се прави, като камерата „погледне“ бял или сив картон на мястото на героя. Ако снимаш в RAW, балансът може да се смени и по-късно без загуба на качество."}},{"id":"studio.light.temp.t03","legacyId":"tyhh5ry","hall":"studio","domain":"light","topic":"light.temp","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Светлина от лампа с жичка (Tungsten light)","bg":"Светлина от лампа с жичка","en":"Tungsten light","alts":["3200 k","3200","волфрамова","tungsten"],"def":"Топлият, оранжев тон на класическите студийни прожектори и на старите домашни крушки.","ex":"Стандартът в киното е около 3200 K, а домашните крушки с жичка са още по-топли — около 2700 K. Днес много LED лампи могат да имитират и нея, и дневната светлина."}},{"id":"studio.light.temp.t04","legacyId":"tbximc3","hall":"studio","domain":"light","topic":"light.temp","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Дневна светлина (Daylight)","bg":"Дневна светлина","en":"Daylight","alts":["5600 k","5600","daylight"],"def":"Слънцето и небето по пладне — приема се за неутрално бяло; облачното небе и сянката са по-сини.","ex":"Стандартът е около 5600 K, но реалната светлина се мени: облачното небе и сянката са 6500 K и повече. HMI прожекторите в киното са направени да я имитират."}},{"id":"studio.light.temp.t05","legacyId":"t4xa8s2","hall":"studio","domain":"light","topic":"light.temp","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy","fixes":["B004","B005"]},"kind":"term","term":{"label":"Корекционен филтър (Colour correction gel)","bg":"Корекционен филтър","en":"Colour correction gel","alts":["cto","ctb","гел","филтър"],"def":"Цветно фолио пред лампата: оранжевото затопля дневната светлина, а синьото охлажда топлата до дневна.","ex":"Гелът е от термоустойчиво фолио и се закрепва на рамка пред лампата. Синият гел (CTB) поглъща доста светлина, затова лампата с него отслабва забележимо."}},{"id":"studio.light.loc.t01","legacyId":"tp3rc1o","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Натура (Location shooting)","bg":"Натура","en":"Location shooting","alts":["exterior","екстериор","външни снимки"],"def":"Снимки на реално място извън студиото — улица, поле, гора или истинска сграда.","ex":"Натурата носи истинска атмосфера, но и рискове: времето, шумът, минувачите, слънцето, което се мести. Затова преди снимките се прави оглед на локации (Location scouting)."}},{"id":"studio.light.loc.t02","legacyId":"tf9zwca","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Павилион (Soundstage)","bg":"Павилион","en":"Soundstage","alts":["студио","soundstage"],"def":"Голямо затворено хале, в което се строи декорът и светлината се контролира изцяло.","ex":"В България известна база с павилиони е киноцентър „Бояна“ в София, където се снимат и български, и чуждестранни продукции. Декорите в павилион често нямат таван, за да светят лампите отгоре."}},{"id":"studio.light.loc.t03","legacyId":"t9dymh9","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Режимни снимки (Magic hour)","bg":"Режимни снимки","en":"Magic hour","alts":["режим","режимно време","magic hour","син час"],"def":"Снимки в кратките минути на здрача, когато небето и изкуствената светлина са в равновесие.","ex":"Небето още дава мек син тон, а уличните лампи и прозорците вече светят — затова градът изглежда вълшебно. Различава се от златния час, който е преди залеза, докато слънцето още грее."}},{"id":"studio.light.loc.t04","legacyId":"t3wfv6s","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Американска нощ (Day for night)","bg":"Американска нощ","en":"Day for night","alts":["day for night","ден за нощ"],"def":"Сцена, която на екрана се развива след мръкване, а е заснета на слънце: недоекспониране, синкав цвят, небето извън кадъра.","ex":"На френски техниката се казва nuit américaine, а Франсоа Трюфо кръщава така свой филм за снимането на филм — „Американска нощ“ (1973)."}},{"id":"studio.light.loc.t05","legacyId":"txi72dr","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Златният час (Golden hour)","bg":"Златният час","en":"Golden hour","alts":["golden hour","златен час"],"def":"Кратко време малко след изгрев и малко преди залез, когато слънцето е ниско: топла, мека светлина и дълги сенки.","ex":"Продължителността зависи от сезона и мястото: близо до екватора слънцето залязва стръмно и златният час е по-кратък. Провери времето в приложение за изгрев и залез."}},{"id":"studio.light.loc.t06","legacyId":"t1uhq18d","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Комбинирани снимки (Compositing)","bg":"Комбинирани снимки","en":"Compositing","alts":["трикови снимки","композитинг","vfx","комбинирани"],"def":"Съчетаване на няколко изображения в едно: рисуван фон, макет, зелен екран.","ex":"Днес се прави в програми като Nuke или After Effects, но идеята е стара: още Мелиес снима по няколко пъти върху една и съща лента, за да съчетае образи."}},{"id":"studio.light.loc.t07","legacyId":"t1vpxjbi","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Зелен екран (Chroma key)","bg":"Зелен екран","en":"Chroma key","alts":["chroma key","green screen","хромакей","син екран"],"def":"Актьорът се снима пред равномерен едноцветен фон, който софтуерът изрязва по цвят и заменя с друг образ.","ex":"Зеленото е най-често, защото е далеч от цвета на кожата и сензорът го записва най-чисто; синьото се ползва, когато в кадъра има зелено. Екранът трябва да е осветен равномерно."}},{"id":"studio.light.loc.t08","legacyId":"tgc950l","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Рисуван фон (Matte painting)","bg":"Рисуван фон","en":"Matte painting","alts":["matte painting","мат пейнтинг","рисуван декор"],"def":"Пейзаж или декор, изобразен от художник — някога върху стъкло, днес дигитално — и съчетан със заснетия кадър, за да разшири пространството.","ex":"Класическият рисуван фон е върху стъкло пред камерата: част от стъклото е прозрачна и през нея се вижда истинският декор. Днес се смесват рисунка, снимки и 3D."}},{"id":"studio.light.loc.t09","legacyId":"t1m2gn1d","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Макет (Miniature)","bg":"Макет","en":"Miniature","alts":["miniature","макет"],"def":"Умален модел на сграда, кораб или град, заснет така, че да изглежда в реален размер.","ex":"Снима се с повече кадри в секунда от нормалното: при прожекция движението се забавя и водата, огънят и рухващите стени изглеждат тежки като в реален размер."}},{"id":"studio.light.loc.t10","legacyId":"t2w3ogr","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Рир-проекция (Rear projection)","bg":"Рир-проекция","en":"Rear projection","alts":["rear projection","рир проекция","задна проекция","back projection"],"def":"Актьорите играят пред полупрозрачен екран, а от другата му страна апарат пуска предварително заснет движещ се фон — класическият начин за сцени в кола.","ex":"Слабото ѝ място е, че прожектираният фон често излиза по-блед и по-мек от актьорите отпред — окото усеща, че са в различни светове."}},{"id":"studio.light.color.t01","legacyId":"t1jetzow","hall":"studio","domain":"light","topic":"light.color","level":10,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy","fixes":["B006","B007","B008"]},"kind":"term","term":{"label":"Колорит (Colour palette)","bg":"Колорит","en":"Colour palette","alts":["палитра","color palette","colour palette"],"def":"Цветовият строй на целия филм или на сцената.","ex":"Пример: светът вътре в „Матрицата“ (1999) има зеленикав колорит, а реалният свят извън нея — студен и синкав. Така само по цвета разбираш къде си."}},{"id":"studio.light.color.t02","legacyId":"t10n96ik","hall":"studio","domain":"light","topic":"light.color","level":10,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy","fixes":["B009","B010","B011"]},"kind":"term","term":{"label":"Цветови сценарий (Colour script)","bg":"Цветови сценарий","en":"Colour script","alts":["color script","колор скрипт","colour script"],"def":"Малки цветни кадри за целия филм, които показват как цветът следва емоцията.","ex":"Използва се най-вече в анимацията — в Pixar го правят още преди продукцията. Не е нужно да е красив: по едно малко цветно петно за всяка сцена стига."}},{"id":"studio.light.color.t03","legacyId":"t1k2zrju","hall":"studio","domain":"light","topic":"light.color","level":10,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy","fixes":["B012","B013"]},"kind":"term","term":{"label":"Топло и студено (Warm and cool colours)","bg":"Топло и студено","en":"Warm and cool colours","alts":["топли и студени","топло срещу студено"],"def":"Цветовете откъм оранжевото приближават и сгряват, а тези откъм синьото отдалечават и охлаждат.","ex":"В много филми домът и близостта са в топли тонове, а опасността и самотата — в студени. Топъл герой на студен фон изпъква напред сам, без допълнителна светлина."}},{"id":"studio.light.color.t04","legacyId":"tzcf4qx","hall":"studio","domain":"light","topic":"light.color","level":10,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy","fixes":["B014","B015"]},"kind":"term","term":{"label":"Цветен акцент (Colour accent)","bg":"Цветен акцент","en":"Colour accent","alts":["акцент"],"def":"Малко петно наситен цвят сред приглушена палитра; веднага става център на внимание.","ex":"Чест похват е червен балон в сив град или жълт дъждобран на дъждовна улица. Акцентът работи, когато е един — два силни акцента се борят за окото."}},{"id":"studio.light.color.t05","legacyId":"t1oz08wm","hall":"studio","domain":"light","topic":"light.color","level":10,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy","fixes":["B016","B017","B018"]},"kind":"term","term":{"label":"Допълващи цветове (Complementary colours)","bg":"Допълващи цветове","en":"Complementary colours","alts":["complementary colors","комплементарни","допълнителни цветове","teal and orange","complementary colours"],"def":"Противоположни в цветния кръг — синьо и оранжево, червено и зелено; заедно дават най-силния цветови контраст.","ex":"Сложени един до друг, двата цвята се засилват взаимно и изглеждат по-наситени. В анимацията често разделят героите — например топъл герой срещу студен противник."}},{"id":"studio.light.color.t06","legacyId":"t1lk2j55","hall":"studio","domain":"light","topic":"light.color","level":10,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Монохромна гама (Monochromatic palette)","bg":"Монохромна гама","en":"Monochromatic palette","alts":["monochromatic","монохромна","монохром"],"def":"Оттенъци на един цвят; внушава единно, силно настроение.","ex":"Монохромната гама не е черно-бяла: може да е изцяло в сини, зелени или червени оттенъци. Подходяща е за сънища, спомени и сцени, в които едно чувство изпълва всичко."}},{"id":"studio.light.color.t07","legacyId":"tkiohr0","hall":"studio","domain":"light","topic":"light.color","level":10,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Наситеност (Saturation)","bg":"Наситеност","en":"Saturation","alts":["saturation","наситеност на цвета"],"def":"Колко чист и силен е цветът: при ниска стойност кадърът е блед и мрачен, при висока — ярък и приказен.","ex":"Наситеността се различава от яркостта: бледорозовото е светло, но ненаситено. В приложенията за снимки плъзгачът „Наситеност“ сменя чистотата на цвета, а не светлината."}},{"id":"studio.light.color.t08","legacyId":"t3o840l","hall":"studio","domain":"light","topic":"light.color","level":10,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy","fixes":["B019","B020"]},"kind":"term","term":{"label":"Цветова корекция (Colour grading)","bg":"Цветова корекция","en":"Colour grading","alts":["color grading","colour grading","грейдинг","цветокорекция"],"def":"Работата на колориста в постпродукцията: уеднаквява кадрите и дава на филма цветови стил.","ex":"Колористът работи в затъмнена стая с калибриран монитор. Популярна програма е DaVinci Resolve, която има и безплатна версия — с нея можеш да опиташ сам."}},{"id":"studio.light.flash.t01","legacyId":"t18e2814","hall":"studio","domain":"light","topic":"light.flash","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Светкавица (Flash)","bg":"Светкавица","en":"Flash","alts":["flash","светкавица"],"def":"Много кратък и силен импулс светлина; „замразява“ движението и осветява там, където светлината не стига.","ex":"Импулсът трае хилядна от секундата или по-малко. Светлината ѝ е близка до дневната — около 5500 K, затова се смесва добре със слънцето, но не и с лампа с жичка."}},{"id":"studio.light.flash.t02","legacyId":"t4rse5p","hall":"studio","domain":"light","topic":"light.flash","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Отразена светкавица (Bounce flash)","bg":"Отразена светкавица","en":"Bounce flash","alts":["bounce flash","отразена светкавица"],"def":"Светкавицата сочи към таван или стена; до героя стига мека, естествена светлина.","ex":"Работи най-добре с нисък бял таван; при висок или цветен таван светлината отслабва или се оцветява. Затова главата на повечето външни светкавици се върти нагоре и встрани."}},{"id":"studio.light.flash.t03","legacyId":"twk29rp","hall":"studio","domain":"light","topic":"light.flash","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Запълваща светкавица (Fill flash)","bg":"Запълваща светкавица","en":"Fill flash","alts":["fill flash","запълваща светкавица"],"def":"Слаба светкавица през деня, която изсветлява сенките по лицето при силно слънце или контражур.","ex":"Обикновено се настройва 1–2 степени по-слабо от дневната светлина, за да не личи, че има светкавица. Стига само до близки обекти — за далечен герой не помага."}},{"id":"studio.light.flash.t04","legacyId":"t12e90mp","hall":"studio","domain":"light","topic":"light.flash","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Синхронна скорост (Sync speed)","bg":"Синхронна скорост","en":"Sync speed","alts":["sync speed","x-sync","синхронна скорост"],"def":"Най-краткото време на експонация, при което целият кадър се осветява от светкавицата — обикновено около 1/200–1/250 s.","ex":"Ограничението идва от завесовия затвор в тялото на апарата. При централен затвор в обектива светкавицата се синхронизира при почти всяка скорост."}},{"id":"studio.light.flash.t05","legacyId":"tr0go3a","hall":"studio","domain":"light","topic":"light.flash","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Водещо число (Guide number)","bg":"Водещо число","en":"Guide number","alts":["guide number","gn","водещо число"],"def":"Мярка за мощността на светкавицата: разстоянието до обекта в метри, умножено по стойността на блендата за правилна експозиция (при ISO 100).","ex":"Във футове същото водещо число е около 3,3 пъти по-голямо, затова провери в каква мярка е дадено. Производителите често го посочват при най-тесния ъгъл на главата — така то изглежда по-голямо."}},{"id":"studio.light.flash.t06","legacyId":"tt95bo7","hall":"studio","domain":"light","topic":"light.flash","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Ефект „червени очи“ (Red-eye effect)","bg":"Ефект „червени очи“","en":"Red-eye effect","alts":["red-eye","red eye","червени очи"],"def":"Отражение на светкавицата от дъното на окото, когато тя е близо до оста на обектива.","ex":"Червеното е от кръвоносните съдове в дъното на окото. Помагат светкавица, отдалечена от обектива, отразяване от тавана или предварително святкане, което свива зениците."}},{"id":"studio.board.types.t01","legacyId":"tmve4r9","hall":"studio","domain":"board","topic":"board.types","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Storyboard","en":"Storyboard","alts":["сториборд","story board","раскадровка"],"def":"Рисунки кадър по кадър, които превръщат сценария в образ преди снимките или анимирането.","ex":"В студиото на Дисни идеята сцените да се рисуват на отделни листове и да се забождат поред на табло приписват на аниматора Уеб Смит. Първите пълни storyboard са направени за „Трите малки прасенца“ (1933)."}},{"id":"studio.board.types.t02","legacyId":"tjg9hv9","hall":"studio","domain":"board","topic":"board.types","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Миниатюри (Thumbnails)","bg":"Миниатюри","en":"Thumbnails","alts":["thumbnails","тъмнейли","скици"],"def":"Малки бързи рисунки, с които се търсят композицията и ъгълът, преди да се рисува чисто.","ex":"Глебас ги описва като скици с размер на пощенска марка и често ги рисува направо в полетата на сценария. Малкият размер те кара да мислиш за композицията, а не за детайлите."}},{"id":"studio.board.types.t03","legacyId":"t6zlevk","hall":"studio","domain":"board","topic":"board.types","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Beat board","en":"Beat board","alts":["beatboard","бийт борд"],"def":"По една рисунка за всяка сцена или ключов момент; целият филм на една стена.","ex":"Глебас сравнява рисунките в beat board с илюстрации в детска книжка: всяка разказва цяла сцена с една картина. С тях режисьорът представя историята пред продуцентите, инвеститорите и екипа."}},{"id":"studio.board.types.t04","legacyId":"t1qmbu8i","hall":"studio","domain":"board","topic":"board.types","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Animatic","en":"Animatic","alts":["story reel","аниматик"],"def":"Панелите на storyboard, монтирани във времето със звук и движения на камерата — първата чернова на филма.","ex":"По-старото име е Leica reel — по фотоапаратите Leica, с които първо са заснемали панелите. В анимацията монтажистът постепенно заменя панелите в animatic с готови сцени."}},{"id":"studio.board.types.t05","legacyId":"th2m7e","hall":"studio","domain":"board","topic":"board.types","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Layout","en":"Layout","alts":["лейаут"],"def":"Точната постановка на кадъра: фон, позиции и размер на героите, движение на камерата.","ex":"Глебас: в игралното кино операторската работа и разстановката на актьорите вършат това, което в анимацията прави отделът по layout. В 2D анимацията layout е и чертежът, по който се рисува фонът."}},{"id":"studio.board.types.t06","legacyId":"t1vz2nmm","hall":"studio","domain":"board","topic":"board.types","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Prose storyboard","en":"Prose storyboard","alts":["прозаичен сториборд","словесен storyboard"],"def":"Всяко изречение описва един кадър; удобно, когато няма време или място за рисуване.","ex":"Пиши в сегашно време — на екрана всичко се случва „сега“ — и започвай всеки ред с плана: „Общ план: …“, „Детайл: …“. Подходящ е за тълпи, взривове и всичко, което трудно се рисува бързо."}},{"id":"studio.board.notation.t01","legacyId":"t16jkq2r","hall":"studio","domain":"board","topic":"board.notation","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Стрелка за героя (Movement arrow)","bg":"Стрелка за героя","en":"Movement arrow","alts":["стрелка за движение"],"def":"Знак вътре в панела, който показва накъде се придвижва персонаж или предмет.","ex":"Ако героят идва към камерата или се отдалечава, нарисувай стрелката в перспектива — широка в близкия край и тясна в далечния. Глебас: със стрелки се отбелязват и влизанията, и излизанията от кадъра."}},{"id":"studio.board.notation.t02","legacyId":"tm9aq89","hall":"studio","domain":"board","topic":"board.notation","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Стрелка за камерата (Camera arrow)","bg":"Стрелка за камерата","en":"Camera arrow","alts":["стрелка за движение на камерата"],"def":"Знак по ръба на панела или извън него, който показва панорама, шарийо или кран — движение на самия кадър, а не на героите.","ex":"Глебас предупреждава: в 3D камерата може да лети навсякъде, но я движи само когато движението помага на историята. Всяка стрелка за камерата трябва да има причина."}},{"id":"studio.board.notation.t03","legacyId":"t1700e2e","hall":"studio","domain":"board","topic":"board.notation","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Рамка в рамка (Push-in)","bg":"Рамка в рамка","en":"Push-in","alts":["вътрешна рамка","push in"],"def":"Малък правоъгълник в панела със стрелки от ъглите към него: камерата приближава (трансфокация или шарийо) до този кадър.","ex":"Не го бъркай с рамка в рамката (Frame within a frame) от композицията: там врата или прозорец обграждат героя в самия кадър. Тук вътрешната рамка не се вижда на екрана — тя е крайният кадър."}},{"id":"studio.board.notation.t04","legacyId":"tdomxdk","hall":"studio","domain":"board","topic":"board.notation","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Номерация (Scene and shot numbers)","bg":"Номерация","en":"Scene and shot numbers","alts":["номер на кадър","номер на сцена"],"def":"Адресът на всеки панел — сцена и пореден кадър, например „Сц. 4 / Кадър 12“; по него се свързват сценарият, снимачният план и монтажът.","ex":"Глебас: студийните бланки за storyboard имат полета за номерата на продукцията, сцената и панела, а под всяка рамка — място за диалог, действие и указания за камерата."}},{"id":"studio.board.notation.t05","legacyId":"t61ghsd","hall":"studio","domain":"board","topic":"board.notation","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Зад кадър (Off-screen / voice-over)","bg":"Зад кадър","en":"Off-screen / voice-over","alts":["зк","off screen","os","vo","глас зад кадър"],"def":"Глас или звук, който зрителят чува, но чийто източник не вижда на екрана; в панела се отбелязва със съкращение до репликата.","ex":"O.S. (off-screen) значи, че героят е в сцената, но извън кадъра — например говори от съседната стая. V.O. (voice-over) е глас извън сцената: разказвач или мислите на героя."}},{"id":"studio.board.persp.t01","legacyId":"t1t5np9i","hall":"studio","domain":"board","topic":"board.persp","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Линия на хоризонта (Horizon line)","bg":"Линия на хоризонта","en":"Horizon line","alts":["horizon line","хоризонт","линия на очите","eye level line"],"def":"Въображаемата права на височината на очите на камерата; на открито там небето среща земята, а предметите под нея виждаме отгоре.","ex":"Глебас: хоризонтът винаги е на нивото на очите на зрителя, дори в стая, където не се вижда. Затова го начертай пръв — по него се строят точките на изчезване и размерите на хората."}},{"id":"studio.board.persp.t02","legacyId":"t17carsn","hall":"studio","domain":"board","topic":"board.persp","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Точка на изчезване (Vanishing point)","bg":"Точка на изчезване","en":"Vanishing point","alts":["vanishing point","vp","точка на сбягване","точка на схождане"],"def":"Мястото на хоризонта, в което се събират успоредните линии, отдалечаващи се от зрителя — като релсите в далечината.","ex":"Всяка група успоредни ръбове има своя точка: ако столовете в стаята са завъртени различно, всеки бяга към свои точки на същия хоризонт. При една и при две точки вертикалите остават отвесни."}},{"id":"studio.board.persp.t03","legacyId":"tckvk9o","hall":"studio","domain":"board","topic":"board.persp","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Перспектива с една точка (One-point perspective)","bg":"Перспектива с една точка","en":"One-point perspective","alts":["една точка","one-point perspective","едноточкова"],"def":"Камерата гледа право по дължината на пространството; всички линии в дълбочина се събират в общ център на хоризонта — коридор, път, релси.","ex":"Глебас: при една точка гледаме предметите право срещу тях — предната им страна е успоредна на рамката и не се изкривява. Затова кадърът изглежда подреден и статичен — силен за коридори и тунели, но скучен, ако се повтаря."}},{"id":"studio.board.persp.t04","legacyId":"ttsq22p","hall":"studio","domain":"board","topic":"board.persp","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Перспектива с две точки (Two-point perspective)","bg":"Перспектива с две точки","en":"Two-point perspective","alts":["две точки","two-point perspective","двуточкова"],"def":"Предметът е обърнат с ъгъл към камерата; ръбовете му бягат наляво и надясно към два отделни центъра на хоризонта — ъгъл на сграда, кутия.","ex":"Глебас: колкото по-далеч една от друга са двете точки, толкова по-спокоен е изгледът, като от телеобектив; близките точки дават силно изкривяване, като широкоъгълен обектив."}},{"id":"studio.board.persp.t05","legacyId":"tz345i6","hall":"studio","domain":"board","topic":"board.persp","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Перспектива с три точки (Three-point perspective)","bg":"Перспектива с три точки","en":"Three-point perspective","alts":["три точки","three-point perspective","триточкова"],"def":"Освен двата центъра на хоризонта има и трети — високо над него или ниско под него, където се събират вертикалите: небостъргач, гледан отдолу или отгоре.","ex":"Глебас: тази перспектива дава най-дълбокото пространство. Подходяща е, когато височината е част от историята — герой виси от покрив, а улицата долу се смалява към третата точка."}},{"id":"studio.board.persp.t06","legacyId":"t41njtd","hall":"studio","domain":"board","topic":"board.persp","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Ефект на асансьора (Elevator effect)","bg":"Ефект на асансьора","en":"Elevator effect","alts":["elevator effect","асансьор"],"def":"Понятие на Джон Харт: когато камерата се качва или слиза, хоризонтът и точките на изчезване се движат заедно с нея.","ex":"Представи си, че снимаш от стъклен асансьор: на партера хоризонтът минава през главите на хората, а на десетия етаж всички глави са далеч под него. При спускане е обратното."}},{"id":"studio.board.persp.t07","legacyId":"t17hwb9s","hall":"studio","domain":"board","topic":"board.persp","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Принудителна перспектива (Forced perspective)","bg":"Принудителна перспектива","en":"Forced perspective","alts":["forced perspective","принудителна"],"def":"Предметите на преден план се уголемяват (или далечните се смаляват), за да изглежда пространството по-дълбоко.","ex":"В storyboard уголемяваш юмрука или ръката на преден план, за да „излезе“ от панела. На снимачната площадка същият принцип прави хобитите във „Властелинът на пръстените“ дребни до Гандалф."}},{"id":"studio.board.persp.t08","legacyId":"t1ez9cvt","hall":"studio","domain":"board","topic":"board.persp","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Въздушна перспектива (Atmospheric perspective)","bg":"Въздушна перспектива","en":"Atmospheric perspective","alts":["atmospheric perspective","aerial perspective","въздушна"],"def":"Далечните предмети са по-светли, по-сини и по-размити; така дълбочината се чете и без линии.","ex":"Глебас предлага всеки план да има свой обхват от тонове: предният — от почти черно до бяло, средният — по-тесен, а далечният — само няколко светлосиви тона. Така има дълбочина дори в черно-бял панел."}},{"id":"studio.board.check.t01","legacyId":"t3ui45t","hall":"studio","domain":"board","topic":"board.check","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Смисъл на кадъра (Story point)","bg":"Смисъл на кадъра","en":"Story point","alts":["story point","сюжетна точка"],"def":"Моментът от историята, който даден панел трябва да предаде на зрителя; изяснява се преди избора на план и ракурс.","ex":"Глебас разказва, че при „Покахонтас“ сбогуването излизало плоско: героинята трябвало да се чувства сама, а в кадрите постоянно била заобиколена от хора. Образите казвали друго, не това, което сцената искала."}},{"id":"studio.board.check.t02","legacyId":"tsc6m4j","hall":"studio","domain":"board","topic":"board.check","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Профилен кадър (Profile shot)","bg":"Профилен кадър","en":"Profile shot","alts":["профил"],"def":"Героят е показан изцяло отстрани, успоредно на рамката; най-лесният за рисуване и най-плосък избор, затова се ползва само с причина.","ex":"Профилът е оправдан, когато ти трябва ясен силует или сблъсък лице в лице, като в дуел. Иначе завърти героя поне в три четвърти към камерата — така се виждат обемът и двете очи."}},{"id":"studio.board.check.t03","legacyId":"t1v5pahv","hall":"studio","domain":"board","topic":"board.check","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Визуална тежест (Visual weight)","bg":"Визуална тежест","en":"Visual weight","alts":["визуална тежест","разнообразие на размерите"],"def":"По-голямото, по-контрастно или по-близко привлича повече внимание; еднакво големите обекти се „бият“.","ex":"Тежест дават не само размерът и контрастът: лицата, очите и надписите привличат погледа дори когато са малки. Глебас сравнява рамката с гравитация, която тегли всичко в кадъра надолу."}},{"id":"studio.board.check.t04","legacyId":"tx6wqkd","hall":"studio","domain":"board","topic":"board.check","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Тангента (Tangent)","bg":"Тангента","en":"Tangent","alts":["tangent","тангенти","допиране на контури"],"def":"Неволно докосване на два контура от различни планове — ръб на маса точно по брадичката, стълб „от главата“; сплесква пространството и дърпа окото.","ex":"Тангента има и с ръба на кадъра: глава, която точно докосва горния ръб, или рамо, легнало точно по страничния. Реши ясно — или отрежи по-смело, или остави въздух."}},{"id":"studio.board.check.t05","legacyId":"t1ron8lj","hall":"studio","domain":"board","topic":"board.check","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Разнообразие на кадрите (Shot variety)","bg":"Разнообразие на кадрите","en":"Shot variety","alts":["shot variety","разнообразие"],"def":"Всеки нов кадър се различава от предишния по план, ракурс или място на героя в рамката, за да не се повтаря една и съща композиция подред.","ex":"Проверка: подреди панелите на сцената един до друг и ги погледни отдалеч, като миниатюри. Ако силуетите им си приличат, кадрите се повтарят и сцената ще изглежда монотонна."}},{"id":"studio.board.check.t06","legacyId":"tvhi1o6","hall":"studio","domain":"board","topic":"board.check","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Движение в дълбочина (Movement in depth)","bg":"Движение в дълбочина","en":"Movement in depth","alts":["movement in depth","към камерата"],"def":"Героите приближават зрителя или се отдалечават навътре в кадъра, а не минават встрани в профил; растящият или смаляващият се размер прави пространството обемно.","ex":"Още в „Пристигането на влака“ на братя Люмиер влакът идва по диагонал към камерата и расте в кадъра — затова кадърът е толкова обемен, макар камерата да не помръдва."}},{"id":"studio.board.action.t01","legacyId":"t9n7il5","hall":"studio","domain":"board","topic":"board.action","level":12,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Цел на героя (Objective)","bg":"Цел на героя","en":"Objective","alts":["цел","objective"],"def":"Какво иска персонажът — в цялата сцена и във всеки отделен момент; без това желание няма залог.","ex":"В action сцената целта трябва да е малка и видима: да грабне ключа, да стигне вратата, преди да се затвори. Зрителят трябва да може да я посочи в кадъра."}},{"id":"studio.board.action.t02","legacyId":"tocp8hl","hall":"studio","domain":"board","topic":"board.action","level":12,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Препятствие (Obstacle)","bg":"Препятствие","en":"Obstacle","alts":["obstacle"],"def":"Това, което пречи на персонажа да постигне желаното; когато расте, напрежението в action сцената се вдига.","ex":"Подреди препятствията по сила: първото героят преодолява лесно, следващото — трудно, а последното изглежда непреодолимо. Най-добрите идват от самото място или от слабостта на героя."}},{"id":"studio.board.action.t03","legacyId":"t14l8gxi","hall":"studio","domain":"board","topic":"board.action","level":12,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Специфичност (Specificity)","bg":"Специфичност","en":"Specificity","alts":["specificity"],"def":"Движение, характерно само за този герой и тази среда; прави action сцената запомняща се.","ex":"Специфичност идва и от героя: дребният и пъргав бяга между краката на противника, а силният минава през стената. Питай се: какво може да направи само този герой, само на това място?"}},{"id":"studio.board.action.t04","legacyId":"t8b3zm","hall":"studio","domain":"board","topic":"board.action","level":12,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Смяна в сцената (Change)","bg":"Смяна в сцената","en":"Change","alts":["смяна"],"def":"Промяна на средата, залога, динамиката (кой води) или тактиката, така че гонитбата или боят да не станат монотонни.","ex":"Пример: гонитба започва по улицата, минава през пазар и свършва на покрив — всяко ново място носи нови препятствия и гагове. Смяната може да е и в ролите: преследваният започва да гони."}},{"id":"studio.board.action.t05","legacyId":"t1f4s3zx","hall":"studio","domain":"board","topic":"board.action","level":12,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Задържане във въздуха (Hang time)","bg":"Задържане във въздуха","en":"Hang time","alts":["hang time","висене"],"def":"Персонажът „виси“ над земята — на върха на скока или след ръба на пропастта — по-дълго от нормалното, а после пада рязко.","ex":"Не го бъркай със задържането (Hold) от timing: там героят стои в поза, а тук виси, преди да падне. Класиката е Койотът от „Шантави рисунки“, който пада едва когато погледне надолу."}},{"id":"studio.story.docs.t01","legacyId":"t3klrrf","hall":"studio","domain":"story","topic":"story.docs","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Анотация (Blurb)","bg":"Анотация","en":"Blurb","alts":["анотация"],"def":"Кратко представяне на филма в 1–3 изречения: за какво е и за кого, без да издава края.","ex":"Анотацията четеш на гърба на книга, в програмата на киното или в каталога на фестивал. Целта ѝ е да те накара да гледаш, затова често завършва с въпрос или загадка."}},{"id":"studio.story.docs.t02","legacyId":"t38t4an","hall":"studio","domain":"story","topic":"story.docs","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Синопсис (Synopsis)","bg":"Синопсис","en":"Synopsis","alts":["synopsis"],"def":"Сбит преразказ на целия сюжет, включително края (до една страница).","ex":"Синопсисът се изпраща на продуценти, фондове и фестивали заедно със сценария. За разлика от анотацията той не пази тайни — продуцентът трябва да прецени и финала."}},{"id":"studio.story.docs.t03","legacyId":"tlhxe4j","hall":"studio","domain":"story","topic":"story.docs","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Logline","en":"Logline","alts":["логлайн","log line"],"def":"Едно изречение: герой, цел, препятствие и залог.","ex":"Logline за „Замръзналото кралство“ може да звучи така: „Безстрашна принцеса тръгва в снежната буря, за да върне сестра си, чиято магия е сковала кралството във вечна зима.“"}},{"id":"studio.story.docs.t04","legacyId":"tlk477x","hall":"studio","domain":"story","topic":"story.docs","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy","fixes":["S66","S67","S68"]},"kind":"term","term":{"label":"Разширен синопсис (Treatment)","bg":"Разширен синопсис","en":"Treatment","alts":["тритмънт","разширен синопсис","treatment"],"def":"Разказ в сегашно време сцена по сцена, преди да се пише диалогът.","ex":"Treatment може да е от няколко до десетки страници и съдържа само най-важните реплики. По него продуцентът преценява историята, преди да поръча целия сценарий."}},{"id":"studio.story.docs.t05","legacyId":"t171e9it","hall":"studio","domain":"story","topic":"story.docs","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Анимационен сценарий (Animation script)","bg":"Анимационен сценарий","en":"Animation script","alts":["анимационен сценарий"],"def":"Текстът, по който се прави рисуван или 3D филм: действието и визуалните гагове са описани подробно, защото всеки кадър ще бъде създаден от нулата.","ex":"В класическите късометражни филми на Disney и Warner Bros. историята често се разработва направо в рисунки на storyboard, без отделен писан сценарий. Днес текстът и рисунките се допълват."}},{"id":"studio.story.docs.t06","legacyId":"t164hhl6","hall":"studio","domain":"story","topic":"story.docs","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Работна книга (Shooting script)","bg":"Работна книга","en":"Shooting script","alts":["режисьорски сценарий","shooting script","режисьорска книга"],"def":"Сценарият, преведен на езика на камерата: всяка сцена е разбита на номерирани кадри с план, ъгъл, движение и звук.","ex":"Работната книга е лична за режисьора: в нея той бележи драматичните блокове, точките на опора и идеи за звука. Затова двама режисьори по един и същ сценарий ще направят различни работни книги."}},{"id":"studio.story.structure.t01","legacyId":"t2o49o6","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Три акта (Three-act structure)","bg":"Три акта","en":"Three-act structure","alts":["триактна структура","три акта"],"def":"Строеж на историята: експозиция и подбудително събитие, после растящи препятствия и обрати, накрая кулминация и ново равновесие.","ex":"Идеята е стара — още Аристотел пише, че цялото има начало, среда и край. Сценаристът Сид Фийлд я популяризира в киното с книгата си Screenplay (1979)."}},{"id":"studio.story.structure.t02","legacyId":"tejh7z8","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Поврат (Turning point)","bg":"Поврат","en":"Turning point","alts":["turning point","повратна точка","обрат"],"def":"Събитие, което сменя посоката на историята и тласка героя в нов етап.","ex":"В класическата схема има две големи повратни точки: първата вкарва героя във втория акт, втората го тласка към кулминацията. Поврат в рамките на една сцена наричаме точка на опора."}},{"id":"studio.story.structure.t03","legacyId":"t1czi3na","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Кулминация (Climax)","bg":"Кулминация","en":"Climax","alts":["climax"],"def":"Най-високата точка на напрежението, в която конфликтът се решава.","ex":"Съвет: измисли кулминацията рано и после провери дали всяка сцена води към нея. Най-силна е, когато героят решава конфликта с това, което е научил по пътя."}},{"id":"studio.story.structure.t04","legacyId":"t1shdp3h","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Гръбнак на ролята (Spine)","bg":"Гръбнак на ролята","en":"Spine","alts":["гръбнак"],"def":"Основното действие на героя или филма, формулирано с глагол: „да спечели…“ (близко до свръхзадачата при Станиславски).","ex":"Гръбнакът на Марлин в „Търсенето на Немо“ може да се формулира като „да опази сина си“. Всяко негово действие, дори грешното, следва от тази цел."}},{"id":"studio.story.structure.t05","legacyId":"tnr8i9l","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Точка на опора (Fulcrum)","bg":"Точка на опора","en":"Fulcrum","alts":["fulcrum","обрат в сцената"],"def":"Моментът в сцената, в който динамиката се обръща и равновесието между героите се сменя.","ex":"Nicholas Proferes използва думата fulcrum — на английски опорната точка на лост. Както лостът се завърта около опората, така и сцената се „завърта“ около този момент."}},{"id":"studio.story.structure.t06","legacyId":"twziwa1","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Драматичен блок (Dramatic block)","bg":"Драматичен блок","en":"Dramatic block","alts":["dramatic block"],"def":"Група моменти в сцената, обединени от една задача — като абзац в текст.","ex":"Драматичният блок е по-малък от сцената, но по-голям от отделния актьорски такт (Acting beat). Nicholas Proferes използва блоковете, за да реши къде да смени позицията на камерата."}},{"id":"studio.story.structure.t07","legacyId":"t18ntlkm","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Подбудително събитие (Inciting incident)","bg":"Подбудително събитие","en":"Inciting incident","alts":["inciting incident","подбудително","завръзка"],"def":"Моментът, който изважда героя от обичайния му живот и задвижва историята.","ex":"В „Красавицата и звярът“ бащата на Бел се изгубва в гората и попада в плен в замъка на Звяра. Оттук Бел вече не може да остане в спокойното си градче."}},{"id":"studio.story.structure.t08","legacyId":"tg02nsu","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Средна точка (Midpoint)","bg":"Средна точка","en":"Midpoint","alts":["midpoint","средата"],"def":"Голям обрат около половината на историята, след който героят не може да се върне към старото.","ex":"Средната точка често е фалшива победа или фалшиво поражение: героят мисли, че е спечелил или изгубил всичко, а истинската битка тепърва предстои."}},{"id":"studio.story.structure.t09","legacyId":"t16zoe6i","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Развръзка (Resolution)","bg":"Развръзка","en":"Resolution","alts":["resolution","финал"],"def":"Краят след кулминацията: новото равновесие и какво се е променило в героя.","ex":"Развръзката често повтаря кадър или място от началото, за да видим разликата: същата стая, същият път, но героят вече е друг."}},{"id":"studio.story.structure.t10","legacyId":"t1al7pm8","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Залог (Stakes)","bg":"Залог","en":"Stakes","alts":["stakes","залог"],"def":"Какво ще загуби героят, ако не успее; колкото по-голяма е загубата, толкова по-силно е напрежението.","ex":"Залогът може да е външен (животът на града) и вътрешен (самоуважението на героя). Най-силните истории свързват двата: спасявайки другите, героят спасява и себе си."}},{"id":"studio.story.irony.t01","legacyId":"tyiun28","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Драматична ирония (Dramatic irony)","bg":"Драматична ирония","en":"Dramatic irony","alts":["dramatic irony"],"def":"Зрителят знае нещо, което героят не знае; поражда напрежение или комизъм.","ex":"В „Рататуй“ зрителят знае, че под шапката на Лингуини се крие плъхът Реми и всъщност готви той. Всяка сцена, в която някой едва не го разкрие, е и смешна, и напрегната."}},{"id":"studio.story.irony.t02","legacyId":"t1jdz3ni","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Ситуационна ирония (Situational irony)","bg":"Ситуационна ирония","en":"Situational irony","alts":["situational irony"],"def":"Случва се обратното на очакваното — не просто нещо различно.","ex":"Пример: фирма за алармени системи е ограбена, защото собствената ѝ аларма не е включена. Обир в обикновен магазин би бил лош късмет — там няма обърнато очакване."}},{"id":"studio.story.irony.t03","legacyId":"tmeztzd","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Вербална ирония (Verbal irony)","bg":"Вербална ирония","en":"Verbal irony","alts":["verbal irony","сарказъм"],"def":"Героят казва противоположното на това, което мисли, и иска да бъде разбран така.","ex":"Вербалната ирония може да е и мека — „Чудесно време за разходка“, казано под проливен дъжд, никого не напада. Когато репликата хапе конкретен човек, говорим за сарказъм."}},{"id":"studio.story.irony.t04","legacyId":"t3ipv1a","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Напрежение (Suspense)","bg":"Напрежение","en":"Suspense","alts":["suspense","суспенс"],"def":"Зрителят знае за опасността и чака: бомбата под масата държи минути, изненадата — секунди (Хичкок).","ex":"Хичкок разказва примера с бомбата в разговорите си с Франсоа Трюфо, издадени като книга през 1966 г. Неслучайно го наричат „майстора на напрежението“."}},{"id":"studio.story.irony.t05","legacyId":"tpr0x8h","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Изненада (Surprise)","bg":"Изненада","en":"Surprise","alts":[],"def":"Зрителят не знае за опасността и я открива заедно с героите — кратък шок, който трае секунди.","ex":"Изненадата е силна, но еднократна — при второ гледане вече я знаеш. Напрежението оцелява: дори да знаеш края, пак се тревожиш за героя."}},{"id":"studio.story.irony.t06","legacyId":"teu3ob8","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Сарказъм (Sarcasm)","bg":"Сарказъм","en":"Sarcasm","alts":["sarcasm","сарказъм"],"def":"Хаплива реплика, която казва обратното на мисленото, за да осмее или засегне някого.","ex":"„Браво, гений!“ към човек, който току-що е разлял кафето, е сарказъм. Същите думи като искрена похвала не са — разпознаваш го по мишената и тона."}},{"id":"studio.story.irony.t07","legacyId":"t121w35","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Подценяване (Understatement)","bg":"Подценяване","en":"Understatement","alts":["understatement","литота","омаловажаване"],"def":"Героят казва много по-малко от истината — „Само драскотина е!“ за отсечена ръка; иронията е в разминаването.","ex":"Подценяването е любим похват на британския хумор. Обратното му е преувеличението: „Умирам от глад“, казано след два часа без храна."}},{"id":"studio.story.irony.t08","legacyId":"t1o9cl28","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Сократова ирония (Socratic irony)","bg":"Сократова ирония","en":"Socratic irony","alts":["socratic irony","сократова"],"def":"Героят се прави на незнаещ и с въпроси кара другия сам да разкрие грешката си.","ex":"Името идва от Сократ, който в диалозите на Платон твърди, че нищо не знае, и с въпроси води събеседника до противоречие. Така работи и детективът Коломбо — прави се на разсеян, докато хване виновния."}},{"id":"studio.story.irony.t09","legacyId":"t19x4sgf","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Космическа ирония (Cosmic irony)","bg":"Космическа ирония","en":"Cosmic irony","alts":["cosmic irony","космическа","ирония на съдбата"],"def":"Съдбата сякаш се подиграва на героя — точно това, от което бяга или което иска, се обръща срещу него.","ex":"Пример от митологията е цар Мидас: желанието всичко, което докосне, да става на злато, се обръща срещу него — дори храната му се превръща в злато."}},{"id":"studio.story.irony.t10","legacyId":"t1ed3kwu","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Поетична справедливост (Poetic justice)","bg":"Поетична справедливост","en":"Poetic justice","alts":["poetic justice"],"def":"Злото е наказано, а доброто — възнаградено, често по ироничен начин: злодеят пада в собствения си капан.","ex":"В „Аладин“ Джафар пожелава да стане най-могъщият дух — и веднага се оказва затворен в лампа, защото всеки дух е пленник на своята лампа. Алчността му сама го наказва."}},{"id":"studio.story.irony.t11","legacyId":"t4s61oo","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Трагична ирония (Tragic irony)","bg":"Трагична ирония","en":"Tragic irony","alts":["tragic irony","трагична"],"def":"Зрителят знае истината, която би спасила героя, но героят не я знае и с всяка стъпка върви към собствената си гибел.","ex":"В „Цар Едип“ на Софокъл публиката познава мита: Едип усърдно търси убиеца на стария цар, без да подозира, че това е самият той."}},{"id":"studio.story.irony.t12","legacyId":"t1q6j5ns","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Структурна ирония (Structural irony)","bg":"Структурна ирония","en":"Structural irony","alts":["structural irony","структурна","unreliable narrator"],"def":"Разминаването с истината е вградено в целия разказ — например ненадежден разказвач, чиято версия накрая се оказва невярна.","ex":"В „Рашомон“ (1950) на Акира Куросава едно престъпление е разказано от четирима свидетели в четири различни версии. Зрителят така и не разбира със сигурност коя е истината."}},{"id":"studio.story.figures.t01","legacyId":"t7z3snv","hall":"studio","domain":"story","topic":"story.figures","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Визуална метафора (Visual metaphor)","bg":"Визуална метафора","en":"Visual metaphor","alts":["visual metaphor","метафора"],"def":"Образ, който означава нещо повече от себе си — птица в клетка за затворения живот на героинята.","ex":"Метафората е най-силна, когато е част от света на историята: птица, която героинята наистина гледа всеки ден, работи по-добре от образ, вмъкнат отвън само заради смисъла."}},{"id":"studio.story.figures.t02","legacyId":"tckte8c","hall":"studio","domain":"story","topic":"story.figures","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Символ (Symbol)","bg":"Символ","en":"Symbol","alts":["symbol","символ"],"def":"Предмет или образ, който се връща във филма и натрупва смисъл — ключ, часовник, червен балон.","ex":"В „Тайната на Коко“ скъсаната снимка с липсващото лице се връща отново и отново — първо е загадка, а накрая носи цялата тайна на семейството."}},{"id":"studio.story.figures.t03","legacyId":"t5rfh4f","hall":"studio","domain":"story","topic":"story.figures","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Лайтмотив (Leitmotif)","bg":"Лайтмотив","en":"Leitmotif","alts":["leitmotif","лайтмотив","лейтмотив"],"def":"Мелодия, образ или реплика, свързани с герой или идея и повтаряни през филма — двете ноти на акулата в „Челюсти“.","ex":"Похватът идва от операта, най-вече от Рихард Вагнер. Джон Уилямс го прилага в „Междузвездни войни“: Дарт Вейдър има свой марш, свързан с него и с Империята."}},{"id":"studio.story.figures.t04","legacyId":"tusrgpz","hall":"studio","domain":"story","topic":"story.figures","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Синекдоха (Synecdoche)","bg":"Синекдоха","en":"Synecdoche","alts":["synecdoche","синекдоха"],"def":"Частта показва цялото — само ботушите на маршируващите войници вместо цялата армия.","ex":"В езика синекдоха е „покрив над главата“ вместо „дом“. В анимацията тя пести и труд: вместо да анимираш цяла тълпа, показваш крака, ръце или сенки."}},{"id":"studio.story.figures.t05","legacyId":"th6cwwa","hall":"studio","domain":"story","topic":"story.figures","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Предзнаменование (Foreshadowing)","bg":"Предзнаменование","en":"Foreshadowing","alts":["foreshadowing","предзнаменование","загатване"],"def":"Детайл в началото подсказва бъдещо събитие; зрителят го разпознава по-късно.","ex":"За разлика от засаждането и изплащането, предзнаменованието не е предмет, който ще бъде използван, а подсказка за бъдещето — буря в началото, счупено огледало, мрачна реплика."}},{"id":"studio.story.figures.t06","legacyId":"txbqlpb","hall":"studio","domain":"story","topic":"story.figures","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Засаждане и изплащане (Setup and payoff)","bg":"Засаждане и изплащане","en":"Setup and payoff","alts":["setup and payoff","setup payoff","чеховата пушка","chekhov’s gun"],"def":"Детайл, показан рано и привидно маловажен, по-късно решава или обръща нещо в историята — пушката на стената, която трябва да гръмне.","ex":"Изплащането трябва да промени нещо: детайлът решава проблем, обръща ситуацията или разкрива характер. Ако просто се появява отново, това е повторение, а не изплащане."}},{"id":"studio.story.staging.t01","legacyId":"t1fnexgr","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Мизансцен (Mise-en-scène)","bg":"Мизансцен","en":"Mise-en-scène","alts":["mise-en-scène","мизансцена","blocking","стейджинг"],"def":"Всичко, подредено пред камерата: декор, реквизит, костюми, грим, светлина, както и местата и движенията на героите.","ex":"Терминът идва от театъра: на френски mise-en-scène буквално означава „поставяне на сцената“. В киното режисьорът го изгражда заедно с художника-постановчик и оператора."}},{"id":"studio.story.staging.t02","legacyId":"t1vhnmpv","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Режисьорска концепция (Director’s vision)","bg":"Режисьорска концепция","en":"Director’s vision","alts":["концепция"],"def":"Общото решение как ще изглежда и звучи филмът — стил, темп, цвят, камера, подчинени на една идея.","ex":"Добра концепция се събира в едно изречение и отговаря на въпроса „Защо точно така?“. Тя помага на целия екип — художник, оператор, композитор — да правят един и същ филм."}},{"id":"studio.story.staging.t03","legacyId":"t11399f8","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Типаж (Character design)","bg":"Типаж","en":"Character design","alts":["character design","дизайн на персонаж"],"def":"Проектът на героя: форма, пропорции, силует, поведение и изражения.","ex":"Силният типаж се разпознава само по силуета. Преди анимацията се рисува лист с героя от всички страни, с позите и изразите му (model sheet), за да изглежда еднакво у всички аниматори."}},{"id":"studio.story.staging.t04","legacyId":"t1jfile","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Местодействие (Setting)","bg":"Местодействие","en":"Setting","alts":["среда","дизайн на средата"],"def":"Светът на историята (епоха, пейзаж, архитектура, интериор), проектиран така, че да подкрепя героите и настроението.","ex":"Във „Отнесена от духовете“ банята на Юбаба е цял свят с етажи, асансьори и работници, а самата тя живее най-горе. Местодействието показва йерархията, преди някой да я обясни."}},{"id":"studio.story.staging.t05","legacyId":"tgl2o8q","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Разстановка на актьорите (Blocking)","bg":"Разстановка на актьорите","en":"Blocking","alts":["blocking","разстановка","блокинг"],"def":"Точно планираните места и движения на хората в кадъра спрямо камерата — кой къде стои, кога и накъде се движи.","ex":"Режисьорите често рисуват разстановката отгоре като схема: кръгчета за актьорите, стрелки за движението и знак за камерата. Така операторът и актьорите виждат плана още преди репетицията."}},{"id":"studio.story.staging.t06","legacyId":"to5bz3l","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Разполагане в дълбочина (Staging in depth)","bg":"Разполагане в дълбочина","en":"Staging in depth","alts":["staging in depth","дълбочинна мизансцена"],"def":"Героите и действията са на различни разстояния от камерата; преден, среден и заден план работят едновременно.","ex":"Разполагането в дълбочина обикновено иска дълбок фокус (Deep focus), за да са ясни всички планове. При плитка рязкост режисьорът премества вниманието с прехвърляне на фокуса (Rack focus)."}},{"id":"studio.story.staging.t07","legacyId":"t15t9xxd","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Дълъг кадър (Long take)","bg":"Дълъг кадър","en":"Long take","alts":["long take","oner","one-shot","план-епизод"],"def":"Цяла сцена или голяма част от нея, заснета без нито едно срязване; актьорите и камерата сами сменят плановете.","ex":"Дългият кадър съвпада с реалното време (Real time): на екрана минава толкова време, колкото и в живота. Затова го използват, когато искат зрителят да не може да „избяга“ от сцената."}},{"id":"studio.anim.principles.t01","legacyId":"t941ipz","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Свиване и разтягане (Squash and Stretch)","bg":"Свиване и разтягане","en":"Squash and Stretch","alts":["squash and stretch","скуош"],"def":"Формата се деформира при удар и скорост, но обемът се запазва; дава тегло и гъвкавост.","ex":"Класическото упражнение е полупълен чувал с брашно: той се сплесква, разтяга и огъва, но количеството брашно в него не се мени — и дори без лице може да изрази умора или радост."}},{"id":"studio.anim.principles.t02","legacyId":"tpu0han","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Подготвително движение (Anticipation)","bg":"Подготвително движение","en":"Anticipation","alts":["подготовка","anticipation"],"def":"Кратко отдръпване в обратна посока преди главното действие, което подсказва на зрителя какво предстои — клякане преди скок.","ex":"Колкото по-силно е действието, толкова по-голяма е подготовката: замахът преди удар с чук е широк, а преди леко почукване — едва забележим. Без подготовка зрителят може да пропусне бързото действие."}},{"id":"studio.anim.principles.t03","legacyId":"t7b9k1","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Сценичност (Staging)","bg":"Сценичност","en":"Staging","alts":["staging"],"def":"Действието е показано така, че идеята да се чете ясно: силует, позиция, камера.","ex":"Проверка със силует: запълни героя с черно. Ако позата пак се чете, сценичността е добра; ръка пред тялото изчезва в силуета, а ръка встрани се вижда веднага."}},{"id":"studio.anim.principles.t04","legacyId":"t1mm9ku2","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Последователно и от поза до поза (Straight Ahead Action and Pose to Pose)","bg":"Последователно и от поза до поза","en":"Straight Ahead Action and Pose to Pose","alts":["straight ahead","pose to pose"],"def":"Два подхода към анимирането: рисунка след рисунка от началото до края или първо главните моменти на движението и накрая рисунките между тях.","ex":"Двата подхода често се смесват: тялото на героя се планира от поза до поза, а развяната коса, огънят или пръските се добавят последователно отгоре."}},{"id":"studio.anim.principles.t05","legacyId":"t1ci34ks","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Продължаващо и застъпващо се движение (Follow Through and Overlapping Action)","bg":"Продължаващо и застъпващо се движение","en":"Follow Through and Overlapping Action","alts":["follow through","overlapping action","продължаващо движение"],"def":"Коса, опашка и дрехи изостават от тялото и спират след него, а отделните части тръгват и спират в различен момент.","ex":"Виж как спира тичащо куче: тялото застава, а ушите, опашката и козината продължават напред и се връщат с малко закъснение. Колкото по-лек и мек е материалът, толкова по-дълго продължава."}},{"id":"studio.anim.principles.t06","legacyId":"tmntvc","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Ускорение и забавяне (Slow In and Slow Out)","bg":"Ускорение и забавяне","en":"Slow In and Slow Out","alts":["slow in slow out","ease in","ease out"],"def":"Повече кадри в началото и края на движението, по-малко в средата.","ex":"В 3D програмите кривите по подразбиране слагат ускорение и забавяне на всеки ключ и движението започва да „плува“. При удар или сблъсък забавяне преди контакта няма — предметът спира рязко."}},{"id":"studio.anim.principles.t07","legacyId":"t1wlb5sg","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Дъги (Arcs)","bg":"Дъги","en":"Arcs","alts":["arcs","дъговидна траектория"],"def":"Крайниците се въртят около ставите, затова естествените движения следват извити, а не прави траектории.","ex":"Проверка: с onion skin проследи една точка — върха на носа или китката — през всички кадри. Ако пътят прави зигзаг или ъгъл, някоя междинна фаза е излязла от дъгата."}},{"id":"studio.anim.principles.t08","legacyId":"t17dzhq4","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Второстепенно действие (Secondary Action)","bg":"Второстепенно действие","en":"Secondary Action","alts":["secondary action"],"def":"Допълнително движение, което подкрепя основното — подсвирква, докато върви.","ex":"Не го бъркай с продължаващото движение: второстепенното действие е отделно намерение на героя (рови в джоба, бърше очи), а развяната коса е само физика. Анимира се след главното, като отделен пласт."}},{"id":"studio.anim.principles.t09","legacyId":"t101rcgl","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Timing","en":"Timing","alts":["тайминг"],"def":"Броят кадри за едно действие; определя тегло, скорост и характер.","ex":"В „The Illusion of Life“ две рисунки на глава се анимират с различен брой междинни фази: без междинна героят сякаш е ударен с огромна сила, с една — с тиган, с четири — дава рязка заповед."}},{"id":"studio.anim.principles.t10","legacyId":"tsjo2yb","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Преувеличение (Exaggeration)","bg":"Преувеличение","en":"Exaggeration","alts":["exaggeration"],"def":"Засилване на позата, израза или движението, за да се чете по-ясно и по-силно.","ex":"Начинаещите почти винаги преувеличават твърде малко: поза, която на неподвижна рисунка изглежда прекалена, в движение често изглежда нормално. Преувеличавай идеята, а не всеки детайл."}},{"id":"studio.anim.principles.t11","legacyId":"t7yhzxx","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Обемна рисунка (Solid Drawing)","bg":"Обемна рисунка","en":"Solid Drawing","alts":["solid drawing","солидна рисунка"],"def":"Формата се изгражда като тяло в пространството, с тегло, дълбочина и перспектива.","ex":"Честа грешка са „близнаците“ (twins): двете ръце или крака правят едно и също огледално. Лекото завъртане на тялото и различните пози на крайниците веднага дават обем и живот."}},{"id":"studio.anim.principles.t12","legacyId":"t1oua46c","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Привлекателност (Appeal)","bg":"Привлекателност","en":"Appeal","alts":["appeal","чар"],"def":"Героят е интересен за гледане — ясен дизайн и характер, дори когато е злодей.","ex":"Скар от „Цар Лъвът“ е опасен, но не можеш да откъснеш поглед от него. Привлекателността идва от ясната форма, контраста между големи и малки части и изразителния силует, а не от сладкия вид."}},{"id":"studio.anim.phases.t01","legacyId":"t12j0bou","hall":"studio","domain":"anim","topic":"anim.phases","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy","fixes":["P01"]},"kind":"term","term":{"label":"Ключова фаза (Key pose)","bg":"Ключова фаза","en":"Key pose","alts":["ключ","key","ключова поза","екстрем"],"def":"Рисунката на най-важната поза, в която движението сменя посоката или стига крайност.","ex":"В големите студия ключовете рисува аниматорът, а междинните фази — по-младши художници. В японското аниме етапите имат свои имена: genga за ключовата анимация и douga за междинната."}},{"id":"studio.anim.phases.t02","legacyId":"t15is8xh","hall":"studio","domain":"anim","topic":"anim.phases","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Breakdown","en":"Breakdown","alts":["брейкдаун","прехвърляща поза"],"def":"Позата между два ключа, която определя пътя и характера на движението.","ex":"В цикъла на ходене breakdown е позата на преминаване (passing position): задният крак минава покрай опорния. От нея зависи дали походката подскача, влачи се или е наперена."}},{"id":"studio.anim.phases.t03","legacyId":"t1tb73he","hall":"studio","domain":"anim","topic":"anim.phases","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Междинна фаза (Inbetween)","bg":"Междинна фаза","en":"Inbetween","alts":["inbetween","междинна","фаза"],"def":"Рисунка, която запълва пътя от ключ до ключ по вече зададената траектория и прави движението плавно.","ex":"Честа грешка: междинната фаза се слага точно по средата, по права линия между ключовете, и движението „чупи“ дъгата. Добрата фаза следва дъгата и spacing от timing chart."}},{"id":"studio.anim.phases.t04","legacyId":"t15ky6wg","hall":"studio","domain":"anim","topic":"anim.phases","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy","fixes":["S03","S04","S05"]},"kind":"term","term":{"label":"Прозрачни слоеве (Onion skin)","bg":"Прозрачни слоеве","en":"Onion skin","alts":["onion skinning","онион скин","onion skin","прозрачни слоеве","прозрачен слой"],"def":"Полупрозрачен показ на съседните кадри, докато рисуваш.","ex":"Името идва от тънката полупрозрачна хартия onionskin: аниматорите рисували върху нея над светеща маса и виждали предишните рисунки през листа. Програмите днес правят същото с бледи слоеве."}},{"id":"studio.anim.phases.t05","legacyId":"tq17cja","hall":"studio","domain":"anim","topic":"anim.phases","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Цикъл (Cycle)","bg":"Цикъл","en":"Cycle","alts":["cycle","loop"],"def":"Поредица, която се повтаря безкрайно — ходене, бягане, пламък.","ex":"Честа грешка: последният кадър повтаря първия и при всяко завъртане движението „спъва“ за миг. Последната рисунка трябва да води към първата, а не да е същата."}},{"id":"studio.anim.phases.t06","legacyId":"tfxl0ar","hall":"studio","domain":"anim","topic":"anim.phases","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Груба анимация (Rough animation)","bg":"Груба анимация","en":"Rough animation","alts":["rough","rough animation","груба","скицова анимация"],"def":"Първата версия на движението: бързи, свободни рисунки за позите и timing-а, без чисти линии.","ex":"Целта е да намериш движението, а не красивата линия: рисуваш бързо, с много търсещи линии. На хартия мнозина скицират със син молив, който лесно се маха при сканиране; в програмата грубото стои на отделен слой."}},{"id":"studio.anim.phases.t07","legacyId":"t4jr0z7","hall":"studio","domain":"anim","topic":"anim.phases","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Pencil test","en":"Pencil test","alts":["pencil test","line test","тест с молив","пенсил тест"],"def":"Грубите рисунки се заснемат и пускат като видео, за да се провери движението, преди да се изчистят.","ex":"Днес pencil test се прави и с телефон: закрепваш го неподвижно над листа, снимаш всяка рисунка на едно и също място с приложение за stop motion и пускаш на 12 кадъра в секунда, ако си рисувал на двойки."}},{"id":"studio.anim.phases.t08","legacyId":"tpvifs3","hall":"studio","domain":"anim","topic":"anim.phases","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy","fixes":["P02"]},"kind":"term","term":{"label":"Изчистване (Clean-up)","bg":"Изчистване","en":"Clean-up","alts":["clean-up","cleanup","clean up","чистовик"],"def":"Прерисуване на грубите фази с прецизна, равномерна линия, така че героят да е точно по модела си във всеки кадър.","ex":"В класическите студия изчистването е работа на асистент-аниматорите: те не сменят движението, а го следват. Добрият резултат личи по това, че линията не трепти и не сменя дебелината си от кадър на кадър."}},{"id":"studio.anim.timing.t01","legacyId":"tjipllt","hall":"studio","domain":"anim","topic":"anim.timing","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Spacing","en":"Spacing","alts":["спейсинг"],"def":"Разстоянието между позициите в съседни кадри: близо — бавно, далеч — бързо.","ex":"В 3D програмите spacing се вижда в редактора на кривите (Graph Editor): стръмна крива значи големи разстояния и бързо движение, полегата — малки разстояния и бавно движение."}},{"id":"studio.anim.timing.t02","legacyId":"tuj3cq9","hall":"studio","domain":"anim","topic":"anim.timing","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy","fixes":["S09"]},"kind":"term","term":{"label":"Анимация на двойки (On twos)","bg":"Анимация на двойки","en":"On twos","alts":["on twos","на двойки"],"def":"Всяка рисунка стои два кадъра: 12 рисунки в секунда при 24 кадъра."}},{"id":"studio.anim.timing.t03","legacyId":"tbq5326","hall":"studio","domain":"anim","topic":"anim.timing","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Анимация на единици (On ones)","bg":"Анимация на единици","en":"On ones","alts":["on ones","на единици"],"def":"Нова рисунка за всеки кадър: 24 рисунки в секунда — за бързи и плавни движения.","ex":"В 3D анимацията единиците са обичайни, защото програмата изчислява всеки кадър. В рисуваната анимация са скъпи — двойно повече рисунки, затова се пазят за бързите движения и движенията на камерата."}},{"id":"studio.anim.timing.t04","legacyId":"tolli41","hall":"studio","domain":"anim","topic":"anim.timing","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Задържане (Hold)","bg":"Задържане","en":"Hold","alts":["hold","moving hold"],"def":"Героят стои в една поза няколко кадъра; в „живия“ вариант леко се движи, за да не изглежда замръзнал.","ex":"Задържането дава време на зрителя да прочете позата: кратка пауза след силно действие поставя акцент. Без задържания всичко се слива в едно непрекъснато, уморително движение."}},{"id":"studio.anim.timing.t05","legacyId":"t2gvw94","hall":"studio","domain":"anim","topic":"anim.timing","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Експозиционен лист (X-sheet)","bg":"Експозиционен лист","en":"X-sheet","alts":["x-sheet","dope sheet"],"def":"Таблица кадър по кадър с диалога по фонеми, рисунките и движенията на камерата.","ex":"Всеки ред в листа е един кадър, а колоните са за действието, диалога, слоевете рисунки и камерата. В програмите наследникът му е прозорецът Dope Sheet (в Blender и Maya) или Xsheet (в Toon Boom Harmony)."}},{"id":"studio.anim.timing.t06","legacyId":"t1o233sm","hall":"studio","domain":"anim","topic":"anim.timing","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Timing chart","en":"Timing chart","alts":["тайминг чарт","spacing chart"],"def":"Скала до ключа, която показва къде да се сложат междинните фази и дали движението ускорява или забавя.","ex":"Запис като ½, ¼, ⅛ значи: първата междинна фаза е по средата, следващата — по средата между нея и ключа и т.н. Така фазите се сгъстяват към ключа и движението забавя."}},{"id":"studio.anim.lipsync.t01","legacyId":"t146qa9q","hall":"studio","domain":"anim","topic":"anim.lipsync","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Синхрон на устните (Lip sync)","bg":"Синхрон на устните","en":"Lip sync","alts":["lipsync","липсинг"],"def":"Анимацията на говора: челюстта и устата се движат кадър по кадър точно в такт със записания диалог.","ex":"Честа грешка е устата да се отваря и затваря на всяка буква — тогава тя „трака“. Важни са гласните с ударение и затварянията при М, Б, П; бързите звуци между тях често се пропускат."}},{"id":"studio.anim.lipsync.t02","legacyId":"t1va92g8","hall":"studio","domain":"anim","topic":"anim.lipsync","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy","fixes":["P03"]},"kind":"term","term":{"label":"Форма на устата (Mouth shape)","bg":"Форма на устата","en":"Mouth shape","alts":["фонема","визема","phoneme"],"def":"Една от няколкото типови рисунки на устните и челюстта, всяка за звук или група звуци, които изглеждат еднакво: А, О, У, М/Б/П, Ф/В и др.","ex":"Широко използван е наборът от около десет форми от книгите на аниматора Престън Блеър, работил в Disney и MGM. Много студия правят свой вариант според стила на героите."}},{"id":"studio.anim.lipsync.t03","legacyId":"t148ck0t","hall":"studio","domain":"anim","topic":"anim.lipsync","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Предварителен запис (Pre-recording)","bg":"Предварителен запис","en":"Pre-recording","alts":["pre-recording","запис на гласа"],"def":"Актьорите озвучават репликите в началото на работата, а аниматорите после движат героите по готовия звук, разписан по кадри.","ex":"За „Creature Comforts“ (1989) на Ник Парк и Aardman първо са записани разговори с обитатели на жилищен квартал и старчески дом, а после по гласовете им са анимирани пластилинени животни от зоопарк."}},{"id":"studio.anim.lipsync.t04","legacyId":"t1yquiz4","hall":"studio","domain":"anim","topic":"anim.lipsync","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Актьорски такт (Acting beat)","bg":"Актьорски такт","en":"Acting beat","alts":["acting beat","такт"],"def":"Малка промяна в мисълта или намерението на героя, показана с поза или поглед.","ex":"В репликата „Ами… да, добре!“ има поне два такта: колебание и решение. Аниматорът ги отбелязва в експозиционния лист и сменя позата при всеки, вместо да движи героя равномерно."}},{"id":"studio.anim.lipsync.t05","legacyId":"td9abj4","hall":"studio","domain":"anim","topic":"anim.lipsync","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Мигане (Blink)","bg":"Мигане","en":"Blink","alts":["blink","мигане"],"def":"Кратко затваряне на очите; поставено при смяна на мисълта, показва, че героят мисли.","ex":"Клепачите обикновено се затварят по-бързо, отколкото се отварят — например 2 кадъра надолу, 1 със затворени очи и 3 нагоре. Двойно мигане често показва изненада или объркване."}},{"id":"studio.anim.lipsync.t06","legacyId":"t1k5hgcc","hall":"studio","domain":"anim","topic":"anim.lipsync","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Движение на очите (Eye darts)","bg":"Движение на очите","en":"Eye darts","alts":["eye darts","стрелкане с очите"],"def":"Бързи малки скокове на зениците встрани; показват, че героят търси, мисли или се колебае.","ex":"При обръщане на главата очите тръгват първи, а главата ги следва; често по средата има и мигане. Самите скокове на зениците са много бързи — 1–2 кадъра, без плавно ускорение."}},{"id":"studio.anim.gags.t01","legacyId":"tfwc3u4","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Гаг (Gag)","bg":"Гаг","en":"Gag","alts":["gag","гагове","визуален хумор"],"def":"Комедиен номер или трик, построен специално, за да разсмее — най-малката единица на смешното. Един от стълбовете на класическата анимация — Disney, „Шантави рисунки“ (Looney Tunes), „Том и Джери“.","ex":"В театралния жаргон „gag“ първо означава шега, вмъкната от актьора в ролята. В Disney през 30-те години има цели екипи „gag men“, които само измислят гагове за филмите."}},{"id":"studio.anim.gags.t02","legacyId":"t17w7cr0","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Визуален гаг (Sight gag)","bg":"Визуален гаг","en":"Sight gag","alts":["sight gag"],"def":"Хуморът идва изцяло от това, което виждаме: героят минава през стената и оставя в нея дупка с точната форма на тялото си.","ex":"Разпознаваш го по това, че работи и без звук: изключи тона и ако пак е смешно, гагът е визуален. Майстори на жанра са Бъстър Кийтън и Жак Тати, а в анимацията — Текс Ейвъри."}},{"id":"studio.anim.gags.t03","legacyId":"t1j4zl1l","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Гаг с предмет (Prop gag)","bg":"Гаг с предмет","en":"Prop gag","alts":["prop gag","гаг с реквизит"],"def":"Неодушевено нещо — инструмент, машина, оръжие — се използва по абсурден начин и накрая се обръща срещу героя, като продуктите на измислената фирма ACME, които Койотът поръчва.","ex":"Гаг с предмет има и без ACME: в „Модерни времена“ машината за автоматично хранене излиза от контрол и измъчва Чаплин, а изобретенията на Уолъс от „Уолъс и Громит“ редовно се объркват."}},{"id":"studio.anim.gags.t04","legacyId":"t6b4opx","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Сюрреалистичен гаг (Surreal gag)","bg":"Сюрреалистичен гаг","en":"Surreal gag","alts":["surreal gag","сюрреалистичен"],"def":"Гагът е невъзможен в реалния свят и следва логиката на съня: героят посяга извън рамката на кадъра и издърпва оттам каквото му трябва.","ex":"Класика на жанра е „Duck Amuck“ (1953) на Чък Джоунс: невидим аниматор трие и прерисува Дафи Дък, сменя фона му и дори гласа му. Накрая се оказва, че аниматорът е Бъгс Бъни."}},{"id":"studio.anim.gags.t05","legacyId":"t1bl6csz","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Бърз гаг (Blackout gag)","bg":"Бърз гаг","en":"Blackout gag","alts":["blackout gag","blackout"],"def":"Кратък самостоятелен гаг, който завършва с удар и срязване, често към черно. Не движи сюжета, а държи темпото; филмите с Койота са верига от такива гагове.","ex":"Днес бързият гаг живее в скечовете и кратките видеа в социалните мрежи: една ситуация, един удар, край. Ключът е да срежеш веднага след удара, докато смехът е най-силен."}},{"id":"studio.anim.gags.t06","legacyId":"tthtivg","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Анимационна физика (Cartoon physics)","bg":"Анимационна физика","en":"Cartoon physics","alts":["cartoon physics","ефектът на койота","ефект на койота"],"def":"Законите на природата се подчиняват на шегата. Първото правило: тяло, увиснало във въздуха, остава там, докато не осъзнае положението си (Марк О’Донъл, 1980).","ex":"Други „закони“ от същия списък: страхът отменя гравитацията, затова уплашеният герой отскача до тавана, а котките могат да бъдат сплескани и нагънати като акордеон, но винаги се възстановяват."}},{"id":"studio.anim.gags.t07","legacyId":"t1ihey8i","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Законът на трите (Rule of three)","bg":"Законът на трите","en":"Rule of three","alts":["rule of three","правилото на трите","три опита"],"def":"Гагът се строи като поредица от опити: подготовка, ескалация и обрат. Първите два изграждат модел в главата на зрителя, последният го нарушава — там е най-силният смях.","ex":"Правилото е по-старо от анимацията: в „Златокоска и трите мечета“ първата каша е твърде гореща, втората — твърде студена, а третата е тъкмо както трябва."}},{"id":"studio.anim.gags.t08","legacyId":"t1ppf39y","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Подготовка (Setup)","bg":"Подготовка","en":"Setup","alts":["setup","сетъп"],"def":"Първият опит на гага: показва проблема и „правилата на играта“. Провалът е логичен и забавен.","ex":"Не я бъркай със засаждането в драматургията (Setup and payoff): там детайлът може да чака до финала, а подготовката е първият опит на гага, пред очите ни. Затова трябва да е кратка и ясна."}},{"id":"studio.anim.gags.t09","legacyId":"t1oplzpe","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Ескалация (Escalation)","bg":"Ескалация","en":"Escalation","alts":["escalation"],"def":"Вторият опит: същата тактика с по-голям залог — повече сила, по-голям предмет, по-голям риск. Резултатът е подобен, но по-болезнен, и зрителят вече очаква същото.","ex":"Ескалацията работи само ако всеки опит е видимо по-голям от предишния: по-голям чук, по-висока стълба, повече динамит. Същият залог втори път е просто повторение."}},{"id":"studio.anim.gags.t10","legacyId":"t1lnkjnx","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Обрат (Payoff)","bg":"Обрат","en":"Payoff","alts":["payoff","twist"],"def":"Третият опит: героят опитва уверено, зрителят очаква същия провал, а моделът се нарушава по начин, който никой не е предвидил.","ex":"Обратът не е задължително провал: понякога героят неочаквано успява, но по абсурден начин. Важното е да наруши модела, изграден от първите два опита."}},{"id":"studio.anim.gags.t11","legacyId":"t11wgrlh","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Слапстик (Slapstick)","bg":"Слапстик","en":"Slapstick","alts":["slapstick"],"def":"Физическа комедия с удари, падания и сблъсъци, при които никой не пострадва наистина. Идва от водевила и нямото кино — Чаплин, Бъстър Кийтън.","ex":"Името идва от „пляскалката“ (slapstick) на клоуните в италианската комедия дел арте — две дъсчици, които при удар плясват силно, без да болят много."}},{"id":"studio.anim.gags.t12","legacyId":"t1a8a448","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Реакция (Take)","bg":"Реакция","en":"Take","alts":["take","тейк"],"def":"Преувеличеният отговор на лицето и тялото в мига, когато героят осъзнае какво се е случило: очите изскачат, челюстта пада, тялото подскача.","ex":"При double take героят поглежда, не разбира какво е видял, обръща се — и чак тогава рязко поглежда пак. Текс Ейвъри довежда реакциите до крайност: очи като фарове и челюст до пода."}},{"id":"studio.anim.tech.t01","legacyId":"t1di75cd","hall":"studio","domain":"anim","topic":"anim.tech","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Покадрова анимация (Frame-by-frame animation)","bg":"Покадрова анимация","en":"Frame-by-frame animation","alts":["frame by frame","кадър по кадър"],"def":"Всяка фаза на движението се рисува на ръка като отделна рисунка — на хартия или в програма.","ex":"Така са рисувани класическите филми на Disney и Studio Ghibli. Днес покадрово се анимира и дигитално — в TVPaint, Krita или Toon Boom Harmony, а Onion skin показва съседните рисунки."}},{"id":"studio.anim.tech.t02","legacyId":"t1kf710t","hall":"studio","domain":"anim","topic":"anim.tech","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Междинно кадриране (Tweening)","bg":"Междинно кадриране","en":"Tweening","alts":["tween","tweening","интерполация"],"def":"Програмата сама изчислява плавния преход от една ключова поза до следващата; аниматорът задава само началото и края.","ex":"Терминът идва от „in-between“: в класическото студио междинните фази рисува отделен художник. Без breakdown пози и ускорение компютърното междинно кадриране изглежда равномерно и безжизнено."}},{"id":"studio.anim.tech.t03","legacyId":"t104spx0","hall":"studio","domain":"anim","topic":"anim.tech","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy","fixes":["S69","S70","S71"]},"kind":"term","term":{"label":"Анимация с предмети (Stop motion)","bg":"Анимация с предмети","en":"Stop motion","alts":["стоп-моушън","стоп моушън","куклена анимация","пластилинова анимация","анимация с предмети","stop motion"],"def":"Реални предмети или кукли се местят малко и се снимат кадър по кадър.","ex":"Студио Aardman („Уолъс и Громит“, „Овцата Шон“) работи с пластилин. При 24 кадъра в секунда и анимация на двойки (On twos) всяка секунда е 12 отделни снимки, а между тях куклата се мести с милиметри."}},{"id":"studio.anim.tech.t04","legacyId":"t91wu8f","hall":"studio","domain":"anim","topic":"anim.tech","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy","fixes":["S72","S73","S74"]},"kind":"term","term":{"label":"Ротоскопиране (Rotoscoping)","bg":"Ротоскопиране","en":"Rotoscoping","alts":["rotoscope","ротоскопия","ротоскоп","ротоскопиране","rotoscoping"],"def":"Прерисуване на заснето движение кадър по кадър.","ex":"Disney снима танцьорка като модел за Снежанка и аниматорите следват движенията ѝ. Днес rotoscoping означава и изрязване на маска около обект кадър по кадър във визуалните ефекти."}},{"id":"studio.anim.tech.t05","legacyId":"t1x18yz1","hall":"studio","domain":"anim","topic":"anim.tech","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Изрезкова анимация (Cut-out animation)","bg":"Изрезкова анимация","en":"Cut-out animation","alts":["cut-out","изрязана анимация"],"def":"Героят е сглобен от плоски хартиени или дигитални части, които се движат, като се завъртат в ставите.","ex":"Опитай без компютър: изрежи герой от картон на 6–8 части, свържи ставите с конец и го снимай с телефона кадър по кадър. Днес същото се прави с Rig в програми като Toon Boom Harmony."}},{"id":"studio.anim.tech.t06","legacyId":"th2w3yy","hall":"studio","domain":"anim","topic":"anim.tech","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy","fixes":["P04"]},"kind":"term","term":{"label":"Rig","en":"Rig","alts":["rigging","риг","ригване"],"def":"„Скелет“ с контроли, с който 3D или 2D героят се движи и деформира.","ex":"Добрият Rig крие сложността: аниматорът върти няколко удобни контрола, а под тях работят десетки кости и ограничения. Изграждането на Rig е отделна професия в студията."}},{"id":"studio.anim.tech.t07","legacyId":"tfjnyl0","hall":"studio","domain":"anim","topic":"anim.tech","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Улавяне на движение (Motion capture)","bg":"Улавяне на движение","en":"Motion capture","alts":["motion capture","mocap"],"def":"Изпълнението на актьор с маркери или сензори по тялото се записва и се пренася върху 3D герой.","ex":"Камери около сцената следят отразяващите маркери по костюма и изчисляват положението им в 3D. Когато се записва и мимиката, говорим за performance capture — така е изигран Цезар във „Възходът на планетата на маймуните“."}},{"id":"studio.anim.tech.t08","legacyId":"t12su4lk","hall":"studio","domain":"anim","topic":"anim.tech","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Полигонален модел (Polygonal model)","bg":"Полигонален модел","en":"Polygonal model","alts":["полигони","polygon","mesh","мрежа"],"def":"3D обект, изграден от върхове, ръбове и плоски стени — най-често триъгълници и четириъгълници.","ex":"Колкото повече полигони, толкова по-гладък и по-тежък е моделът. Героите във видеоигрите имат по-малко полигони, за да се изчисляват в реално време, а киното може да си позволи милиони."}},{"id":"studio.anim.3d.t01","legacyId":"t1cty1bg","hall":"studio","domain":"anim","topic":"anim.3d","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Примитив (Primitive)","bg":"Примитив","en":"Primitive","alts":["primitive","примитиви","геометричен примитив"],"def":"Готова основна форма — куб, сфера, цилиндър, конус — от която започва моделирането.","ex":"Опитай да видиш всеки предмет като сбор от примитиви: чашата е цилиндър, главата — сфера, нощната лампа — конус върху цилиндър. Така започва и рисуването на герои — с прости обеми."}},{"id":"studio.anim.3d.t02","legacyId":"t13z60j4","hall":"studio","domain":"anim","topic":"anim.3d","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Екструзия (Extrude)","bg":"Екструзия","en":"Extrude","alts":["extrude","екструдиране","изтегляне"],"def":"Издърпване на стена или ръб, при което се създава нова геометрия в дълбочина.","ex":"Така от плоски букви става обемен 3D надпис, а от квадрат — стена с дебелина. В Blender клавишът E издърпва избраната стена, ръб или връх."}},{"id":"studio.anim.3d.t03","legacyId":"tdgvcs8","hall":"studio","domain":"anim","topic":"anim.3d","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Ротационно тяло (Lathe)","bg":"Ротационно тяло","en":"Lathe","alts":["lathe","revolve","ротация","ротационно"],"def":"Профил, завъртян около ос; така се моделират чаши, вази, колони.","ex":"Ако профилът не допира оста, тялото става кухо като пръстен. Завърти кръг около ос встрани от него — и ще получиш поничка (торус)."}},{"id":"studio.anim.3d.t04","legacyId":"te8ll36","hall":"studio","domain":"anim","topic":"anim.3d","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Булеви операции (Boolean)","bg":"Булеви операции","en":"Boolean","alts":["boolean","булеви","булева операция"],"def":"Обединение, изваждане или сечение на два обекта — например дупка за прозорец в стена.","ex":"След тях мрежата често остава неравна, с дълги тесни триъгълници. Затова се ползват най-вече за твърди предмети като сгради и машини, а не за герои, които ще се деформират."}},{"id":"studio.anim.3d.t05","legacyId":"tca3yet","hall":"studio","domain":"anim","topic":"anim.3d","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"NURBS","en":"NURBS","alts":["nurbs","нърбс"],"def":"Повърхности, описани с математически криви вместо с полигони; остават идеално гладки при всяко увеличение — коли, продуктов дизайн.","ex":"Съкращението е от Non-Uniform Rational B-Splines. Формата се управлява с контролни точки, които дърпат повърхността като магнити, без да лежат върху нея."}},{"id":"studio.anim.3d.t06","legacyId":"t875nud","hall":"studio","domain":"anim","topic":"anim.3d","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"UV разгъване (UV unwrapping)","bg":"UV разгъване","en":"UV unwrapping","alts":["uv","uv unwrapping","uv mapping","разгъване"],"def":"3D повърхността се разрязва по шевове и се разстила в плоска карта, върху която текстурата ляга с възможно най-малко разтягане.","ex":"Провери разгъването с текстура на шахматна дъска: ако квадратчетата са еднакви и неизкривени, картата е добра; ако се разтягат или свиват, премести шевовете."}},{"id":"studio.anim.3d.t07","legacyId":"t6pajys","hall":"studio","domain":"anim","topic":"anim.3d","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Текстура (Texture)","bg":"Текстура","en":"Texture","alts":["texture","текстура"],"def":"Изображение, което дава цвят и детайл на повърхността — дърво, плат, ръжда, кожа.","ex":"Текстурата може да носи не само цвят: отделни карти задават грапавостта, релефа (normal map) или кои части блестят. Добър източник са снимки на истински повърхности — кора, тухли, ръжда."}},{"id":"studio.anim.3d.t08","legacyId":"tv8fjsh","hall":"studio","domain":"anim","topic":"anim.3d","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Материал (Material)","bg":"Материал","en":"Material","alts":["material","shader","шейдър"],"def":"Описание как повърхността отразява, пречупва и пропуска светлина — метал, стъкло, кожа.","ex":"Една и съща сива текстура може да е метал или пластмаса — решава материалът: колко гланц има и как отразява светлината. В Blender материалите се сглобяват от възли (nodes) в Shader Editor."}},{"id":"studio.anim.3d.t09","legacyId":"tcvhmqi","hall":"studio","domain":"anim","topic":"anim.3d","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy","fixes":["P05"]},"kind":"term","term":{"label":"Рендиране (Rendering)","bg":"Рендиране","en":"Rendering","alts":["rendering","render","рендер","рендиране"],"def":"Изчисляване на крайните кадри от 3D сцената — геометрия, материали, светлина и камера.","ex":"Във филмовата анимация един кадър може да се рендира с часове, затова студията ползват огромни „ферми“ от компютри. Във видеоигрите рендирането става в реално време — десетки кадри в секунда."}},{"id":"studio.anim.3d.t10","legacyId":"tidaw2v","hall":"studio","domain":"anim","topic":"anim.3d","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Процедурна анимация (Procedural animation)","bg":"Процедурна анимация","en":"Procedural animation","alts":["procedural animation","процедурна"],"def":"Движението се изчислява по правила и симулации — частици, плат, коса, тълпи — вместо да се задава с ключови кадри.","ex":"Буйните къдрици на Мерида от „Храбро сърце“ на Pixar са симулирани: аниматорът движи героинята, а програмата изчислява как подскача всяка къдрица."}},{"id":"studio.anim.fx.t01","legacyId":"tcprzpq","hall":"studio","domain":"anim","topic":"anim.fx","level":11,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Анимация на ефекти (FX animation)","bg":"Анимация на ефекти","en":"FX animation","alts":["fx","fx animation","effects animation","ефекти"],"def":"Движението на огън, вода, дим, прах, искри и магия, което се рисува или симулира отделно от героите.","ex":"В класическото студио ефектите рисува отделен аниматор, на отделен слой, когато движението на героите е готово. Днес 3D ефектите се правят най-често в Houdini, но и в Blender."}},{"id":"studio.anim.fx.t02","legacyId":"t3s85qh","hall":"studio","domain":"anim","topic":"anim.fx","level":11,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Система от частици (Particle system)","bg":"Система от частици","en":"Particle system","alts":["particle system","particles","частици"],"def":"В 3D: хиляди малки елементи, които се раждат от източник (emitter), движат се по зададени правила и изчезват — дъжд, искри, дим.","ex":"Техниката е въведена във „Стар Трек II: Гневът на Хан“ (1982) за ефекта „Генезис“ — огнена стена, която обхваща цяла планета. Уилям Рийвс я описва в статия през 1983 г."}},{"id":"studio.anim.fx.t03","legacyId":"t6kszul","hall":"studio","domain":"anim","topic":"anim.fx","level":11,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Цикъл на пламъка (Fire cycle)","bg":"Цикъл на пламъка","en":"Fire cycle","alts":["fire cycle","цикъл на огъня"],"def":"Повтаряща се, но неравна поредица от рисунки: езиците на огъня се издигат, изтъняват и се откъсват нагоре.","ex":"Пламъкът на свещ е най-простият вариант: един език се удължава, изтънява и откъсва малко пламъче нагоре. Голям огън е няколко такива цикъла с различна дължина, наслоени един върху друг."}},{"id":"studio.anim.fx.t04","legacyId":"ttgfq6s","hall":"studio","domain":"anim","topic":"anim.fx","level":11,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Разсейване (Dissipation)","bg":"Разсейване","en":"Dissipation","alts":["dissipation","разсейване"],"def":"Димът и парата се разширяват, забавят и изтъняват, докато изчезнат.","ex":"Същото се случва с прах, мъгла и дъха в студено време. В Blender симулацията на дим има настройка Dissolve, с която димът постепенно изчезва."}},{"id":"studio.anim.fx.t05","legacyId":"tvpml7u","hall":"studio","domain":"anim","topic":"anim.fx","level":11,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Пръски (Splash)","bg":"Пръски","en":"Splash","alts":["splash","пръски"],"def":"При удар водата образува корона от капки, които летят по дъги и падат обратно.","ex":"Харолд Еджъртън от MIT снима пръските със стробоскопска светкавица; кадърът му „Milk Drop Coronet“ показва короната от капка мляко, замръзнала във въздуха."}},{"id":"studio.prod.periods.t01","legacyId":"t1im8cya","hall":"studio","domain":"prod","topic":"prod.periods","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Преподготвителен период (Development)","bg":"Преподготвителен период","en":"Development","alts":["преподготвителен","development"],"def":"Най-ранният етап: от идеята се пише сценарий, намират се продуцент и финансиране.","ex":"Много проекти така и не излизат от този период. В Холивуд се говори за „development hell“, когато сценарият се пренаписва години наред, а парите все не стигат."}},{"id":"studio.prod.periods.t02","legacyId":"t1f5v92","hall":"studio","domain":"prod","topic":"prod.periods","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Подготвителен период (Pre-production)","bg":"Подготвителен период","en":"Pre-production","alts":["подготвителен","предпродукция"],"def":"Подбор на актьори, локации, екип, storyboard, снимачен план, бюджет.","ex":"Тук се правят и пробите — грим, костюми, камера, звук. Правилото е просто: всичко, което може да се провери преди снимачния ден, се проверява в подготвителния период."}},{"id":"studio.prod.periods.t03","legacyId":"t1mveudl","hall":"studio","domain":"prod","topic":"prod.periods","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Продукционен период (Production)","bg":"Продукционен период","en":"Production","alts":["продукционен","production","снимки"],"def":"Самите снимки или анимирането.","ex":"Снимките на игрален филм траят седмици, а в анимацията продукционният период може да трае години: в рисуваната анимация всяка секунда обикновено изисква от 12 до 24 рисунки."}},{"id":"studio.prod.periods.t04","legacyId":"t5k38kc","hall":"studio","domain":"prod","topic":"prod.periods","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Постпродукционен период (Post-production)","bg":"Постпродукционен период","en":"Post-production","alts":["постпродукция","postproduction"],"def":"Монтаж, звук, музика, цветови корекции, визуални ефекти, надписи.","ex":"Често трае по-дълго от самите снимки. Тук се прави и окончателният звук — шумове (Foley), постсинхрон (ADR) и музика; виж темата „Звук и образ“."}},{"id":"studio.prod.periods.t05","legacyId":"t1jg7gjt","hall":"studio","domain":"prod","topic":"prod.periods","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Ликвидационен период (Wrap)","bg":"Ликвидационен период","en":"Wrap","alts":["ликвидационен","приключване"],"def":"Последният етап: техниката се връща, разходите се отчитат, материалът се архивира, копията се предават.","ex":"На английски краят на снимките се обявява с „That's a wrap!“. Но работата не свършва с последния дубъл: техниката, сметките и договорите също трябва да се приключат."}},{"id":"studio.prod.crew.t01","legacyId":"t1vu15y0","hall":"studio","domain":"prod","topic":"prod.crew","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Продуцент (Producer)","bg":"Продуцент","en":"Producer","alts":["producer"],"def":"Отговаря за проекта като цяло: пари, хора, срокове, права.","ex":"„Оскар“ за най-добър филм получават продуцентите, а не режисьорът — защото те отговарят за филма като цяло, от идеята до разпространението."}},{"id":"studio.prod.crew.t02","legacyId":"txu7d13","hall":"studio","domain":"prod","topic":"prod.crew","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Асистент-режисьор (Assistant director)","bg":"Асистент-режисьор","en":"Assistant director","alts":["първи асистент","1st ad"],"def":"Прави снимачния план и държи темпото и реда на площадката.","ex":"Въпреки името асистент-режисьорът не работи с актьорите по ролите: той е организаторът на площадката. Вика екипа, обявява кадрите и следи часовника, за да се заснеме всичко по план."}},{"id":"studio.prod.crew.t03","legacyId":"t1aj6a1d","hall":"studio","domain":"prod","topic":"prod.crew","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Оператор-постановчик (Director of photography)","bg":"Оператор-постановчик","en":"Director of photography","alts":["dop","director of photography","главен оператор"],"def":"Отговаря за образа: светлина, камера, обективи, композиция.","ex":"Емануел Любецки печели три поредни „Оскара“ за операторско майсторство — за „Гравитация“, „Бърдмен“ и „Завръщането“. В „Бърдмен“ целият филм изглежда като един непрекъснат кадър."}},{"id":"studio.prod.crew.t04","legacyId":"t1a7m685","hall":"studio","domain":"prod","topic":"prod.crew","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Главен осветител (Gaffer)","bg":"Главен осветител","en":"Gaffer","alts":["гафер"],"def":"Ръководи екипа, който поставя и захранва лампите по светлинния план на оператора-постановчик.","ex":"Главният осветител следи и захранването — колко лампи понася един контакт или генератор. На училищен филм не включвай няколко мощни лампи в един разклонител: бушонът може да падне насред дубъла."}},{"id":"studio.prod.crew.t05","legacyId":"t1mpl468","hall":"studio","domain":"prod","topic":"prod.crew","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Художник-постановчик (Production designer)","bg":"Художник-постановчик","en":"Production designer","alts":["production designer","сценограф"],"def":"Създава визуалния свят: декори, реквизит, цветовете на средата.","ex":"Английското название production designer е измислено от продуцента Дейвид О. Селзник за Уилям Камерън Мензис — човека, определил визията на „Отнесени от вихъра“."}},{"id":"studio.prod.crew.t06","legacyId":"t14lseks","hall":"studio","domain":"prod","topic":"prod.crew","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Script supervisor","en":"Script supervisor","alts":["скрипт","скриптерка"],"def":"Следи непрекъснатостта на кадрите и записва всеки заснет дубъл.","ex":"Script supervisor чертае по сценария вертикални линии, които показват кой кадър кои реплики покрива (lined script). Така монтажистът веднага вижда с какъв материал разполага."}},{"id":"studio.prod.crew.t07","legacyId":"t185ykti","hall":"studio","domain":"prod","topic":"prod.crew","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Тонрежисьор (Production sound mixer)","bg":"Тонрежисьор","en":"Production sound mixer","alts":["звукорежисьор","sound mixer","звукооператор"],"def":"Записва звука на площадката заедно с бум-оператора.","ex":"Тонрежисьорът слуша всеки дубъл със слушалки и води звуков отчет: кой дубъл е чист, къде е минал самолет. Ако звукът е развален, той казва това веднага, а не чак в монтажа."}},{"id":"studio.prod.crew.t08","legacyId":"t1ysxvbb","hall":"studio","domain":"prod","topic":"prod.crew","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Монтажист (Editor)","bg":"Монтажист","en":"Editor","alts":["editor","монтажист","монтажистка"],"def":"Подрежда заснетия материал, избира дублите и определя ритъма на филма.","ex":"Уолтър Мърч, носител на „Оскар“ за монтажа на „Английският пациент“, поставя емоцията на първо място при избора къде да се среже — пред сюжета и ритъма."}},{"id":"studio.prod.crew.t09","legacyId":"tl130m9","hall":"studio","domain":"prod","topic":"prod.crew","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy","fixes":["B021","B022","B023"]},"kind":"term","term":{"label":"Колорист (Colourist)","bg":"Колорист","en":"Colourist","alts":["colorist","колорист","колористка","colourist"],"def":"В постпродукцията уеднаквява цвета на кадрите и създава цветовия стил на филма.","ex":"„О, братко, къде си?“ (2000) е сред първите филми, оцветени изцяло цифрово: зелените летни поля са превърнати в сухи и жълтеникави, като на стара оцветена снимка."}},{"id":"studio.prod.crew.t10","legacyId":"t1n5ucdq","hall":"studio","domain":"prod","topic":"prod.crew","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Композитор (Composer)","bg":"Композитор","en":"Composer","alts":["composer","композитор"],"def":"Пише оригиналната музика на филма в диалог с режисьора и монтажиста.","ex":"Две редуващи се ноти на Джон Уилямс в „Челюсти“ създават страх много преди акулата да се покаже. Музиката може да разкаже това, което образът още крие."}},{"id":"studio.prod.plan.t01","legacyId":"tp1qsgr","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Разбивка на сценария (Script breakdown)","bg":"Разбивка на сценария","en":"Script breakdown","alts":["разбивка","breakdown"],"def":"Разписване на всяка сцена: персонажи, реквизит, костюми, локация, ефекти.","ex":"За всяка сцена се попълва отделен лист за разбивка (breakdown sheet). От всички листове после се събират общите списъци за реквизит, костюми и актьорски дни."}},{"id":"studio.prod.plan.t02","legacyId":"t14d6w09","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Stripboard","en":"Stripboard","alts":["стрипборд","strip board"],"def":"Цветни ленти за всяка сцена, които се пренареждат в снимачен план.","ex":"Доскоро лентите бяха картонени и се местеха на ръка в специална рамка. Днес същото става в програми за планиране, но принципът е същият: всяка лента е една сцена."}},{"id":"studio.prod.plan.t03","legacyId":"t17dvet6","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Снимачен план (Shooting schedule)","bg":"Снимачен план","en":"Shooting schedule","alts":["shooting schedule","график"],"def":"Разпределението на сцените по дни: кои сцени в кой ден и в какъв ред се правят.","ex":"Добрият снимачен план брои страниците за всеки ден и оставя време за смяна на локация и хранене. Иначе денят изглежда възможен само на хартия."}},{"id":"studio.prod.plan.t04","legacyId":"tk552k7","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Повиквателна (Call sheet)","bg":"Повиквателна","en":"Call sheet","alts":["call sheet","кол шийт","повиквателен лист"],"def":"Документ за следващия снимачен ден: кой, кога и къде идва и какво се снима.","ex":"Освен часовете и сцените повиквателната съдържа прогнозата за времето, часа на изгрева и залеза, мястото за паркиране и най-близката болница."}},{"id":"studio.prod.plan.t05","legacyId":"tofc0m7","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Снимане извън последователност (Shooting out of sequence)","bg":"Снимане извън последователност","en":"Shooting out of sequence","alts":["out of sequence","непоследователно"],"def":"Сцените се групират по локации и актьори, не по реда в сценария.","ex":"Рядко изключение е „Извънземното“ (1982): Спилбърг снима почти по реда на сюжета, за да се сбогуват децата с E.T. наистина развълнувани."}},{"id":"studio.prod.plan.t06","legacyId":"t1r7331g","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Смяна на локация (Company move)","bg":"Смяна на локация","en":"Company move","alts":["company move","преместване"],"def":"Прехвърляне на целия екип и техника на ново място в същия ден; отнема часове.","ex":"В stripboard смяната на локация се отбелязва с отделна лента с надпис (banner), защото отнема време от снимачния ден точно като сцена."}},{"id":"studio.prod.plan.t07","legacyId":"t13sh91t","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Списък на кадрите (Shot list)","bg":"Списък на кадрите","en":"Shot list","alts":["shot list","шот лист"],"def":"Номерирана таблица за сцената: за всеки ред — размер на плана, ракурс, движение и обектив; по нея се планира снимачният ден.","ex":"Подреди списъка на кадрите по посока на камерата: първо всички кадри към едната стена, после всички към другата. Така светлината се пренарежда веднъж, а не при всеки кадър."}},{"id":"studio.prod.plan.t08","legacyId":"tphqr1c","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Оглед на локации (Location scouting)","bg":"Оглед на локации","en":"Location scouting","alts":["location scouting","scouting","оглед","скаутинг"],"def":"Посещение на възможните места за снимки: проверяват се светлината, шумът, достъпът, токът и разрешенията.","ex":"Първо се търсят и избират места, а после идва технически оглед: на мястото отиват ръководителите на отделите и решават къде ще стоят камерата, лампите и колите."}},{"id":"studio.prod.plan.t09","legacyId":"t174nvpn","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Day Out of Days","en":"Day Out of Days","alts":["dood","day out of days"],"def":"Таблица кой актьор в кои дни работи, с кодове: SW — започва, W — работи, WF — приключва, H — задържан.","ex":"Освен за актьорите такава таблица може да се направи и за локации, коли или животни — за всичко, което се плаща на ден."}},{"id":"studio.prod.plan.t10","legacyId":"th38wue","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Почивка между смените (Turnaround)","bg":"Почивка между смените","en":"Turnaround","alts":["turnaround"],"def":"Минималното време за отдих от края на снимачния ден до следващото повикване — обикновено 10–12 часа.","ex":"Почивката се смята за всеки човек отделно: гримьорите идват първи и често си тръгват последни, затова тяхната почивка може да определи кога започва следващият ден."}},{"id":"studio.prod.set.t01","legacyId":"tkh8d5w","hall":"studio","domain":"prod","topic":"prod.set","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Клапа (Clapperboard)","bg":"Клапа","en":"Clapperboard","alts":["clapperboard","slate","хлопка"],"def":"Табло с номер на сцена, кадър и дубъл; ударът ѝ дава точка за синхрон на звука и образа.","ex":"Електронните клапи показват и времевия код (timecode) от рекордера. Така звукът и образът могат да се синхронизират и по числата, без да се търси ударът."}},{"id":"studio.prod.set.t02","legacyId":"t2j6rg3","hall":"studio","domain":"prod","topic":"prod.set","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Дубъл (Take)","bg":"Дубъл","en":"Take","alts":["take"],"def":"Всеки отделен запис на един и същ кадър.","ex":"В епохата на лентата целият негатив се проявяваше, но на позитив се копираха само дублите, оградени в отчета (circle takes) — за да се пестят пари."}},{"id":"studio.prod.set.t03","legacyId":"t2sb9wy","hall":"studio","domain":"prod","topic":"prod.set","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Непрекъснатост (Continuity)","bg":"Непрекъснатост","en":"Continuity","alts":["континюити","continuity","приемственост"],"def":"Еднаквостта на детайлите между кадрите: реквизит, коса, позиции, посоки.","ex":"Непрекъснатостта следи и посоките: ако героят излиза от кадъра вдясно, в следващия трябва да влезе отляво. Затова е свързана с правилото 180° от темата „Правила за пространството“."}},{"id":"studio.prod.set.t04","legacyId":"t17ycjx7","hall":"studio","domain":"prod","topic":"prod.set","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Кадър без звук (MOS)","bg":"Кадър без звук","en":"MOS","alts":["без звук","ням кадър"],"def":"Материал, заснет само от камерата, докато рекордерът е спрян — например пейзаж или детайл, към които шумовете се добавят в монтажа.","ex":"Произходът на съкращението MOS е спорен. Най-популярната легенда е, че идва от развалено „mit out sound“ на немски режисьори в Холивуд, но това не е доказано."}},{"id":"studio.prod.set.t05","legacyId":"tnnf98o","hall":"studio","domain":"prod","topic":"prod.set","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Репетиция (Rehearsal)","bg":"Репетиция","en":"Rehearsal","alts":["rehearsal","репетиция","проба"],"def":"Изиграване на сцената с актьорите и камерата преди дубъла; уточняват се разстановката, фокусът и нивата на звука.","ex":"Докато се нагласява светлината, на мястото на актьорите често стоят заместници със сходен ръст (stand-ins), а главните актьори пазят силите си за дубъла."}},{"id":"studio.prod.set.t06","legacyId":"t125r1g8","hall":"studio","domain":"prod","topic":"prod.set","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Позиция на актьора (Mark)","bg":"Позиция на актьора","en":"Mark","alts":["mark","марка","знак на пода","hit the mark"],"def":"Парче лента на пода, на което изпълнителят спира, за да попадне в светлината и във фокуса.","ex":"Марките често са във формата на буквата T и в различен цвят за всеки актьор. Асистентът по фокуса мери разстоянието от камерата до всяка от тях."}},{"id":"studio.prod.set.t07","legacyId":"t1kikjb6","hall":"studio","domain":"prod","topic":"prod.set","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Martini shot","en":"Martini shot","alts":["martini","martini shot","мартини"],"def":"Последният кадър за снимачния ден; асистент-режисьорът го обявява на екипа.","ex":"Предпоследният кадър на деня също има име — „Abby Singer“, на асистент-режисьора Аби Сингър, който обявявал „този и още един“, за да спечели време за преместването."}},{"id":"studio.prod.sound.t01","legacyId":"tn04qq2","hall":"studio","domain":"prod","topic":"prod.sound","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Насочен микрофон (Shotgun microphone)","bg":"Насочен микрофон","en":"Shotgun microphone","alts":["shotgun","shotgun microphone","насочен","пушка"],"def":"Окачва се на бум над актьорите; чува в тясна зона пред себе си, затова хваща диалога и потиска околния шум.","ex":"Насоченият микрофон е като фенерче за звук: чува най-добре там, накъдето сочи. Затова бум операторът го обръща към всеки, който заговори."}},{"id":"studio.prod.sound.t02","legacyId":"t1k2j0v","hall":"studio","domain":"prod","topic":"prod.sound","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Петличен микрофон (Lavalier microphone)","bg":"Петличен микрофон","en":"Lavalier microphone","alts":["lavalier","lav","петличка","петличен"],"def":"Миниатюрна капсула, закрепена на дрехата или скрита под нея; удобна за интервюта, широки и движещи се кадри и коли, но платът шумоли, а околният звук се губи.","ex":"В телевизията и в документалните интервюта петличката често се вижда на ревера. В игралното кино я крият — под яката, зад копче или дори в косата."}},{"id":"studio.prod.sound.t03","legacyId":"t2mtbjf","hall":"studio","domain":"prod","topic":"prod.sound","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Бум (Boom pole)","bg":"Бум","en":"Boom pole","alts":["boom","boom pole","бум"],"def":"Телескопичен прът, на който насоченият микрофон се държи над актьорите, точно извън кадъра.","ex":"Прътите са от алуминий или въглеродни влакна, за да са леки: бум операторът ги държи над главата си с минути. При някои кабелът минава вътре, за да не потропва."}},{"id":"studio.prod.sound.t04","legacyId":"tvy7oa1","hall":"studio","domain":"prod","topic":"prod.sound","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Бум оператор (Boom operator)","bg":"Бум оператор","en":"Boom operator","alts":["boom operator","бум оператор","микрофонист"],"def":"Държи микрофона на еднакво разстояние, насочен към говорещия, извън кадъра и без да хвърля сянка; винаги слуша със слушалки.","ex":"Добрият бум оператор научава репликите наизуст. Така насочва микрофона към следващия говорещ, преди той да е започнал."}},{"id":"studio.prod.sound.t05","legacyId":"t1b8ghqt","hall":"studio","domain":"prod","topic":"prod.sound","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Ветробран (Windscreen)","bg":"Ветробран","en":"Windscreen","alts":["windscreen","zeppelin","цепелин","deadcat","ветробран"],"def":"Решетъчен кожух или „рошав“ калъф върху микрофона, който пази записа от шума на вятъра.","ex":"Поролоновият калъф стига на закрито. Навън се слага кожух, а при вятър — и „рошав“ калъф отгоре, защото дори лек полъх бучи в микрофона."}},{"id":"studio.prod.sound.t06","legacyId":"t1iux1q0","hall":"studio","domain":"prod","topic":"prod.sound","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Амортисьор (Shock mount)","bg":"Амортисьор","en":"Shock mount","alts":["shock mount","амортисьор"],"def":"Държач с ластици, който спира шума от докосването и движението на бума.","ex":"Без амортисьор всяко плъзгане на ръката по пръта се чува като тропане. Закрепи и кабела към пръта — свободно висящият кабел също потропва в записа."}},{"id":"studio.prod.sound.t07","legacyId":"t5ccyq4","hall":"studio","domain":"prod","topic":"prod.sound","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Отделен запис на звука (Double-system sound)","bg":"Отделен запис на звука","en":"Double-system sound","alts":["double-system sound","double system","sync sound","отделен запис"],"def":"Чистият звук идва от самостоятелен рекордер, а не от камерата; в монтажа двата файла се подравняват по удара на клапата.","ex":"Записвай звук и в камерата, дори да е лош. Програмите за монтаж могат да подравнят двата файла сами по формата на звуковата вълна."}},{"id":"studio.prod.sound.t08","legacyId":"te6zy5a","hall":"studio","domain":"prod","topic":"prod.sound","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Претоварване (Clipping)","bg":"Претоварване","en":"Clipping","alts":["clipping","клипинг","претоварване"],"def":"Звукът е по-силен от максимума на записа и се изкривява безвъзвратно; нивата се държат с резерв.","ex":"Таванът на цифровия запис е 0 dB по скалата на рекордера. Ориентир за диалог: пиковете при нормален говор около −12 dB, за да остане място за вик."}},{"id":"studio.hist.pre.t01","legacyId":"t11wc327","hall":"studio","domain":"hist","topic":"hist.pre","level":10,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Камера обскура (Camera obscura)","bg":"Камера обскура","en":"Camera obscura","alts":["camera obscura","тъмна стая"],"def":"Тъмна кутия с малък отвор, през който на стената се появява обърнат образ на света.","ex":"На латински името означава „тъмна стая“. Художниците векове наред я използват, за да прерисуват точно гледки и перспектива, а фотоапаратът е същата кутия с обектив вместо дупка."}},{"id":"studio.hist.pre.t02","legacyId":"tifgc5g","hall":"studio","domain":"hist","topic":"hist.pre","level":10,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Латерна магика (Magic lantern)","bg":"Латерна магика","en":"Magic lantern","alts":["вълшебен фенер","magic lantern"],"def":"Прожекционен апарат от XVII век: светлината на лампа минава през рисунка на стъкло и през леща и хвърля увеличен образ на стената.","ex":"Пътуващи прожекционисти показват с нея приказки и страшни „призраци“. Някои стъкла имат лостчета и макари, с които рисунката се движи — първа стъпка към движещата се картина."}},{"id":"studio.hist.pre.t03","legacyId":"t1g4g51w","hall":"studio","domain":"hist","topic":"hist.pre","level":10,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Фенакистископ (Phenakistiscope)","bg":"Фенакистископ","en":"Phenakistiscope","alts":["phenakistiscope"],"def":"Въртящ се диск с фази на движение, гледан през процепи (Плато, 1832).","ex":"Дискът се върти пред огледало и през процепите окото вижда всяка фаза само за миг, затова фазите се сливат в движение. Почти по същото време подобен диск прави и австриецът Симон Щампфер."}},{"id":"studio.hist.pre.t04","legacyId":"t1s6tgio","hall":"studio","domain":"hist","topic":"hist.pre","level":10,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Зоетроп (Zoetrope)","bg":"Зоетроп","en":"Zoetrope","alts":["zoetrope"],"def":"Цилиндър с процепи и лента с рисунки, които при въртене оживяват (1834).","ex":"За разлика от фенакистископа, зоетропа могат да гледат няколко души наведнъж, а лентите с рисунки се сменят лесно. Днес има и 3D зоетропи с фигурки — например с Тоторо в музея на Studio Ghibli."}},{"id":"studio.hist.pre.t05","legacyId":"td7f7zj","hall":"studio","domain":"hist","topic":"hist.pre","level":10,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Праксиноскоп (Praxinoscope)","bg":"Праксиноскоп","en":"Praxinoscope","alts":["praxinoscope"],"def":"Барабан с огледала вместо процепи (Емил Рейно, 1877) — по-ясен образ.","ex":"Огледалата в центъра показват всяка рисунка в точния миг и без тъмните процепи образът е по-светъл и по-ясен. По-късно Рейно го развива в Оптическия театър, с който прожектира пред публика."}},{"id":"studio.hist.pre.t06","legacyId":"t1i30t0r","hall":"studio","domain":"hist","topic":"hist.pre","level":10,"subjects":["kino","anim"],"sources":[{"title":"Wikipedia: Eadweard Muybridge","url":"https://en.wikipedia.org/wiki/Eadweard_Muybridge"},{"title":"Wikipedia: Étienne-Jules Marey","url":"https://en.wikipedia.org/wiki/%C3%89tienne-Jules_Marey"}],"review":{"status":"legacy","fixes":["S06","S07","S08"]},"kind":"term","term":{"label":"Хронофотография (Chronophotography)","bg":"Хронофотография","en":"Chronophotography","alts":["мейбридж","маре","chronophotography","muybridge","marey"],"def":"Поредица от бързо направени снимки, които разлагат движението на фази — например галопиращ кон или човек в скок.","ex":"Еадуърд Мейбридж (Eadweard Muybridge) снима галопиращ кон с редица фотоапарати, а Етиен-Жул Маре (Étienne-Jules Marey) — с „фотографска пушка“, която прави много кадри от една точка. Аниматорите и днес ползват сериите им като референция."}},{"id":"studio.hist.pre.t07","legacyId":"t1o7oidb","hall":"studio","domain":"hist","topic":"hist.pre","level":10,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Кинетоскоп (Kinetoscope)","bg":"Кинетоскоп","en":"Kinetoscope","alts":["kinetoscope","едисън"],"def":"Американски апарат (1891–1893) — кутия с шпионка, през която само един зрител гледа движещи се снимки от въртяща се филмова лента.","ex":"Създаден е в лабораторията на Томас Едисън главно от Уилям Кенеди Диксън. През 1894 г. в Ню Йорк отваря първият салон с кинетоскопи — всеки зрител плаща, за да надникне в кутията."}},{"id":"studio.hist.pioneer.t01","legacyId":"tw4g07x","hall":"studio","domain":"hist","topic":"hist.pioneer","level":12,"subjects":["kino"],"sources":[{"title":"Wikipedia: Lumière brothers","url":"https://en.wikipedia.org/wiki/Auguste_and_Louis_Lumi%C3%A8re"}],"review":{"status":"legacy","fixes":["S11","S12","S13"]},"kind":"term","term":{"label":"Братя Люмиер (Auguste and Louis Lumière)","bg":"Братя Люмиер","en":"Auguste and Louis Lumière","alts":["люмиер","lumière","auguste and louis lumière","lumière brothers","lumiere brothers"],"def":"Френски изобретатели, чийто кинематограф снима, копира и прожектира; прожекцията им срещу билет в Гран кафе в Париж (28 декември 1895 г.) се смята за рождението на киното.","ex":"Филмите им траят под минута и показват делника: работници излизат от фабриката, влак пристига на гарата, бебе закусва. Операторите им обикалят света и снимат гледки за прожекции навсякъде."}},{"id":"studio.hist.pioneer.t02","legacyId":"t1h5gmzh","hall":"studio","domain":"hist","topic":"hist.pioneer","level":12,"subjects":["kino"],"sources":[{"title":"Wikipedia: Georges Méliès","url":"https://en.wikipedia.org/wiki/Georges_M%C3%A9li%C3%A8s"}],"review":{"status":"legacy","fixes":["S14","S15","S16"]},"kind":"term","term":{"label":"Жорж Мелиес (Georges Méliès)","bg":"Жорж Мелиес","en":"Georges Méliès","alts":["мелиес","méliès","georges méliès","georges melies"],"def":"Илюзионист, който превръща киното в спектакъл с трикове; „Пътешествие до Луната“ (1902).","ex":"Строи едно от първите филмови студия — остъклен павилион в Монтрьой — и сам рисува декорите. Историята на късния му живот разказва филмът на Скорсезе „Изобретението на Хюго“ (2011)."}},{"id":"studio.hist.pioneer.t03","legacyId":"t3qu5yg","hall":"studio","domain":"hist","topic":"hist.pioneer","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Брайтънска школа (Brighton School)","bg":"Брайтънска школа","en":"Brighton School","alts":["брайтън","brighton school"],"def":"Английски пионери (Смит, Уилямсън), които около 1900 г. въвеждат в монтажа крупния план и кадъра от гледна точка.","ex":"В „Grandma’s Reading Glass“ (1900) на Джордж Албърт Смит момче гледа през лупа, а ние виждаме увеличените предмети в кръгла рамка — като през неговите очи."}},{"id":"studio.hist.pioneer.t04","legacyId":"t9mylpf","hall":"studio","domain":"hist","topic":"hist.pioneer","level":12,"subjects":["kino"],"sources":[{"title":"Wikipedia: Edwin S. Porter","url":"https://en.wikipedia.org/wiki/Edwin_S._Porter"}],"review":{"status":"legacy","fixes":["S17","S18","S19"]},"kind":"term","term":{"label":"Едуин Портър (Edwin S. Porter)","bg":"Едуин Портър","en":"Edwin S. Porter","alts":["портър","porter","edwin s. porter","edwin porter"],"def":"„Големият влаков обир“ (1903): монтаж, който свързва действия на различни места.","ex":"Работи за компанията на Едисън. Във „Големият влаков обир“ има кадър, в който бандит стреля право към зрителите; кината сами избират дали да го пуснат в началото или в края."}},{"id":"studio.hist.pioneer.t05","legacyId":"tt9gt3c","hall":"studio","domain":"hist","topic":"hist.pioneer","level":12,"subjects":["kino"],"sources":[{"title":"Wikipedia: Alice Guy-Blaché","url":"https://en.wikipedia.org/wiki/Alice_Guy-Blach%C3%A9"}],"review":{"status":"legacy","fixes":["S20","S21"]},"kind":"term","term":{"label":"Алис Ги (Alice Guy)","bg":"Алис Ги","en":"Alice Guy","alts":["алис ги","alice guy","alice guy-blaché"],"def":"Смятана за първата жена режисьор; от „Феята на зелето“ (средата на 1890-те) нататък снима стотици филми за Gaumont и за собственото си студио в САЩ.","ex":"Тя снима и ранни звукови филми с хронофона на Gaumont — песни и танци, синхронизирани с грамофонна плоча, около две десетилетия преди звуковото кино."}},{"id":"studio.hist.pioneer.t06","legacyId":"tja2a9a","hall":"studio","domain":"hist","topic":"hist.pioneer","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Стоп-трик (Stop trick)","bg":"Стоп-трик","en":"Stop trick","alts":["stop trick","стоп трик","substitution splice"],"def":"Камерата спира, нещо в сцената се сменя и снимането продължава — на екрана предметът изчезва или се превръща в друг; прочут похват на Мелиес.","ex":"Опитай с телефона на статив: снимай приятел, спри, нека излезе от кадъра, без да местиш телефона, и продължи. Без статив фонът подскача и илюзията се разваля."}},{"id":"studio.hist.pioneer.t07","legacyId":"tflsv23","hall":"studio","domain":"hist","topic":"hist.pioneer","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Кино на атракциите (Cinema of attractions)","bg":"Кино на атракциите","en":"Cinema of attractions","alts":["cinema of attractions","кино на атракциите"],"def":"Ранното кино до около 1906 г., което показва зрелище и трикове, вместо да разказва история.","ex":"Атракцията живее и днес — в сцените с ефекти, които спират разказа, за да ни зашеметят, и в кратките видеа, които разчитат на трик още в първите секунди."}},{"id":"studio.hist.pioneer.t08","legacyId":"t27ajeu","hall":"studio","domain":"hist","topic":"hist.pioneer","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Пате (Pathé)","bg":"Пате","en":"Pathé","alts":["pathe","pathé","пате","братя пате"],"def":"Френска компания, основана през 1896 г. от четирима братя; първа превръща киното в световна индустрия — продукция, разпространение, лента и апарати.","ex":"Емблемата им е петел. Пате са сред първите, които дават филмите на кината под наем, вместо да ги продават — модел, който разпространението следва и днес."}},{"id":"studio.hist.early.t01","legacyId":"t1oap101","hall":"studio","domain":"hist","topic":"hist.early","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Филм д’ар (Film d’Art)","bg":"Филм д’ар","en":"Film d’Art","alts":["film d’art","филм дар","филм д ар"],"def":"Френска продуцентска компания и течение от 1908 г., които привличат театрални актьори и писатели, за да превърнат киното в изкуство.","ex":"Името означава „художествен филм“. Критиците хвалят престижа, но мнозина намират играта твърде театрална — актьорите играят като на сцена, а камерата стои като зрител в салона."}},{"id":"studio.hist.early.t02","legacyId":"t1fjryna","hall":"studio","domain":"hist","topic":"hist.early","level":12,"subjects":["kino"],"sources":[{"title":"Wikipedia: Nordisk Film","url":"https://en.wikipedia.org/wiki/Nordisk_Film"}],"review":{"status":"legacy","fixes":["S23","S24","S25"]},"kind":"term","term":{"label":"Нордиск (Nordisk Film)","bg":"Нордиск","en":"Nordisk Film","alts":["nordisk","нордиск филм","nordisk film"],"def":"Датското студио, основано през 1906 г.; прави Дания водеща кинематография преди Първата световна война („Атлантида“, 1913).","ex":"Основано е от Оле Олсен и е сред най-старите все още работещи филмови компании в света. Емблемата му е бяла мечка върху земното кълбо."}},{"id":"studio.hist.early.t03","legacyId":"t4h0iqy","hall":"studio","domain":"hist","topic":"hist.early","level":12,"subjects":["kino"],"sources":[{"title":"Wikipedia: Asta Nielsen","url":"https://en.wikipedia.org/wiki/Asta_Nielsen"}],"review":{"status":"legacy","fixes":["S26","S27"]},"kind":"term","term":{"label":"Аста Нилсен (Asta Nielsen)","bg":"Аста Нилсен","en":"Asta Nielsen","alts":["нилсен","asta nielsen"],"def":"Датската актриса, една от първите международни филмови звезди; пробивът ѝ е „Бездната“ (1910).","ex":"Играе естествено и сдържано, без театрални жестове, и прави кариера главно в Германия. През 1921 г. дори играе Хамлет в немска екранизация."}},{"id":"studio.hist.early.t04","legacyId":"tn3dny0","hall":"studio","domain":"hist","topic":"hist.early","level":12,"subjects":["kino"],"sources":[{"title":"Wikipedia: Cabiria","url":"https://en.wikipedia.org/wiki/Cabiria"}],"review":{"status":"legacy","fixes":["S29","S30"]},"kind":"term","term":{"label":"„Кабирия“ (Cabiria)","bg":"„Кабирия“","en":"Cabiria","alts":["кабирия","cabiria","пастроне"],"def":"Италианска историческа епопея от 1914 г. за времето на Пуническите войни, с огромни декори и камера на колички.","ex":"Режисьор е Джовани Пастроне, а надписите пише поетът Габриеле д’Анунцио. Силният роб Мачисте става толкова популярен, че получава собствена поредица филми."}},{"id":"studio.hist.early.t05","legacyId":"twd9dfk","hall":"studio","domain":"hist","topic":"hist.early","level":12,"subjects":["kino"],"sources":[{"title":"Wikipedia: D. W. Griffith","url":"https://en.wikipedia.org/wiki/D._W._Griffith"}],"review":{"status":"legacy","fixes":["S32","S33","S34"]},"kind":"term","term":{"label":"Д. У. Грифит (D. W. Griffith)","bg":"Д. У. Грифит","en":"D. W. Griffith","alts":["грифит","griffith","d. w. griffith","d.w. griffith"],"def":"Систематизира паралелния монтаж, крупния план и ритъма; „Раждането на една нация“ (1915), „Нетърпимост“ (1916).","ex":"В „Нетърпимост“ преплита четири истории от различни епохи — паралелният монтаж свързва цели векове. Работи дълги години с оператора Били Битцър."}},{"id":"studio.hist.early.t06","legacyId":"tbrodlr","hall":"studio","domain":"hist","topic":"hist.early","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Шведската школа (Swedish school)","bg":"Шведската школа","en":"Swedish school","alts":["шьострьом","щилер","шведска школа"],"def":"Скандинавско кино от 1910-те и началото на 20-те: суровата природа участва в драмата като сила, а героите имат психологическа дълбочина.","ex":"Начело са Виктор Шьострьом и Мориц Щилер. По-късно и двамата заминават за Холивуд, а Щилер води със себе си младата Грета Гарбо."}},{"id":"studio.hist.silent.t01","legacyId":"t18dy4so","hall":"studio","domain":"hist","topic":"hist.silent","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Немски експресионизъм (German Expressionism)","bg":"Немски експресионизъм","en":"German Expressionism","alts":["експресионизъм","калигари"],"def":"Германско течение след Първата световна война: изкривени декори, рисувани сенки и контрастна светлина изразяват вътрешния ужас на героите.","ex":"В „Кабинетът на д-р Калигари“ (1920) светлините и сенките са нарисувани направо върху декорите. Много германски режисьори и оператори по-късно емигрират в Холивуд и пренасят тези сенки във филм ноар."}},{"id":"studio.hist.silent.t02","legacyId":"t197h9y2","hall":"studio","domain":"hist","topic":"hist.silent","level":12,"subjects":["kino"],"sources":[{"title":"Wikipedia: Nosferatu","url":"https://en.wikipedia.org/wiki/Nosferatu"}],"review":{"status":"legacy","fixes":["S35","S36"]},"kind":"term","term":{"label":"„Носферату“ (Nosferatu)","bg":"„Носферату“","en":"Nosferatu","alts":["носферату","nosferatu","мурнау"],"def":"Германски вампирски филм от 1922 г. — неофициална версия на „Дракула“, заснета на реални места, но с експресионистични сенки.","ex":"Режисьор е Ф. В. Мурнау. Вдовицата на Брам Стокър печели дело и съдът нарежда копията да бъдат унищожени, но някои оцеляват — затова днес можем да гледаме филма."}},{"id":"studio.hist.silent.t03","legacyId":"tyccfdq","hall":"studio","domain":"hist","topic":"hist.silent","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Камершпил (Kammerspielfilm)","bg":"Камершпил","en":"Kammerspielfilm","alts":["kammerspiel","камерна пиеса"],"def":"Германска интимна драма от 20-те: малко герои, делничен свят и почти никакви междинни надписи; пример е „Последният човек“ (1924) на Мурнау.","ex":"Името идва от немски — „камерна пиеса“, като малкия театър за интимни драми. В „Последният човек“ портиер губи униформата си, а с нея и достойнството си."}},{"id":"studio.hist.silent.t04","legacyId":"t10o8hx5","hall":"studio","domain":"hist","topic":"hist.silent","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Студийна система (Studio system)","bg":"Студийна система","en":"Studio system","alts":["холивудска студийна система","studio system"],"def":"Холивудският модел, при който няколко големи компании държат производството, разпространението и кината, а звездите и режисьорите работят по дългосрочни договори.","ex":"През 1948 г. Върховният съд на САЩ задължава големите компании да продадат кината си — началото на края на системата."}},{"id":"studio.hist.silent.t05","legacyId":"t77zn0y","hall":"studio","domain":"hist","topic":"hist.silent","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Съветски монтаж (Soviet montage)","bg":"Съветски монтаж","en":"Soviet montage","alts":["съветска школа","айзенщайн"],"def":"Течение в СССР през 20-те (Кулешов, Пудовкин, Вертов и др.): смисълът се ражда от сблъсъка и съпоставянето на кадрите, а не от всеки кадър поотделно.","ex":"Сергей Айзенщайн прави „Броненосецът Потьомкин“ (1925), а Лев Кулешов показва, че едно и също лице „изразява“ различни чувства според съседния кадър. Повече — в темата „Монтажна теория“."}},{"id":"studio.hist.silent.t06","legacyId":"t1guqiqx","hall":"studio","domain":"hist","topic":"hist.silent","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Френски импресионизъм (French Impressionism)","bg":"Френски импресионизъм","en":"French Impressionism","alts":["първи авангард","импресионизъм"],"def":"Течение във Франция през 20-те (Ганс, Делюк, Епщайн, Дюлак): субективни състояния, ритмичен монтаж и „фотогения“ — особената поетичност на нещата на екрана.","ex":"Абел Ганс снима „Наполеон“ (1927) с камера, качена на кон, а във финала използва три екрана един до друг. Думата „фотогения“ популяризира Луи Делюк."}},{"id":"studio.hist.silent.t07","legacyId":"tqgiscl","hall":"studio","domain":"hist","topic":"hist.silent","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Сюрреализъм в киното (Surrealist cinema)","bg":"Сюрреализъм в киното","en":"Surrealist cinema","alts":["сюрреализъм","втори авангард","андалуското куче"],"def":"Течение от края на 20-те, което следва логиката на съня и шокира с образи от подсъзнанието; пример са филмите на Бунюел и Дали.","ex":"„Андалуското куче“ (1929) няма сюжет в обичайния смисъл: Бунюел и Дали приемат само образи, за които няма логично обяснение. По-късно Бунюел пренася сюрреалистичния хумор и в пълнометражните си филми."}},{"id":"studio.hist.anim.t01","legacyId":"t1mravvd","hall":"studio","domain":"hist","topic":"hist.anim","level":10,"subjects":["anim"],"sources":[{"title":"Wikipedia: Émile Reynaud","url":"https://en.wikipedia.org/wiki/%C3%89mile_Reynaud"}],"review":{"status":"legacy","fixes":["S38","S39","S40"]},"kind":"term","term":{"label":"Емил Рейно (Émile Reynaud)","bg":"Емил Рейно","en":"Émile Reynaud","alts":["рейно","reynaud","оптически театър","émile reynaud","emile reynaud"],"def":"Изобретателят на праксиноскопа, който от 1892 г. в музея „Гревен“ в Париж прожектира пред публика рисувани „светлинни пантомими“ — преди Люмиер.","ex":"Рисува всяка фаза на ръка върху малки желатинови пластинки, свързани в дълга лента; сред пантомимите му е „Бедният Пиеро“ (1892). Апарата си нарича Оптически театър."}},{"id":"studio.hist.anim.t02","legacyId":"t1rdyztv","hall":"studio","domain":"hist","topic":"hist.anim","level":10,"subjects":["anim"],"sources":[{"title":"Wikipedia: Émile Cohl","url":"https://en.wikipedia.org/wiki/%C3%89mile_Cohl"}],"review":{"status":"legacy","fixes":["S41","S42","S43"]},"kind":"term","term":{"label":"Емил Кол (Émile Cohl)","bg":"Емил Кол","en":"Émile Cohl","alts":["кол","cohl","фантасмагория","émile cohl","emile cohl"],"def":"Френски карикатурист, чийто филм от 1908 г. — бели линии върху черен фон — е сред първите изцяло рисувани анимационни филми.","ex":"„Фантасмагория“ трае под две минути и е съставена от стотици рисунки, в които фигурите непрекъснато се превръщат една в друга. Кол рисува с черно на бяла хартия, а негативът дава белите линии."}},{"id":"studio.hist.anim.t03","legacyId":"t8wy8hf","hall":"studio","domain":"hist","topic":"hist.anim","level":10,"subjects":["anim"],"sources":[{"title":"Wikipedia: Winsor McCay","url":"https://en.wikipedia.org/wiki/Winsor_McCay"}],"review":{"status":"legacy","fixes":["S44","S45","S46"]},"kind":"term","term":{"label":"Уинзър Маккей (Winsor McCay)","bg":"Уинзър Маккей","en":"Winsor McCay","alts":["маккей","mccay","герти","winsor mccay"],"def":"Американски автор на комикси („Малкият Немо“), чиято рисувана динозавърка от 1914 г. има характер и „разговаря“ с автора си на сцената.","ex":"На сцената Маккей стои до екрана и дава команди, а Герти „отговаря“. Накрая той сякаш влиза в рисунката и се качва на гърба ѝ."}},{"id":"studio.hist.anim.t04","legacyId":"t1ih43ia","hall":"studio","domain":"hist","topic":"hist.anim","level":10,"subjects":["anim"],"sources":[{"title":"Wikipedia: Lotte Reiniger","url":"https://en.wikipedia.org/wiki/Lotte_Reiniger"}],"review":{"status":"legacy","fixes":["S47","S48","S49"]},"kind":"term","term":{"label":"Лоте Райнигер (Lotte Reiniger)","bg":"Лоте Райнигер","en":"Lotte Reiniger","alts":["райнигер","reiniger","принц ахмед","lotte reiniger"],"def":"Германска аниматорка, чийто силуетен филм от 1926 г. по „Хиляда и една нощ“ е най-старият запазен пълнометражен анимационен филм.","ex":"Изрязва фигурите с ножица от черен картон и ги анимира кадър по кадър върху стъклена маса, осветена отдолу. Работата по „Приключенията на принц Ахмед“ отнема три години."}},{"id":"studio.hist.anim.t05","legacyId":"t1muix0s","hall":"studio","domain":"hist","topic":"hist.anim","level":10,"subjects":["anim"],"sources":[{"title":"Wikipedia: Walt Disney","url":"https://en.wikipedia.org/wiki/Walt_Disney"}],"review":{"status":"legacy","fixes":["S50","S51","S52"]},"kind":"term","term":{"label":"Уолт Дисни (Walt Disney)","bg":"Уолт Дисни","en":"Walt Disney","alts":["дисни","disney","walt disney"],"def":"„Параходът Уили“ (1928) със синхронен звук; „Снежанка“ (1937) — първият пълнометражен филм на студиото.","ex":"Мики Маус е създаден заедно с аниматора Аб Айуъркс, а самият Уолт озвучава Мики почти двадесет години. „Снежанка“ получава почетен „Оскар“ — една голяма и седем малки статуетки."}},{"id":"studio.hist.anim.t06","legacyId":"t1c3dyej","hall":"studio","domain":"hist","topic":"hist.anim","level":10,"subjects":["anim"],"sources":[{"title":"Wikipedia: Toy Story","url":"https://en.wikipedia.org/wiki/Toy_Story"}],"review":{"status":"legacy","fixes":["S53","S54"]},"kind":"term","term":{"label":"„Играта на играчките“ (Toy Story)","bg":"„Играта на играчките“","en":"Toy Story","alts":["toy story","играта на играчките","пиксар"],"def":"Първият пълнометражен анимационен филм, изцяло направен на компютър (1995); героите са каубой и космически рейнджър, които оживяват, щом хората ги няма.","ex":"Режисьор е Джон Ласетър, който получава специален „Оскар“ за постижението. Компютърът смята светлината и перспективата, но движението и актьорската игра задават аниматорите — по същите принципи като в рисуваната анимация."}},{"id":"studio.hist.bg.t01","legacyId":"t1mqsrov","hall":"studio","domain":"hist","topic":"hist.bg","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Васил Гендов","bg":"Васил Гендов","alts":["гендов","българан е галант"],"def":"Пионер на българското кино: режисьор и изпълнител на главната роля в първия български игрален филм (1915).","ex":"Гендов прави и първия български звуков филм — „Бунтът на робите“ (1933), в който сам играе Васил Левски. Във филмите му играе и съпругата му Жана Гендова."}},{"id":"studio.hist.bg.t02","legacyId":"t1iip1y3","hall":"studio","domain":"hist","topic":"hist.bg","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Тодор Динов","bg":"Тодор Динов","alts":["динов","тодор динов"],"def":"Основоположник на българската анимационна школа; режисьор на „Юнак Марко“ — първия професионален български рисуван филм, и на „Маргаритка“.","ex":"Динов търси лаконичен рисунък и философска притча вместо приказка за деца — подход, по който българската анимационна школа става разпознаваема в чужбина."}},{"id":"studio.hist.bg.t03","legacyId":"t1r3z533","hall":"studio","domain":"hist","topic":"hist.bg","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Доньо Донев","bg":"Доньо Донев","alts":["донев","тримата глупаци"],"def":"Български аниматор, майстор на сатирата и гротеската; най-известен с поредица за трима недосетливи герои.","ex":"Героите в „Тримата глупаци“ говорят на изкривен, почти неразбираем език, а музиката е от тъпан и гайда — затова филмите не се нуждаят от превод."}},{"id":"studio.hist.bg.t04","legacyId":"t18eyrlg","hall":"studio","domain":"hist","topic":"hist.bg","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"„Бунтът на робите“","bg":"„Бунтът на робите“","alts":["бунтът на робите","бунта на робите"],"def":"Първият български звуков филм (1933) на Васил Гендов — за живота и делото на Васил Левски.","ex":"Звукът променя и снимането: камерата трябва да е в звукоизолирана кутия, а актьорите да стоят близо до микрофона. Затова ранните звукови филми често изглеждат по-статични от късните неми."}},{"id":"studio.hist.bg.t05","legacyId":"t111nx9p","hall":"studio","domain":"hist","topic":"hist.bg","level":12,"subjects":["kino","anim"],"sources":[{"title":"Festival de Cannes: Jenitba","url":"https://cinemadedemain.festival-cannes.com/en/f/jenitba/"}],"review":{"status":"legacy","fixes":["S10"]},"kind":"term","term":{"label":"„Женитба“","bg":"„Женитба“","alts":["женитба"],"def":"Анимационен филм на Слав Бакалов и Румен Петков, спечелил „Златна палма“ за късометражен филм в Кан (1985).","ex":"Филмът трае около пет минути — кратката форма е силата на българската анимационна школа. Слав Бакалов по-късно преподава в Нов български университет."}},{"id":"studio.hist.bg.t06","legacyId":"tyjcm7q","hall":"studio","domain":"hist","topic":"hist.bg","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Българска анимационна школа","bg":"Българска анимационна школа","alts":["анимационна школа","българската школа"],"def":"Авторските рисувани филми у нас от 60-те до 80-те години: философски притчи, гротеска и лаконичен рисунък; основоположник е Тодор Динов.","ex":"Филмите често са кратки и разчитат повече на образа, отколкото на думите, затова се разбират навсякъде. Сред авторите са Тодор Динов, Доньо Донев, Стоян Дуков, Иван Андонов, Слав Бакалов и Румен Петков."}},{"id":"studio.hist.fest.t01","legacyId":"t18lfufd","hall":"studio","domain":"hist","topic":"hist.fest","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Кан (Cannes)","bg":"Кан","en":"Cannes","alts":["кан","cannes","palme d’or"],"def":"Международният филмов фестивал на Лазурния бряг във Франция, провеждан от 1946 г.; главната награда е „Златна палма“.","ex":"Фестивалът е замислен още за 1939 г., но откриването е отменено заради войната. „Златна палма“ е въведена през 1955 г. — дотогава главният приз се нарича Голямата награда."}},{"id":"studio.hist.fest.t02","legacyId":"t1j5qbpm","hall":"studio","domain":"hist","topic":"hist.fest","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Венеция (Venice)","bg":"Венеция","en":"Venice","alts":["венеция","venice"],"def":"Най-старият международен кинофестивал (от 1932 г.); главната награда е „Златен лъв“.","ex":"Провежда се на остров Лидо в края на лятото, а прожекциите и червеният килим са в историческия Дворец на киното."}},{"id":"studio.hist.fest.t03","legacyId":"tehdnxq","hall":"studio","domain":"hist","topic":"hist.fest","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Берлинале (Berlinale)","bg":"Берлинале","en":"Berlinale","alts":["берлин","berlinale"],"def":"Международният филмов фестивал в германската столица (от 1951 г.), който днес се провежда през февруари; главната награда е „Златна мечка“.","ex":"Мечката е символът на Берлин. Фестивалът има голям филмов пазар и програма Generation с филми за деца и тийнейджъри."}},{"id":"studio.hist.fest.t04","legacyId":"t1365o4u","hall":"studio","domain":"hist","topic":"hist.fest","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Анси (Annecy)","bg":"Анси","en":"Annecy","alts":["анси","annecy"],"def":"Най-големият фестивал за анимационно кино, във Франция (от 1960 г.); главната награда е „Кристал“.","ex":"До 1997 г. фестивалът е на всеки две години, а от 1998 г. е ежегоден. Провежда се през юни в град Анси във Френските Алпи, на брега на езеро."}},{"id":"studio.hist.fest.t05","legacyId":"t169fqfd","hall":"studio","domain":"hist","topic":"hist.fest","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"term","term":{"label":"Оскар (Academy Awards)","bg":"Оскар","en":"Academy Awards","alts":["оскар","oscar","academy awards","оскари"],"def":"Годишните награди на Американската филмова академия (от 1929 г.) — церемония, а не фестивал.","ex":"Отделна категория за пълнометражен анимационен филм има едва от 2002 г.; първият носител е „Шрек“. Преди това „Красавицата и звяра“ (1991) е номиниран дори за най-добър филм."}},{"id":"studio.lang.shots.c01","legacyId":"shot-els","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Какъв е планът в този кадър?","options":[{"text":"Общ план","why":"При общия план фигурата е цялата и заема почти цялата височина на кадъра; тук човекът е мъничък."},{"text":"Американски план","why":"Американският план реже фигурата над коленете; тук тя се вижда цялата, но е мъничка."},{"text":"Среден план","why":"Средният план реже на кръста и е близо до героя; тук мястото е много по-важно от него."},{"text":"Далечен план","why":""}],"answer":3,"explain":"Човекът заема съвсем малка част от височината на кадъра, а пейзажът доминира. Затова далечният план дава мащаб, самота или епичност — мястото е по-важно от лицето.","more":"В началото на „УОЛ-И“ малкият робот почти се губи сред кулите от боклук. Далечните планове показват колко е сам на опустялата Земя, още преди да го опознаем.","visual":{"type":"shot","params":{"p":"els"}}},{"id":"studio.lang.shots.c02","legacyId":"shot-ls","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Какъв е планът в този кадър?","options":[{"text":"Далечен план","why":"При далечния план човекът е малка точка в пейзажа; тук фигурата заема почти цялата височина на кадъра."},{"text":"Американски план","why":"Американският план реже над коленете; тук се виждат и стъпалата."},{"text":"Среден план","why":"Средният план реже на кръста; тук се вижда целият човек."},{"text":"Общ план","why":""}],"answer":3,"explain":"Рамката стига малко над главата и под стъпалата: фигурата е цялата, но още достатъчно голяма. Така се четат и позата на тялото, и мястото около героя — виждаме кой къде е.","more":"Честа грешка: рамката реже точно по стъпалата и героят сякаш стои на ръба на кадъра. Остави малко земя под краката му, за да „стъпи“ в кадъра.","visual":{"type":"shot","params":{"p":"ls"}}},{"id":"studio.lang.shots.c03","legacyId":"shot-amer","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Какъв е планът в този кадър?","options":[{"text":"Общ план","why":"Общият план показва цялата фигура заедно със стъпалата; тук краката са изрязани над коленете."},{"text":"Среден план","why":"Средният план реже по-високо — на кръста; тук се виждат и бедрата."},{"text":"Американски план","why":""},{"text":"Далечен план","why":"При далечния план човекът е малък сред пейзажа; тук фигурата е едра и изрязана."}],"answer":2,"explain":"Рамката реже малко над коленете: виждат се лицето, ръцете и бедрата. Името идва от уестърните, в които пистолетът на бедрото трябва да е в кадъра.","more":"Американският план е удобен за група: трима-четирима души един до друг се побират в кадъра, а лицата и ръцете им още се четат.","visual":{"type":"shot","params":{"p":"amer"}}},{"id":"studio.lang.shots.c04","legacyId":"shot-ms","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Какъв е планът в този кадър?","options":[{"text":"Среден план","why":""},{"text":"Американски план","why":"Американският план реже по-ниско — над коленете; тук рамката минава през кръста."},{"text":"Близък план","why":"Близкият план реже по-високо — на гърдите; тук се вижда тялото до кръста."},{"text":"Общ план","why":"Общият план показва цялата фигура; тук краката не се виждат."}],"answer":0,"explain":"Рамката реже около кръста, затова лицето и ръцете се виждат еднакво добре. Зрителят чете едновременно изражението и жестовете — затова средният план е основен за разговор и действие.","more":"Опитай: снимай съученик, който обяснява нещо с ръце, веднъж в среден и веднъж в крупен план. В крупния жестовете изчезват и част от смисъла се губи.","visual":{"type":"shot","params":{"p":"ms"}}},{"id":"studio.lang.shots.c05","legacyId":"shot-mcu","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Какъв е планът в този кадър?","options":[{"text":"Среден план","why":"Средният план реже по-ниско — на кръста; тук рамката минава през гърдите."},{"text":"Крупен план","why":"При крупния план лицето изпълва кадъра; тук се виждат още раменете и гърдите."},{"text":"Близък план","why":""},{"text":"Американски план","why":"Американският план стига до коленете; тук се вижда само горната част на тялото."}],"answer":2,"explain":"Рамката реже на гърдите: лицето вече е главното, но раменете и началото на жеста още се виждат. Затова близкият план е чест избор за разговор, в който думите са по-важни от действието.","more":"Когато двама разговарят в близки планове, дръж еднакъв размер за двамата. Ако единият е по-едър в кадъра, зрителят несъзнателно ще го приеме за по-важен.","visual":{"type":"shot","params":{"p":"mcu"}}},{"id":"studio.lang.shots.c06","legacyId":"shot-cu","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Какъв е планът в този кадър?","options":[{"text":"Близък план","why":"Близкият план включва и гърдите; тук долният ръб минава около шията."},{"text":"Детайл","why":"Детайлът показва само част от лицето, например очите; тук се вижда цялото лице."},{"text":"Среден план","why":"Средният план стига до кръста; тук тялото почти не се вижда."},{"text":"Крупен план","why":""}],"answer":3,"explain":"Лицето изпълва кадъра и няма нищо друго, към което да отиде окото. Изражението става толкова голямо, че емоцията се превръща в главното събитие на сцената.","more":"Громит от „Уолъс и Громит“ няма уста, но крупните планове на очите и веждите му разказват всичко. Аниматорите от Aardman предават емоцията само с тях.","visual":{"type":"shot","params":{"p":"cu"}}},{"id":"studio.lang.shots.c07","legacyId":"shot-ecu","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Какъв е планът в този кадър?","options":[{"text":"Крупен план","why":"Крупният план показва цялото лице; тук устата и брадичката са извън кадъра."},{"text":"Детайл","why":""},{"text":"Близък план","why":"Близкият план показва главата и гърдите; тук се виждат само очите."},{"text":"Среден план","why":"Средният план показва тялото до кръста; тук е изрязано дори лицето."}],"answer":1,"explain":"В кадъра са само очите — по-малко от цялото лице. Детайлът изрязва всичко друго, затова зрителят няма избор къде да гледа и подробността става едно-единствено усещане или улика.","more":"В последния дуел на „Добрият, лошият и злият“ Серджо Леоне редува детайли на очите с далечни планове на гробището. Скокът между двете крайности засилва напрежението.","visual":{"type":"shot","params":{"p":"ecu"}}},{"id":"studio.lang.shots.c08","legacyId":"shot-ots","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Как се нарича този кадър в диалог?","options":[{"text":"Засечка през рамо","why":""},{"text":"Кадър от гледна точка","why":"Кадърът от гледна точка е през очите на героя и неговото рамо не се вижда; тук то е в преден план."},{"text":"Среден план","why":"„Среден план“ казва само докъде реже кадърът; тук важното е, че гледаме над рамото на другия."},{"text":"Установяващ план","why":"Установяващият план показва мястото и всички в него; тук виждаме само двамата отблизо."}],"answer":0,"explain":"Тилът и рамото на единия събеседник в преден план показват, че той е там и слуша, а другият гледа към него. Така двамата остават свързани и посоката на погледите е ясна.","more":"Рамото в преден план трябва да рамкира, а не да закрива: остави лицето на говорещия свободно и не позволявай тилът да застъпва носа или устата му.","visual":{"type":"shot","params":{"p":"ots"}}},{"id":"studio.lang.shots.c09","legacyId":"cgx3g7y","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди плановете от най-широкия към най-тесния.","sequence":["Далечен план","Общ план","Американски план","Среден план","Близък план","Крупен план","Детайл"],"explain":"Всяка стъпка приближава зрителя: от мястото към човека, от тялото към лицето, от лицето към детайла. Ориентир е линията, на която рамката реже тялото.","more":"Названията на плановете не са съвсем единни — в различни книги и държави един и същ кадър може да се нарича различно. При съмнение описвай докъде реже рамката."},{"id":"studio.lang.shots.c10","legacyId":"c17ypyzt","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Героинята отваря писмо, което обръща живота ѝ. Искаш зрителят първо да прочете какво пише, а после да види как реагира тя. Коя двойка кадри избираш?","options":[{"text":"Среден план с писмото в ръката → детайл на очите","why":"В среден план писмото е твърде малко, за да се прочете — информацията се губи още в първия кадър."},{"text":"Крупен план на лицето → детайл на писмото","why":"Редът е обърнат: зрителят вижда реакцията, преди да знае причината."},{"text":"Детайл на писмото → крупен план на лицето","why":""},{"text":"Кадър през рамото ѝ към писмото → общ план на стаята","why":"Първият кадър може да покаже писмото, но общият план отдалечава точно в момента на реакцията."}],"answer":2,"explain":"„Информация → реакция“ е основна монтажна двойка: детайлът показва уликата, крупният план — емоцията. Зрителят първо разбира какво се е случило, после го съпреживява.","more":"Кадър отблизо на предмет от действието, като писмото, в монтажа се нарича Insert shot. Дръж го на екрана поне толкова, колкото ти трябва да прочетеш текста на глас."},{"id":"studio.lang.shots.c11","legacyId":"c1vuwjsw","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Първи кадър на сцена в кафене. Зрителят трябва веднага да разбере къде се намират двамата герои и как седят един спрямо друг. Кой кадър избираш?","options":[{"text":"Далечен план (Extreme long shot)","why":"Далечният план показва мястото, но героите са толкова малки, че не се разбира как седят."},{"text":"Засечка през рамо (Over-the-shoulder shot)","why":"Засечката показва единия през рамото на другия, но не и мястото; тя идва след ориентацията."},{"text":"Детайл (Extreme close-up)","why":"Детайлът създава загадка, а не ориентация; става за начало само като съзнателен избор."},{"text":"Установяващ план (Establishing shot)","why":""}],"answer":3,"explain":"Установяващият план отговаря на въпросите „къде“ и „кой къде е“, преди сцената да влезе в по-близките планове. След като зрителят има карта на мястото, засечките и крупните планове не го объркват.","more":"Установяващият план показва и линията между двамата герои. Ако после камерата мине от другата ѝ страна, героите сякаш сменят местата си — затова се спазва правилото 180° (180-degree rule)."},{"id":"studio.lang.shots.c12","legacyId":"c9m2bis","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Сцена с двама събеседници. Режисьорът показва един общ план в началото, а после до края редува само крупни планове на двамата. Какъв е основният риск?","options":[{"text":"Губи се пространството, а крупният план спира да изпъква, защото няма контраст","why":""},{"text":"Нарушава се правилото 180°, защото камерата сменя страната при всяко срязване","why":"Редуването на крупни планове не нарушава правилото 180°, ако камерата остава от едната страна на оста."},{"text":"Зрителят вижда твърде много от мястото и вниманието се разсейва от лицата","why":"Обратното: крупните планове показват твърде малко от мястото, а не твърде много."},{"text":"Ритъмът става бавен, защото крупните планове изискват дълги кадри","why":"Дължината на кадъра зависи от монтажа, не от плана; крупните планове може да се режат бързо."}],"answer":0,"explain":"Крупният план действа чрез контраст: ако всичко е крупно, нищо не изпъква. А без по-широки планове зрителят забравя кой къде седи. Връщай се към по-широк план, когато сцената се обръща.","more":"В storyboard това се проверява с „Разнообразие на кадрите (Shot variety)“: подреди миниатюрите една до друга и виж дали размерите на плановете се сменят."},{"id":"studio.lang.shots.c13","legacyId":"cycxst7","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"explain","prompt":"Обясни на съученик защо цял филм, заснет само в среден план, ще бъде слаб.","checklist":["Няма мащаб и ориентация, защото липсват общите планове","Няма емоционален акцент, защото липсват крупните планове и детайлите","Ритъмът е монотонен: смяната на плана е като смяната на силата на гласа","Размерът на плана носи значение, а не е само разстояние"],"model":"Общият план казва къде сме, крупният — какво чувстваме, детайлът — какво е важно. Ако всичко е в среден план, зрителят не знае кое е главното и кога сцената се засилва. Филмът звучи като човек, който говори с един и същ тон.","more":"Провери свой клип: запиши размера на всеки кадър един след друг — общ, среден, крупен… Ако дълга поредица е с един и същ размер, там зрителят вероятно ще започне да се отегчава."},{"id":"studio.lang.shots.c14","legacyId":"cur2cza","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Откъде идва името „американски план“?","options":[{"text":"От ранния Холивуд: кадърът побира двама актьори в цял ръст","why":"Кадър с двама актьори в цял ръст е общ план; американският реже фигурата около коленете."},{"text":"От американските новини: водещият се вижда до кръста зад бюрото","why":"Кадърът до кръста е среден план; американският е по-широк и стига до бедрото или коленете."},{"text":"От мюзикълите: краката на танцьорите остават в кадъра","why":"Американският план реже над коленете — краката не се виждат, така че не би показал танца."},{"text":"От уестърните: кадърът трябва да покаже пистолета на бедрото","why":""}],"answer":3,"explain":"Терминът е френски — plan américain. Френските критици го свързват с холивудските уестърни, в които ръката до кобура е част от действието и трябва да се вижда.","more":"Пробвай с телефона: снимай съученик, който вади телефон от джоба си, веднъж в среден и веднъж в американски план. В средния ръката излиза от кадъра и действието се губи."},{"id":"studio.lang.angle.c01","legacyId":"c1qbgq59","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy","fixes":["P06"]},"kind":"card","format":"visual","prompt":"Камерата е поставена така спрямо героя. Какво най-вероятно внушава кадърът?","options":[{"text":"Героят изглежда малък и уязвим","why":"Малък и уязвим изглежда героят при горен ракурс; тук камерата е под него и гледа нагоре."},{"text":"Героят изглежда равен на зрителя","why":"Равенство дава камерата на нивото на очите; тук тя е ниско и гледа нагоре."},{"text":"Героят изглежда силен и заплашителен","why":""},{"text":"Героят изглежда объркан и неспокоен","why":"Объркване внушава наклоненият хоризонт (холандски ъгъл), а не височината на камерата."}],"answer":2,"explain":"Камерата е под нивото на очите и гледа нагоре — това е долен ракурс. Зрителят гледа героя отдолу, както дете гледа възрастен, затова той изглежда по-голям и по-силен.","more":"В „Гражданинът Кейн“ (1941) камерата често е толкова ниско, че в кадъра влизат таваните. Затова декорите са построени с тавани — нещо необичайно за студията тогава.","visual":{"type":"angle","params":{"p":"low"}}},{"id":"studio.lang.angle.c02","legacyId":"c5bz8ul","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Камерата е поставена така спрямо героя. Как се нарича ракурсът и какво внушава?","options":[{"text":"Долен ракурс — сила и превъзходство","why":"При долен ракурс камерата е под очите и гледа нагоре; тук тя е над героя и гледа надолу."},{"text":"Нормален ъгъл — неутрално наблюдение","why":"При нормален ъгъл камерата е на височината на очите и гледа право; тук гледа отвисоко."},{"text":"Горен ракурс — уязвимост и малкост","why":""},{"text":"Холандски ъгъл — тревога и нестабилност","why":"Холандският ъгъл е наклонен хоризонт; тук хоризонтът е прав, а камерата е високо."}],"answer":2,"explain":"Камерата е над очите на героя и гледа надолу, затова зрителят буквално го „гледа отвисоко“. Героят изглежда по-малък и сякаш притиснат към земята.","more":"Горният ракурс може да е и чужд поглед — от прозорец, балкон или охранителна камера. Тогава зрителят усеща, че героят е наблюдаван, без самият той да знае.","visual":{"type":"angle","params":{"p":"high"}}},{"id":"studio.lang.angle.c03","legacyId":"c131t0r0","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Как се нарича този кадър и какво внушава?","options":[{"text":"Холандски ъгъл — нестабилност, тревога","why":""},{"text":"Горен ракурс — уязвимост","why":"При горен ракурс камерата гледа надолу; тук тя е на височината на героя, но е наклонена настрани."},{"text":"Птичи поглед — сцената като карта","why":"Птичият поглед е точно отгоре и превръща сцената в карта; тук героят е видян отпред."},{"text":"Нормален ъгъл — неутралност","why":"При нормален ъгъл хоризонтът е прав; тук линиите на стаята са накриво."}],"answer":0,"explain":"Вертикалите на стаята и прозорецът са накриво, макар героят да е в обикновен среден план. Окото очаква прав хоризонт, затова кривият свят изглежда нестабилен — подходящ за объркване, лудост, опасност.","more":"Наклонените кадри в „Третият човек“ (1949) са толкова много, че режисьорът Уилям Уайлър изпраща на Карол Рийд нивелир с бележка: следващия път да го сложи върху камерата.","visual":{"type":"shot","params":{"p":"dutch"}}},{"id":"studio.lang.angle.c04","legacyId":"cvg4cpj","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Ученик, когото тормозят, стои срещу трима по-големи. Искаш зрителят да изпита страха му. Как снимаш тримата?","options":[{"text":"Горен ракурс, за да се видят и тримата","why":"Горният ракурс ги смалява: побира тримата, но им отнема заплахата."},{"text":"Долен ракурс от височината на ученика","why":""},{"text":"Нормален ъгъл от височината на тримата","why":"Камерата на тяхната височина прави зрителя равен на тях, а не на ученика."},{"text":"Птичи поглед над цялата група","why":"Птичият поглед превръща сцената в карта и отдалечава зрителя от страха."}],"answer":1,"explain":"Височината на камерата е гледна точка. Когато камерата е на нивото на ученика и гледа нагоре, зрителят застава на негово място и тримата се извисяват и над него.","more":"Не прекалявай: силно долен ракурс отблизо с широкоъгълен обектив изкривява лицата и сцената може да стане смешна вместо страшна. Често стига камерата да е малко под очите."},{"id":"studio.lang.angle.c05","legacyId":"clud4ap","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи ракурса с най-честото му внушение.","pairs":[["Долен ракурс","Сила, заплаха, монументалност"],["Горен ракурс","Уязвимост, самота"],["Холандски ъгъл","Нестабилност, тревога"],["Птичи поглед","Сцената като карта или шаблон"],["Нормален ъгъл","Равнопоставеност със зрителя"]],"explain":"Ракурсът поставя зрителя в отношение към героя: щом гледаме нагоре, героят е над нас; щом гледаме надолу — под нас. Това са тенденции, а не закони: контекстът може да обърне значението.","more":"В storyboard ракурсът личи по линията на хоризонта (Horizon line): при долен ракурс тя е ниско в кадъра или под него, а при горен — високо или над него."},{"id":"studio.lang.angle.c06","legacyId":"ce6bb92","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"В анимационен сериал камерата стои на височината на детето, а възрастните се виждат само до кръста. Защо?","options":[{"text":"Детето е снимано отдолу, за да изглежда силно","why":"Камерата е на височината на детето, а не под него — за детето това е нормален ъгъл."},{"text":"Подчертава, че възрастните командват, а детето е второстепенно","why":"Обратното: възрастните без глави стават фон, а детето е в центъра на света."},{"text":"Светът е показан от гледната точка на детето","why":""},{"text":"Пести се анимация на лицата и продукцията е по-бърза","why":"Може и да пести работа, но основната причина е разказвателна — чий е този свят."}],"answer":2,"explain":"Височината на камерата избира чий е светът. Щом обективът е на нивото на детето, възрастните „без глави“ стават част от обстановката, а детските грижи и игри — главното.","more":"Подобно е в класическите „Том и Джери“: жената в къщата почти винаги се вижда само от кръста надолу, защото светът е на котката и мишката."},{"id":"studio.lang.comp.c01","legacyId":"c180x6ud","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"И в двата кадъра героят гледа надясно. Кой кадър създава усещане за притиснатост и защо?","options":[{"text":"Б — пред погледа на героя няма място","why":""},{"text":"А — героят не е в центъра на кадъра","why":"Героят встрани от центъра не е грешка: в А пред погледа му има място и кадърът „диша“."},{"text":"Нито един — кадрите са равностойни","why":"Не са равностойни: в Б лицето почти опира в десния ръб, а в А пред него има място."},{"text":"Б — над главата има твърде много въздух","why":"Над главата и в двата кадъра има еднакво място; разликата е пред лицето."}],"answer":0,"explain":"Зрителят проследява погледа на героя. В Б погледът веднага се удря в ръба, затова кадърът изглежда затворен. Пространството за поглед оставя място, където мисълта на героя „отива“.","more":"Нарушението може да е съзнателно: ако празното място е зад гърба на героя, а не пред лицето му, зрителят очаква нещо да се появи там — похват от филмите на ужасите.","visual":{"type":"leadroom"}},{"id":"studio.lang.comp.c02","legacyId":"c1e4b8rx","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Портрет: героят е в центъра, а хоризонтът минава през средата на кадъра. Кадърът изглежда статичен. Какво променяш първо?","options":[{"text":"Накланям хоризонта, за да влезе движение в кадъра","why":"Наклонът добавя тревога, която портретът може да не иска; първо реши разположението."},{"text":"Приближавам до крупен план, за да изпълни кадъра","why":"По-близкият план сменя смисъла на кадъра, но не решава централното разположение."},{"text":"Оставям повече въздух над главата, за да диша","why":"Повече въздух над главата смалява героя и прави кадъра още по-празен."},{"text":"Местя героя и хоризонта към линиите на третините","why":""}],"answer":3,"explain":"Третините делят кадъра на неравни части и окото започва да се движи между пълното и празното. Централната композиция е силна, когато е съзнателна — симетрия, ред, изолация.","more":"Включи мрежата в настройките на камерата на телефона. Сложи хоризонта на горната линия, когато земята е по-интересна, и на долната — когато небето е по-интересно."},{"id":"studio.lang.comp.c03","legacyId":"c1l913dq","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","prompt":"Назови три начина да насочиш погледа на зрителя към героя, без да сменяш осветлението.","checklist":["Водещи линии, които отвеждат към героя","Рамка в рамката (врата, прозорец, огледало)","Плитка дълбочина на рязкост — героят е рязък, фонът не","Контраст на размер или цвят (цветен акцент)","Позиция в пресечна точка на третините","Движение — окото следва това, което се движи"],"model":"Например: пътят в кадъра води към героя, той стои в рамката на вратата и е единственото рязко нещо в кадъра. Може и цветен акцент — само той е в червено.","more":"Провери с присвити очи: детайлите изчезват и остават само петната. Ако героят не е петното, което хваща окото първо, композицията още не го насочва към него."},{"id":"studio.lang.comp.c04","legacyId":"c1srow35","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Близък план: очите на героя са в долната половина на кадъра, а над главата му остава много празно. Как поправяш кадъра?","options":[{"text":"Оставям празното — то показва, че героят е свободен","why":"Празното над главата в близък план не внушава свобода — героят сякаш потъва надолу."},{"text":"Минавам на по-широк план, за да се запълни празното","why":"По-широкият план смалява героя и празното става още по-голямо."},{"text":"Центрирам лицето, за да са очите точно в средата","why":"Очите в средата също изглеждат ниско; в близките планове те стоят около горната трета."},{"text":"Режа горе, докато очите стигнат горната линия на третините","why":""}],"answer":3,"explain":"Зрителят гледа първо очите, затова те са опорната точка на кадъра. Щом ги вдигнеш до горната третина, празното отгоре изчезва и лицето застава там, където окото естествено го търси.","more":"При интервю провери кадъра в движение: помоли човека да се наведе напред и назад. Главата не бива да излиза от рамката при естествено движение."},{"id":"studio.lang.comp.c05","legacyId":"cdnymh3","hall":"studio","domain":"lang","topic":"lang.comp","topic2":"anim.principles","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо аниматорите проверяват позата като черен силует?","options":[{"text":"Ако позата е ясна като петно, жестът ще се чете и на екрана","why":""},{"text":"Така се проверява дали пропорциите на героя са анатомично верни","why":"Силуетът не показва анатомия; той проверява дали жестът и действието се четат."},{"text":"Така се вижда откъде пада светлината и къде са сенките","why":"Черното петно премахва светлината и сенките — остава само формата."},{"text":"Така се проверява дали героят се откроява по цвят от фона","why":"Силуетът няма цвят; той проверява формата, не контраста на цветовете."}],"answer":0,"explain":"Силуетът е проверка за сценичността (Staging): ръка, скрита пред тялото, изчезва в петното и жестът се губи. Затова ръцете се държат встрани от тялото, така че между тях и торса да се вижда празно място.","more":"Добрият герой се познава и само по силуета: трите кръга на главата и ушите на Мики Маус се разпознават дори като черно петно."},{"id":"studio.lang.comp.c06","legacyId":"cikgzdk","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Героят се чувства като в капан в собствения си дом. Как ще го подчертаеш с композицията?","options":[{"text":"Далечен план: героят е малък сред празния двор пред къщата","why":"Празният двор внушава самота, но е извън дома — капанът е вътре, в стените."},{"text":"Рамка в рамката: касите на вратите го затварят отвсякъде","why":""},{"text":"Холандски ъгъл: наклоненият хоризонт показва, че е объркан","why":"Наклонът показва тревога, но не и затварянето в пространството."},{"text":"Крупен план: лицето изпълва кадъра и показва паниката","why":"Крупният план показва чувството, но изрязва пространството, което го притиска."}],"answer":1,"explain":"Рамките в кадъра — каси, прозорци, решетки — работят като визуална клетка: героят е затворен в още един правоъгълник вътре в кадъра. Стените на дома буквално го обграждат.","more":"Рамката може и да изключва: в края на „Следотърсачите“ (1956) Джон Форд показва героя през вратата от тъмната къща — той остава навън, далеч от дома и семейството."},{"id":"studio.lang.pov.c01","legacyId":"c15nctdn","hall":"studio","domain":"lang","topic":"lang.pov","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Героят е замаян: образът се размазва и люлее, звуците заглъхват. Какъв похват е това?","options":[{"text":"Кадър от гледна точка (POV shot)","why":"Кадърът от гледна точка показва накъде гледа героят; тук е изкривено и как го преживява."},{"text":"Субективна камера (Subjective camera)","why":""},{"text":"Холандски ъгъл (Dutch angle)","why":"Наклонът внушава тревога, но не размазва образа и не заглушава звука."},{"text":"Обективна камера (Objective camera)","why":"Обективната камера гледа отстрани и не предава състоянието на героя."}],"answer":1,"explain":"Размазването, люлеенето и заглъхналият звук не съществуват в света на филма — те са в главата на героя. Субективната камера предава не само мястото, от което гледа той, а и състоянието му.","more":"Субективната камера може да изкриви и времето: забавеният каданс (Slow motion) показва миг, който за героя сякаш трае вечно — например падане."},{"id":"studio.lang.pov.c02","legacyId":"c15xqwwo","hall":"studio","domain":"lang","topic":"lang.pov","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Каква е разликата между кадър от гледна точка и субективна камера?","options":[{"text":"Първият се снима с ръчна камера, а вторият — от статив","why":"И двата се снимат по всякакъв начин; разликата е какво предават, не с какво се снимат."},{"text":"Първият показва героя отстрани, а вторият — през неговите очи","why":"Отстрани гледа обективната камера; кадърът от гледна точка е през очите на героя."},{"text":"Първият е крупен план, а вторият — общ план на мястото","why":"Размерът на плана не ги определя — и двата може да са широки или близки."},{"text":"Първият показва какво вижда героят, а вторият — и как го преживява","why":""}],"answer":3,"explain":"Кадърът от гледна точка е „през очите“: показва накъде и към какво гледа героят. Субективната камера отива по-навътре — може да изкриви образа, звука и времето според чувствата му.","more":"В игрите от първо лице камерата е постоянно в кадър от гледна точка. Когато героят е ранен и екранът се размаже или почервенее, това вече е субективна камера."},{"id":"studio.lang.pov.c03","legacyId":"cqhr6ov","hall":"studio","domain":"lang","topic":"lang.pov","topic2":"story.irony","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Искаш зрителят да се плаши заедно с героинята в тъмния коридор, а не да се страхува за нея. Как снимаш?","options":[{"text":"Само от нейната гледна точка — знаем колкото нея","why":""},{"text":"Широк план, в който виждаме убиеца зад гърба ѝ","why":"Така зрителят знае повече от нея: това е страх за нея, а не заедно с нея."},{"text":"Птичи поглед над коридора, за да се види капанът","why":"Отгоре зрителят вижда повече от героинята и е дистанциран от страха ѝ."},{"text":"Детайл на часовник, който отброява секундите","why":"Часовникът добавя срок и напрежение, но не поставя зрителя на нейно място."}],"answer":0,"explain":"Кой какво знае решава вида на страха. Щом зрителят вижда само това, което вижда и героинята, опасността го изненадва в същия миг. Ако знае повече от нея, страхът се превръща в напрежение за нея.","more":"Хичкок обяснява разликата с бомба под масата: ако избухне внезапно, зрителят получава секунди изненада (Surprise); ако знае за нея отрано — минути напрежение (Suspense)."},{"id":"studio.lang.pov.c04","legacyId":"cm57igy","hall":"studio","domain":"lang","topic":"lang.pov","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"explain","prompt":"Как ще покажеш, че влизащият герой е важен, още преди да е казал дума?","checklist":["Подготовка: другите говорят за него или гледат към вратата","Разкриване чрез движение на камерата или фокуса","Ракурс и размер на плана подчертават статуса","Звук или музика го „обявяват“","Характерна поза или детайл (обувки, ръка, предмет)"],"model":"Първо другите замлъкват и гледат към вратата. Виждаме само обувките му в детайл, после камерата бавно се издига до лицето в долен ракурс. Появата е подготвена и затова тежи.","more":"В „Карибски пирати: Проклятието на Черната перла“ Джак Спароу пристига гордо изправен на мачтата на потъваща лодка и стъпва на кея точно когато тя изчезва под водата. Появата казва всичко за него."},{"id":"studio.lang.pov.c05","legacyId":"cpoqafg","hall":"studio","domain":"lang","topic":"lang.pov","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Камерата бавно се отдръпва от усмихнатото момиче и накрая виждаме, че тя стои сама на празен стадион. Какво постига това движение?","options":[{"text":"Ориентира зрителя в мястото в началото на сцената","why":"Ориентирането е задача на установяващия план в началото; тук мястото идва накрая и променя смисъла."},{"text":"Последната нова информация обръща смисъла на кадъра","why":""},{"text":"Замайва зрителя, защото фонът зад героинята се разтяга","why":"Разтягане на фона дава вертиго ефектът (Dolly zoom); тук камерата просто се отдалечава."},{"text":"Въвежда героинята за първи път пред зрителя","why":"Героинята вече е в кадъра — новото е мястото около нея, не тя."}],"answer":1,"explain":"Това е разкриване (Reveal): докато кадърът е тесен, зрителят тълкува усмивката по един начин. Щом отдръпването покаже празния стадион, същата усмивка става самотна.","more":"Движението назад се нарича отдалечаване на камерата (Pull out). Разкриване можеш да направиш и без движение — с прехвърляне на фокуса (Rack focus) от предния към задния план."},{"id":"studio.edit.space.c01","legacyId":"c95yc7k","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Кадри от позиции 1 и 2 вече са в монтажа на диалога. Коя позиция нарушава правилото 180°?","options":[{"text":"1","why":"Позиция 1 е от същата страна на оста като 2 — кадрите от нея пазят посоките."},{"text":"2","why":"Позиция 2 е от същата страна като 1: и в двата кадъра А гледа надясно, а Б — наляво."},{"text":"Никоя","why":"Позиция 3 е от другата страна на оста — срязване към нея обръща посоките."},{"text":"3","why":""}],"answer":3,"explain":"Позиции 1 и 2 са от една и съща страна на оста, затова в кадрите им А винаги гледа надясно, а Б — наляво. Позиция 3 е от другата страна: при срязване към нея двамата сменят местата си на екрана.","more":"Преди снимки начертай сцената отгоре като тази схема — героите, оста и всички позиции на камерата. Така целият екип вижда къде е безопасната страна, още преди да е поставен статив.","visual":{"type":"axis"}},{"id":"studio.edit.space.c02","legacyId":"c9jr9uz","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Какво ще види зрителят, ако срежеш от кадъра на камера 1 към кадъра на камера 3?","options":[{"text":"Героите остават по местата си, само фонът е друг","why":"От другата страна на оста ляво и дясно се разменят: който е бил вляво, изведнъж е вдясно."},{"text":"Срязването е невидимо, защото ъгълът е над 30°","why":"Правилото 30° е спазено, но камерата е минала оста — посоките се обръщат и срязването се забелязва."},{"text":"Героите сякаш сменят местата си на екрана","why":""},{"text":"Получава се неутрален кадър без посока","why":"Неутрален е кадърът по самата ос; камера 3 гледа напреко на оста, от другата ѝ страна."}],"answer":2,"explain":"Камера 3 е от другата страна на оста, а оттам ляво и дясно са огледално обърнати. Затова героят, който в кадъра на камера 1 е вляво, в кадъра на камера 3 е вдясно — и зрителят губи ориентация.","more":"Проверка при преглед на материала: следи накъде гледа един и същ герой в поредните кадри. Щом посоката му се смени без причина, търси кадъра, сниман от другата страна на оста.","visual":{"type":"axis"}},{"id":"studio.edit.space.c03","legacyId":"c3628fd","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Засечка в диалог. Кадър 1: А е вляво и гледа надясно към Б. Кадър 2: Б също гледа надясно. Какво не е наред?","options":[{"text":"Нарушено е правилото 30°, защото ъглите са твърде близки","why":"Правилото 30° е за два кадъра на един и същ обект; тук проблемът е в посоката на погледите."},{"text":"Липсва установяващ план, затова посоките се объркват","why":"Установяващ план помага, но и с него погледите в една посока ще изглеждат грешно."},{"text":"Кадрите са наред — в засечка двамата гледат в една посока","why":"В засечка погледите сочат един към друг: единият надясно, другият наляво."},{"text":"Камерата е прескочила оста и погледите не се срещат","why":""}],"answer":3,"explain":"А гледа надясно, значи Б трябва да гледа наляво, за да изглежда, че се гледат. Щом и Б гледа надясно, втората камера е минала от другата страна на оста и зрителят вижда двама души, които гледат в една посока.","more":"Японският режисьор Ясуджиро Озу често не се съобразява с оста: в разговорите му камерата минава от двете страни и погледите не винаги се срещат. При него това е съзнателен стил, а не грешка."},{"id":"studio.edit.space.c04","legacyId":"c1fpqklh","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Кадър 1: среден план на героинята. Кадър 2: същата героиня в почти същия размер, но камерата е преместена само с 10°. Какво ще се получи?","options":[{"text":"Образът ще подскочи, защото е нарушено правилото 30°","why":""},{"text":"Посоките ще се обърнат, защото е нарушено правилото 180°","why":"10° встрани не прекосяват оста; посоката на погледа остава същата."},{"text":"Срязването ще е невидимо, защото кадрите са почти еднакви","why":"Точно обратното: почти еднаквите кадри правят срязването да изглежда като грешка."},{"text":"Героинята ще изглежда по-голяма, защото планът се сменя","why":"Размерът е почти същият — затова срязването изглежда като подскок, а не като нов кадър."}],"answer":0,"explain":"При 10° и почти същия размер окото не възприема нов кадър, а вижда как същият образ леко подскача — като изрязано парче. Смяната трябва да е ясна: ъгъл поне 30° или отчетливо различен план.","more":"Същият подскок понякога се търси нарочно — тогава се нарича прескачащ монтаж (Jump cut). Разликата е в намерението: когато не е нарочно, зрителят го приема като грешка."},{"id":"studio.edit.space.c05","legacyId":"c1et4bob","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кое от тези прави прескачането на оста оправдано?","options":[{"text":"Когато в сцената участват повече от двама герои","why":"С повече герои има повече оси, но правилото важи за всяка от тях."},{"text":"Когато и двамата герои са заснети в крупни планове","why":"И в крупни планове посоката на погледите се обръща и зрителят се обърква."},{"text":"Когато зрителят вижда как камерата минава през оста","why":""},{"text":"Когато срязването е в движение и окото не го забелязва","why":"Срязването в движение крие шева, но не и обърнатите посоки."}],"answer":2,"explain":"Когато камерата мине през оста в самия кадър — с шарийо или ръчна камера, — зрителят проследява движението и сам обновява представата си за пространството. Други оправдани случаи: неутрален кадър по оста или нарочно смущение в силен момент.","more":"Оста може да се премести и от самите герои: ако единият обиколи другия и застане от отсрещната му страна, линията между тях се завърта и камерата може спокойно да ги последва."},{"id":"studio.edit.space.c06","legacyId":"c1trtdwv","hall":"studio","domain":"edit","topic":"edit.space","topic2":"board.notation","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Сценарият казва: „Героят бърза към гарата, без да спира.“ Какъв е проблемът в тези два панела?","options":[{"text":"Героят трябва да върви към камерата, не встрани","why":"Страничният кадър е удобен за ходене; важното е посоката в двата панела да е една и съща."},{"text":"Героят сменя посоката и изглежда, че се връща","why":""},{"text":"Героят излиза от кадъра, вместо да остане в него","why":"Излизането от кадъра е нормална връзка между два кадъра; бедата е, че героят влиза отново от същата страна."},{"text":"В панел 2 героят е твърде близо до ръба на кадъра","why":"Героят тъкмо влиза в кадъра, затова е до ръба — това е нормално; проблемът е накъде върви."}],"answer":1,"explain":"В панел 1 героят излиза вдясно, а в панел 2 влиза отново отдясно и върви наляво — зрителят чете това като обратен път. За да продължи към гарата, той трябва да влезе отляво. Стрелките в storyboard улавят такава грешка още на хартия.","more":"Честа грешка при снимане на ходене: операторът сменя страната спрямо пътя на героя от кадър на кадър. Реши предварително от коя страна на пътя ще е камерата и я пази до края на сцената.","visual":{"type":"direction"}},{"id":"studio.edit.space.c07","legacyId":"c1mp035d","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"В много филми героят напредва към целта отляво надясно, а когато го отблъскват, бяга отдясно наляво. Защо това работи?","options":[{"text":"Посоката носи смисъл: движението надясно се чете като напредване","why":""},{"text":"Окото чете отдясно наляво, затова бягството изглежда по-бързо","why":"Зрителите, които четат отляво надясно, усещат движението надясно като напред — не обратното."},{"text":"Така се спазва правилото 30° между два поредни кадъра","why":"Правилото 30° е за ъгъла между кадрите, а не за посоката на движение."},{"text":"Движението наляво подсказва, че героят крие нещо","why":"Посоката не носи морален смисъл; тя се чете като напредване или отстъпление."}],"answer":0,"explain":"Свикнали сме да четем и да следим поредици отляво надясно, затова движението надясно често се усеща като напредване, а наляво — като връщане или съпротива. Това е тенденция, не закон, но е силен инструмент.","more":"Опитай: заснеми съученик, който върви надясно, после наляво, и покажи двата клипа на други хора. Попитай кой изглежда, че отива към целта, и кой — че се прибира."},{"id":"studio.edit.cuts.c01","legacyId":"c7z6fd3","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кадър 1: ръката натиска дръжката на вратата. Кадър 2: от стаята виждаме как вратата се отваря в същия миг. Как се нарича тази връзка?","options":[{"text":"Графично съвпадение (Match cut)","why":"Графичното съвпадение свързва две различни неща по форма; тук е едно и също действие от две места."},{"text":"Кадър – контракадър (Shot/reverse shot)","why":"Кадър – контракадър редува двама събеседници; тук няма диалог, а едно продължаващо действие."},{"text":"Съвпадение по действие (Match on action)","why":""},{"text":"Паралелен монтаж (Cross-cutting)","why":"Паралелният монтаж редува различни действия на различни места; тук действието е едно."}],"answer":2,"explain":"Действието започва в единия кадър и завършва в другия без пауза. Вниманието следи ръката и вратата, затова смяната на гледната точка остава незабелязана.","more":"При снимане повтаряй цялото движение и в двата кадъра — от натискането на дръжката до отварянето. Така в монтажа ще избереш най-точния миг за срязване."},{"id":"studio.edit.cuts.c02","legacyId":"c70q4u","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кога съзнателно ще използваш прескачащ монтаж (jump cut)?","options":[{"text":"За да скриеш грешка в непрекъснатостта на кадрите","why":"Прескачащият монтаж подчертава срязването — грешката той не скрива, а показва."},{"text":"За да направиш монтажа гладък и невидим","why":"Той е видим по природа; невидим е класическият монтаж по действие."},{"text":"За да внушиш нервност или бързо изтичащо време","why":""},{"text":"За да свържеш два героя на различни места","why":"Това е паралелен монтаж; прескачащият реже в един и същ кадър."}],"answer":2,"explain":"Прескачащият монтаж е видим по природа: образът подскача и зрителят усеща, че нещо е изрязано. Затова работи там, където накъсаният ритъм е самият смисъл на сцената.","more":"Опитай: заснеми се как чакаш автобуса две минути от една и съща позиция, после изрежи пет-шест парчета. За десет секунди прескачащият монтаж ще разкаже нетърпението."},{"id":"studio.edit.cuts.c03","legacyId":"chpq4jf","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Трябва да покажеш, че между две сцени е минала цяла година. Кой вариант е най-ясен?","options":[{"text":"Прескачащ монтаж на героя, който върви по улицата","why":"Прескачащият монтаж съкращава минути от едно действие, а не година."},{"text":"Стрелки на часовник, които се въртят все по-бързо","why":"Въртящите се стрелки внушават часове; няма знак за сезон или възраст."},{"text":"Преливане през четирите сезона на едно и също място","why":""},{"text":"Затъмнение към черно и нова сцена в същата стая","why":"Затъмнението казва, че е минало време, но не колко — може да е една нощ."}],"answer":2,"explain":"Преливането само по себе си казва „мина време“, а сезоните казват колко: зима, пролет, лято и есен на едно и също място са година, която зрителят „преброява“ без надписи.","more":"За да се слеят кадрите гладко, снимай всички сезони от една и съща точка — със статив, на същата височина и със същия обектив. Отбележи мястото, за да се върнеш точно там."},{"id":"studio.edit.cuts.c04","legacyId":"ck0fmzg","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Героинята още говори в кадър, а вече чуваме влака от следващата сцена. Какво е това?","options":[{"text":"L-срязване (L-cut)","why":"При L-срязване звукът от предишната сцена продължава над новия образ — обратната посока."},{"text":"J-срязване (J-cut)","why":""},{"text":"Преливане (Dissolve)","why":"Преливането смесва два образа; тук се смесват звук от едната сцена и образ от другата."},{"text":"Прескачащ монтаж (Jump cut)","why":"Прескачащият монтаж реже в един и същ кадър; тук звукът преминава между сцени."}],"answer":1,"explain":"Звукът от следващата сцена идва преди образа ѝ и подготвя зрителя: той вече „чува“ влака, докато още гледа героинята. Така преходът е мек, а двете сцени се свързват.","more":"Имената идват от формата на клиповете в монтажната програма: при J звукът „стърчи“ напред под предишния кадър като опашката на буквата J, а при L продължава след образа като долната черта на L."},{"id":"studio.edit.cuts.c05","legacyId":"ca7i4wk","hall":"studio","domain":"edit","topic":"edit.cuts","topic2":"hist.pioneer","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"В „Големият влаков обир“ (1903) Портър показва ту бандитите, ту вързания телеграфист, ту хората, които тръгват да ги гонят. Кой монтажен похват е в зародиш?","options":[{"text":"Монтажна поредица (Montage)","why":"Монтажната поредица сгъстява време, обикновено под музика; тук се редуват различни линии на действие."},{"text":"Интелектуален монтаж (Intellectual montage)","why":"Интелектуалният монтаж ражда метафора от съпоставка (Айзенщайн, 1920-те), а не свързва едновременни действия."},{"text":"Кадър – контракадър (Shot/reverse shot)","why":"Кадър – контракадър редува събеседници в една сцена, а не различни места."},{"text":"Паралелен монтаж (Cross-cutting)","why":""}],"answer":3,"explain":"Портър разказва историята на няколко места, които зрителят свързва в едно време. Грифит по-късно превръща редуването в система за напрежение — с все по-кратки кадри до спасението в последния миг.","more":"Филмът завършва с кадър, в който бандит стреля право към публиката. Кината можели сами да решат дали да го пуснат в началото, или в края на прожекцията."},{"id":"studio.edit.cuts.c06","legacyId":"c1db60z7","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо монтажистите предпочитат да режат по време на движение?","options":[{"text":"Движението размазва кадъра и скрива грешките","why":"Размазването не е причината; срязването се крие, защото вниманието следи движението."},{"text":"Така срязването пада точно на удар в музиката","why":"Рязането по ударите на музиката е друг похват; рязането в движение крие шева и в сцени без музика."},{"text":"Окото следи движението и пропуска срязването","why":""},{"text":"Така зрителят вижда по-ясно смяната на кадъра","why":"Обратното: целта е зрителят да не забележи срязването."}],"answer":2,"explain":"Докато очите следят движение, вниманието е заето да го „довърши“ и смяната на кадъра минава незабелязано. Срязване в пълен покой е по-видимо, защото нищо не отвлича погледа.","more":"Монтажистът Уолтър Мърч сравнява срязването с мигането: мигаме, когато мисълта ни се сменя, а добрият монтаж реже точно в такива мигове."},{"id":"studio.edit.cuts.c07","legacyId":"c1v0gsqy","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"В интервю махаш едно изречение и лицето на говорещия „подскача“. С какво покриваш срязването?","options":[{"text":"С прескачащ монтаж, за да изглежда нарочно","why":"Прескачащият монтаж показва срязването, а задачата е да го скриеш."},{"text":"Със затъмнение между двете изречения","why":"Затъмнението прекъсва разказа по средата на мисълта."},{"text":"С по-силен звук точно в мига на срязването","why":"Звукът не скрива подскока на образа; гласът трябва да продължи, а образът — да е друг."},{"text":"С вмъкнат кадър на ръцете или на слушащия","why":""}],"answer":3,"explain":"Гласът продължава без прекъсване, а образът се сменя с вмъкнат кадър (Cutaway) — затова подскокът изчезва. В документалното кино такива кадри се снимат нарочно като допълнителен материал (B-roll).","more":"В телевизионните новини отделно се снимат и кадри на журналиста, който кима и слуша. В британската телевизия ги наричат noddies и ги ползват точно за такива лепенки."},{"id":"studio.edit.cuts.c08","legacyId":"c1lrmbeb","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кръглото око в крупен план се срязва към пълната луна със същия размер и на същото място в кадъра. Как се нарича връзката?","options":[{"text":"Съвпадение по действие (Match on action)","why":"Съвпадението по действие продължава едно движение; тук се свързват два различни предмета по форма."},{"text":"Паралелен монтаж (Cross-cutting)","why":"Паралелният монтаж редува действия на различни места; тук е един скок по форма."},{"text":"Графично съвпадение (Match cut)","why":""},{"text":"Вмъкнат кадър (Cutaway)","why":"Вмъкнатият кадър прекъсва действието с нещо извън него; тук формата свързва двата кадъра."}],"answer":2,"explain":"Кръглата форма остава на същото място в рамката, затова окото възприема срязването като превръщане, а не като скок. Връзката е по форма, не по действие — често за метафора или за гладък скок в пространството и времето.","more":"Упражнение: намери у дома два различни кръгли предмета, например чиния и стенен часовник, и ги заснеми в еднакъв размер на едно и също място в кадъра. Срежи между тях и виж как формата ги „слепва“."},{"id":"studio.edit.time.c01","legacyId":"ccf39nt","hall":"studio","domain":"edit","topic":"edit.time","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Героят излиза от вкъщи и отива на работа. Искаш целият път да трае 5 секунди на екрана. Как го монтираш?","options":[{"text":"Реално време: целият път до работа в един дълъг кадър","why":"Реалното време би отнело минути — точно обратното на целта."},{"text":"Разтягане: много кадри на заключването на вратата","why":"Разтягането удължава момента, а ти трябва да съкратиш."},{"text":"Компресия: заключва вратата → кара колата → влиза в офиса","why":""},{"text":"Паралелен монтаж: редувам пътя му с шефа, който чака","why":"Паралелният монтаж добавя втора линия и удължава сцената."}],"answer":2,"explain":"Три кратки кадъра с началото, средата и края на пътя са достатъчни: действията са логично свързани и зрителят сам „дописва“ липсващото. Скучното отпада, а логиката остава.","more":"Монтажистите казват: „Влез в сцената късно, излез рано.“ Започни с действието, а не с подготовката му, и срежи веднага щом смисълът е ясен."},{"id":"studio.edit.time.c02","legacyId":"c1b8wg26","hall":"studio","domain":"edit","topic":"edit.time","topic2":"hist.silent","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Слизането по стълбите в Одеса в „Броненосецът Потьомкин“ (1925) е съставено от десетки кадри на едно кратко действие — войниците, майката, количката. Какво става с времето на екрана?","options":[{"text":"Сгъстява се: пропуска се скучното от действието","why":"Компресията съкращава; тук многото кадри удължават кратко действие."},{"text":"Прескача се: между кадрите минават години","why":"Елипсата прескача време между сцени; тук сме в едно и също действие."},{"text":"Разтяга се: екранът трае повече от действието","why":""},{"text":"Съвпада с реалното време на действието","why":"Реалното време е без съкращения и без удължаване; тук действието трае повече от реалното."}],"answer":2,"explain":"Това е разтягане на времето (Elaboration): многото кадри на едно действие удължават ужаса. Времето на екрана следва емоцията, не часовника.","more":"Брайън Де Палма цитира сцената в „Недосегаемите“ (1987): престрелка на стълбите на гара, по които се търкаля бебешка количка — разтегната с много кадри и забавен каданс."},{"id":"studio.edit.time.c03","legacyId":"c16z16t2","hall":"studio","domain":"edit","topic":"edit.time","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Детето духва свещите на тортата — срязване — същата стая, то е на 18 години. Какво е това?","options":[{"text":"Компресия (Compression)","why":"Компресията съкращава незабележимо; тук скокът от 18 години е явен."},{"text":"Елипса (Ellipsis)","why":""},{"text":"Ретроспекция (Flashback)","why":"Ретроспекцията връща назад; тук времето скача напред."},{"text":"Реално време (Real time)","why":"Реалното време тече без пропуски; тук липсват 18 години."}],"answer":1,"explain":"Срязването прескача 18 години наведнъж, а еднаквата стая помага на зрителя веднага да разбере, че е минало време. Скокът е явен — той иска да бъде забелязан.","more":"Дори филм, който изглежда като един непрекъснат кадър, може да има елипса: в „1917“ героят губи съзнание, екранът почернява и когато се свестява, вече е нощ."},{"id":"studio.edit.time.c04","legacyId":"cazzb9q","hall":"studio","domain":"edit","topic":"edit.time","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"explain","prompt":"Обясни как темпото на монтажа влияе на емоцията. Дай пример за бавно и за бързо темпо.","checklist":["Бързите срязвания носят напрежение, енергия или хаос","Дългите кадри носят съзерцание, тъга или напрежение от очакване","Ритъмът е смяната на темпото, не само скоростта","Темпото следва емоцията на сцената"],"model":"Гонитба с кадри по една секунда кара сърцето да бие по-бързо. Сбогуване с дълъг кадър дава време чувството да се утаи. Най-силен е контрастът — бърза сцена, последвана от тишина и дълъг кадър.","more":"Монтажистът Уолтър Мърч подрежда шест причини за срязване и поставя емоцията най-отгоре — преди историята и ритъма. Ако срязването служи на емоцията, зрителят прощава дребните несъответствия."},{"id":"studio.edit.time.c05","legacyId":"c1t99s2h","hall":"studio","domain":"edit","topic":"edit.time","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Сцена на гонитба трае 40 секунди, а средната дължина на кадъра е 1,6 секунди. Колко кадъра (shots) има?","answer":25,"unit":"кадъра","explain":"40 ÷ 1,6 = 25 кадъра. Средната дължина на кадъра — общото време, разделено на броя на кадрите — е проста мярка за темпото: колкото е по-малка, толкова по-бързо се реже.","more":"Измери сам: пусни любима сцена, засечи времето и брой срязванията. Сравни бойна сцена и спокоен разговор — разликата в средната дължина на кадъра ще е голяма."},{"id":"studio.edit.sound.c01","legacyId":"ch6xu31","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи вида звук с примера.","pairs":[["Диегетичен звук","Радиото в стаята, което героят изключва"],["Недиегетичен звук","Оркестрова музика над битката"],["Шумове","Стъпки по чакъл, записани в студио"],["Фон на помещението","30 секунди „тишина“ в стаята след дубъла"],["Постсинхрон","Актьорът презаписва реплика, развалена от самолет"]],"explain":"Решаващото е откъде идва звукът в историята: ако източникът е в света на героя и той може да го чуе, звукът е диегетичен; ако е само за зрителя — недиегетичен. Шумовете, фонът и постсинхронът са работни пластове, които карат този свят да звучи истински.","more":"Стъпки в сняг шумовите артисти често правят, като мачкат торбичка с нишесте близо до микрофона. Опитай и ти: важен е звукът, а не предметът, от който идва."},{"id":"studio.edit.sound.c02","legacyId":"clw5ew5","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Над сцена на катастрофа звучи весела детска песничка като филмова музика. Какво постига това?","options":[{"text":"Разликата между звук и образ засилва ужаса","why":""},{"text":"Успокоява зрителя, че краят ще е щастлив","why":"Веселата песен не успокоява — несъответствието прави сцената още по-страшна или горчива."},{"text":"Показва, че героите слушат радио в колата","why":"Песента звучи като филмова музика, без източник в сцената; тя е там, за да коментира образа."},{"text":"Скрива лошия запис на реалния звук","why":"Контрапунктът е смислов избор, не лепенка за технически проблем."}],"answer":0,"explain":"Звукът и образът казват противоположни неща и зрителят търси смисъла в разликата. Безгрижната мелодия подчертава колко беззащитни са хората пред бедата — това е звуков контрапункт (Contrapuntal sound), който ражда ирония, ужас или горчивина.","more":"Още през 1928 г. Айзенщайн, Пудовкин и Александров пишат обща заявка за звуковото кино: те се опасяват, че звукът само ще повтаря образа, и призовават да се използва в контрапункт с него."},{"id":"studio.edit.sound.c03","legacyId":"c8q78eq","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Сцена в кафене. След монтажа звукът между репликите „пропада“ в пълна тишина. Каква е причината?","options":[{"text":"Микрофонът е бил твърде далеч от актьорите","why":"Далечният микрофон дава кух и шумен звук, но не и дупки от пълна тишина между репликите."},{"text":"Липсва музика, която да запълва паузите","why":"Музиката може да прикрие дупките, но в кафене зрителят очаква звука на мястото."},{"text":"Разминал се е синхронът на звука с образа","why":"Разминатият синхрон се вижда по устните; тишината между репликите е друг проблем."},{"text":"Липсва записан фон на самото помещение","why":""}],"answer":3,"explain":"Дори „тихото“ кафене звучи — хладилник, улица, приглушени гласове. Когато паузите се изрежат, между репликите остава мъртва тишина и ухото я чува като дупка. Записаният фон на помещението (Room tone) се подлага под тези места и звукът става непрекъснат.","more":"На снимки записвай фона веднага след сцената, докато всички стоят неподвижно, а уредите работят както по време на дубъла. Ако климатикът е бучал в дубъла, той трябва да бучи и във фона."},{"id":"studio.edit.sound.c04","legacyId":"cd9unru","hall":"studio","domain":"edit","topic":"edit.sound","topic2":"anim.lipsync","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо в анимацията диалогът обикновено се записва преди анимирането?","options":[{"text":"Така звукорежисьорът може да добави шумовете още в началото","why":"Шумовете се правят накрая, по готовата анимация; първо се записва само гласът."},{"text":"Звукът се записва по-бързо и така се пести време","why":"Скоростта не е причината — важно е аниматорът да играе по готовия запис."},{"text":"Аниматорът нагажда движенията по паузите и интонацията","why":""},{"text":"Гласът е най-скъпият етап и трябва да приключи първи","why":"Цената не е причината; аниматорът има нужда от записа, за да разпредели звуците по кадри."}],"answer":2,"explain":"Аниматорът разпределя записа по кадри в експозиционния лист и знае на кой кадър пада всяка сричка, пауза и въздишка. Така движенията и мимиките следват интонацията на актьора. В игралното кино е различно: гласът и образът се записват заедно на снимки.","more":"Студиата често снимат и самите актьори по време на записа. Аниматорите ползват видеото като отправна точка за мимики и жестове, без да го копират кадър по кадър."},{"id":"studio.edit.sound.c05","legacyId":"cxhgf3t","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy","fixes":["P07"]},"kind":"card","format":"recall","prompt":"Изброи петте звукови пласта на филма.","checklist":["Диалог (включително постсинхрон)","Шумове (Foley)","Фон и атмосфера на мястото","Звукови ефекти","Музика"],"model":"Диалог, шумове, фон, ефекти и музика. Всеки се записва и смесва отделно, за да може да се контролира.","more":"Освен общия микс студията пазят и отделна версия само с музиката и ефектите, без диалога (M&E). С нея филмът може да се дублира на друг език, без да се губят шумовете и музиката."},{"id":"studio.edit.sound.c06","legacyId":"cswavm5","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Героят пуска радиото в колата и песента продължава като музика над следващите кадри по магистралата. Какво става със звука?","options":[{"text":"Песента е филмова музика, която героят започва да чува","why":"Обратното: песента тръгва от радиото в колата и после звучи над кадри, в които героят не я чува."},{"text":"Песента тръгва от света на героя и става филмова музика","why":""},{"text":"Песента противоречи на образа и създава ирония","why":"Нищо не казва, че песента противоречи на образа; тук се сменя източникът ѝ."},{"text":"Песента се презаписва в студио върху готовия образ","why":"Презаписът е технически етап; въпросът е откъде идва музиката в разказа."}],"answer":1,"explain":"Песента започва от радиото в колата — източник в света на героя, затова е диегетична. Когато продължи с пълен, чист звук над следващите кадри по магистралата, тя „излиза“ от този свят и вече коментира пътуването като филмова музика.","more":"В монтажа: пусни песента в колата през филтър, който я прави тънка като от малък високоговорител, и махни филтъра в мига на срязването към магистралата. Ухото ще усети прехода."},{"id":"studio.edit.theory.c01","legacyId":"chrguya","hall":"studio","domain":"edit","topic":"edit.theory","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"explain","prompt":"Обясни ефекта на Кулешов със съвременен пример — клип, мем или реклама.","checklist":["Едно и също неутрално лице + различен следващ кадър","Зрителят сам „дописва“ емоцията","Смисълът се ражда от съпоставката, а не от отделния кадър","Даден е собствен съвременен пример"],"model":"Едно и също неутрално лице, последвано от кученце, изглежда умилено, а последвано от катастрофа — ужасено. Така работят и клиповете с реакции: монтажът казва какво „чувства“ лицето.","more":"Хичкок обяснява ефекта в телевизионно интервю със собственото си лице: усмивката му след кадър с майка и бебе изглежда мила, а същата усмивка след кадър с момиче по бански изглежда съвсем различно."},{"id":"studio.edit.theory.c02","legacyId":"c1v4zu3g","hall":"studio","domain":"edit","topic":"edit.theory","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Айзенщайн редува кадри на разстреляни работници с кадри на клане на бик („Стачка“, 1925). Бикът не е в същото място и време. Защо е там?","options":[{"text":"За да покаже какво става в същия момент наблизо","why":"Бикът не е в същото време и място — това не е паралелен монтаж."},{"text":"За да скрие срязванията между кадрите на разстрела","why":"Срязванията тук не се крият, а се подчертават — сблъсъкът е целта."},{"text":"За да даде ритъм по часовник на поредицата","why":"Метричният монтаж реже по дължина на кадрите; тук е важно значението на образа."},{"text":"За да роди у зрителя мисълта за клане","why":""}],"answer":3,"explain":"Бикът не принадлежи на сцената, затова зрителят не го приема като събитие, а като сравнение: работниците са избивани като добитък. Смисълът се ражда от съпоставката и го няма в нито един от двата кадъра поотделно — ранен пример за интелектуален монтаж.","more":"„Стачка“ е първият пълнометражен филм на Айзенщайн. Две години по-рано той описва идеята си за „монтаж на атракционите“ — силни, шокиращи моменти, подредени така, че да разтърсят публиката."},{"id":"studio.edit.theory.c03","legacyId":"c1b4h15u","hall":"studio","domain":"edit","topic":"edit.theory","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Каква е основната разлика между холивудския невидим монтаж и съветската монтажна школа?","options":[{"text":"Холивуд реже по-бързо, съветските автори — с дълги кадри","why":"Съветските автори режат често и остро; разликата е в целта на срязването, не в темпото."},{"text":"Холивуд снима в студио, а съветските автори — на натура","why":"Мястото на снимките не е разликата; разликата е дали срязването се крие, или се показва."},{"text":"Холивуд крие срязването, съветските автори го правят сблъсък","why":""},{"text":"Холивуд търси метафори, съветските автори — ясна история","why":"Обратното: метафората от сблъсък е съветска идея, а Холивуд пази ясната история."}],"answer":2,"explain":"Холивуд иска зрителят да се потопи в историята, затова срязването трябва да мине незабелязано. Съветските режисьори вярват, че смисълът се ражда при сблъсъка на два кадъра, затова срязването трябва да се усети. Двата подхода живеят и днес.","more":"Съветските режисьори учат и от американското кино: Кулешов и учениците му внимателно изучават филмите на Грифит, особено „Нетърпимост“ (1916)."},{"id":"studio.edit.theory.c04","legacyId":"ccufpvi","hall":"studio","domain":"edit","topic":"edit.theory","topic2":"hist.silent","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кулешов, Айзенщайн, Пудовкин и Вертов принадлежат на…","options":[{"text":"Немския експресионизъм","why":"Немският експресионизъм („Кабинетът на д-р Калигари“) работи с декор и светлина, не с монтаж."},{"text":"Френския импресионизъм","why":"Френските импресионисти (Ганс, Епщайн) експериментират с образа, но не са тази група."},{"text":"Холивудската студийна система","why":"Холивудската система създава невидимия монтаж — обратното на съветския сблъсък."},{"text":"Съветската монтажна школа","why":""}],"answer":3,"explain":"През 1920-те тези режисьори правят монтажа основа на филмовия език: според тях смисълът се ражда в съпоставката на кадрите. Всеки има свой път — Кулешов експериментира, Айзенщайн търси сблъсъка, Пудовкин — свързването, Вертов — документалния образ.","more":"Вертов снима „Човекът с кинокамерата“ (1929) без актьори и без надписи: филмът е сглобен от кадри на градския живот и е пълен с монтажни експерименти."},{"id":"studio.cam.lens.c01","legacyId":"c1bwm5rk","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Трите конуса показват ъгъла на видимост на три обектива (пълен кадър). Кой е 200 mm телеобектив?","options":[{"text":"В"},{"text":"А"},{"text":"Б"}],"answer":0,"explain":"Колкото по-дълго е фокусното разстояние, толкова по-тесен е ъгълът: сензорът е по-далеч от оптичния център и улавя по-тесен сноп лъчи. При пълен кадър 200 mm обхваща около 10° хоризонтално (12° по диагонала).","more":"Удобно правило за дългите обективи: двойно по-дълго фокусно разстояние дава приблизително двойно по-тесен ъгъл. Така 100 mm обхваща около 20° хоризонтално, а 400 mm — около 5°.","visual":{"type":"fov"}},{"id":"studio.cam.lens.c02","legacyId":"c1otnf45","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Кой конус съответства на 24 mm широкоъгълен обектив?","options":[{"text":"А"},{"text":"В"},{"text":"Б"}],"answer":2,"explain":"Колкото по-късо е фокусното разстояние, толкова по-широк е ъгълът. При пълен кадър 24 mm обхваща около 74° хоризонтално (84° по диагонала), затова му отговаря най-широкият конус.","more":"Честа грешка при широк обектив: в краищата на кадъра влизат неща, които не искаш — лампи, кабели, хора от екипа. Преди дубъла огледай внимателно и четирите края на кадъра.","visual":{"type":"fov"}},{"id":"studio.cam.lens.c03","legacyId":"c12xnfoo","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Искаш героят да изглежда притиснат от тълпата зад него. Кой обектив избираш?","options":[{"text":"Широкоъгълен отблизо, за да се вижда цялата тълпа","why":"Широкоъгълният разтяга разстоянията — тълпата ще изглежда далеч от героя."},{"text":"Рибешко око, за да се изкриви тълпата около него","why":"Рибешкото око изкривява силно и стилизира до комичност."},{"text":"Нормален обектив, за да остане перспективата естествена","why":"Нормалният обектив е неутрален — няма да притисне тълпата към героя."},{"text":"Телеобектив отдалеч, за да се сгъсти пространството","why":""}],"answer":3,"explain":"Сгъстяването идва от голямото разстояние: отдалеч героят и тълпата са почти еднакво далеч от камерата и изглеждат близо един до друг. Телеобективът е нужен само за да остане героят голям в кадъра и отдалеч.","more":"Опитай с телефона: приятел застава на няколко метра пред ограда, а ти го снимаш отблизо. После се отдалечи на десетина крачки и приближи образа, докато той стане със същия размер. Оградата зад него ще изглежда много по-близо."},{"id":"studio.cam.lens.c04","legacyId":"cgys5d3","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо широкоъгълен обектив много близо до лицето не е ласкав за портрет?","options":[{"text":"Размива фона твърде силно зад лицето","why":"Широкоъгълният обектив дава по-дълбока рязкост — фонът е по-рязък, не по-размит."},{"text":"Сплесква лицето и го прави по-широко","why":"Сплескването идва от телеобектив отдалеч; широкоъгълният отблизо издува лицето."},{"text":"Пропуска по-малко светлина и лицето потъмнява","why":"Светлината зависи от блендата, не от фокусното разстояние."},{"text":"Уголемява близките части, например носа","why":""}],"answer":3,"explain":"Перспективата зависи от разстоянието, а не от обектива. От 30–40 cm носът е значително по-близо до камерата от ушите, затова се уголемява непропорционално и лицето изглежда издуто.","more":"Затова класическите портретни обективи са 85–135 mm при пълен кадър: с тях заставаш на около 1,5–3 m и лицето запазва естествените си пропорции."},{"id":"studio.cam.lens.c05","legacyId":"c7xvzdf","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи фокусното разстояние (пълен кадър) с типа обектив.","pairs":[["8 mm","Рибешко око"],["24 mm","Широкоъгълен"],["50 mm","Нормален"],["200 mm","Телеобектив"]],"explain":"Колкото по-късо е фокусното разстояние, толкова по-широк е ъгълът: хоризонтално 200 mm обхваща около 10°, 50 mm — около 40°, 24 mm — около 74°, а рибешкото око 8 mm — до 180°. Границите между групите са приблизителни.","more":"Основната камера на повечето телефони е широкоъгълна — около 24–26 mm в еквивалент за пълен кадър. Приближението 2x от нея дава около 50 mm, тоест нормален обектив."},{"id":"studio.cam.lens.c06","legacyId":"clwn4tl","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Bokeh с овална форма и хоризонтални сини отблясъци подсказват, че е използван…","options":[{"text":"Анаморфен обектив (Anamorphic lens)","why":""},{"text":"Рибешко око (Fisheye lens)","why":"Рибешкото око извива линиите, но не прави размитите светлини овални."},{"text":"Макро обектив (Macro lens)","why":"Макрото снима отблизо в мащаб 1:1; не дава овално bokeh и хоризонтални отблясъци."},{"text":"Обектив с наклон и отместване (Tilt-shift lens)","why":"Tilt-shift накланя равнината на рязкост; размитите светлини остават кръгли."}],"answer":0,"explain":"Анаморфният обектив има цилиндрични лещи, които свиват образа по хоризонтала, обикновено 2 пъти. След разпъването размитите светлини стават вертикални овали, а ярките източници дават хоризонтални ивици.","more":"Анаморфната оптика навлиза масово с CinemaScope през 1953 г.: широкият кадър се свива и се побира върху обикновена 35 mm лента, а обективът на прожекционния апарат го разпъва обратно."},{"id":"studio.cam.lens.c07","legacyId":"crmueog","hall":"studio","domain":"cam","topic":"cam.lens","topic2":"board.action","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Action сцена: героят тича право към камерата и искаш движението да изглежда бързо и агресивно. Кой обектив?","options":[{"text":"Телеобектив от голямо разстояние","why":"Телеобективът сгъстява разстоянието: героят тича почти на място. Полезно е за безнадеждно бягане, но не и за агресия."},{"text":"Широкоъгълен обектив отблизо","why":""},{"text":"Нормален обектив от средно разстояние","why":"Нормалният обектив е неутрален — няма да подсили скоростта."},{"text":"Анаморфен обектив от средно разстояние","why":"Анаморфният дава широк формат и характерни отблясъци, но не ускорява движението към камерата."}],"answer":1,"explain":"Отблизо всяка крачка променя силно разстоянието до камерата, затова героят расте бързо в кадъра и сякаш връхлита. Широкият обектив подсилва движението по оста към камерата, а дългият — движението встрани.","more":"В storyboard подсили ефекта като при широк обектив: нарисувай близкия крак или юмрук огромен, а главата — малка и далечна. Така рисунката подсказва на оператора какъв обектив искаш."},{"id":"studio.cam.lens.c08","legacyId":"c1fv0578","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кое е типично предимство на фикс обектива пред вариообектива?","options":[{"text":"Може да сменя фокусното разстояние","why":"Това е предимство на вариообектива; фиксът има едно фокусно разстояние."},{"text":"Обикновено е по-светъл и по-рязък","why":""},{"text":"Обикновено дава по-широк ъгъл на видимост","why":"Ъгълът зависи от фокусното разстояние, не от това дали обективът е фикс."},{"text":"Обикновено пази фокуса при трансфокация","why":"Фиксът не прави трансфокация; пазенето на фокуса е свойство на парфокалния вариообектив."}],"answer":1,"explain":"Фиксът е проектиран само за едно фокусно разстояние, затова му трябват по-малко лещи. Така конструкторите постигат по-голям отвор — например f/1,4 срещу f/2,8–f/4 при повечето вариообективи — и по-висока рязкост.","more":"Упражнение: снимай цял ден само с едно фокусно разстояние — например само с 1x на телефона, без да приближаваш. За всеки нов кадър ще трябва да се движиш и ще започнеш да мислиш за разстоянието."},{"id":"studio.cam.lens.c09","legacyId":"cfonj6","hall":"studio","domain":"cam","topic":"cam.lens","topic2":"cam.format","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Слагаш 50 mm обектив на камера с crop factor 1,5. На какво фокусно разстояние при пълен кадър отговаря образът?","answer":75,"unit":"mm","explain":"50 × 1,5 = 75 mm. Самият обектив не се променя: по-малкият сензор само изрязва средата на образа, затова ъгълът на видимост е като на 75 mm при пълен кадър.","more":"Внимание при рязкостта: при същия кадър 50 mm f/2 на сензор с crop factor 1,5 дава дълбочина на рязкост като 75 mm f/3 на пълен кадър — по-малкият сензор размива фона по-трудно."},{"id":"studio.cam.expo.c01","legacyId":"c15zkl3a","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Снимаш с 25 кадъра в секунда и спазваш правилото за 180° на затвора. Каква скорост на затвора избираш? Въведи знаменателя (1/…).","answer":50,"unit":"(1/… s)","explain":"Затворът е отворен половината от времето на всеки кадър: кадърът трае 1/25 s, а половината от него е 1/50 s. Така размазването на движението изглежда естествено, както сме свикнали в киното.","more":"Телефонът в автоматичен режим на ярко слънце сам скъсява затвора и движението става накъсано. Приложение с ръчни настройки и ND филтър за телефон ти връщат контрола."},{"id":"studio.cam.expo.c02","legacyId":"c1gdpp4e","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Затваряш блендата от f/2,8 на f/5,6. С колко степени (stops) намалява светлината?","answer":2,"unit":"степени","explain":"Стандартният ред е f/2,8 → f/4 → f/5,6: две степени, всяка намалява светлината наполовина — общо 4 пъти. Всяко следващо f-число е предишното, умножено по около 1,4 (√2), защото така площта на отвора намалява наполовина.","more":"Запомни реда на целите степени: f/1,4 – f/2 – f/2,8 – f/4 – f/5,6 – f/8 – f/11 – f/16 – f/22. Помага, че всяко второ число е удвоено: 2 → 4 → 8 → 16."},{"id":"studio.cam.expo.c03","legacyId":"c140zt7f","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Вдигаш ISO от 400 на 1600. С колко степени (stops) по-светъл става образът?","answer":2,"unit":"степени","explain":"При ISO всяко удвояване на числото е една степен: 400 → 800 → 1600 са две степени, тоест сигналът от сензора се засилва 4 пъти. Цената е повече шум.","more":"Честа грешка: снимаш тъмно на ниско ISO и после изсветляваш в програмата. Шумът в сенките обикновено става по-силен, отколкото ако беше вдигнал ISO още при снимането."},{"id":"studio.cam.expo.c04","legacyId":"cu832ds","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Снимаш водопад и танцьор с 25 кадъра в секунда и затвор 1/1000 s. Движението изглежда накъсано. Защо?","options":[{"text":"Затворът е твърде кратък и липсва размазване","why":""},{"text":"Кадровата честота е твърде ниска за бързо движение","why":"25 кадъра в секунда са стандарт и дават плавно движение при нормален затвор — около 1/50."},{"text":"Блендата е твърде отворена и рязкостта е плитка","why":"Блендата влияе на рязкостта в дълбочина, не на това дали движението е накъсано."},{"text":"Затворът е твърде дълъг и фазите се сливат","why":"Обратното: 1/1000 е много кратък затвор, затова всяка фаза е замразена."}],"answer":0,"explain":"При 1/1000 s всеки кадър хваща движението замразено, а между два кадъра минава 1/25 s. Без следата от размазване окото вижда отделни скокове вместо плавно движение. Понякога това е нарочен ефект за нервни action сцени.","more":"Опитай: в ръчен видеорежим снимай фонтан веднъж при 1/50 s и веднъж при 1/1000 s. Във втория клип пръските са остри замразени капки, които подскачат от кадър на кадър."},{"id":"studio.cam.expo.c05","legacyId":"clpyxpn","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"explain","prompt":"Обясни триъгълника на експозицията на съученик с аналогия по твой избор.","checklist":["Бленда: колко широк е отворът (и влияе на дълбочината на рязкост)","Затвор: колко дълго е отворено (и влияе на размазването)","ISO: чувствителност (и носи шум)","Всяка промяна има художествена цена, не само яркост"],"model":"Пълниш кофа от чешма. Блендата е колко е отворен кранът, затворът — колко време го държиш отворен, ISO — колко малка е кофата. Всяка настройка сменя и нещо друго: размит фон, размазано движение или шум.","more":"Аналогията не е точна в едно: по-високото ISO не събира повече светлина, а засилва сигнала от сензора — затова заедно с образа се засилва и шумът."},{"id":"studio.cam.expo.c06","legacyId":"c1b62cpg","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Ярко слънце. Снимаш видео на f/1,8 заради размития фон, ISO е на най-ниската стойност, а затворът трябва да остане 1/50. Образът е прегорял. Какво правиш?","options":[{"text":"Слагам неутрален филтър пред обектива","why":""},{"text":"Затварям блендата до f/16 и оставям затвора","why":"Губиш размития фон — дълбочината на рязкост расте."},{"text":"Сменям с по-светъл обектив с бленда f/1,4","why":"По-светлият обектив пуска още повече светлина — образът ще прегори още повече."},{"text":"Скъсявам затвора до 1/2000 за по-малко светлина","why":"Затворът трябва да остане 1/50; при 1/2000 движението става накъсано."}],"answer":0,"explain":"ND филтърът е „слънчеви очила“ за обектива: намалява само количеството светлина, без да пипа цвета. Така блендата, затворът и ISO остават такива, каквито ги искаш за образа.","more":"Правилото Sunny 16 („слънчево 16“): на ярко слънце f/16 при затвор 1/ISO дава правилна експозиция. При ISO 100, f/1,8 и 1/50 s това са около 7 степени в повече — толкова трябва да поеме ND филтърът."},{"id":"studio.cam.expo.c07","legacyId":"c40ahup","hall":"studio","domain":"cam","topic":"cam.expo","topic2":"anim.principles","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Аниматорите понякога рисуват „размазани“ кадри при много бързо движение. Какво имитират?","options":[{"text":"Размазването от плитка дълбочина на рязкост","why":"Плитката рязкост размива фона по дълбочина, а не по посоката на движението."},{"text":"Размазването от обектив, който не е на фокус","why":"Грешният фокус размива всичко еднакво; тук размазването следва движението."},{"text":"Размазването от прекалено компресиран видеофайл","why":"Компресията дава блокчета и артефакти, а не следа от движение."},{"text":"Размазването от затвора, когато се снима жив човек","why":""}],"answer":3,"explain":"При много бързо движение предметът прескача голямо разстояние между два кадъра и движението изглежда накъсано. Размазаният кадър (smear) запълва празнината със следа — ролята, която при снимане играе затворът.","more":"В 3D програмите същото се постига с размазване при движение (motion blur), което се добавя при рендирането. Настройва се като ъгъл на затвора или като част от кадъра — в Blender стойност 0,5 отговаря на 180°."},{"id":"studio.cam.focus.c01","legacyId":"ced3dhw","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","prompt":"Изброи начините да размажеш фона зад героя.","checklist":["По-отворена бленда (по-малко f-число)","По-дълъг обектив","Камерата по-близо до героя","Фонът по-далеч от героя"],"model":"Отвори блендата, вземи по-дълъг обектив и се приближи до героя — така дълбочината на рязкост намалява. Отдалечи героя от стената — тогава фонът остава още по-далеч извън рязката зона и се размива повече.","more":"Портретният режим на телефона не променя оптиката: той пресмята разстоянието до всяка точка и размива фона с програма. Затова около косата и ушите понякога остават неестествени ръбове."},{"id":"studio.cam.focus.c02","legacyId":"cydr7sq","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Искаш портрет с размит фон: f/16, широкоъгълен 18 mm, героят е залепен за стената. Какво не е наред?","options":[{"text":"Блендата е грешна, а обективът и стената са наред","why":"f/16 наистина увеличава рязкостта, но и 18 mm, и близката стена правят същото."},{"text":"И блендата, и обективът, и стената правят фона рязък","why":""},{"text":"Обективът е грешен, а блендата и стената са наред","why":"Широкоъгълният наистина пречи, но f/16 и близката стена също правят фона рязък."},{"text":"Стената е проблемът, а блендата и обективът са наред","why":"Близката стена е проблем, но f/16 и 18 mm също задълбочават рязкостта."}],"answer":1,"explain":"Трите избора действат в една посока: f/16 е малък отвор, 18 mm е къс обектив, а стената е толкова близо, че попада в рязката зона. За размит фон отвори блендата (например f/2,8), вземи по-дълъг обектив и отдалечи героя от стената.","more":"Ако стаята е тясна и не можеш да отдалечиш героя от стената, завърти го така, че зад него да остане врата, коридор или прозорец — далечен фон, който може да се размие."},{"id":"studio.cam.focus.c03","legacyId":"c1mnu1x","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Двама герои са в един кадър, един зад друг: жената е по-близо до камерата, мъжът — в дъното. Първо говори тя, после той. Как прехвърляш вниманието без срязване?","options":[{"text":"Приближавам с трансфокация към мъжа","why":"Трансфокацията уголемява целия кадър и не избира кого да гледаме."},{"text":"Панорамирам от нея към него","why":"Двамата са на една линия, един зад друг — панорамата няма накъде да се завърти."},{"text":"Прехвърлям фокуса от нея към него","why":""},{"text":"Затварям блендата, за да са рязко и двамата","why":"Когато и двамата са рязко, окото не знае къде да гледа — вниманието не се прехвърля."}],"answer":2,"explain":"Окото винаги търси рязкото. Затова прехвърлянето на фокуса работи като „монтаж в кадъра“: вниманието минава от жената към мъжа, без дубълът да се прекъсва.","more":"На снимачната площадка асистентът по фокуса (Focus puller) отбелязва двете разстояния върху пръстена на обектива и репетира прехода, за да съвпадне с началото на репликата."},{"id":"studio.cam.focus.c04","legacyId":"c1xmoawx","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Снимаш футболист, който тича към теб. Кой режим на фокуса избираш?","options":[{"text":"Следящ фокус (AF-C)","why":""},{"text":"Заключен фокус (AF-S)","why":"Заключеният фокус се задава веднъж и не се мени — футболистът ще излезе от рязкост, докато тича към теб."},{"text":"Ръчен фокус (MF)","why":"Ръчният фокус при бързо приближаване е много труден без репетиция."},{"text":"Автоматичен избор (AF-A)","why":"AF-A сам решава кога да следи и често закъснява при бързо движение — за спорт избираш следящия режим директно."}],"answer":0,"explain":"Разстоянието до футболиста се мени всеки миг. В този режим камерата преизчислява рязкостта непрекъснато и дори предвижда накъде ще се премести обектът.","more":"При видео следящият фокус може да „скочи“ към човек, който мине пред обектива. Затова в игралното кино важните дубли и днес обикновено се фокусират ръчно от асистента по фокуса."},{"id":"studio.cam.focus.c05","legacyId":"c1l4bau","hall":"studio","domain":"cam","topic":"cam.focus","topic2":"lang.comp","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Как плитката дълбочина на рязкост работи като инструмент на композицията?","options":[{"text":"Показва ясно връзката между героя и мястото","why":"Връзката с мястото показва дълбокият фокус; плитката рязкост размива мястото."},{"text":"Прави кадъра по-светъл, защото блендата е отворена","why":"По-отворената бленда пуска повече светлина, но експозицията се изравнява със затвора, ISO или ND филтър — ролята ѝ в композицията е изолацията."},{"text":"Дава на кадъра повече пространство в дълбочина","why":"Размитият фон сплесква пространството зад героя, вместо да го разгърне."},{"text":"Отделя героя от фона и насочва окото към него","why":""}],"answer":3,"explain":"Окото първо отива към рязкото — както към най-светлото и най-контрастното. Така рязкостта подрежда йерархия на вниманието: героят е главен, а размитият фон остава на заден план.","more":"Внимавай: при f/1,4 отблизо рязкостта може да е само няколко сантиметра — ако фокусираш в носа, очите ще са меки. Фокусирай в окото, което е най-близо до камерата."},{"id":"studio.cam.move.c01","legacyId":"c1qw44i6","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Героят внезапно осъзнава ужасна истина. Коя техника подсилва момента?","options":[{"text":"Вертиго ефект (Dolly zoom)","why":""},{"text":"Бавна панорама (Slow pan)","why":"Панорамата оглежда пространството, но не „разклаща“ света."},{"text":"Статичен общ план (Static long shot)","why":"Статичният общ план отдалечава от преживяването."},{"text":"Затъмнение (Fade)","why":"Затъмнението прекъсва точно силния момент."}],"answer":0,"explain":"Камерата се движи, а трансфокацията я компенсира: героят остава със същия размер, но фонът се разтяга или свива зад него. Мозъкът не очаква такава смяна на перспективата и я усеща като световъртеж — като шока на героя.","more":"В „Челюсти“ (1975) Спилбърг използва вертиго ефекта върху лицето на шерифа Броуди на плажа — в мига, в който той вижда нападението на акулата."},{"id":"studio.cam.move.c02","legacyId":"cb8vs15","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Каква е разликата между шарийо към героя и трансфокация?","options":[{"text":"При трансфокацията се мени перспективата, при шарийото — не","why":"Обратното: трансфокацията само уголемява образа, а шарийото мести камерата и сменя перспективата."},{"text":"Шарийото е по-бавно, а трансфокацията — по-бърза","why":"И двете могат да са бързи или бавни; разликата е в перспективата."},{"text":"При шарийото се мени перспективата, при трансфокацията — не","why":""},{"text":"Шарийото е хоризонтално, а трансфокацията — вертикална","why":"Трансфокацията не е движение в посока — тя е промяна на оптиката."}],"answer":2,"explain":"При шарийото камерата физически се приближава: близките предмети растат по-бързо от далечните и разположението на фона се мени. Трансфокацията само уголемява целия образ еднакво — като изрязване на снимка.","more":"Опитай с телефона: заснеми приятел пред сграда два пъти — веднъж се приближи с крачки, веднъж приближи образа с пръсти по екрана. Сравни как изглежда сградата зад него в края на двата кадъра."},{"id":"studio.cam.move.c03","legacyId":"c90q4rm","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи движението на камерата с типичното му внушение.","pairs":[["Ръчна камера","Документалност, тревога, присъствие"],["Кран нагоре","Разкрива мащаба или завършва сцената"],["Шарийо към героя","Засилва вниманието към мисълта му"],["Панорама","Проследява или оглежда пространството"]],"explain":"Всяко движение променя отношението ни към героя: ръчната камера ни слага до него, кранът ни вдига над събитието, шарийото ни приближава до мислите му, а панорамата обхожда мястото от една точка. Движението трябва да има мотив.","more":"Упражнение: заснеми една и съща кратка сцена три пъти — от статив, с ръчна камера и с бавно приближаване. Покажи ги на съученици и ги питай какво усещат при всяка версия."},{"id":"studio.cam.move.c04","legacyId":"cy044rc","hall":"studio","domain":"cam","topic":"cam.move","topic2":"board.action","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Хаотичен бой е заснет с бавно, плавно движение на крана. Какво постига контрастът?","options":[{"text":"Дистанция: зрителят гледа хаоса отгоре, като съдба","why":""},{"text":"Повече енергия, отколкото би дала ръчната камера","why":"Плавният кран успокоява; енергията на боя идва от ръчна камера и бърз монтаж."},{"text":"Зрителят влиза в боя, сякаш е един от бойците","why":"Кранът е далеч и високо — зрителят е наблюдател, а не участник."},{"text":"Кадърът изглежда по-реалистичен и документален","why":"Документално усещане дава ръчната камера; кранът е подчертано постановъчен."}],"answer":0,"explain":"Когато ритъмът на камерата противоречи на действието, зрителят спира да участва и започва да наблюдава. Високата, бавна гледна точка превръща боя в картина и ни кара да мислим за смисъла му, а не за ударите.","more":"Същото в звука се нарича звуков контрапункт (Contrapuntal sound): спокойна музика върху насилие също създава дистанция и кара зрителя да се замисли."},{"id":"studio.cam.move.c05","legacyId":"cy6m6jk","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Камерата стои на едно място и се накланя нагоре по небостъргача. Това е…","options":[{"text":"Вертикална панорама (Tilt)","why":""},{"text":"Хоризонтална панорама (Pan)","why":"Хоризонталната панорама завърта камерата наляво-надясно; тук тя се накланя нагоре."},{"text":"Кран (Crane shot)","why":"Кранът повдига самата камера; тук тя стои на място и само се накланя."},{"text":"Шарийо (Dolly shot)","why":"Шарийото мести камерата по земята; тук тя не се премества."}],"answer":0,"explain":"Вертикалната панорама завърта камерата нагоре или надолу около хоризонтална ос, а мястото ѝ не се мени. Кранът, за разлика от нея, издига самата камера, а шарийото я мести по земята.","more":"Когато накланяш камерата нагоре по сграда, вертикалите се събират към небето. Ако искаш да останат успоредни, архитектурните фотографи ползват обектив с наклон и отместване (Tilt-shift lens)."},{"id":"studio.cam.format.c01","legacyId":"cyz9ox9","hall":"studio","domain":"cam","topic":"cam.format","level":10,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Снимаш забавен каданс със 100 кадъра в секунда и го пускаш с 25. Колко пъти по-бавно изглежда движението?","answer":4,"unit":"пъти","explain":"Всяка реална секунда е заснета в 100 кадъра, а прожекцията показва по 25 в секунда. Затова тези 100 кадъра траят на екрана 100 ÷ 25 = 4 секунди.","more":"Внимавай със светлината: при 100 кадъра правилото за 180° иска около 1/200 s — с две степени по-тъмно от 1/50 s. Затова забавеният каданс изисква много светлина."},{"id":"studio.cam.format.c02","legacyId":"c6xw50p","hall":"studio","domain":"cam","topic":"cam.format","level":10,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Колко кадъра има 10-секунден клип при 24 кадъра в секунда?","answer":240,"unit":"кадъра","explain":"Кадровата честота е броят кадри за всяка секунда, затова общият брой е секундите, умножени по честотата: 10 × 24 = 240. Аниматорът мисли в кадри, не в секунди.","more":"При анимация на двойки (On twos) всяка рисунка стои 2 кадъра, така че за тези 10 секунди стигат 120 рисунки вместо 240."},{"id":"studio.cam.format.c03","legacyId":"c17pg895","hall":"studio","domain":"cam","topic":"cam.format","level":10,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Кой правоъгълник показва широкоекранния кинотеатрален формат 2,39:1?","options":[{"text":"А","why":"А е 16:9 (около 1,78:1) — форматът на телевизията и уеб видеото; по-висок е от широкия екран."},{"text":"Б","why":""},{"text":"В","why":"В е 4:3 (около 1,33:1) — най-високият от трите, форматът на старата телевизия и ранното кино."}],"answer":1,"explain":"При еднаква ширина по-широкият формат е по-нисък. Б е най-ниският правоъгълник: ширината му е 2,39 пъти височината — това е широкият кинотеатрален екран.","more":"Широкият екран се налага през 50-те години, когато киното се бори с телевизията за зрители. CinemaScope го постига с анаморфен обектив, който свива образа по ширина при снимане и го разтяга при прожекция.","visual":{"type":"aspect"}},{"id":"studio.cam.format.c04","legacyId":"c1u4bn70","hall":"studio","domain":"cam","topic":"cam.format","topic2":"anim.tech","level":10,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Правиш анимационен клип за вертикалните видеа в социалните мрежи. Какви са формат и резолюция?","options":[{"text":"9:16, 1080 × 1920","why":""},{"text":"16:9, 1920 × 1080","why":"Хоризонтален кадър — в телефона ще остане тясна ивица."},{"text":"4:3, 1440 × 1080","why":"Почти квадратен и хоризонтален — не пасва на вертикалния екран."},{"text":"2,39:1, 3840 × 1607","why":"Кинотеатрален широк екран — най-неподходящ за телефон."}],"answer":0,"explain":"Телефонът се държи изправен и приложенията показват вертикалното видео във формат 9:16 — така то запълва екрана. 1080 × 1920 е Full HD кадър, завъртян на 90°.","more":"Вертикалният кадър сменя композицията: героят се вписва във височина, а плановете са по-близки. Остави място горе и долу — там приложенията слагат надписи и бутони."},{"id":"studio.cam.format.c05","legacyId":"c17x9x62","hall":"studio","domain":"cam","topic":"cam.format","level":10,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Вертикален кадър 9:16 е широк 1080 пиксела. Колко е висок?","answer":1920,"unit":"px","explain":"9:16 значи 9 части ширина на 16 части височина. Една част е 1080 ÷ 9 = 120 px, а височината е 16 × 120 = 1920 px.","more":"Същата сметка работи за всеки формат: кадър 16:9, широк 3840 px, е висок 3840 ÷ 16 × 9 = 2160 px — това е 4K UHD."},{"id":"studio.cam.format.c06","legacyId":"c1yeggb0","hall":"studio","domain":"cam","topic":"cam.format","level":10,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо в Европа телевизията използва 25 кадъра в секунда, а киното — 24?","options":[{"text":"25 е по-плавно за окото, а 24 — по-евтино за лентата","why":"Разликата от един кадър не прави движението по-плавно; причината е честотата на мрежата."},{"text":"24 е по-плавно, а 25 — по-лесно за монтаж","why":"24 не е по-плавно; то е стандартът, приет със звуковото кино."},{"text":"25 идва от мрежата с 50 Hz, 24 — от звуковото кино","why":""},{"text":"25 дава по-добър звук, а 24 — по-добър образ","why":"Звукът в киното зависи от постоянната скорост, а не от 24 срещу 25."}],"answer":2,"explain":"Ранната телевизия синхронизира образа с честотата на тока, за да няма трептене и смущения: при 50 Hz това са 50 полукадъра, тоест 25 цели кадъра в секунда, а в САЩ при 60 Hz — 30. Киното приема 24 кадъра с идването на звука.","more":"Когато филм с 24 кадъра се излъчва по европейската телевизия, обикновено го пускат с 25 — с около 4% по-бързо. Затова филмът е малко по-кратък, а звукът — леко по-висок, ако не се коригира."},{"id":"studio.light.3pt.c01","legacyId":"c11928l7","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Схема отгоре: героят гледа към камерата, а трите лампи са еднакво мощни. Коя е запълващата светлина?","options":[{"text":"1"},{"text":"2"},{"text":"3"}],"answer":1,"explain":"Светлината отслабва бързо с разстоянието, затова от двете предни лампи по-далечната — 2 — осветява по-слабо: тя е запълващата. 1 е по-близо и е рисуващата, а 3 стои зад героя — това е контражурът.","more":"Запълващата често се слага близо до камерата, за да не хвърля втора сянка по лицето. Пробвай с две настолни лампи: отдалечавай втората и гледай как сенките от първата потъмняват.","visual":{"type":"threept"}},{"id":"studio.light.3pt.c02","legacyId":"c13o4vla","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Фонът зад героя е тъмен. Какво ще стане, ако изключиш светлина 3?","options":[{"text":"Героят ще се слее с фона","why":""},{"text":"Лицето ще потъмнее изцяло","why":"Лицето осветяват 1 и 2 отпред; 3 е зад героя и почти не стига до лицето."},{"text":"Сенките по лицето ще омекнат","why":"Мекотата на сенките зависи от рисуващата и запълващата, а не от светлината отзад."},{"text":"Нищо няма да се промени","why":"Изчезва светлият контур по косата и раменете — разликата се вижда веднага."}],"answer":0,"explain":"Светлина 3 е контражурът: пада отзад и отгоре и рисува светъл ръб по косата и раменете. Без него тъмната коса и дрехите се сливат с тъмния фон и кадърът губи дълбочина.","more":"Внимавай лампата отзад да не свети право в обектива: ще получиш отблясък и по-блед, по-малко контрастен образ. Скрий я зад героя или я засенчи с картон.","visual":{"type":"threept"}},{"id":"studio.light.3pt.c03","legacyId":"c18aa3i3","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Рисуващата светлина е с 2 степени (stops) по-силна от запълващата. Какво е съотношението (… : 1)?","answer":4,"unit":": 1","explain":"Една степен (stop) означава двойно повече светлина. Две степени са 2 × 2 = 4 пъти повече, затова съотношението е 4:1 — лицето има ясен обем, а сенчестата страна запазва детайл.","more":"Как се мери: с експонометър измерваш поотделно светлината от рисуващата и от запълващата и сравняваш блендите. Разликата от f/4 до f/8 например е две степени."},{"id":"studio.light.3pt.c04","legacyId":"c1msljns","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","prompt":"Опиши схемата с три светлини: къде е всяка и каква е ролята ѝ.","checklist":["Рисуваща: отпред, около 30–45° встрани и малко над очите — основната","Запълваща: от другата страна, по-слаба — омекотява сенките","Контражур: отзад и отгоре — отделя героя от фона","Съотношението между тях определя настроението"],"model":"Рисуващата моделира лицето, запълващата решава колко тъмни са сенките, контражурът рисува контур. Колкото по-голямо е съотношението, толкова по-драматично.","more":"Упражнение: в тъмна стая освети съученик с три източника — настолна лампа, фенерчето на телефона и лампа отзад. Включвай ги един по един и снимай след всеки, за да видиш какво добавя всяка светлина."},{"id":"studio.light.3pt.c05","legacyId":"c1h32v03","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Интервю навън без лампи. Слънцето е отстрани и половината лице е в тъмна сянка. Какво правиш?","options":[{"text":"Обръщам героя със слънцето в гръб","why":"Със слънцето в гръб лицето остава в сянка — без отражател става силует."},{"text":"Вдигам ISO, за да изсветля сенките","why":"ISO вдига всичко, а контрастът между светлата и тъмната страна остава."},{"text":"Слагам ND филтър, за да намаля контраста","why":"ND филтърът намалява цялата светлина, а не разликата между двете страни на лицето."},{"text":"Слагам отражател от сенчестата страна","why":""}],"answer":3,"explain":"Отражателят връща част от слънцето в сенчестата страна. Така получаваш безплатна запълваща светлина, която намалява контраста, без да пипаш експозицията на светлата страна.","more":"Няма отражател? Бял картон, лист стиропор или светла стена също вършат работа. Приближавай го, докато сянката изсветлее колкото трябва — колкото по-близо е, толкова по-силен е ефектът."},{"id":"studio.light.quality.c01","legacyId":"co0c8pa","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Сцена от филм на ужасите в мазе. Каква светлина избираш?","options":[{"text":"Светла тоналност, мека светлина от тавана","why":"Светлата тоналност (High-key) е за комедия и реклама — убива страха."},{"text":"Тъмна тоналност, мека светлина от целия таван","why":"Меката светлина отгоре изглажда сенките — няма къде да се крие нещо."},{"text":"Тъмна тоналност, твърда светлина от фенерче","why":""},{"text":"Топла светлина на залез през малкото прозорче","why":"Топлата светлина на залеза е уютна и романтична, а не страшна."}],"answer":2,"explain":"Страхът живее в сенките: зрителят вижда малко и си представя останалото. Твърдият лъч на фенерчето оставя остри ръбове и пълна тъмнина извън светлото петно.","more":"Класически трик във филмите на ужасите е светлината отдолу — например фенерче под брадичката. Сенките тръгват нагоре по лицето и то изглежда неестествено и зловещо."},{"id":"studio.light.quality.c02","legacyId":"cq1lj1j","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи ситуацията със светлината.","pairs":[["Реклама на паста за зъби","Светла тоналност"],["Филм ноар","Тъмна тоналност (Low-key) с твърди сенки"],["Сцена до прозорец в облачен ден","Мека светлина"],["Нощна лампа, която се вижда в кадъра","Практична лампа"]],"explain":"Светлината е част от езика на жанра: рекламата иска чисто и светло, ноарът крие заплаха в твърдите сенки. Облачният прозорец е голям мек източник, а лампата, която се вижда в кадъра, е практична.","more":"Упражнение: изгледай минута от любим филм без звук и се опитай да познаеш жанра само по светлината. После провери дали си прав."},{"id":"studio.light.quality.c03","legacyId":"c7fi998","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Как правиш светлината по-мека?","options":[{"text":"Отдалечавам лампата от героя","why":"Далечният източник е относително по-малък — светлината става по-твърда."},{"text":"Сменям с по-малка, но по-мощна лампа","why":"По-малкият източник дава по-твърди сенки, независимо от мощността."},{"text":"Намалявам мощността на лампата наполовина","why":"По-слабата светлина не е по-мека: сенките остават със същите остри ръбове."},{"text":"Приближавам голям дифузер до героя","why":""}],"answer":3,"explain":"Мекотата зависи от относителния размер на източника: колкото по-голям е спрямо героя, толкова от повече посоки идва светлината и ръбовете на сенките се размиват. Затова голям дифузер отблизо дава най-мека светлина.","more":"Правилото работи и в природата: слънцето е огромно, но е толкова далеч, че в небето е малка точка — затова в ясен ден сенките са твърди. Облаците го превръщат в голям източник и светлината омеква."},{"id":"studio.light.quality.c04","legacyId":"ct4wks","hall":"studio","domain":"light","topic":"light.quality","topic2":"hist.silent","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Ивиците сянка от щорите по лицето във филмите ноар наследяват…","options":[{"text":"Немския експресионизъм","why":""},{"text":"Френския импресионизъм","why":"Френските импресионисти търсят поетичен образ, а не твърдите сенки на ноара."},{"text":"Италианския неореализъм","why":"Неореализмът снима на улицата с естествена светлина — обратното на стилизираните сенки."},{"text":"Съветската монтажна школа","why":"Съветската школа е за монтажа; ноарът наследява светлината на германското кино."}],"answer":0,"explain":"Много от холивудските автори на ноара идват от германското кино на 1920-те — като режисьора Фриц Ланг — и носят неговата светлина: твърди лъчи, косо падащи сенки, лица наполовина в тъмнина.","more":"В „Кабинетът на доктор Калигари“ (1920) светлината и сенките са нарисувани направо върху декора — крайна форма на същия стил. Виж и понятието „Немски експресионизъм (German Expressionism)“."},{"id":"studio.light.quality.c05","legacyId":"cnmr0c3","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо операторите искат светлината да бъде „мотивирана“?","options":[{"text":"Светлината трябва да идва от реални лампи в кадъра","why":"Мотивираната светлина може изцяло да е от прожектори — важното е да изглежда, че идва от прозореца или лампата."},{"text":"Светлината има логичен източник и зрителят ѝ вярва","why":""},{"text":"Мотивираната светлина е по-силна и по-ярка","why":"Силата няма значение; мотивацията е въпрос на логика и достоверност."},{"text":"Мотивираната светлина пести време на площадката","why":"Често иска повече работа, не по-малко — важна е достоверността."}],"answer":1,"explain":"Зрителят не мисли за прожекторите — той вярва на света на филма. Ако светлината идва откъдето няма източник, илюзията се разпада, затова дори изцяло изкуствената светлина се „оправдава“ с прозорец, лампа или огън.","more":"Опитай: сложи съученик до настолна лампа в кадъра, а от същата страна постави по-силна скрита лампа в подобен цвят. На екрана ще изглежда, че цялата светлина идва от настолната."},{"id":"studio.light.temp.c01","legacyId":"c1iz47wa","hall":"studio","domain":"light","topic":"light.temp","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Коя стрелка по скалата отговаря на лампа с жичка?","options":[{"text":"Б"},{"text":"А"},{"text":"В"},{"text":"Г"}],"answer":0,"explain":"Лампата с жичка е около 3200 K — в топлата, оранжева част на скалата. А е свещ (≈1900 K), В — обедна дневна светлина (≈5600 K), Г — облачно небе и сянка (≈7500 K).","more":"Домашните LED крушки често пишат цветната температура на опаковката: 2700 K е „топло бяло“, а 6500 K — „студено бяло“. Провери крушките у дома.","visual":{"type":"kelvin"}},{"id":"studio.light.temp.c02","legacyId":"c1jv9npv","hall":"studio","domain":"light","topic":"light.temp","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Коя стрелка отговаря на обедна дневна светлина?","options":[{"text":"Б"},{"text":"Г"},{"text":"А"},{"text":"В"}],"answer":3,"explain":"Обедната дневна светлина е около 5600 K — в средата на скалата, където светлината изглежда неутрално бяла. За нея са направени „дневните“ лампи и дневната настройка на камерата.","more":"Дневната светлина не е постоянна: сутрин и вечер е по-топла, а в сянка и при облаци — по-синя. Затова при снимки през целия ден балансът на бялото се проверява отново.","visual":{"type":"kelvin"}},{"id":"studio.light.temp.c03","legacyId":"c187oi27","hall":"studio","domain":"light","topic":"light.temp","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди източниците от най-топлия към най-студения.","sequence":["Свещ (≈1900 K)","Лампа с жичка (≈3200 K)","Дневна светлина по пладне (≈5600 K)","Облачно небе (≈6500–7000 K)","Синьо небе в сянка (≈10 000 K)"],"explain":"Колкото по-ниска е температурата, толкова по-оранжева е светлината. Скалата е обратна на всекидневната представа: „топлото“ при цветовете е ниско в келвини, а „студеното“ — високо.","more":"Сянката в слънчев ден е толкова синкава, защото там не стига пряко слънце — осветява я само синьото небе. Затова портрет на сянка често излиза студен, ако не смениш баланса."},{"id":"studio.light.temp.c04","legacyId":"c1d6ex0w","hall":"studio","domain":"light","topic":"light.temp","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Интервю до прозорец, а отстрани свети лампа с жичка. Балансът на бялото е 5600 K и едната страна на лицето е оранжева. Какво не е наред?","options":[{"text":"Балансът на бялото трябва да е 3200 K за цялата сцена","why":"При 3200 K лампата ще стане бяла, но прозорецът ще посинее — проблемът само се обръща."},{"text":"Смесени са два източника с различна цветна температура","why":""},{"text":"Лампата е твърде силна и прегаря едната страна","why":"Силата дава светло петно, не оранжев цвят; оранжевото е от по-ниската температура на жичката."},{"text":"Прозорецът дава зелен оттенък, който оцветява лицето","why":"Дневната светлина не е зелена; оранжевото е от лампата с жичка."}],"answer":1,"explain":"При 5600 K камерата вижда дневната светлина като бяла, а лампата (≈3200 K) — като оранжева. Настройката е само една, затова източниците се изравняват: син гел (CTB) на лампата или дневна LED лампа — или смесването става нарочно.","more":"Бърза проверка на площадката: дръж бял лист до лицето и погледни екрана на камерата. Ако двете половини на листа са в различен цвят, източниците не съвпадат."},{"id":"studio.light.temp.c05","legacyId":"c1a6y4k6","hall":"studio","domain":"light","topic":"light.temp","topic2":"light.loc","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Балансът на бялото е 3200 K, а снимаш навън на дневна светлина. Каква ще е картината?","options":[{"text":"Оранжева","why":"Оранжева става, когато балансът е по-висок от светлината — тук е обратното."},{"text":"Зеленикава","why":"Зеленикав оттенък дават някои флуоресцентни лампи, не дневната светлина."},{"text":"Синкава","why":""},{"text":"Неутрална","why":"Неутрална ще е при около 5600 K; при 3200 K камерата добавя синьо."}],"answer":2,"explain":"Настройката 3200 K казва на камерата да очаква оранжева светлина и тя добавя синьо. Дневната светлина е много по-синя от 3200 K и всичко посинява — трик, използван и за американска нощ.","more":"Действа и обратно: на залез сложи баланс, по-висок от реалната светлина — например 7000 K, — и камерата ще затопли кадъра още повече."},{"id":"studio.light.temp.c06","legacyId":"ctqugdr","hall":"studio","domain":"light","topic":"light.temp","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Сцена на свещи: искаш пламъкът и лицата да останат топли и оранжеви. Кой баланс на бялото избираш?","options":[{"text":"Около 1900 K — колкото е пламъкът","why":"Камерата ще приеме светлината на пламъка за бяла и ще я неутрализира — уютът изчезва."},{"text":"Около 5600 K — дневната настройка","why":""},{"text":"Автоматичен баланс на камерата","why":"Автоматиката търси неутрален образ и „поправя“ голяма част от топлината на свещите."},{"text":"Ръчен баланс по бял лист до свещта","why":"Ръчният баланс прави листа бял, а заедно с него неутрализира и светлината на свещите."}],"answer":1,"explain":"Камерата неутрализира само светлина с температурата, на която е настроена. Свещта (≈1900 K) е далеч под 5600 K и остава оранжева — тук балансът е художествен избор, а не поправка.","more":"Често се избира и междинен баланс — около 3200 K: пламъкът пак е топъл, но кожата не става прекалено оранжева. Пробвай двата варианта с телефона в ръчен режим."},{"id":"studio.light.loc.c01","legacyId":"c8hckgs","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Влюбени на покрив в синкав здрач, а градът свети. Имате около 20 минути такава светлина. Как планирате?","options":[{"text":"Снимате по пладне и затъмнявате при корекцията","why":"Пладнето дава твърди сенки, а синьото небе не прилича на здрач."},{"text":"Снимате в полунощ и вдигате ISO до максимум","why":"Небето вече е черно, а шумът при максимално ISO е огромен."},{"text":"Започвате следобед и снимате, докато се стъмни","why":"Светлината се сменя постоянно и кадрите няма да си пасват — важен е краткият прозорец."},{"text":"Репетирате предварително и снимате в краткия режим","why":""}],"answer":3,"explain":"Режимът трае кратко и не прощава: светлината се сменя от минута на минута. Затова всичко се репетира и подготвя по-рано, а в правилните минути само се снима.","more":"Провери предварително точния час на залеза за деня и мястото. Някои екипи снимат режимна сцена в няколко поредни вечери, по няколко кадъра всяка вечер."},{"id":"studio.light.loc.c02","legacyId":"c1sbmg9m","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Нощна сцена в пустинята, а нямате осветление за нощ. Какво правите?","options":[{"text":"Снимате денем, преекспонирате, затопляте и включвате небето","why":"Обратното: нощта иска по-тъмен и по-студен образ, а небето издава деня."},{"text":"Снимате нощем с максимално ISO и без лампи","why":"В пустинята нощем без светлина сензорът няма какво да запише — само шум."},{"text":"Снимате по залез и после оцветявате небето в черно","why":"Залезът е топъл и ярък; черното небе над осветена земя издава трика."},{"text":"Снимате денем, недоекспонирате, охлаждате и криете небето","why":""}],"answer":3,"explain":"Американската нощ е стар и евтин трик: тъмнината и студеният тон идват от експозицията и цвета, а не от истинската нощ. Светлото небе издава деня, затова стои извън кадъра.","more":"Днес голяма част от ефекта се постига при цветовата корекция, но кадърът пак се подготвя на снимките: ниско слънце отстрани или отзад дава сенки и отблясъци, които приличат на лунна светлина."},{"id":"studio.light.loc.c03","legacyId":"c1djy9h7","hall":"studio","domain":"light","topic":"light.loc","topic2":"hist.pioneer","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Мелиес спира камерата, премахва актьора и продължава — човекът „изчезва“. Какви снимки се раждат така?","options":[{"text":"Режимни снимки на здрач","why":"Режимни са снимките в кратка природна светлина — здрач или изгрев."},{"text":"Натурни снимки","why":"Натурните са на реално място извън павилиона; тук е трик с камерата."},{"text":"Документални снимки","why":"Документалното кино записва реалността, а Мелиес я подменя с трик."},{"text":"Трикови снимки","why":""}],"answer":3,"explain":"Камерата спира, нещо в кадъра се сменя и снимането продължава — на екрана промяната е мигновена. Това е стоп-трикът (Stop trick), един от първите специални ефекти и роднина на Stop motion анимацията.","more":"Според самия Мелиес той открива трика случайно: камерата му засяда на улица в Париж и на прожекцията един омнибус се превръща в катафалка."},{"id":"studio.light.loc.c04","legacyId":"c1a90d53","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кое е главното предимство на павилиона пред натурата?","options":[{"text":"По-ниска цена, защото няма пътувания","why":"Павилионът често е по-скъп: всичко трябва да се построи."},{"text":"Пълен контрол над светлината, звука и времето","why":""},{"text":"По-голяма достоверност на мястото","why":"Истинското място обикновено е по-достоверно; павилионът печели с контрол."},{"text":"По-малко нужда от осветление и техника","why":"Обратното: в павилиона всичко трябва да се освети от нулата."}],"answer":1,"explain":"В павилиона не вали, слънцето не се мести и няма шум от улицата — снима се по график. Затова пък всичко трябва да се построи и освети от нулата.","more":"Често двата подхода се смесват: фасадата на къщата се снима на натура, а стаите ѝ се строят в павилион, където стените могат да се махат, за да влезе камерата."},{"id":"studio.light.loc.c05","legacyId":"cnav5jx","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"За какви сцени операторите чакат златния час?","options":[{"text":"Напрегнати сцени със студена, твърда светлина","why":"Златният час е топъл и мек — обратното на студена, твърда светлина."},{"text":"Романтични и носталгични сцени с меки дълги сенки","why":""},{"text":"Сцени, които трябва да изглеждат като нощ","why":"За нощ се използва американска нощ или истинската нощ; златният час е ярък и топъл."},{"text":"Сцени с равномерна светлина без сенки","why":"Ниското слънце рисува дълги сенки — светлината не е равномерна."}],"answer":1,"explain":"Ниско над хоризонта лъчите минават през повече въздух, който разсейва синьото: остава топла, по-слаба и по-мека светлина, а сенките се удължават. Това носи усещане за спомен и нежност.","more":"Пробвай: снимай портрет в златния час със слънцето зад героя. Косата светва като естествен контражур, а лицето можеш да изсветлиш с бял картон отпред."},{"id":"studio.light.color.c01","legacyId":"c19ayusg","hall":"studio","domain":"light","topic":"light.color","topic2":"story.structure","level":10,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy","fixes":["B024","B025"]},"kind":"card","format":"choice","prompt":"Цветовият сценарий (colour script) показва: топли цветове в началото, студени и сиви в средата, топли в края. Какво разказва?","options":[{"text":"Действието минава от лято през зима към лято","why":"Цветовият сценарий следва чувствата, а не календара — сезоните може и да не се сменят."},{"text":"Действието се мести от ден към нощ и пак към ден","why":"Цветът тук разказва емоционалната дъга, а не часа от денонощието."},{"text":"Героят губи щастието си и после го възвръща","why":""},{"text":"Героят се сменя с друг герой в средата на филма","why":"Смяната на цвета не означава смяна на героя, а промяна в неговото състояние."}],"answer":2,"explain":"Цветовият сценарий е емоционалната карта на филма: цветът следва чувствата на героя, а не календара. Художниците го рисуват преди продукцията, за да планират цвета на всяка сцена.","more":"Потърси в интернет цветовия сценарий (colour script) на „Феноменалните“ на Pixar и проследи как цветът се сменя с историята. После опитай същото за своя кратък филм — по едно малко петно за сцена."},{"id":"studio.light.color.c02","legacyId":"cxkl98u","hall":"studio","domain":"light","topic":"light.color","level":10,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Черно-бяла сцена с голяма тълпа. Искаш зрителят веднага да забележи едно момиченце. Какво правиш?","options":[{"text":"Оцветявам цялата сцена, за да оживее","why":"В цветна тълпа момиченцето ще се загуби сред всички цветове."},{"text":"Засилвам контраста в целия кадър","why":"Контрастът навсякъде засилва всичко еднакво — нищо не изпъква."},{"text":"Добавям тъжна музика, когато тя се появи","why":"Музиката не показва къде да гледа окото."},{"text":"Оцветявам само нейното палто в червено","why":""}],"answer":3,"explain":"Окото търси различното: едно петно наситен цвят сред безцветна картина привлича погледа веднага, без нужда от думи или музика.","more":"Така е направено момиченцето в червено палто в черно-белия „Списъкът на Шиндлер“ (1993) на Стивън Спилбърг. Акцентът работи, защото е един-единствен."},{"id":"studio.light.color.c03","legacyId":"cejp90r","hall":"studio","domain":"light","topic":"light.color","topic2":"story.staging","level":10,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"В „Легенда за вълците“ (Wolfwalkers, 2020) градът е с ъгловати, твърди линии и приглушени цветове, а гората — с живи, свободни линии и наситени цветове. Каква е целта?","options":[{"text":"Двете части са рисувани от различни екипи художници","why":"Разликата е замислена от режисьорите — дизайнът разказва, а не е случайност."},{"text":"Стилът показва два свята: ред и контрол срещу свобода","why":""},{"text":"Гората е по-сложна и затова е с повече цветове","why":"Сложността не определя цвета; наситеността показва свободата на гората."},{"text":"Градът е по-стар и цветовете му са избелели","why":"Приглушените цветове не са от възраст — те изразяват контрола и страха в града."}],"answer":1,"explain":"Дизайнът на местодействието разказва: твърдите линии и приглушените цветове внушават ред и потисничество, а свободните линии и наситеният цвят — живот и свобода.","more":"Градът е вдъхновен от стари гравюри на дърво с твърди ръбове, а гората е рисувана с видими линии на молив и графит. Режисьори са Том Мур и Рос Стюарт от ирландското студио Cartoon Saloon."},{"id":"studio.light.color.c04","legacyId":"c1dhy8oz","hall":"studio","domain":"light","topic":"light.color","level":10,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво правят топлите и студените цветове с пространството?","options":[{"text":"Топлите приближават, а студените отдалечават","why":""},{"text":"Топлите отдалечават, а студените приближават","why":"Обратното: затова далечните планини изглеждат синкави."},{"text":"Топлите разширяват, а студените стесняват кадъра","why":"Цветовете влияят на дълбочината, а не на ширината на кадъра."},{"text":"Цветовете не влияят на усещането за дълбочина","why":"Влияят: въздушната перспектива охлажда и избледнява далечното."}],"answer":0,"explain":"Окото е свикнало от природата: въздухът разсейва синята светлина и далечните планини изглеждат синкави и бледи — това е въздушната перспектива (Atmospheric perspective). Затова и в кадъра студеното и бледото четем като далечно.","more":"В анимацията фоновете се рисуват по-студени и по-бледи с всеки план навътре. Пробвай с три слоя — преден, среден и заден план — и виж как картината придобива дълбочина."},{"id":"studio.board.types.c01","legacyId":"c168p1ce","hall":"studio","domain":"board","topic":"board.types","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди етапите на превизуализацията в анимационно студио.","sequence":["Beat board","Миниатюри","Груб storyboard","Чист storyboard","Animatic","Layout"],"explain":"От голямата картина към детайла: първо ключовите моменти, после кадрите, после времето и накрая точната постановка. Всеки следващ етап е по-подробен и по-скъп за промяна, затова грешките се ловят възможно най-рано.","more":"В 3D анимацията layout е груба сцена в софтуера: прости модели на героите и виртуална камера, с които се определят план, ракурс и движение, преди аниматорите да започнат."},{"id":"studio.board.types.c02","legacyId":"cqqc8ye","hall":"studio","domain":"board","topic":"board.types","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо animatic спестява пари?","options":[{"text":"Готовите панели влизат направо във финалния филм","why":"Animatic е само чернова: финалните кадри се рисуват или анимират наново."},{"text":"Замества записа на гласовете и музиката на филма","why":"Animatic използва временен звук, но не замества истинския запис."},{"text":"Позволява да се снима без оператор и осветление","why":"Animatic не замества снимачния екип, а помага да се планира работата му."},{"text":"Ритъмът и историята се проверяват преди скъпата работа","why":""}],"answer":3,"explain":"Animatic показва историята във времето и със звук, докато промените още са евтини. Да изрежеш 20 секунди от animatic струва минути, а 20 секунди готова анимация — седмици работа.","more":"При „Играта на играчките“ през 1993 г. прожекцията на story reel показала, че Уди е груб и несимпатичен. Дисни спрели производството, докато историята не била преработена — още на етапа на рисунките."},{"id":"studio.board.types.c03","legacyId":"c12uq55f","hall":"studio","domain":"board","topic":"board.types","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Storyboard от 48 панела е монтиран в animatic от 2 минути. Колко секунди средно стои един панел?","answer":2.5,"unit":"s","explain":"Превръщаш минутите в секунди и делиш общото време на броя на панелите: 2 min = 120 s; 120 ÷ 48 = 2,5 s на панел.","more":"Средното време е само ориентир. В истинския animatic всеки панел стои толкова, колкото трае действието или репликата в него — изиграй ги на глас с хронометъра на телефона."},{"id":"studio.board.types.c04","legacyId":"coytlo6","hall":"studio","domain":"board","topic":"board.types","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Нямате време да рисувате, но утре операторът трябва да разбере сцената. Какво правите?","options":[{"text":"Изпращаме сценария и оставяме оператора да реши","why":"Сценарият казва какво се случва, но не и как се вижда в кадър."},{"text":"Снимаме сцената от един общ план и режем после","why":"Така няма да има монтаж и акцент."},{"text":"Пишем кадър по кадър с думи какво се вижда","why":""},{"text":"Импровизираме на площадката, щом видим мястото","why":"Импровизацията струва време на площадката — точно това, което липсва."}],"answer":2,"explain":"Това е prose storyboard: всяко изречение е един кадър с план и действие — „Крупен план: Ана вдига поглед.“, „Кадър от гледна точка: вратата се открехва.“ Така и без рисунки операторът знае какво да снима.","more":"Prose storyboard описва какво вижда зрителят, а списъкът на кадрите (Shot list) — какво трябва да подготви екипът: план, ракурс, обектив, движение. Често първото се превръща във второто."},{"id":"studio.board.types.c05","legacyId":"cqxsxyq","hall":"studio","domain":"board","topic":"board.types","topic2":"prod.periods","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"В кой период на производството се правят storyboard и animatic?","options":[{"text":"Продукционния","why":"В продукционния период се снима или анимира — решенията вече трябва да са взети."},{"text":"Постпродукционния","why":"Постпродукцията е монтаж, звук и цвят; тогава е късно за превизуализация."},{"text":"Ликвидационния","why":"Ликвидационният период приключва документите и сметките на продукцията."},{"text":"Подготвителния","why":""}],"answer":3,"explain":"Превизуализацията е подготовка: решенията се взимат на хартия, където са евтини. Когато започнат снимките или анимацията, всеки кадър вече трябва да е измислен.","more":"За битките в космоса в „Междузвездни войни“ Джордж Лукас монтира кадри от стари филми за въздушни боеве. Така екипът по ефектите видя какъв ритъм и какви ъгли иска режисьорът, преди да е готов дори един кадър."},{"id":"studio.board.types.c06","legacyId":"ca6rk6d","hall":"studio","domain":"board","topic":"board.types","topic2":"prod.periods","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди етапите на производството на анимационен филм.","sequence":["Сценарий","Storyboard","Animatic","Layout","Анимация","Комбинирани снимки (Compositing)","Финален звук и монтаж"],"explain":"Всеки етап проверява предишния: animatic проверява storyboard във времето, а layout подготвя точната сцена за аниматорите. Слоевете се събират в готов кадър едва когато движението е завършено.","more":"В анимацията гласовете обикновено се записват преди анимацията — предварителен запис (Pre-recording). Аниматорът играе и синхронизира устата по готовата реплика, а не обратното."},{"id":"studio.board.types.c07","legacyId":"cbk24lw","hall":"studio","domain":"board","topic":"board.types","topic2":"story.docs","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy","fixes":["P08"]},"kind":"card","format":"choice","prompt":"Защо в много анимационни студия storyboard е и начин да се „пише“ историята?","options":[{"text":"Сценаристите в анимацията обикновено не пишат текст","why":"В анимацията също има сценарии; в storyboard те се проверяват и развиват в образи."},{"text":"Рисунките се използват направо във финалния филм","why":"Панелите са чернова — финалните кадри се рисуват наново."},{"text":"Гаговете и ритъмът се откриват по-добре в рисунки","why":""},{"text":"Така историята може да се разкаже без диалог","why":"Диалогът остава; рисунките помагат да се открият гаговете и ритъмът."}],"answer":2,"explain":"Анимацията е визуално изкуство: дали един гаг е смешен и дали ритъмът работи, се вижда в рисунките, а не в текста. Затова историята често се преработва на стената с панели, докато не заработи.","more":"Хаяо Миядзаки от студио „Гибли“ работи без написан сценарий: сам рисува storyboard и той служи за сценарий на целия екип. Понякога анимацията започва, преди storyboard да е завършен."},{"id":"studio.board.notation.c01","legacyId":"ctdz6g4","hall":"studio","domain":"board","topic":"board.notation","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Какво означават вътрешната рамка и стрелките в този панел?","options":[{"text":"Камерата се отдалечава от вътрешната рамка","why":"При отдалечаване стрелките сочат навън — от вътрешната рамка към ъглите на панела; тук сочат навътре."},{"text":"Героят се отдалечава навътре в кадъра","why":"Движението на героя се отбелязва със стрелка, която тръгва от самия него, а не от ъглите на панела."},{"text":"Камерата се приближава до вътрешната рамка","why":""},{"text":"Героят гледа през рамката на прозорец","why":"Прозорецът би бил част от декора и нямаше да има стрелки; рамката със стрелки е знак за движение на камерата."}],"answer":2,"explain":"Вътрешната рамка е крайният кадър, а стрелките от ъглите показват, че рамката на екрана се свива до нея — с шарийо или трансфокация. Обратните стрелки значат отдалечаване.","more":"Знакът е общ за трансфокация и шарийо, затова уточни с надпис кое имаш предвид. При трансфокация камерата стои и сменя фокусното разстояние, а при шарийо минава през пространството и перспективата се променя.","visual":{"type":"notation"}},{"id":"studio.board.notation.c02","legacyId":"c15qdc8z","hall":"studio","domain":"board","topic":"board.notation","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи знака в storyboard със значението му.","pairs":[["Стрелка вътре в кадъра","Движение на героя или предмета"],["Стрелка по рамката или извън нея","Движение на камерата"],["Вътрешна рамка със стрелки към нея","Приближаване"],["ЗК","Глас или звук зад кадър"],["„Сц. 4 / Кадър 12“","Номерация"]],"explain":"Всеки знак отговаря на един въпрос: какво се движи в кадъра, какво прави камерата, откъде идва звукът и кой е този кадър. Затова нотацията е общ език между режисьор, оператор, аниматор и монтажист.","more":"Глебас: обикновеното срязване се отбелязва с „CUT“ в горния ляв ъгъл на следващия кадър, а преливането (Dissolve) — с „X“ между двата панела."},{"id":"studio.board.notation.c03","legacyId":"c1neuars","hall":"studio","domain":"board","topic":"board.notation","topic2":"edit.space","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Два поредни панела показват една и съща героиня в почти един и същ размер от почти същия ъгъл. Какво ще се случи на екрана?","options":[{"text":"Образът ще подскочи — нарушено е правилото 30°","why":""},{"text":"Монтажът ще е плавен, защото кадрите почти съвпадат","why":"Почти еднаквите кадри изглеждат като грешка — образът подскача."},{"text":"Героинята ще смени посоката — нарушено е правилото 180°","why":"Ъгълът почти не се мени, така че оста не е прекосена."},{"text":"Ще се получи графично съвпадение по форма","why":"Графичното съвпадение свързва различни неща по форма; тук е едно и също нещо, почти без промяна."}],"answer":0,"explain":"Когато размерът и ъгълът почти не се променят, окото не приема срязването като нов кадър, а като скок в същия образ. Storyboard е мястото да хванеш тази грешка, преди да е заснета.","more":"Ако ти трябват два кадъра на една героиня, смени ясно поне едно: размера (например от среден към крупен план) или ъгъла с поне 30°. Помага и вмъкнат кадър (Cutaway) помежду им."},{"id":"studio.board.notation.c04","legacyId":"ccw2szr","hall":"studio","domain":"board","topic":"board.notation","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо номерираме панелите?","options":[{"text":"Така софтуерът за монтаж ги подрежда автоматично","why":"Софтуерът не чете номерата на хартия; номерът е общ адрес за хората в екипа."},{"text":"Така се изчислява колко секунди ще трае филмът","why":"Времето се мери в animatic; номерът е адрес, а не продължителност."},{"text":"Така всички в екипа говорят за един и същ кадър","why":""},{"text":"Така продуцентът знае колко панела да плати","why":"Номерът служи за комуникация между сценарий, снимачен план и монтаж."}],"answer":2,"explain":"„Сц. 7, кадър 3“ значи едно и също за режисьора, оператора, аниматора и монтажиста. Когато панели се разместят или се добавят нови, бележките пак стигат до точния кадър.","more":"Глебас приключва краткия си преглед на работата по storyboard със съвета: „Номерирай рисунките си!“. Ако по-късно вмъкнеш панел между 12 и 13, означи го 12A, вместо да преномерираш всичко."},{"id":"studio.board.check.c01","legacyId":"c1mdv2hy","hall":"studio","domain":"board","topic":"board.check","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","prompt":"Кои въпроси задаваш на всеки кадър от storyboard, преди да го рисуваш на чисто?","checklist":["Какъв е смисълът — кой момент от историята показва?","Чия гледна точка е?","Защо точно този план и ракурс?","Ясни ли са посоките и оста?","Какво ново носи спрямо предишния кадър?","Къде ще гледа зрителят?"],"model":"Първо: какво казва този кадър и чий е. После: защо този размер и ъгъл, какво е новото, пазят ли се посоките и къде е фокусът на вниманието.","more":"Глебас гради цялата си книга върху два въпроса: „Защо гледаме?“ и „Какво прави зрителят?“. Според него двата врага на добрия дизайн са скуката и объркването."},{"id":"studio.board.check.c02","legacyId":"cmc4pwv","hall":"studio","domain":"board","topic":"board.check","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Storyboard от 12 панела: всички в профил, всички в среден план, героят винаги е в центъра. Какъв е проблемът?","options":[{"text":"Липсва цвят, затова панелите изглеждат еднакво","why":"Цветът не решава проблема; еднаквите кадри пак нямат ритъм и акцент."},{"text":"Липсва разнообразие в размера, ъгъла и позицията","why":""},{"text":"Дванайсет панела са твърде много за една сцена","why":"Броят не е проблемът — дори три еднакви панела са скучни."},{"text":"Нарушено е правилото 180°, защото героят е в профил","why":"Профилът не нарушава правилото 180°; проблемът е еднообразието."}],"answer":1,"explain":"Когато всеки панел повтаря предишния, окото не получава нищо ново и сцената губи ритъм и акценти. Профилът е най-лесният и най-плоският избор; всяка смяна на кадъра трябва да идва от историята.","more":"Упражнение: изпиши до всеки панел плана и ракурса му. Ако едно и също се повтаря три пъти подред, потърси в историята повод за смяна — нов герой, ново чувство, нова информация."},{"id":"studio.board.check.c03","legacyId":"c15iw3li","hall":"studio","domain":"board","topic":"board.check","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво означава „всеки кадър е крупен план на нещо“?","options":[{"text":"Кадрите трябва да са предимно крупни планове на лица","why":"Изразът е метафора: и общият план е „крупен план“ на мястото."},{"text":"Общите планове трябва да се избягват в разказа","why":"Общите планове са нужни — те също показват едно главно нещо: мястото."},{"text":"Всеки кадър трябва да показва колкото може повече","why":"Кадър, който показва всичко еднакво, не показва нищо."},{"text":"Всеки кадър трябва да показва ясно едно главно нещо","why":""}],"answer":3,"explain":"Глебас: когато насочим камерата, избираме какво влиза в рамката, затова всеки кадър казва „Виж това!“. Както в речта — една мисъл наведнъж, иначе зрителят не знае къде да гледа.","more":"Проверка преди рисуване: напиши под панела с една дума главното в него — „лице“, „ключ“, „площад“. Ако не можеш да избереш една дума, кадърът още не е измислен."},{"id":"studio.board.check.c04","legacyId":"c3j879l","hall":"studio","domain":"board","topic":"board.check","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"В кадъра две еднакво големи и еднакво осветени фигури стоят в двата края, а сцената е за едната от тях. Какъв е проблемът?","options":[{"text":"Фигурите са твърде далеч и не се чете лицето","why":"Разстоянието не е проблемът; проблемът е, че и двете фигури тежат еднакво."},{"text":"Вниманието се разделя и няма главна фигура","why":""},{"text":"Нарушено е правилото 180° между двете фигури","why":"Правилото 180° е за монтажа между кадри, не за разположението в един кадър."},{"text":"Кадърът е добре балансиран и няма проблем","why":"Равновесието тук разделя вниманието — окото не знае кого да гледа."}],"answer":1,"explain":"Окото първо отива към по-голямото, по-близкото, по-светлото и по-контрастното. Когато двете фигури тежат еднакво, зрителят се лута между тях; направи главната по-голяма, по-близо, по-светла или в цвят.","more":"Глебас режисира епизода „Pomp and Circumstance“ във „Фантазия 2000“. В ранен вариант Доналд и Дейзи се разминаваха в двата края на Ноевия ковчег и зрителят не знаеше къде да гледа; решението беше да са близо, но нещо да им пречи да се видят."},{"id":"studio.board.action.c01","legacyId":"ciggvyh","hall":"studio","domain":"board","topic":"board.action","level":12,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Гонитба върви в storyboard, но след десетия кадър става скучна. Какво правиш?","options":[{"text":"Сменям средата, залога или кой води","why":""},{"text":"Добавям още кадри от същото действие","why":"Повече от същото е още по-скучно."},{"text":"Ускорявам монтажа, за да се усети скорост","why":"По-бързото е същото, само по-бързо."},{"text":"Слагам по-силна и по-бърза музика","why":"Музиката не поправя липсата на развитие."}],"answer":0,"explain":"Action сцената е история: зрителят следи не скоростта, а развитието. Всяка смяна поставя нов малък конфликт и нов въпрос „А сега какво?“, затова интересът се връща.","more":"В „Генералът“ на Бъстър Кийтън гонитбата се обръща по средата: първо героят преследва откраднатия си локомотив, после преследват него. Същото действие, но с нова динамика — кой води."},{"id":"studio.board.action.c02","legacyId":"c1k3xpg6","hall":"studio","domain":"board","topic":"board.action","level":12,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","prompt":"Какви са основите на добрата action сцена?","checklist":["Цел — какво иска героят","Препятствие — какво му пречи","Емоция и тон","Специфичност — движения, възможни само тук и само за този герой"],"model":"Героят трябва да иска нещо конкретно, препятствието трябва да расте, тонът трябва да е ясен (смешно, страшно, епично), а действието — специфично за героя и мястото.","more":"Тест преди рисуване: опиши сцената с едно изречение „… иска …, но …“. Ако не можеш да го допълниш, на сцената ѝ липсва цел или препятствие и никакви ефектни удари няма да я спасят."},{"id":"studio.board.action.c03","legacyId":"cwxldlu","hall":"studio","domain":"board","topic":"board.action","topic2":"anim.timing","level":12,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Задържане във въздуха (Hang time): какво става със spacing в най-високата точка на скока?","options":[{"text":"Позициите се разреждат горе и се сгъстяват при падането","why":"Обратното: горе героят „виси“ — позициите са близо една до друга, а при падането се раздалечават."},{"text":"Позициите са на равни разстояния през целия скок","why":"Равното spacing дава механично движение без задържане."},{"text":"Позициите се сгъстяват горе и се разреждат при падането","why":""},{"text":"Горната точка се пропуска, за да е скокът по-бърз","why":"Задържането е точно горе — ако го пропуснеш, ефектът изчезва."}],"answer":2,"explain":"Задържането е ускорение и забавяне (Slow In and Slow Out), доведени до крайност: мигът горе трае, а падането е светкавично. Близките позиции четем като бавно движение, далечните — като бързо.","more":"В storyboard и animatic задръж панела с върха на скока по-дълго, а падането покажи с един-два бързи панела. Така ефектът се проверява още преди анимацията."},{"id":"studio.board.action.c04","legacyId":"cx46obl","hall":"studio","domain":"board","topic":"board.action","topic2":"edit.space","level":12,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо в action сцена са нужни преориентиращи общи планове?","options":[{"text":"Сцената да стане по-дълга и по-епична","why":"Целта не е дължината, а ориентацията между бързите кадри."},{"text":"Да се спестят скъпите крупни планове","why":"Крупните планове не са по-скъпи; общият план дава карта на действието."},{"text":"Зрителят да не се обърка кой къде е","why":""},{"text":"Да се скрият грешките в хореографията","why":"Общият план показва хореографията по-ясно, а не я крие."}],"answer":2,"explain":"Бърз монтаж без ориентация е шум: зрителят вижда удари, но не разбира кой печели. Общият план е „картата“, след която крупните планове отново имат смисъл.","more":"Глебас съветва сложна сцена да се планира с прост план отгоре и стрелки — като схема на разиграване във футбола. Начертай такъв план на боя, преди да рисуваш панелите, и сам няма да се объркаш кой къде е."},{"id":"studio.board.action.c05","legacyId":"c112inil","hall":"studio","domain":"board","topic":"board.action","level":12,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Бой в кухня. Как го правиш специфичен?","options":[{"text":"Героите се бият с тигани, брашно и чекмеджета","why":""},{"text":"Героите се бият със стандартни удари с юмруци","why":"Стандартните удари може да са навсякъде — нищо не е специфично за кухнята."},{"text":"Всеки удар е показан на забавен каданс","why":"Забавеният каданс подчертава, но не прави боя специфичен за мястото."},{"text":"Боят се снима с ръчна камера отблизо","why":"Ръчната камера добавя енергия, но не използва кухнята."}],"answer":0,"explain":"Специфичността прави сцената запомняща се: предметите на мястото стават оръжия, препятствия и гагове, затова този бой може да се случи само тук.","more":"Джеки Чан гради боевете си точно така: стълби, столове, маси — всичко наоколо влиза в играта. Опитай: избери стая у дома и запиши пет предмета, които могат да станат част от гонитба."},{"id":"studio.story.docs.c01","legacyId":"c118q864","hall":"studio","domain":"story","topic":"story.docs","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди документите в обичайния ред на разработка на игрален филм.","sequence":["Идея","Logline","Синопсис","Treatment","Сценарий","Работна книга"],"explain":"Всеки документ разгъва предишния: едно изречение → страница → разказ сцена по сцена → сценарий с диалог → разбивка на кадри. Така слабостите в историята излизат наяве, докато промените още са евтини.","more":"Работната книга е мостът към подготовката на снимките: от нея се правят storyboard, списъкът на кадрите (Shot list) и разбивката на сценария (Script breakdown), а по тях — снимачният план."},{"id":"studio.story.docs.c02","legacyId":"c9jy4g5","hall":"studio","domain":"story","topic":"story.docs","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Logline: „Филм за приятелството и надеждата.“ Какво не е наред?","options":[{"text":"Твърде кратко е — logline трябва да е поне абзац","why":"Logline е едно изречение; проблемът е в съдържанието, не в дължината."},{"text":"Това е тема: липсват герой, цел, препятствие и залог","why":""},{"text":"Не издава края, а logline трябва да го казва","why":"Краят е за синопсиса; logline показва героя, целта и препятствието."},{"text":"Липсва името на героя, иначе е наред","why":"Името не е задължително; липсват цел, препятствие и залог — това е тема."}],"answer":1,"explain":"„Приятелство и надежда“ казват за какво е филмът, но не и какво се случва в него — това е тема. Logline разказва действие: кой, какво иска, какво му пречи и какво рискува. Пример: „Срамежливо момче трябва да спечели конкурса по танци, за да спаси школата на баба си.“","more":"В logline героят често се описва с черта и роля вместо с име — „срамежливо момче“, „свръхгрижовен баща“. Чертата веднага подсказва конфликта: срамежливият ще трябва да излезе на сцена."},{"id":"studio.story.docs.c03","legacyId":"c12nm7wz","hall":"studio","domain":"story","topic":"story.docs","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","prompt":"Напиши logline за „Червената шапчица“ в едно изречение.","checklist":["Герой (кой)","Цел (какво иска)","Препятствие или антагонист","Залог (какво ще загуби)","Едно изречение"],"model":"Момиче, изпратено да занесе храна на болната си баба, трябва да разпознае вълка, преоблечен като баба ѝ, преди самата тя да стане негова вечеря.","more":"Опитай формулата: „Когато [подбудително събитие], [герой] трябва да [цел], иначе [залог].“ Попълни я за три различни приказки и провери дали залогът е ясен — без него logline звучи като преразказ."},{"id":"studio.story.docs.c04","legacyId":"cl5qq59","hall":"studio","domain":"story","topic":"story.docs","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Каква е разликата между анотация и синопсис?","options":[{"text":"Синопсисът не издава края, а анотацията го разказва","why":"Обратното: анотацията привлича, без да издава края, а синопсисът преразказва всичко."},{"text":"Анотацията е за продуцента, а синопсисът — за зрителя","why":"Обратно е: анотацията е за зрителя (афиш, каталог), синопсисът — за продуцента и журито."},{"text":"Анотацията не издава края, а синопсисът го разказва","why":""},{"text":"Синопсисът е едно изречение, а анотацията — страница","why":"Едно изречение е logline; синопсисът преразказва целия сюжет."}],"answer":2,"explain":"Анотацията е реклама: тя трябва да събуди любопитство, затова пази тайната. Синопсисът е работен документ — по него се преценява дали цялата история работи, а без края това е невъзможно.","more":"Упражнение: вземи синопсиса на любим филм и го съкрати до анотация от три изречения. Остави героя, света му и подбудителното събитие — това е куката. Всичко след него махни."},{"id":"studio.story.docs.c05","legacyId":"c17bfaxx","hall":"studio","domain":"story","topic":"story.docs","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво съдържа работната книга, което го няма в литературния сценарий?","options":[{"text":"Диалога на героите и ремарките към актьорите","why":"Диалогът и ремарките са още в литературния сценарий."},{"text":"Описание на героите и на техните мотиви","why":"Героите са описани в литературния сценарий; работната книга добавя езика на камерата."},{"text":"Разбивка на кадри с план, ракурс и движение","why":""},{"text":"Кратък синопсис и анотация за продуцента","why":"Синопсисът и анотацията са отделни документи преди сценария."}],"answer":2,"explain":"Литературният сценарий казва какво се случва; работната книга казва как ще го види зрителят. Режисьорът разбива всяка сцена на номерирани кадри и така текстът става план за снимане.","more":"Работната книга често се оформя като таблица с колони: номер на кадъра, план, действие, диалог и звук, продължителност. Опитай с една сцена от свой сценарий — веднага ще видиш колко кадъра ти трябват."},{"id":"studio.story.structure.c01","legacyId":"c72wsqu","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"explain","prompt":"Разкажи любим анимационен филм в три акта за 30 секунди.","checklist":["Завръзка: светът на героя и подбудителното събитие","Развитие: растящи препятствия и повратни точки","Кулминация: решаващият сблъсък","Развръзка: новото равновесие","Героят се е променил"],"model":"Пример: героят живее в познатия си свят; нещо го изважда оттам; препятствията растат; в кулминацията рискува всичко; накрая светът е в нов баланс, а героят вече е друг.","more":"Пример — „Търсенето на Немо“: водолаз хваща Немо; Марлин прекосява океана през акули и медузи; в кулминацията при рибарската мрежа се доверява на сина си; накрая сам го пуска на училище — вече не е свръхгрижовен."},{"id":"studio.story.structure.c02","legacyId":"c1c9v5tb","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Сираче живее под стълбището, докато един ден не пристига писмо, което го кани в училище за магьосници. Каква роля има писмото в структурата на историята?","options":[{"text":"Събитието, което нарушава обичайния му живот","why":""},{"text":"Моментът, в който той сам решава да тръгне","why":"Решението да тръгне идва по-късно — това е първата повратна точка; писмото е подбудата."},{"text":"Най-високата точка на конфликта във филма","why":"Кулминацията е към края; писмото е в началото."},{"text":"Обратът в средата, след който светът се променя","why":"Средната точка е обрат по средата на филма; писмото отваря историята."}],"answer":0,"explain":"Писмото нарушава равновесието и отваря историята — затова е подбудителното събитие (Inciting incident). Решението на героя да тръгне е отделен, по-късен момент: първата повратна точка.","more":"Във филма „Хари Потър и Философският камък“ вуйчо Върнън унищожава писмата, но те прииждат на стотици, дори през камината. Силното подбудително събитие не може да бъде пренебрегнато."},{"id":"studio.story.structure.c03","legacyId":"c1j9bok3","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво е гръбнакът на ролята (spine) и защо се формулира с глагол?","options":[{"text":"Главната черта на героя; прилагателното е по-точно","why":"„Тъжен“ не може да се изиграе; „да докаже, че е прав“ може — затова е глагол."},{"text":"Главното действие на героя; глаголът може да се изиграе","why":""},{"text":"Биографията на героя; глаголът показва миналото му","why":"Биографията е предистория; гръбнакът е това, което героят прави сега."},{"text":"Първата реплика на героя; глаголът я прави ясна","why":"Гръбнакът не е реплика, а основното действие, което движи героя през цялата роля."}],"answer":1,"explain":"Глаголът дава посока: всяка сцена може да се провери с въпроса „Как героят се опитва да постигне това тук?“. Чувствата са резултат от действието — актьорът или аниматорът не може да ги играе направо.","more":"Практика: напиши гръбнака на своя герой като „да + глагол“ над първата страница на сценария. Ако в някоя сцена героят не прави нищо за тази цел, сцената вероятно е излишна."},{"id":"studio.story.structure.c04","legacyId":"ch4ip4z","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Сцена: майка обвинява дъщеря си, а дъщерята се оправдава. Къде е точката на опора (Fulcrum)?","options":[{"text":"Когато майката каже първата си реплика в спора","why":"Началото задава конфликта, но силата още не се обръща."},{"text":"Когато дъщерята спре да се защитава и мине в атака","why":""},{"text":"Когато дъщерята излезе и затръшне вратата","why":"Излизането е краят на сцената; обратът е по-рано, когато силата сменя страната."},{"text":"Когато майката повиши глас за първи път","why":"Повишеният глас засилва конфликта, но силата остава у майката — обратът е при дъщерята."}],"answer":1,"explain":"Точката на опора е мигът, в който балансът на силите се обръща: досега води майката, оттук — дъщерята. Около него режисьорът често сменя плана или мизансцена, за да усети обрата и зрителят.","more":"Упражнение: изиграйте спора по двама и разменете позициите точно в точката на опора — който стоеше, сяда, а който седеше, става. Едно движение прави обрата видим без нито една дума."},{"id":"studio.story.structure.c05","legacyId":"c1xttmyc","hall":"studio","domain":"story","topic":"story.structure","topic2":"story.staging","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо режисьорът разделя сцената на драматични блокове (dramatic blocks)?","options":[{"text":"Така всяка смяна на задачата получава своя постановка","why":""},{"text":"Така сцената се съкращава до най-важните реплики","why":"Блоковете не съкращават — те показват къде се сменя задачата и с нея постановката."},{"text":"Така се изчислява колко страници ще е сцената","why":"Страниците се броят за графика; блоковете са драматургичен инструмент."},{"text":"Така всеки блок се снима в отделен снимачен ден","why":"Блоковете са части на една сцена и обикновено се снимат заедно."}],"answer":0,"explain":"Драматичният блок е отрязък, в който героят преследва една задача. Когато задачата се смени, се сменя и начинът, по който снимаме — затова блоковете са карта за плановете и мизансцена.","more":"Опитай: в сцена от свой сценарий начертай линия навсякъде, където героят сменя задачата си, и дай на всеки блок заглавие с глагол — „моли“, „заплашва“, „отстъпва“. Заглавията ще ти покажат и точката на опора."},{"id":"studio.story.irony.c01","legacyId":"cbopad","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Под масата има бомба. Зрителят я вижда, героите — не, и пет минути си говорят за футбол. Какво получаваме?","options":[{"text":"Изненада (Surprise)","why":"Изненада би било, ако зрителят не знае за бомбата и тя просто избухне."},{"text":"Ситуационна ирония (Situational irony)","why":"Тук няма резултат, обратен на очакваното — има чакане."},{"text":"Кулминация (Climax)","why":"Кулминацията е най-високата точка на историята, а не похват за знание и чакане."},{"text":"Напрежение (Suspense)","why":""}],"answer":3,"explain":"Хичкок обяснява разликата точно с този пример: ако бомбата просто избухне, зрителят получава 15 секунди изненада; ако знае за нея, получава 15 минути напрежение. Ключът е в това какво знае зрителят.","more":"Опитай в свой филм: покажи опасността рано и после дай на героите обикновен, дори скучен разговор. Колкото по-безобиден е разговорът, толкова по-силно е напрежението — зрителят иска да им извика."},{"id":"studio.story.irony.c02","legacyId":"cgu6pop","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Пожарникар губи къщата си в пожар, защото е на смяна на друг пожар. Каква е иронията?","options":[{"text":"Драматична ирония (Dramatic irony)","why":"Драматичната ирония е, когато зрителят знае нещо, което героят не знае."},{"text":"Вербална ирония (Verbal irony)","why":"Вербалната е в думите — казва се обратното на мисленото."},{"text":"Структурна ирония (Structural irony)","why":"Структурната е вградена в самия разказ, например ненадежден разказвач."},{"text":"Ситуационна ирония (Situational irony)","why":""}],"answer":3,"explain":"От пожарникаря очакваме да е най-защитен от огъня, а точно работата му го лишава от дома. Ситуационната ирония е в разминаването между очакването и резултата.","more":"В „Шрек“ всички чакат целувката на истинската любов да превърне Фиона в красива принцеса, а тя завинаги приема облика си на огър — обратното на приказния край."},{"id":"studio.story.irony.c03","legacyId":"c1tylbgd","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Дъжд в деня на сватбата ирония ли е?","options":[{"text":"Да — ситуационна, защото никой не иска дъжд на сватба","why":"Нежеланото не е непременно обратното на очакваното; иначе всяко нещастие би било ирония."},{"text":"Да — драматична, защото зрителят знае прогнозата","why":"Нищо не казва, че зрителят знае повече от героите."},{"text":"Да — вербална, защото хората казват „какъв късмет“","why":"Вербалната ирония е в думите на някого, а не в самото събитие."},{"text":"Не — това е лош късмет, а не обратното на очакваното","why":""}],"answer":3,"explain":"Иронията изисква обратното на очакваното, а не просто нещо неприятно. Ирония би била дъжд на сватба в пустинята, избрана точно заради сухото време.","more":"Примерът идва от песента „Ironic“ на Аланис Морисет. Повечето неща, които тя изброява като ирония, всъщност са лош късмет — затова песента често се дава като пример за тази честа грешка."},{"id":"studio.story.irony.c04","legacyId":"c1mn18qt","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди етапите на драматичната ирония.","sequence":["Подготовка: зрителят научава тайната","Задържане: героят действа, без да знае","Развръзка: героят научава истината"],"explain":"Първо зрителят трябва да научи тайната — иначе няма какво да задържаш. После героят действа, без да знае, а зрителят чака разкриването. Колкото по-дълго държиш, толкова по-силна е развръзката.","more":"В „Играта на играчките“ зрителят знае, че Бъз е играчка, а той се мисли за истински космически рейнджър. Развръзката идва, когато вижда по телевизията реклама на самия себе си."},{"id":"studio.story.irony.c05","legacyId":"ceat3hf","hall":"studio","domain":"story","topic":"story.irony","topic2":"lang.pov","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кой кадър е задължителен, за да се получи напрежение с бомбата под масата?","options":[{"text":"Кадър от гледната точка на един от героите","why":"През очите на героите бомбата остава скрита — зрителят няма да знае за нея."},{"text":"Крупен план на лицето на говорещия герой","why":"Лицето показва героя, но не дава на зрителя знанието за бомбата."},{"text":"Кадър на бомбата, който героите не виждат","why":""},{"text":"Установяващ план на кафенето отвън","why":"Установяващият план ориентира, но не показва бомбата."}],"answer":2,"explain":"Напрежението започва с информация, а в киното информацията се дава с кадър. Бомбата трябва да бъде показана на зрителя, но извън погледа на героите — камерата знае повече от тях.","more":"В примера си Хичкок слага в декора и часовник, за да знае зрителят кога ще избухне бомбата. Опитай и ти: след кадъра на опасността връщай камерата към часовника — зрителят ще брои заедно с теб."},{"id":"studio.story.irony.c06","legacyId":"csyvs3q","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"explain","prompt":"Каква е разликата между изненада и напрежение? Дай собствен пример.","checklist":["Изненада: зрителят не знае — кратък шок","Напрежение: зрителят знае предварително — продължително очакване","Напрежението изисква информация, дадена рано","Даден е собствен пример"],"model":"Изненада: вратата се отваря и чудовището изскача. Напрежение: зрителят видя чудовището да влиза в гардероба, а героинята отива да си вземе палто.","more":"Двата похвата често работят заедно: напрежението трупа очакване към една врата, а изненадата идва от друга. Зрителят е бил нащрек, но не там, където трябва."},{"id":"studio.story.staging.c01","legacyId":"c151k6w7","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Двама бивши приятели се срещат в кафене. Как показваш дистанцията, без да я назоваваш с думи?","options":[{"text":"Казват си направо, че вече не са приятели","why":"Думите казват, мизансценът показва — показаното е по-силно."},{"text":"Сядат в двата края на масата, с колона между тях","why":""},{"text":"Крупни планове на лицата и тъжна музика","why":"Музиката подсказва чувство, но не и отношението между тях."},{"text":"Снимаме цялото кафене отгоре, с птичи поглед","why":"Птичият поглед е далечен и не показва отношението."}],"answer":1,"explain":"В мизансцена разстоянието и преградите са отношение: близките хора сядат близо, а разделените — разделени. Предмет между тях превръща дистанцията във видима граница, която зрителят усеща без думи.","more":"Ако и в кадрите кадър – контракадър (Shot/reverse shot) колоната остава в края на кадъра, дистанцията се усеща през цялата сцена. Когато се сдобрят, махни преградата и ги събери в един кадър."},{"id":"studio.story.staging.c02","legacyId":"c1xiodr2","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Шеф и служител разговарят в кабинет с голямо бюро между тях. Какво прави мизансценът?","options":[{"text":"Бюрото ги сближава, защото са на една маса","why":"Голямото бюро разделя, а не сближава — то е бариера."},{"text":"Бюрото е бариера и знак за властта на шефа","why":""},{"text":"Бюрото е реквизит, който показва професията","why":"Мястото показва професията, но бюрото между тях говори за власт и дистанция."},{"text":"Бюрото скрива краката и прави кадъра по-чист","why":"Техническата полза не е смисълът на мизансцена."}],"answer":1,"explain":"Предметите в мизансцена са инструменти: разделят, свързват, дават статус. Голямото бюро държи служителя на разстояние и прави шефа център на пространството — властта се вижда, без да се казва.","more":"Опитай с един предмет: снимай същия разговор веднъж с бюро между героите и веднъж със служителя, седнал на ръба на бюрото. Във втората версия отношенията веднага стават по-близки или по-дръзки."},{"id":"studio.story.staging.c03","legacyId":"cdj1zv2","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"explain","prompt":"Формулирай режисьорска концепция за 30-секунден клип на тема по избор.","checklist":["Една централна идея или емоция","Визуален стил (техника, форма)","Правило за камерата (планове, движение)","Правило за цвета и светлината","Всичко е подчинено на идеята"],"model":"Пример: „Самотата в големия град“. Изрезкова анимация с остри форми; само статични общи планове и един крупен план в края; сива палитра с един топъл прозорец.","more":"Провери концепцията си и с „не“: запиши какво няма да има във филма — например ръчна камера или червен цвят. Ограниченията пазят стила цял и помагат на екипа да взема решения бързо."},{"id":"studio.story.staging.c04","legacyId":"cx1tz03","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо в типажа злодеите често имат остри, триъгълни форми, а добрите герои — кръгли?","options":[{"text":"Кръглите форми са по-лесни за рисуване и анимиране","why":"Лекотата не е причината; формата носи характер."},{"text":"Острите форми се виждат по-добре на тъмен фон","why":"Видимостта зависи от контраста, не от ъглите; острото внушава заплаха."},{"text":"Кръглото внушава безопасност, а острото — опасност","why":""},{"text":"Така е било в комиксите и никой не го променя","why":"Традицията съществува, но работи, защото формите носят асоциации."}],"answer":2,"explain":"Зрителят чете формите, преди да чуе дума: кръгът е мек и безопасен, триъгълникът е остър и насочен, квадратът е стабилен и упорит. Аниматорите нарушават този език съзнателно, когато искат изненада.","more":"Във филма „В небето“ на Pixar Карл е изграден от квадрати — твърд и затворен, а Ръсел е кръгъл като яйце. Само по силуетите разбираш, че двамата ще се сблъскат и ще се допълнят."},{"id":"studio.anim.principles.c01","legacyId":"c1bsg6jq","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи примера с принципа на анимацията.","pairs":[["Топката се сплесква при удара в земята","Свиване и разтягане"],["Героят кляка преди скока","Подготвително движение"],["Опашката на котката спира след тялото","Продължаващо и застъпващо се движение"],["Ръката се движи по дъга, не по права","Дъги"],["Колата тръгва бавно, после ускорява","Ускорение и забавяне"]],"explain":"Всеки пример показва физиката зад принципа: ударът сплесква топката, клякането трупа сила за скока, опашката изостава по инерция, ръката се върти около рамото, а колата набира скорост постепенно. Принципите са наблюдения върху реалното движение, преведени на езика на рисунката.","more":"Класическо упражнение: анимирай топка с опашка, която подскача по пода. За 2–3 секунди тренираш свиване и разтягане, дъги, ускорение и забавяне, а опашката добавя и продължаващото движение."},{"id":"studio.anim.principles.c02","legacyId":"c17fkux","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Топката минава през тези позиции кадър по кадър. Какво не е наред?","options":[{"text":"Разстоянията трябва да се скъсяват долу, при удара, а горе да растат","why":"Обратно е: при удара топката е най-бърза, затова долу позициите са най-далеч една от друга."},{"text":"Втората дъга е по-ниска: след удара топката трябва да стига същата височина","why":"При всеки удар топката губи енергия, затова всеки следващ подскок е по-нисък — тук това е вярно."},{"text":"Във върха на дъгата топката трябва да се разтегне, защото там лети най-бързо","why":"Във върха топката е най-бавна и затова е кръгла; разтяга се долу, където скоростта е най-голяма."},{"text":"Разстоянията са почти равни: горе трябва да се скъсяват, а долу да растат","why":""}],"answer":3,"explain":"Скоростта се вижда в spacing: почти равните разстояния значат почти равна скорост — като робот. Истинската топка забавя към върха и ускорява към земята, а при удара трябва и да се сплеска.","more":"Опитай: заснеми истинска подскачаща топка с телефона на забавен каданс (Slow motion) и я пусни кадър по кадър. Във върха позициите почти се застъпват, а до земята са далеч една от друга.","visual":{"type":"ball"}},{"id":"studio.anim.principles.c03","legacyId":"c1yiez62","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","prompt":"Назови поне шест от 12-те принципа на анимацията.","checklist":["Свиване и разтягане (Squash and Stretch)","Подготвително движение (Anticipation)","Сценичност (Staging)","Последователно и от поза до поза (Straight Ahead Action and Pose to Pose)","Продължаващо и застъпващо се движение (Follow Through and Overlapping Action)","Ускорение и забавяне (Slow In and Slow Out)","Дъги (Arcs)","Второстепенно действие (Secondary Action)","Timing","Преувеличение (Exaggeration)","Обемна рисунка (Solid Drawing)","Привлекателност (Appeal)"],"checklistNeed":6,"model":"Squash and Stretch, Anticipation, Staging, Straight Ahead Action and Pose to Pose, Follow Through and Overlapping Action, Slow In and Slow Out, Arcs, Secondary Action, Timing, Exaggeration, Solid Drawing, Appeal — на български: свиване и разтягане, подготвително движение, сценичност, последователно и от поза до поза, продължаващо и застъпващо се движение, ускорение и забавяне, дъги, второстепенно действие, timing, преувеличение, обемна рисунка, привлекателност.","more":"Принципите са описани от Франк Томас и Оли Джонстън — двама от водещите аниматори на Disney — в книгата „The Illusion of Life“ (1981). Те ги извеждат от опита на студиото от 30-те години насам, а днес се преподават и в 3D анимацията."},{"id":"studio.anim.principles.c04","legacyId":"c1gxisov","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво става, ако при свиване и разтягане (squash and stretch) топката променя обема си?","options":[{"text":"Топката сякаш се надува и спада, а теглото се губи","why":""},{"text":"Топката изглежда по-гъвкава и по-реалистична","why":"Промяната на обема не добавя реализъм — предметът сякаш губи и набира материя."},{"text":"Топката изглежда по-тежка, защото се сплесква повече","why":"Тежестта се чете, когато обемът се пази; ако се мени, топката прилича на балон."},{"text":"Движението изглежда по-бързо и по-енергично","why":"Скоростта зависи от timing и spacing, а не от обема."}],"answer":0,"explain":"Колкото топката се сплеска на височина, толкова трябва да се разшири на ширина. Само тогава окото вярва, че материята е същата и просто е сменила формата си — и усеща тегло.","more":"Бърза проверка: начертай правоъгълник около кръглата топка и друг около сплесканата. Площите им трябва да са приблизително равни — ако вторият е много по-голям, топката „набъбва“, а ако е по-малък — „изтича“."},{"id":"studio.anim.principles.c05","legacyId":"cvlu80w","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Героинята върви ядосано по улицата. Кое е добър пример за второстепенно действие (Secondary Action)?","options":[{"text":"Тропа силно с крака при всяка стъпка","why":"Тропането е начинът, по който тя върви — част от главното действие, а не отделно действие към него."},{"text":"Докато върви, бърше сълзите си с ръка","why":""},{"text":"Спира рязко и тръгва в обратната посока","why":"Това са две последователни главни действия, а не второстепенно действие към едно главно."},{"text":"Камерата я следва отстрани, докато върви","why":"Движението на камерата не е действие на героинята."}],"answer":1,"explain":"Второстепенното действие върви успоредно с главното и казва нещо ново за чувството: походката показва гнева, а бърсането на сълзите издава, че под него има болка.","more":"Честа грешка: второстепенното действие става толкова силно, че открадва вниманието от главното. Пусни сцената и виж къде отива погледът ти — ако е на ръката, а не на походката, намали жеста."},{"id":"studio.anim.principles.c06","legacyId":"c13psj90","hall":"studio","domain":"anim","topic":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"За огън, вода и хаотичен дим аниматорите често предпочитат…","options":[{"text":"От поза до поза (Pose to Pose)","why":"От поза до поза дава точен контрол — добър е за планирани действия, а не за органичен хаос."},{"text":"Последователно (Straight Ahead Action)","why":""},{"text":"Rotoscoping","why":"При rotoscoping се прерисува заснет материал; огънят се анимира по-свободно."},{"text":"Изрезкова анимация (Cut-out animation)","why":"Изрезковата анимация движи готови части — за пламък и дим не става."}],"answer":1,"explain":"Последователното анимиране ражда движението рисунка след рисунка, без предварително зададени крайни пози. Затова формата се развива свободно и непредвидимо — точно като огъня, водата и дима. От поза до поза е за ясни, планирани действия.","more":"Stop motion по принцип се снима последователно: куклата се мести и снима кадър след кадър и после няма как да вмъкнеш междинни фази. Затова аниматорът планира позите предварително, а снима поред."},{"id":"studio.anim.phases.c01","legacyId":"cej0f3z","hall":"studio","domain":"anim","topic":"anim.phases","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди работата при анимиране от поза до поза.","sequence":["Миниатюри (Thumbnails)","Ключови фази (Key poses)","Breakdowns","Междинни фази (Inbetweens)","Пускане на сцената и корекции"],"explain":"Първо мислиш на малки скици, после поставяш крайностите, после пътя между тях и накрая плавността. Всеки етап стъпва на предишния, затова грешка в позите се оправя най-лесно, преди да си нарисувал междинните фази.","more":"Упражнение: анимирай скок на герой за 2 секунди (48 кадъра при 24 кадъра в секунда). Първо нарисувай миниатюри на петте ключа — подготовка, отскок, връх, приземяване, изправяне — и чак тогава отвори програмата."},{"id":"studio.anim.phases.c02","legacyId":"ca5yu69","hall":"studio","domain":"anim","topic":"anim.phases","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Главата се обръща от ляво надясно. Breakdown позата е с наведена глава. Какво постига тази поза?","options":[{"text":"Главата минава по права линия, но по-бавно","why":"Точно обратното: наведената поза по средата изкривява пътя в дъга."},{"text":"Движението става по-бързо, защото има още една поза","why":"Скоростта зависи от броя кадри, а не от това каква е междинната поза."},{"text":"Главата се свива и разтяга по средата на обръщането","why":"Свиването и разтягането е друг принцип; тук позата определя траекторията."},{"text":"Главата минава по дъга надолу, а не по права линия","why":""}],"answer":3,"explain":"Breakdown решава по какъв път главата отива от единия ключ до другия, затова е „характерът“ на движението. Без него софтуерът слага проста средна точка, главата се плъзга по права линия и движението става механично.","more":"Упражнение: анимирай обръщане на глава за 12 кадъра в три версии — с наведена глава в breakdown, с вдигната и изобщо без breakdown. Пусни ги една след друга и сравни как се сменя характерът."},{"id":"studio.anim.phases.c03","legacyId":"c13fwjhx","hall":"studio","domain":"anim","topic":"anim.phases","topic2":"hist.pre","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Зоетропът показва безкрайно повтарящо се движение с 12 рисунки. Как днес наричаме такава поредица?","options":[{"text":"Ключови фази (Key poses)","why":"Ключовите фази са главните точки на едно движение; безкрайното повторение е цикъл."},{"text":"Layout","why":"Layout е планът на кадъра — фон, камера, позиции на героите."},{"text":"Animatic","why":"Animatic е storyboard, монтиран с точното време и звука на филма."},{"text":"Цикъл (Cycle)","why":""}],"answer":3,"explain":"Последната рисунка на лентата води плавно обратно към първата, затова зоетропът може да се върти безкрай. Същото прави цикълът в анимацията: ходене, пламък, крила — рисуваш веднъж, повтаряш много пъти.","more":"Направи си прост зоетроп: картонен цилиндър с 12 процепа и лента с 12 рисунки на махаща птица. Процепите работят като затвор на камера — показват всяка рисунка за миг и движението не се размазва."},{"id":"studio.anim.phases.c04","legacyId":"ce576la","hall":"studio","domain":"anim","topic":"anim.phases","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"За какво служи onion skin?","options":[{"text":"Виждаш съседните рисунки прозрачно и сверяваш дъгите","why":""},{"text":"Оцветяваш много кадри наведнъж с един и същ цвят","why":"Оцветяването е отделен етап; onion skin показва съседните рисунки като през калка."},{"text":"Подреждаш звука точно по кадрите на анимацията","why":"Звукът се подрежда по кадрите в експозиционния лист (X-sheet) или на времевата линия в програмата."},{"text":"Изчистваш грубите линии в тънка, чиста линия","why":"Изчистването (Clean-up) е отделен етап; onion skin само показва съседните рисунки."}],"answer":0,"explain":"Onion skin показва предишните и следващите рисунки като бледи силуети, често в два различни цвята. Така виждаш траекторията и разстоянията между позициите, без да прелистваш.","more":"Включвай само 1–2 съседни рисунки във всяка посока — иначе екранът се пълни с линии и губиш позата. За да провериш дълга дъга, включи повече, а после пак намали."},{"id":"studio.anim.timing.c01","legacyId":"c6n1qx6","hall":"studio","domain":"anim","topic":"anim.timing","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"visual","prompt":"Трите редици показват позиции между два ключа. В коя редица движението забавя към втория ключ?","options":[{"text":"Б","why":""},{"text":"А","why":"Редица А е равномерна: еднаквите разстояния значат еднаква скорост, без забавяне."},{"text":"В","why":"Редица В се сгъстява в началото: там движението тръгва плавно, а към ключ 2 ускорява."}],"answer":0,"explain":"По-малко разстояние за кадър значи по-ниска скорост. В Б всяка следваща стъпка е по-къса от предишната, затова обектът плавно забавя и „каца“ меко в ключ 2.","more":"Внимавай с имената: в традицията на Disney slow in значи забавяне към ключа, а в някои програми ease in значи точно обратното — плавно тръгване. Не разчитай на името, гледай разстоянията или кривата.","visual":{"type":"spacing"}},{"id":"studio.anim.timing.c02","legacyId":"cia1qwl","hall":"studio","domain":"anim","topic":"anim.timing","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Три секунди анимация на двойки при 24 кадъра в секунда. Колко рисунки са нужни?","answer":36,"unit":"рисунки","explain":"3 × 24 = 72 кадъра. На двойки всяка рисунка стои 2 кадъра, затова рисунките са наполовина: 72 ÷ 2 = 36.","more":"Японското аниме често работи и на тройки — една рисунка за 3 кадъра, тоест 8 рисунки в секунда. За същите 3 секунди това са само 24 рисунки."},{"id":"studio.anim.timing.c03","legacyId":"c1qvdvh","hall":"studio","domain":"anim","topic":"anim.timing","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Действие трае 18 кадъра при 24 кадъра в секунда. Колко секунди е това?","answer":0.75,"unit":"s","explain":"Секундите са кадрите, разделени на кадровата честота: 18 ÷ 24 = 0,75 s — три четвърти от секундата.","more":"Запомни ориентирите при 24 кадъра в секунда: 6 кадъра = 0,25 s, 12 = 0,5 s, 18 = 0,75 s, 24 = 1 s. Така с един поглед в експозиционния лист знаеш колко трае едно действие."},{"id":"studio.anim.timing.c04","legacyId":"cpbkvjp","hall":"studio","domain":"anim","topic":"anim.timing","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Цикъл на ходене: една крачка = 12 кадъра при 24 кадъра в секунда. Колко крачки прави героят за 6 секунди?","answer":12,"unit":"крачки","explain":"Първо превръщаш секундите в кадри: 6 × 24 = 144. После делиш на кадрите за една крачка: 144 ÷ 12 = 12 крачки — по две в секунда.","more":"Пълният цикъл на ходене има две крачки — при 12 кадъра на крачка това са 24 кадъра. Упражнение: направи цикъла на 12 и на 16 кадъра на крачка и сравни — втората версия изглежда като спокойна разходка."},{"id":"studio.anim.timing.c05","legacyId":"c1m2y0a2","hall":"studio","domain":"anim","topic":"anim.timing","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"explain","prompt":"Обясни на съученик разликата между timing и spacing.","checklist":["Timing — колко кадъра трае действието","Spacing — как са разпределени позициите в тези кадри","Еднакъв timing с различен spacing дава различно усещане","Даден е пример"],"model":"Timing казва „ударът трае 6 кадъра“. Spacing казва дали юмрукът тръгва бавно и удря рязко, или обратното. Два удара с еднакъв timing могат да изглеждат съвсем различно.","more":"Класическо упражнение е махалото: едно люлеене от край до край за 24 кадъра. Сложи позициите нагъсто в двете крайни точки и нарядко долу, където махалото е най-бързо — същият брой кадри изведнъж придобива тежест."},{"id":"studio.anim.timing.c06","legacyId":"c90m0cy","hall":"studio","domain":"anim","topic":"anim.timing","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Тежка наковалня пада за 6 кадъра с равен spacing. Какво не е наред?","options":[{"text":"Липсва ускорение: разстоянията трябва да растат","why":""},{"text":"Липсва забавяне: разстоянията трябва да намаляват","why":"Падащият предмет ускорява — разстоянията растат, а не намаляват."},{"text":"Кадрите са малко: трябва да е на единици, не на двойки","why":"Единици или двойки не решават липсата на ускорение."},{"text":"Падането е твърде бавно: трябват по-малко кадри","why":"Броят кадри не е проблемът; равните разстояния правят падането като на асансьор."}],"answer":0,"explain":"Гравитацията добавя скорост във всеки кадър, затова всяко следващо разстояние трябва да е по-голямо от предишното. Равните разстояния значат равна скорост — като асансьор, а не като свободно падане.","more":"Галилей открива, че при падане от покой разстоянията за равни интервали растат като 1, 3, 5, 7… Упражнение: раздели пътя на 36 части и сложи наковалнята след 1, 4, 9, 16, 25 и 36 части — 6 кадъра истинско ускорение."},{"id":"studio.anim.timing.c07","legacyId":"c14rbctw","hall":"studio","domain":"anim","topic":"anim.timing","topic2":"anim.principles","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Уморен старец става от стол. Какъв timing избираш?","options":[{"text":"Малко кадри, кратка подготовка, рязко изправяне","why":"Така става младеж или супергерой."},{"text":"Равен spacing и еднаква скорост през цялото време","why":"Равният spacing е механичен — няма тежест и възраст."},{"text":"Повече кадри, но без подготовка, направо нагоре","why":"Повечето кадри забавят, но без подготовка и опит движението няма тежест."},{"text":"Повече кадри, дълга подготовка, опит и пауза","why":""}],"answer":3,"explain":"Timing е характер. За да стане, човек първо се навежда напред, докато тежестта мине над стъпалата; уморено старо тяло прави това бавно, понякога от втори опит, и спира за миг, преди да се изправи.","more":"Изиграй го сам: стани от стол като 80-годишен човек и после като дете, заснеми се с телефона и преброй кадрите. Ще видиш, че разликата е не само в скоростта, а и в подготовката и паузите."},{"id":"studio.anim.timing.c08","legacyId":"cdl6tgv","hall":"studio","domain":"anim","topic":"anim.timing","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кога анимираш на единици вместо на двойки?","options":[{"text":"При задържане, за да изглежда героят по-жив","why":"Задържането иска малко движение; единиците там не са нужни."},{"text":"При бързо движение или панорама, където двойките трептят","why":""},{"text":"При синхрон на устните, за да е говорът по-точен","why":"Синхронът обикновено работи и на двойки; единиците са за бързите движения."},{"text":"Когато искаш да спестиш рисунки и да работиш по-бързо","why":"Обратно е: единиците искат двойно повече рисунки от двойките за същото време."}],"answer":1,"explain":"При двойки всяка рисунка стои 1/12 от секундата (при 24 кадъра в секунда). При бързо движение или при движение на камерата разстоянието между рисунките става голямо и окото вижда отделни скокове; единиците ги разполовяват.","more":"Упражнение: анимирай бързо замахване с ръка на двойки, после добави рисунки между тях и го пусни на единици. Сравни двете версии — на двойки ръката „прескача“, а на единици минава плавно."},{"id":"studio.anim.lipsync.c01","legacyId":"c1xzu5wy","hall":"studio","domain":"anim","topic":"anim.lipsync","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди стъпките при синхрона на устните (lip sync).","sequence":["Запис на диалога","Разписване на звуците в експозиционния лист","Актьорски тактове (Acting beats) и ключови фази","Форми на устата по кадрите","Пускане със звука и корекции"],"explain":"Гласът е готов пръв и дава точния timing. После аниматорът решава какво мисли и чувства героят — тялото и лицето носят смисъла — и чак накрая слага формите на устата върху вече живата поза.","more":"Упражнение: запиши с телефона своя реплика от 2–3 секунди и я разпиши по кадри. Преди да рисуваш, изиграй я пред огледало и отбележи къде се сменя мисълта — там ще са новите ключови фази."},{"id":"studio.anim.lipsync.c02","legacyId":"c11wtso5","hall":"studio","domain":"anim","topic":"anim.lipsync","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо формата на устата често се слага 1–2 кадъра преди звука?","options":[{"text":"Защото софтуерът забавя звука с един-два кадъра","why":"Не е техническо закъснение — окото приема за синхронно движение, което леко изпреварва звука."},{"text":"Така зрителят възприема устата и звука като синхронни","why":""},{"text":"За да изглежда говорът по-бавен и по-ясен","why":"Изместването не променя скоростта на говора."},{"text":"За да се пестят рисунки на формите на устата","why":"Броят рисунки остава същият — само се изместват напред."}],"answer":1,"explain":"В живата реч устните заемат формата малко преди звукът да прозвучи. Мозъкът лесно приема образ, който леко изпреварва звука, но много по-лесно забелязва уста, която закъснява.","more":"Проверявай, като пускаш сцената със звука: ако устата „гони“ звука, премести всички форми с кадър-два напред. Особено важно е за М, Б и П — устните трябва да се затворят, преди звукът да „избухне“."},{"id":"studio.anim.lipsync.c03","legacyId":"cd9h6o1","hall":"studio","domain":"anim","topic":"anim.lipsync","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Реплика трае 2 секунди при 25 кадъра в секунда. Колко кадъра разписваш в експозиционния лист?","answer":50,"unit":"кадъра","explain":"Кадрите са секундите, умножени по кадровата честота: 2 × 25 = 50. Всеки ред в експозиционния лист е 1/25 от секундата.","more":"25 кадъра в секунда е европейският телевизионен стандарт, затова сериалите в Европа често се анимират на 25, а киното — на 24. Провери честотата преди разписването: същата реплика при 24 кадъра заема 48 реда."},{"id":"studio.anim.lipsync.c04","legacyId":"c6ue91r","hall":"studio","domain":"anim","topic":"anim.lipsync","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кои звуци обикновено имат една и съща форма на устата?","options":[{"text":"М, Б, П","why":""},{"text":"А, О, У","why":"Гласните А, О и У имат различни форми — отворена, кръгла, издадена напред."},{"text":"Л, О, Ф","why":"Л вдига езика, О закръгля устните, Ф опира зъбите в устната — три различни форми."},{"text":"И, У, В","why":"И разтяга устните, У ги издава напред, В опира зъбите в устната."}],"answer":0,"explain":"М, Б и П се правят с плътно затворени устни: разликата е дали звучи гласът и дали въздухът минава през носа, а това отвън не се вижда. Затова за трите стига една рисунка — изобщо се работи с малък набор форми.","more":"Опитай пред огледало: кажи „мама“, „баба“ и „папа“ — устните изглеждат еднакво. После кажи „фар“ и „вар“: и при двете горните зъби докосват долната устна — още една обща форма."},{"id":"studio.anim.lipsync.c05","legacyId":"c3ivxrw","hall":"studio","domain":"anim","topic":"anim.lipsync","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"explain","prompt":"Защо само синхронът на устните (lip sync) не стига, за да оживее говорещ герой?","checklist":["Тялото и очите също играят","Актьорски тактове (acting beats): мисълта се сменя преди думите","Мигане, поглед и жест поставят акцента","Анимира се намерението, не буквите"],"model":"Героят първо мисли, после говори. Погледът, наклонът на главата и жестът показват намерението; устата само го озвучава.","more":"Громит от „Уолъс и Громит“ (Aardman) няма видима уста и не говори, но зрителят винаги знае какво мисли — играе само с израза на лицето и с тялото. Най-добрият урок, че мисълта е по-важна от устата."},{"id":"studio.anim.tech.c01","legacyId":"c6g8gb","hall":"studio","domain":"anim","topic":"anim.tech","topic2":"hist.anim","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи филма с техниката.","pairs":[["„Приключенията на принц Ахмед“ (1926)","Силуетна изрезкова анимация"],["„Играта на играчките“ (1995)","3D компютърна анимация"],["„Уолъс и Громит“","Stop motion с пластилин"],["„Коко клоунът“ на братя Флайшер","Rotoscoping"]],"explain":"Макс Флайшер патентова устройството rotoscope през 1917 г.: брат му Дейв е заснет в костюм на клоун, а кадрите са прерисувани един по един — така се ражда Коко. Затова клоунът се движи толкова живо.","more":"„Приключенията на принц Ахмед“ на Лоте Райнигер е най-старият запазен пълнометражен анимационен филм. Фигурите са изрязани от картон и тънки оловни листове и се местят под камерата."},{"id":"studio.anim.tech.c02","legacyId":"c1p3rsqf","hall":"studio","domain":"anim","topic":"anim.tech","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Имаш 2 седмици и си сам. Трябва 30-секунден клип с говорещ герой. Коя техника избираш?","options":[{"text":"Покадрова рисувана анимация на единици","why":"Красиво, но 720 рисунки за две седмици са твърде много."},{"text":"2D изрезкова анимация с rig и сменяеми усти","why":""},{"text":"3D анимация с улавяне на движение в студио","why":"Нямаш студио за улавяне на движение."},{"text":"Stop motion с десет ръчно направени кукли","why":"Десет кукли не се правят за две седмици."}],"answer":1,"explain":"Техниката е и производствено решение: време, екип, умения. При изрезковата анимация героят се изгражда веднъж и после се движи с Rig, а сменяемите усти правят синхрона на устните (Lip sync) бърз.","more":"Направи производствен тест: анимирай 2 секунди с избраната техника и засечи времето. Умножи по 15 и ще знаеш колко ще отнеме целият клип — още преди поправките."},{"id":"studio.anim.tech.c03","legacyId":"c1gtpm9i","hall":"studio","domain":"anim","topic":"anim.tech","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво прави автоматичното междинно кадриране (tweening) по-лошо от ръчните фази, ако не внимаваш?","options":[{"text":"Файлът става по-голям и се рендира по-бавно","why":"Размерът не е проблемът; проблемът е механичното движение."},{"text":"Кадрите не могат да се експортират като видео","why":"Tweening се експортира нормално; въпросът е качеството на движението."},{"text":"Движението става прекалено бързо и накъсано","why":"Софтуерът прави движението равномерно, а не накъсано — липсват ускорение и дъги."},{"text":"Движението става равномерно и по прави линии","why":""}],"answer":3,"explain":"Между два ключови кадъра програмата избира най-краткия път — права линия, често и с еднаква стъпка. Характерът идва от breakdown позите, които извиват пътя в дъга, и от ускорението и забавянето (Slow In and Slow Out).","more":"Отвори графичния редактор на кривите (Graph Editor в Blender и Maya): права наклонена линия значи равномерно движение, а линия, която се извива в краищата, значи ускорение и забавяне."},{"id":"studio.anim.tech.c04","legacyId":"c1oxy6w1","hall":"studio","domain":"anim","topic":"anim.tech","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Стена и кутия с размера на прозореца се застъпват в 3D сцената. Коя операция ще остави в стената отвор с формата на кутията?","options":[{"text":"Булево обединение (Union)","why":"Обединението слива стената и кутията в едно тяло — кутията ще стърчи от стената, а отвор няма да има."},{"text":"Булево сечение (Intersect)","why":"Сечението оставя само общата част на двата обекта — парче стена с размера на прозореца вместо отвор."},{"text":"Екструзия на стената (Extrude)","why":"Екструзията издърпва стената навън или навътре, но не изрязва отвор с формата на друг обект."},{"text":"Булево изваждане (Difference)","why":""}],"answer":3,"explain":"Изваждането запазва стената и маха от нея всичко, което кутията заема: стената минус кутията. Редът е важен — кутията минус стената дава съвсем друг резултат.","more":"Честа грешка: кутията е точно колкото дебелината на стената и отворът остава затворен от тънък слой или с дефекти. Направи я малко по-дебела от стената, за да я пробие изцяло."},{"id":"studio.anim.tech.c05","legacyId":"c1s30jpt","hall":"studio","domain":"anim","topic":"anim.tech","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Ято от 5000 птици в 3D трябва да се движи правдоподобно. Кой подход е най-разумен?","options":[{"text":"Ръчни ключове за всяка птица поотделно","why":"Хиляди ръчни анимации са непосилни — и пак няма да изглеждат като ято."},{"text":"Една анимирана птица, копирана 5000 пъти","why":"Еднаквите копия се движат в синхрон и изглеждат изкуствено."},{"text":"Rotoscoping на заснето истинско ято","why":"Прерисуването на 5000 птици кадър по кадър е огромна работа; правилата го правят автоматично."},{"text":"Симулация по правила, а не ръчни ключове","why":""}],"answer":3,"explain":"Когато обектите са хиляди, аниматорът задава правилата, а не всяко движение. Всяка птица следи само съседите си: не се доближава твърде, лети в тяхната посока и не се отделя от групата — от това се ражда поведението на ятото.","more":"Тези три правила описва Крейг Рейнолдс през 1987 г. в модела си „boids“. Същата идея — всеки агент реагира на околните — стои зад софтуера Massive, създаден за битките във „Властелинът на пръстените“."},{"id":"studio.anim.tech.c06","legacyId":"c4kgax0","hall":"studio","domain":"anim","topic":"anim.tech","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"В какъв формат изнасяш анимация с прозрачен фон (алфа канал) за compositing?","options":[{"text":"PNG секвенция","why":""},{"text":"JPEG секвенция","why":"JPEG няма алфа канал — фонът ще е плътен."},{"text":"MP4 с H.264","why":"Обичайният MP4 (H.264) няма алфа канал."},{"text":"Анимиран GIF","why":"GIF има само „вкл./изкл.“ прозрачност без меки ръбове и едва 256 цвята — не става за compositing."}],"answer":0,"explain":"PNG пази отделен алфа канал с плавни степени на прозрачност за всеки пиксел и компресира без загуби, затова меките ръбове, косата и сенките остават чисти. Секвенцията е и по-сигурна: ако изнасянето спре, губиш един кадър, а не целия файл.","more":"В професионалния compositing се ползват и OpenEXR, който пази повече информация за цвета, и кодекът (Codec) ProRes 4444 — видео с алфа канал в един файл."},{"id":"studio.prod.periods.c01","legacyId":"c1859bmo","hall":"studio","domain":"prod","topic":"prod.periods","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди периодите на филмопроизводството.","sequence":["Преподготвителен период","Подготвителен период","Продукционен период","Постпродукционен период","Ликвидационен период"],"explain":"Всеки период стъпва на предишния: без сценарий и пари няма какво да се планира, без план няма снимки, а без заснет материал няма монтаж. Ликвидационният период затваря сметките, когато всичко друго е готово.","more":"В английските източници петият етап често е разпространението (Distribution): готовият филм тръгва по фестивали, кина и платформи. За фестивалите виж темата „Кинофестивали“."},{"id":"studio.prod.periods.c02","legacyId":"c4txx3z","hall":"studio","domain":"prod","topic":"prod.periods","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи задачата с периода.","pairs":[["Намиране на финансиране и права","Преподготвителен период"],["Подбор на актьори и оглед на локации","Подготвителен период"],["Снимачните дни","Продукционен период"],["Монтаж и цветови корекции","Постпродукционен период"],["Връщане на техниката и финансов отчет","Ликвидационен период"]],"explain":"Задачите следват логиката на работата: правата и парите идват първи, защото без тях няма проект; актьорите и локациите се избират, преди да се снима; финансовият отчет е последен, когато всички сметки са платени.","more":"Периодите често се застъпват: монтажистът може да сглобява сцените още докато се снима и навреме да предупреди, ако липсва кадър. Тогава дозаснемането става, докато екипът и декорът още са налице."},{"id":"studio.prod.periods.c03","legacyId":"cuf14n","hall":"studio","domain":"prod","topic":"prod.periods","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","prompt":"Изброи петте периода на филмопроизводството и по една задача за всеки.","checklist":["Преподготвителен — идея, сценарий, финансиране","Подготвителен — екип, подбор на актьори, локации, план","Продукционен — снимки или анимиране","Постпродукционен — монтаж, звук, цвят, ефекти","Ликвидационен — отчет, архив, връщане на техниката"],"model":"Преподготвителен (идея и пари), подготвителен (планиране), продукционен (снимки), постпродукционен (монтаж и звук), ликвидационен (приключване).","more":"Сложи периодите в календар още в началото: например две седмици подготовка, уикенд за снимки, две седмици монтаж и ден за връщане на техниката и предаване на копията. Така веднага виждаш дали стигаш до крайния срок."},{"id":"studio.prod.periods.c04","legacyId":"c13301ln","hall":"studio","domain":"prod","topic":"prod.periods","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо подготвителният период е най-важен за бюджета?","options":[{"text":"Грешка на хартия е евтина, а на площадката — скъпа","why":""},{"text":"Той е най-дългият период и затова струва най-много","why":"Подготовката не е най-скъпият период; тя пести пари за скъпите снимачни дни."},{"text":"Тогава се плащат хонорарите на целия актьорски състав","why":"Хонорарите се плащат по договор, най-вече за снимачните дни."},{"text":"Тогава се купува цялата техника за снимките","why":"Техниката обикновено се наема за снимките; подготовката решава какво ще трябва."}],"answer":0,"explain":"Снимачният ден е най-скъпото време: плащат се целият екип, актьорите, наетата техника и локацията. Всеки проблем, решен с молив в подготовката, спестява часове чакане на площадката.","more":"Алфред Хичкок планирал филмите си кадър по кадър още на хартия и казвал, че за него творческата работа приключва преди снимките — те са само изпълнение на готовия план."},{"id":"studio.prod.crew.c01","legacyId":"cfq0odf","hall":"studio","domain":"prod","topic":"prod.crew","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи човека от екипа със задачата.","pairs":[["Продуцент","Пари, хора, срокове, права"],["Асистент-режисьор","Снимачният план и редът на площадката"],["Оператор-постановчик","Светлина, камера, композиция"],["Script supervisor","Непрекъснатостта (continuity) и записът на дублите"],["Тонрежисьор","Звукът на площадката"]],"explain":"Ясното разделение пести време: за всеки въпрос има един отговорен човек и никой не губи време да търси кой решава. Така дори екип от стотици хора работи като един механизъм.","more":"В малък училищен екип ролите се съвместяват: режисьорът е и продуцент, операторът — и осветител. Важното е преди първия снимачен ден да запишете кой за какво отговаря."},{"id":"studio.prod.crew.c02","legacyId":"c7t2b8i","hall":"studio","domain":"prod","topic":"prod.crew","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кой следи дали чашата е в същата ръка между дублите?","options":[{"text":"Главният осветител (Gaffer)","why":"Главният осветител отговаря за лампите и светлината, а не за детайлите между дублите."},{"text":"Script supervisor","why":""},{"text":"Художникът-постановчик (Production designer)","why":"Художникът-постановчик създава декора и реквизита, но не следи какво става с тях във всеки дубъл."},{"text":"Операторът-постановчик (Director of photography)","why":"Операторът-постановчик отговаря за образа — светлина, камера, композиция, а не за непрекъснатостта."}],"answer":1,"explain":"Script supervisor записва за всеки дубъл в коя ръка е чашата, колко е отпито от нея и кога героят я вдига. Без тези бележки кадрите от различни дубли и ъгли няма да се връзват при монтажа.","more":"Трик от практиката: след всеки дубъл снимай с телефона актьора и реквизита. Тези снимки спасяват деня, когато сцената се дозаснема след седмица и никой не помни как е изглеждало всичко."},{"id":"studio.prod.crew.c03","legacyId":"c1i3jixd","hall":"studio","domain":"prod","topic":"prod.crew","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Операторът-постановчик иска „по-мека светлина отляво“. Към кого се обръща?","options":[{"text":"Художника-постановчик (Production designer)","why":"Художникът-постановчик отговаря за декора и визията на пространството, а не за светлината."},{"text":"Тонрежисьора (Production sound mixer)","why":"Тонрежисьорът отговаря за звука на площадката, а не за лампите."},{"text":"Главния осветител (Gaffer)","why":""},{"text":"Асистент-режисьора (Assistant director)","why":"Асистент-режисьорът води графика и площадката, но светлината изпълнява екипът на главния осветител."}],"answer":2,"explain":"Операторът-постановчик решава какъв да е образът, а главният осветител превежда това в техника: коя лампа, колко дифузия, от каква посока. Така операторът остава при камерата, а екипът по светлината работи паралелно.","more":"„По-мека светлина“ на практика означава по-голям източник: лампата се пуска през дифузия или се насочва към отражател. Пробвай с настолна лампа и бял картон и виж как сенките по лицето омекват."},{"id":"studio.prod.crew.c04","legacyId":"c1jvfi21","hall":"studio","domain":"prod","topic":"prod.crew","topic2":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кой обикновено прави stripboard и снимачния план?","options":[{"text":"Операторът-постановчик","why":"Операторът планира кадрите и светлината, а не графика на целия екип."},{"text":"Асистент-режисьорът","why":""},{"text":"Script supervisor","why":"Script supervisor следи непрекъснатостта и записва дублите."},{"text":"Художникът-постановчик","why":"Художникът-постановчик отговаря за декора и визията."}],"answer":1,"explain":"Първият асистент-режисьор разбива сценария, подрежда лентите в stripboard и после на площадката следи графикът да се спазва. Затова той знае най-добре колко време има за всеки кадър.","more":"Вторият асистент-режисьор обикновено съставя повиквателните по плана на първия, а на площадката се грижи актьорите да минат през грим и костюм и да са готови навреме."},{"id":"studio.prod.plan.c01","legacyId":"c1x7wzvl","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Сцена е дълга 2 3/8 страници. Колко осмини е това?","answer":19,"unit":"осмини","explain":"Една страница е 8 осмини, значи 2 страници са 16 осмини; с още 3 осмини стават 19. Страниците се броят в осмини, за да може и кратка сцена да се отчете точно в плана.","more":"Грубото правило е, че страница сценарий е около минута екранно време, така че тази сцена ще трае малко над две минути. При бой или преследване правилото не важи: един ред текст може да се снима цял ден."},{"id":"studio.prod.plan.c02","legacyId":"cmplth3","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Екипът снима средно 3 4/8 страници на ден. За колко снимачни дни ще заснеме сценарий от 91 страници?","answer":26,"unit":"дни","explain":"Осмините се превръщат в десетична дроб: 4/8 = 0,5, значи екипът снима по 3,5 страници на ден. 91 ÷ 3,5 = 26 снимачни дни; в истинския график към тях се добавят и резервни дни.","more":"За външните сцени подготви резервна сцена на закрито (cover set): ако вали, екипът се мести там и снимачният ден не се губи."},{"id":"studio.prod.plan.c03","legacyId":"cb760j7","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Снимачният план следва реда на сценария: сц. 1 (апартамент), сц. 2 (плаж), сц. 3 (апартамент), сц. 4 (плаж). Какво не е наред?","options":[{"text":"Редът е наред — актьорите играят по-добре хронологично","why":"Снимането извън последователност е нормално; местенето между локации струва часове."},{"text":"Трябва да се започне с плажа, защото светлината е по-трудна","why":"Редът на локациите е втори въпрос; първо сцените на едно място трябва да се групират."},{"text":"Екипът ще се мести напред-назад; сцените се групират по място","why":""},{"text":"Сцените трябва да се редуват, за да не се уморява екипът","why":"Редуването точно създава проблема — всяко местене отнема часове."}],"answer":2,"explain":"При всяка смяна на локация (Company move) техниката се прибира, пренася и нагласява наново, а екипът губи часове. Затова сцените на едно място се снимат наведнъж и се групират по време на деня и актьори.","more":"Сцени 1 и 3 може да се заснемат в един ден в апартамента, а 2 и 4 — в друг на плажа. Внимавай с непрекъснатостта: ако в сцена 3 героят идва от плажа с мокра коса, това трябва да е записано."},{"id":"studio.prod.plan.c04","legacyId":"c1ea4r8w","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Известен актьор е свободен само един ден. Какво правите?","options":[{"text":"Снимате по реда на сценария, докъдето стигнете","why":"Ще изпуснете повечето му сцени — той е свободен само този ден."},{"text":"Групирате сцените му в този ден, извън реда на сценария","why":""},{"text":"Сменяте актьора с друг, който е свободен повече дни","why":"Смяната на известен актьор е крайна мярка; първо се пренарежда графикът."},{"text":"Снимате сцените му в общи планове с дубльор в ролята","why":"Дубльорът не може да замести лицето и гласа в главните моменти."}],"answer":1,"explain":"Снимането извън последователност (Shooting out of sequence) е нормално: графикът се подрежда около човека, който е най-труден за осигуряване. Режисьорът помага на актьора да знае в какво състояние е героят във всяка сцена.","more":"В Day Out of Days такъв актьор получава кода SWF (Start-Work-Finish): започва, работи и приключва в един и същи ден."},{"id":"studio.prod.plan.c05","legacyId":"c1n3a2wv","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy","fixes":["P09"]},"kind":"card","format":"choice","prompt":"По най-разпространената конвенция в stripboard жълтата лента означава…","options":[{"text":"Нощ — интериор","why":"Нощ — интериор обикновено е синя лента."},{"text":"Ден — интериор","why":"Ден — интериор обикновено е бяла лента."},{"text":"Нощ — натура","why":"Нощ — натура обикновено е зелена лента."},{"text":"Ден — натура","why":""}],"answer":3,"explain":"Цветът показва с един поглед кога и къде е сцената, без да се чете текстът на лентата. Лесно се помни: жълто като слънцето навън. Някои студия ползват своя схема, затова легендата винаги се уточнява.","more":"Между дните се слагат черни или сиви ленти, които отбелязват края на всеки снимачен ден, често с общия брой страници за него. Така веднага се вижда дали някой ден не е прекалено натоварен."},{"id":"studio.prod.plan.c06","legacyId":"cftruxx","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди документите за планиране на снимките в реда, в който се изготвят.","sequence":["Разбивка на сценария","Stripboard","Снимачен план","Повиквателна"],"explain":"Всеки документ се прави от предишния: разбивката изважда елементите на сцените, те се пренасят на ленти, лентите се подреждат в снимачни дни, а от плана за деня се прави повиквателната.","more":"Повиквателната се разпраща вечерта преди снимачния ден. За училищен филм стига съобщение в общия чат: час, адрес, сцени и какво да донесе всеки."},{"id":"studio.prod.plan.c07","legacyId":"cpu5m9d","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо рисковите сцени — сложни каскади, трудни локации — често се планират рано в графика?","options":[{"text":"Актьорите са отпочинали и правят по-малко грешки","why":"Почивката помага, но главната причина е резервът за поправка."},{"text":"Ако нещо се обърка, остава време и пари за поправка","why":""},{"text":"Така най-трудното приключва и екипът се отпуска","why":"Целта не е отпускането, а времето за поправки, ако нещо се провали."},{"text":"Каскадьорите са свободни в началото на снимките","why":"Графикът на каскадьорите се договаря; причината за ранното планиране е рискът."}],"answer":1,"explain":"Ако каскадата се провали в първата седмица, има дни и пари да се заснеме отново. Ако същото стане в последния ден, резерв няма, а актьорите и локацията може вече да ги няма.","more":"Практичен съвет: направи първия снимачен ден по-лек, защото екипът тепърва се сработва. Трудните сцени сложи скоро след него, докато още има резерв."},{"id":"studio.prod.plan.c08","legacyId":"co1iu8i","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо между края на един снимачен ден и началото на следващия се пазят около 10–12 часа почивка?","options":[{"text":"Уморен екип греши и се наранява по-лесно","why":""},{"text":"Батериите и техниката трябва да се заредят","why":"Батериите се зареждат между кадрите; почивката е за хората."},{"text":"Монтажистът трябва да прегледа заснетото","why":"Монтажът върви паралелно и не зависи от почивката на екипа."},{"text":"Нощем е забранено да се снима по закон","why":"Нощни снимки се правят често; почивката е заради умората, а не заради часа."}],"answer":0,"explain":"Умората забавя реакциите, а на площадката има тежки стойки, кабели, лампи и коли. Затова почивката между смените (Turnaround) се записва в графика като задължителна, а не като лукс.","more":"Пресметни: ако снимките приключат в 22:00, при 12 часа почивка следващото повикване е най-рано в 10:00. Затова след нощни снимки не може да се започне рано сутринта."},{"id":"studio.prod.set.c01","legacyId":"c1ozdutm","hall":"studio","domain":"prod","topic":"prod.set","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди командите на снимачната площадка преди и след дубъла.","sequence":["Тишина на площадката!","Звук!","Камера!","Клапа!","Начало!","Стоп!"],"explain":"По традиция звукът тръгва първи: записът му е по-евтин от филмовата лента, а старите магнетофони трябваше да наберат скорост. Клапата се удря, когато и звукът, и камерата вече записват, а режисьорът дава начало и край на действието.","more":"Само режисьорът казва „Стоп!“. Ако забележиш проблем по време на дубъл, кажи на асистент-режисьора след него — освен ако някой е в опасност."},{"id":"studio.prod.set.c02","legacyId":"cwtnht2","hall":"studio","domain":"prod","topic":"prod.set","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо се удря клапата?","options":[{"text":"Ударът дава точка за синхрон на образа и звука","why":""},{"text":"Ударът дава сигнал на актьорите да започнат","why":"Сигналът за актьорите е командата „Начало!“; ударът е за синхрона."},{"text":"Ударът показва на оператора кога да включи камерата","why":"Камерата вече записва, когато се удря клапата — за да хване удара."},{"text":"Ударът е сигнал за тишина на цялата площадка","why":"Тишина се иска преди клапата; ударът е точката за синхрон."}],"answer":0,"explain":"В образа се вижда кадърът, в който пръчките се допират, а в звука — острият пик на удара. Монтажистът подравнява двете точки и оттам нататък устните и гласът съвпадат.","more":"При крупен план клапата се удря тихо и близо до лицето (soft sticks), за да не стресне актьора. А ако нямаш клапа, плясни с длани пред камерата — пикът в звука върши същата работа."},{"id":"studio.prod.set.c03","legacyId":"cnt0kn","hall":"studio","domain":"prod","topic":"prod.set","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"В общия план героят държи чашата в дясната си ръка, а в следващия, по-близък кадър — в лявата. При монтажа кадрите не се връзват. Каква е грешката?","options":[{"text":"Нарушение на правилото 30° (30-degree rule)","why":"Правилото 30° е за ъгъла между два поредни кадъра; тук е сменена ръката, а не ъгълът."},{"text":"Грешка в непрекъснатостта (Continuity error)","why":""},{"text":"Прескачане на оста (Crossing the line)","why":"Прескачането на оста обръща посоките на екрана, но не мести чашата в другата ръка."},{"text":"Разминаване в синхрона (Sync)","why":"При разминат синхрон устните и гласът не съвпадат; тук проблемът е в предмета."}],"answer":1,"explain":"Зрителят приема монтираните кадри като едно непрекъснато действие, затова всеки сменен детайл изглежда като скок. Непрекъснатостта е грижа на целия екип, но script supervisor я пази в записките си.","more":"Ако грешката вече е заснета, монтажистът може да я скрие с вмъкнат кадър (Cutaway) към лицето на партньора: докато не виждаме героя, чашата „сменя“ ръката извън кадър."},{"id":"studio.prod.set.c04","legacyId":"c15rhu2b","hall":"studio","domain":"prod","topic":"prod.set","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"На клапата пише „Сц. 12, Кадър 3, Дубъл 4“. Какво означава това за монтажиста?","options":[{"text":"Сцена 12, кадър 3, заснет в четвъртия снимачен ден","why":"Дубълът е поредният опит, а не денят на снимките."},{"text":"Сцена 12, кадър 3, заснет с четвъртата камера","why":"Камерата се отбелязва отделно (A, B); „Дубъл 4“ е четвъртият опит."},{"text":"Сцена 12, кадър 3, четвъртият опит за този кадър","why":""},{"text":"Сцена 12, кадър 3, с продължителност 4 секунди","why":"Дубълът не е мярка за време."}],"answer":2,"explain":"Сцената и кадърът остават същите, а всяко ново повторение получава следващ номер на дубъл. Така от стотици файлове монтажистът намира точно опита, който режисьорът е харесал.","more":"В американската система кадрите се отбелязват с букви след номера на сцената: 12A, 12B, 12C. Буквите I, O и S обикновено се пропускат, защото лесно се бъркат с 1, 0 и 5."},{"id":"studio.prod.set.c05","legacyId":"capx7vj","hall":"studio","domain":"prod","topic":"prod.set","topic2":"edit.sound","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"След последния дубъл тонрежисьорът иска 30 секунди пълна тишина от всички. Защо?","options":[{"text":"Записва фона на помещението за монтажа","why":""},{"text":"Проверява дали микрофонът още работи правилно","why":"Микрофонът се проверява преди дубъла; тишината след него е за запис на фона."},{"text":"Дава на екипа кратка почивка между дублите","why":"Тишината не е почивка — тогава се записва звукът на мястото."},{"text":"Измерва колко е шумна площадката за доклада","why":"Не се мери за доклад; записва се фонът, който монтажистът ще използва."}],"answer":0,"explain":"Всяко помещение има свой тих фон — бръмчене, далечен трафик, вентилация. Без записан фон на помещението (Room tone) монтажистът няма с какво да запълни дупките между репликите и при всяко срязване фонът „прескача“.","more":"При записа на фона всички остават по местата си, а техниката продължава да работи. Така акустиката и бръмченето са същите като в дублите."},{"id":"studio.hist.pre.c01","legacyId":"c1rur4bg","hall":"studio","domain":"hist","topic":"hist.pre","level":10,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди изобретенията по време на появата им.","sequence":["Камера обскура","Латерна магика","Фенакистископ","Зоетроп","Праксиноскоп","Кинетоскоп","Кинематограф"],"explain":"Камера обскура е позната още от Античността, латерна магика се появява през XVII век, а оптичните играчки с диск и барабан — през XIX век. Кинетоскопът (1891–1893) е за един зрител, а кинематографът (1895) прожектира за цяла зала.","more":"Направи си фенакистископ: на картонен кръг нарисувай в кръг 8–12 фази на подскачаща топка, изрежи по ръба толкова процепа и завърти диска пред огледало, като гледаш през процепите."},{"id":"studio.hist.pre.c02","legacyId":"c1rs08qz","hall":"studio","domain":"hist","topic":"hist.pre","level":10,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи изобретението с автора и годината.","pairs":[["Фенакистископ","Плато, 1832"],["Праксиноскоп","Рейно, 1877"],["Галопиращият кон на серия снимки","Мейбридж, 1878"],["Кинетоскоп","Едисън и Диксън, 1891–1893"]],"explain":"Всяко изобретение решава част от задачата: Плато показва, че бързо сменени фази се сливат в движение, Рейно изчиства образа с огледала, Мейбридж разлага реалното движение, а Едисън и Диксън пускат снимките на лента.","more":"Мейбридж снима галопиращия кон с редица фотоапарати и доказва, че за миг конят не докосва земята — но с крака, свити под тялото, а не изпънати напред и назад, както дотогава го рисуват художниците."},{"id":"studio.hist.pre.c03","legacyId":"c1k3hprr","hall":"studio","domain":"hist","topic":"hist.pre","level":10,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво общо имат зоетропът и GIF анимацията?","options":[{"text":"Движението се вижда чрез въртящ се барабан с процепи","why":"Барабанът с процепи е само на зоетропа; GIF-ът се върти на екран."},{"text":"И двете показват снимки от реалността, а не рисунки","why":"Зоетропът обикновено показва рисунки, а GIF може да е от всякакви кадри."},{"text":"И двете се пускат с музика в синхрон с движението","why":"Нито зоетропът, нито GIF-ът имат звук."},{"text":"Кратка поредица фази, която се повтаря безкрайно","why":""}],"answer":3,"explain":"И зоетропът, и GIF-ът показват няколко фази, които след последната започват отначало. Затова движението трябва да е зациклено — без скок между края и началото.","more":"Когато правиш цикъл на ходене или на пламък, нарисувай последната фаза така, че да води плавно към първата, а не да я повтаря — иначе в цикъла ще има засечка. Виж „Цикъл (Cycle)“."},{"id":"studio.hist.pre.c04","legacyId":"cwflh25","hall":"studio","domain":"hist","topic":"hist.pre","level":10,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо сериите снимки на Мейбридж са полезни и за аниматорите днес?","options":[{"text":"Разлагат реалното движение на фази — готова референция","why":""},{"text":"Показват движението в цвят и с високо качество","why":"Сериите са черно-бели фотографии; ценни са заради фазите на движението."},{"text":"Показват първите опити с рисувана анимация","why":"Мейбридж снима с фотоапарати, не рисува."},{"text":"Съдържат първите записи на звук заедно с образ","why":"Сериите са неми фотографии — звук няма."}],"answer":0,"explain":"Всяка снимка хваща движението в един миг, на равни интервали — като ключовите и междинните фази в анимацията. Затова по тях аниматорите проверяват как стъпва конят или как се отблъсква човек при скок.","more":"Направи си собствена референция: снимай скок или ходене с телефона на серийни снимки или на видео и прерисувай кадрите един по един. Така ще видиш фази, които окото пропуска."},{"id":"studio.hist.pre.c05","legacyId":"c19lsv53","hall":"studio","domain":"hist","topic":"hist.pre","level":10,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"explain","prompt":"Обясни как работи камера обскура и защо образът е обърнат.","checklist":["Светлината минава през малък отвор","Лъчите се пресичат в отвора — горното става долно, лявото дясно","Образът се появява на стената срещу отвора","Това е принципът на всяка камера"],"model":"Светлината от горната част на дървото минава през отвора и пада долу на стената, а тази от долната част — горе. Същото става в обектива на всяка камера и в окото.","more":"Направи камера обскура вкъщи: затъмни стаята, залепи на прозореца картон с дупка около 1 cm и гледай обърнатия пейзаж на отсрещната стена. Колкото по-малък е отворът, толкова по-рязък, но и по-тъмен е образът."},{"id":"studio.hist.pioneer.c01","legacyId":"c1b6t3p5","hall":"studio","domain":"hist","topic":"hist.pioneer","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кога и къде е първата публична платена прожекция на братя Люмиер?","options":[{"text":"28 декември 1895 г., фабриката им в Лион","why":"В Лион е фабриката им и там са заснети първите филми, но платената публична прожекция е в Париж."},{"text":"1 ноември 1895 г., Винтергартен в Берлин","why":"На 1 ноември 1895 г. в Берлин прожектират братя Складановски, а не Люмиер."},{"text":"1891 г., лабораторията на Едисън в Ню Джърси","why":"Кинетоскопът на Едисън е за гледане от един човек, без прожекция пред публика."},{"text":"28 декември 1895 г., Гран кафе в Париж","why":""}],"answer":3,"explain":"Зрителите плащат билет и гледат заедно на голям екран — киното става общо преживяване, а не апарат за един човек като кинетоскопа. Затова тази прожекция често се смята за рождения ден на киното.","more":"Прожекцията е в Индийския салон в подземието на Гран кафе на булевард „Капуцините“. Програмата е от десетина филма, всеки по-кратък от минута."},{"id":"studio.hist.pioneer.c02","legacyId":"c1c2lxpx","hall":"studio","domain":"hist","topic":"hist.pioneer","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Афиш за училищна прожекция: „Братя Люмиер представят „Пътешествие до Луната“ (1902)“. Къде е грешката?","options":[{"text":"Годината е грешна — филмът е прожектиран през 1895 г.","why":"Годината 1902 е вярна; грешно е името на авторите."},{"text":"Филмът е на Едисън, а Люмиер правят апаратите","why":"Филмът не е на Едисън, а на Жорж Мелиес."},{"text":"Филмът е на Мелиес, а Люмиер снимат сцени от живота","why":""},{"text":"Грешка няма — Люмиер са заснели и този филм","why":"Люмиер снимат реални сцени; фантастичното пътешествие е на Мелиес."}],"answer":2,"explain":"„Пътешествие до Луната“ е заснет в студио с рисувани декори, костюми и трикове — светът е измислен от Мелиес. Люмиер снимат реални сцени: работници, гари, улици.","more":"Запазено е и ръчно оцветено копие на филма — след дълга реставрация то е показано в Кан през 2011 г. Кадърът с ракетата в окото на Луната е сред най-цитираните в историята на киното."},{"id":"studio.hist.pioneer.c03","legacyId":"cxfqv4p","hall":"studio","domain":"hist","topic":"hist.pioneer","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"explain","prompt":"Люмиер срещу Мелиес: кое наследяват днешните vloggers и документалисти и кое — филмите с визуални ефекти?","checklist":["Люмиер: реалният живот, наблюдението („Пристигането на влака“)","Мелиес: спектакъл, трик, фантазия, декор","Vloggers и документалистите следват Люмиер","Визуалните ефекти и фентъзито следват Мелиес","Двете линии живеят и днес"],"model":"Люмиер поставят камерата пред живота и го наблюдават. Мелиес строи декор и прави магия. Днешните vlogs и документални филми продължават първата линия, а фентъзито и ефектите — втората.","more":"Двете линии се срещат в техниката Rotoscoping: заснет истински човек се прерисува кадър по кадър. Така Макс Флайшер анимира Клоуна Коко в края на 1910-те."},{"id":"studio.hist.pioneer.c04","legacyId":"c1va2qfg","hall":"studio","domain":"hist","topic":"hist.pioneer","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво въвеждат английските пионери от Брайтънската школа около 1900 г.?","options":[{"text":"Звука, записан на плоча в синхрон с образа","why":"Синхронният звук се налага в киното чак в края на 1920-те."},{"text":"Дългия непрекъснат кадър с подвижна камера","why":"Обратното: те режат в средата на сцената и вмъкват нов кадър."},{"text":"Студийната система с договорни звезди","why":"Студийната система е холивудска и се оформя през 1910-те и 1920-те."},{"text":"Крупния план и кадъра от гледна точка в сцената","why":""}],"answer":3,"explain":"Смит и Уилямсън режат в средата на сцената към по-близък кадър или към това, което героят вижда. Така сцената вече не е една неподвижна картина, а поредица от кадри — зародиш на монтажа.","more":"В „The Big Swallow“ (1901) на Джеймс Уилямсън раздразнен човек се приближава до камерата, докато устата му изпълни кадъра, и сякаш я „поглъща“."},{"id":"studio.hist.early.c01","legacyId":"ckdx5vj","hall":"studio","domain":"hist","topic":"hist.early","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Грифит не е изобретил паралелния монтаж и крупния план. Защо все пак е толкова важен?","options":[{"text":"Прави ги видими, защото снима с цветна лента","why":"Грифит снима на черно-бяла лента; цвят дава само оцветяването на копията."},{"text":"Добавя към тях синхронен звук и записана музика","why":"Звукът идва след големите му филми."},{"text":"Използва ги най-вече в документалните си филми","why":"Грифит прави игрални филми; значението му е в повествователния език."},{"text":"Превръща ги в система за разказ в дълъг филм","why":""}],"answer":3,"explain":"Грифит подрежда крупния план, паралелния монтаж и смяната на ритъма така, че да водят чувствата на зрителя през дълъг филм. „Раждането на една нация“ (1915) е новаторски и същевременно расистки — важен, но спорен.","more":"Неговият запазен знак е „спасяването в последната минута“: монтажът редува жертвата в опасност и бързащите спасители, а кадрите стават все по-къси, докато двете линии се срещнат. Виж „Паралелен монтаж (Cross-cutting)“."},{"id":"studio.hist.early.c02","legacyId":"c1p2ifjp","hall":"studio","domain":"hist","topic":"hist.early","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"С какво е известна италианската „Кабирия“ (1914)?","options":[{"text":"Бърз монтаж и множество крупни планове на лицата","why":"„Кабирия“ е прочута с бавната камера и декорите, а не с бърз монтаж."},{"text":"Грандиозни декори и бавни движения на камерата","why":""},{"text":"Снимки на реални места с непрофесионални актьори","why":"Това описва неореализма от 1940-те; „Кабирия“ е постановъчна епопея."},{"text":"Първите опити за цветно оцветяване на лентата","why":"Оцветяването на лентата е по-старо; „Кабирия“ е известна с декорите и камерата."}],"answer":1,"explain":"Камерата бавно се движи на колички през огромните декори и зрителят усеща тяхната дълбочина и мащаб. Италианските епопеи правят киното зрелищно и влияят на „Нетърпимост“ на Грифит.","more":"Днес същото усещане за мащаб дава бавното приближаване с количка или кран над масова сцена. Виж „Шарийо (Dolly shot)“ и „Кран (Crane shot)“ в темата за движението на камерата."},{"id":"studio.hist.early.c03","legacyId":"c1mdo1pr","hall":"studio","domain":"hist","topic":"hist.early","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи школата или филма със страната.","pairs":[["Филм д’ар","Франция"],["Нордиск","Дания"],["„Кабирия“","Италия"],["Шьострьом и Щилер","Швеция"],["Грифит","САЩ"]],"explain":"Всяка страна развива свое силно място: Франция — престижа на театъра и литературата, Дания — драмата и звездите, Италия — епопеите, Швеция — природата и психологията, САЩ — монтажния разказ.","more":"Първата световна война спира голяма част от европейското производство и износ на филми. Американските студия запълват кината по света и след 1918 г. Холивуд води."},{"id":"studio.hist.early.c04","legacyId":"chxycas","hall":"studio","domain":"hist","topic":"hist.early","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво отличава шведската школа от 1910-те?","options":[{"text":"Бързи комедии с гонитби, трикове и много падания","why":"Това е американският слапстик (Мак Сенет)."},{"text":"Грандиозни исторически декори и епични битки","why":"Това е италианската епопея („Кабирия“)."},{"text":"Изкривени рисувани декори и остри, тревожни сенки","why":"Това е немският експресионизъм („Кабинетът на д-р Калигари“)."},{"text":"Природата участва в драмата, героите са психологически","why":""}],"answer":3,"explain":"Шведските режисьори снимат много на натура: морето, снегът и скалите не са фон, а сила, която движи историята и отразява чувствата на героите.","more":"Традицията продължава Ингмар Бергман: в „Поляната с дивите ягоди“ (1957) той дава главната роля на Виктор Шьострьом — един от създателите на шведската школа."},{"id":"studio.hist.early.c05","legacyId":"c1wonq7i","hall":"studio","domain":"hist","topic":"hist.early","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо Филм д’ар привлича актьори от „Комеди Франсез“ и известни писатели?","options":[{"text":"Защото театралните актьори струват по-евтино","why":"Звездите на „Комеди Франсез“ не са евтини; целта е престиж."},{"text":"Защото филмите вече са със звук и искат гласове","why":"Филмите са неми — звукът идва чак в края на 1920-те."},{"text":"За да издигне престижа на киното като изкуство","why":""},{"text":"За да заснеме цели пиеси направо в театъра","why":"Филмите се снимат в студио; от театъра се взимат престижът и актьорите."}],"answer":2,"explain":"Около 1908 г. киното още минава за евтино панаирджийско забавление. Известни актьори и писатели трябва да привлекат образованата публика и да покажат, че филмът може да е изкуство.","more":"Първият им филм, „Убийството на херцог дьо Гиз“ (1908), има музика, написана специално за него от композитора Камий Сен-Санс — рядкост за времето."},{"id":"studio.hist.silent.c01","legacyId":"c13infac","hall":"studio","domain":"hist","topic":"hist.silent","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи филма с направлението.","pairs":[["„Кабинетът на д-р Калигари“ (1920)","Немски експресионизъм"],["„Последният човек“ (1924)","Камершпил"],["„Броненосецът Потьомкин“ (1925)","Съветски монтаж"],["„Андалуското куче“ (1929)","Сюрреализъм"],["„Колелото“ на Абел Ганс (1923)","Френски импресионизъм"]],"explain":"Всяко течение търси свое изразно средство: експресионизмът — декора и сянката, камершпилът — подвижната камера, съветската школа — сблъсъка на кадрите, сюрреализмът — логиката на съня, импресионизмът — субективния ритъм.","more":"Сцената на Одеското стълбище от „Броненосецът Потьомкин“ е сред най-цитираните в историята — например в „Недосегаемите“ (1987) количка с бебе се търкаля по стълбите на гара."},{"id":"studio.hist.silent.c02","legacyId":"c1yfjtzz","hall":"studio","domain":"hist","topic":"hist.silent","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кои белези ще те насочат към немския експресионизъм в съвременен филм?","options":[{"text":"Изкривени декори, остри сенки и силен контраст","why":""},{"text":"Реални места, естествена светлина и дълги кадри","why":"Това е белег на неореализма и на документалното кино."},{"text":"Бърз монтаж, ръчна камера и много крупни планове","why":"Това е белег на съвременното динамично кино или на документалния стил."},{"text":"Ярки пастелни цветове и мека, равномерна светлина","why":"Експресионизмът е тъмен и контрастен — обратното на пастелите."}],"answer":0,"explain":"Експресионистите не показват света обективно: изкривените форми и острите сенки правят видими страха и лудостта на героя. Тъмната тоналност и силният контраст засилват тревогата.","more":"Опитай: в тъмна стая освети приятел с една силна лампа отстрани или отдолу. Сянката на стената веднага става заплашителна — като сянката на граф Орлок по стълбите в „Носферату“."},{"id":"studio.hist.silent.c03","legacyId":"c6kibpi","hall":"studio","domain":"hist","topic":"hist.silent","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","prompt":"Назови три белега на немския експресионизъм, които ще откриеш у Тим Бъртън или в анимационните филми на ужасите.","checklist":["Изкривени, наклонени декори","Силни сенки — рисувани или хвърлени","Контраст светло–тъмно (тъмна тоналност)","Вътрешното състояние е изразено чрез средата","Гротескни, издължени фигури"],"model":"Криви къщи и стълби, дълги рисувани сенки, остър контраст и слаби, издължени фигури — светът изглежда така, както се чувства героят.","more":"Сравни кадри от „Кабинетът на д-р Калигари“ (1920) и от „Кошмарът преди Коледа“ (1993): ще откриеш същите наклонени къщи, остри покриви и издължени сенки."},{"id":"studio.hist.silent.c04","legacyId":"c2zvep6","hall":"studio","domain":"hist","topic":"hist.silent","topic2":"hist.fest","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кой от тези европейски кинофестивали е най-старият?","options":[{"text":"Кан (Cannes)","why":"Кан е замислен за 1939 г., но заради войната първият фестивал е чак през 1946 г."},{"text":"Берлинале (Berlinale)","why":"Берлинале започва през 1951 г."},{"text":"Венеция (Venice)","why":""},{"text":"Карлови Вари (Karlovy Vary)","why":"Карлови Вари започва през 1946 г. — след Венеция (1932)."}],"answer":2,"explain":"Фестивалът във Венеция започва през 1932 г. като част от Биеналето на изкуствата. Кан, Карлови Вари и Берлин се появяват след Втората световна война.","more":"Освен „Златен лъв“ Венеция връчва и „Купа Волпи“ за най-добра мъжка и женска роля, кръстена на основателя на фестивала граф Джузепе Волпи."},{"id":"studio.hist.silent.c05","legacyId":"c1bk8hpz","hall":"studio","domain":"hist","topic":"hist.silent","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кое е необичайно за камершпила „Последният човек“ (1924)?","options":[{"text":"Почти няма междинни надписи — разказват образът и камерата","why":""},{"text":"Това е един от първите филми със синхронен звук","why":"Филмът е от 1924 г. — изцяло ням."},{"text":"Заснет е на натура, без нито един студиен декор","why":"Камершпилът е интимна драма в декори, заснета в студио."},{"text":"Разказан е с много надписи, като роман на екрана","why":"Обратното: Мурнау почти изцяло маха надписите."}],"answer":0,"explain":"Мурнау и операторът Карл Фройнд освобождават камерата: тя се движи из сцената, а в сцената с пиянството се люшка заедно с героя. Чувствата се виждат в образа и думите стават излишни.","more":"Филмът има само един междинен надпис: той обявява, че следва „малко вероятен“ щастлив край, защото авторът се е смилил над героя."},{"id":"studio.hist.silent.c06","legacyId":"c1rllkdl","hall":"studio","domain":"hist","topic":"hist.silent","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Сюрреализмът в киното („Андалуското куче“, 1929) следва логиката на…","options":[{"text":"документалния репортаж — факти от живота","why":"Сюрреализмът бяга от фактите — показва подсъзнанието."},{"text":"класическия разказ — причина и следствие","why":"Сюрреалистите нарочно рушат причината и следствието."},{"text":"съня — шокиращи образи без логическа връзка","why":""},{"text":"рекламата — кратко и запомнящо се послание","why":"Шокът при сюрреалистите не продава, а разклаща логиката на зрителя."}],"answer":2,"explain":"Сюрреалистите са вдъхновени от сънищата и от идеите на Фройд за подсъзнанието. Сцените се сменят без причина и следствие, за да разклатят навиците на зрителя.","more":"Салвадор Дали работи и с Disney: късометражният „Destino“, започнат през 1945 г., е завършен чак през 2003 г. Сюрреалистичният гаг в анимацията следва същата логика — виж „Сюрреалистичен гаг (Surreal gag)“."},{"id":"studio.hist.silent.c07","legacyId":"cn4wc4t","hall":"studio","domain":"hist","topic":"hist.silent","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кое е вярно за холивудската студийна система през 1920-те?","options":[{"text":"Всеки режисьор е независим и сам финансира филмите си","why":"Точно обратното: режисьорите работят по договор за студиото."},{"text":"Филмите се снимат на натура, без декори в павилион","why":"Студиата строят огромни павилиони и декори."},{"text":"Актьорите сами избират ролите си, без дългосрочни договори","why":"Звездите са вързани с дългосрочни договори със студиото."},{"text":"Студиата държат производството, разпространението и кината","why":""}],"answer":3,"explain":"Като фабрика, студиото държи цялата верига: сценаристи, режисьори и звезди работят по договор, филмите се снимат в собствени павилиони и се прожектират в собствени кина. Така печалбата остава в студиото.","more":"Всяко голямо студио има свой почерк: Warner Bros. е известно с гангстерските филми, Universal — с филмите на ужасите, а MGM — с бляскавите мюзикъли."},{"id":"studio.hist.anim.c01","legacyId":"c190q81g","hall":"studio","domain":"hist","topic":"hist.anim","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди събитията в историята на анимацията.","sequence":["Оптическият театър на Рейно (1892)","„Фантасмагория“ на Кол (1908)","„Динозавърът Герти“ на Маккей (1914)","„Приключенията на принц Ахмед“ на Райнигер (1926)","„Параходът Уили“ на Дисни (1928)","„Снежанка“ на Дисни (1937)","„Играта на играчките“ на Pixar (1995)"],"explain":"Всяка стъпка добавя нещо ново: Рейно прожектира рисунки пред публика, Кол прави изцяло рисуван филм, Маккей дава на героинята характер, Райнигер — пълнометражен силуетен филм, Дисни — синхронен звук и рисувана приказка в цял филм, а Pixar — компютърна анимация.","more":"Между „Снежанка“ и „Играта на играчките“ минават почти 60 години. В тях идват телевизионните анимационни сериали, разцветът на японското аниме и Studio Ghibli, основано през 1985 г."},{"id":"studio.hist.anim.c02","legacyId":"c1711bk6","hall":"studio","domain":"hist","topic":"hist.anim","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо Лоте Райнигер е важна за историята на анимацията?","options":[{"text":"Прави най-стария запазен пълнометражен анимационен филм","why":""},{"text":"Създава първия анимационен филм със синхронен звук","why":"Със синхронния звук в анимацията се свързва „Параходът Уили“ (1928) на Дисни."},{"text":"Създава първата анимационна героиня с характер","why":"Това е „Динозавърът Герти“ (1914) на Уинзър Маккей."},{"text":"Прави първия цветен анимационен филм в Европа","why":"Силуетите ѝ са черни, а цветът идва само от оцветяването на лентата; значението ѝ е в „Принц Ахмед“ (1926)."}],"answer":0,"explain":"Има и по-ранни пълнометражни анимации, като аржентинския „El Apóstol“ (1917), но те са изгубени. „Принц Ахмед“ е най-старият оцелял, а силуетите му са изрязани от картон и тънки листове олово.","more":"Още в „Принц Ахмед“ Райнигер използва ранна форма на многопланова камера — цяло десетилетие преди Дисни. Слоевете стъкло дават дълбочина на силуетния свят."},{"id":"studio.hist.anim.c03","legacyId":"cj5gchp","hall":"studio","domain":"hist","topic":"hist.anim","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво е особеното в „Динозавърът Герти“ (1914)?","options":[{"text":"Това е първият цветен анимационен филм","why":"„Герти“ е черно-бяла рисувана анимация."},{"text":"Героинята има характер и „отговаря“ на Маккей на сцената","why":""},{"text":"Героинята е кукла, анимирана кадър по кадър","why":"Герти е рисувана на хартия, а не кукла (stop motion)."},{"text":"Героинята е нарисувана върху заснети кадри от природата","why":"Фонът е рисуван; по-важното е, че Герти има характер и „говори“ с Маккей."}],"answer":1,"explain":"Маккей анимира не само движение, а характер: Герти плаче, когато я смъмрят, играе и не винаги слуша. Затова зрителите я възприемат като живо същество с настроение.","more":"Герти е нарисувана на хартия и фонът е прерисуван наново на всяка рисунка. По-късно аниматорите минават към прозрачно целулоидно фолио (cel), за да рисуват фона само веднъж."},{"id":"studio.hist.anim.c04","legacyId":"c1rotu3i","hall":"studio","domain":"hist","topic":"hist.anim","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво нововъведение свързваме с „Параходът Уили“ (1928)?","options":[{"text":"Първият цвят по системата „Техниколор“","why":"Първият анимационен филм в пълен „Техниколор“ е „Цветя и дървета“ (1932)."},{"text":"Първият пълнометражен анимационен филм","why":"„Уили“ е късометражен; пълнометражната „Снежанка“ идва през 1937 г."},{"text":"Синхронен звук, който е част от самия гаг","why":""},{"text":"Многоплановата камера за дълбочина на кадъра","why":"Многоплановата камера идва по-късно — в „Старата мелница“ и „Снежанка“ (1937)."}],"answer":2,"explain":"Музиката и шумовете следват движенията кадър по кадър, затова Мики „свири“ на животни и предмети точно в ритъма. По-ранни звукови анимации има, но тук звукът става част от самия гаг.","more":"Аниматорите разчитат движенията по такта на метроном, а музиката се записва после в същото темпо. Днес такава подготовка се отбелязва в експозиционния лист — виж „Експозиционен лист (X-sheet)“."},{"id":"studio.hist.anim.c05","legacyId":"cyorvsm","hall":"studio","domain":"hist","topic":"hist.anim","topic2":"lang.comp","level":10,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво постига многоплановата камера (multiplane camera) на Дисни, използвана в „Снежанка“?","options":[{"text":"Позволява всеки кадър да се рисува по-бързо и по-евтино","why":"Многоплановата камера прави снимането по-сложно, а не по-бързо."},{"text":"Слоевете на различно разстояние дават дълбочина и паралакс","why":""},{"text":"Смесва рисувани герои със заснети живи актьори","why":"Смесването с живи актьори е друга техника — не многопланова."},{"text":"Дава по-наситен цвят чрез няколко цветни филтъра","why":"Слоевете са за дълбочина, а не за цвят."}],"answer":1,"explain":"Преден, среден и заден план са нарисувани на отделни стъкла на различно разстояние от камерата. При приближаване близките слоеве растат по-бързо, а при изместване се движат с различна скорост — както при реален паралакс.","more":"Можеш да постигнеш същото в After Effects или Blender: раздели фона на слоеве и ги отдалечи в 3D пространството. Виж „Преден, среден и заден план (Foreground, midground, background)“."},{"id":"studio.hist.bg.c01","legacyId":"c1sevp5u","hall":"studio","domain":"hist","topic":"hist.bg","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво е „Българан е галант“ (1915)?","options":[{"text":"Първият български звуков филм — на Васил Гендов","why":"Първият звуков е „Бунтът на робите“ (1933), пак на Гендов."},{"text":"Първият български анимационен филм — на Тодор Динов","why":"„Българан е галант“ е игрален филм; първият професионален рисуван филм, „Юнак Марко“ на Динов, идва чак в средата на 50-те."},{"text":"Първият български документален филм — за войната","why":"„Българан е галант“ е игрална комедия, а не документален филм."},{"text":"Първият български игрален филм — на Васил Гендов","why":""}],"answer":3,"explain":"Филмът е кратка комедия за наперен кавалер, когото една дама ловко надхитрява. Гендов е едновременно сценарист, режисьор и изпълнител на главната роля.","more":"Премиерата е на 13 януари 1915 г. в софийското кино „Модерен театър“. Самият филм е изгубен — сюжетът му е известен главно от спомените на Гендов."},{"id":"studio.hist.bg.c02","legacyId":"c19zmhpc","hall":"studio","domain":"hist","topic":"hist.bg","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"С какво е свързано името на Тодор Динов?","options":[{"text":"С първия български игрален филм, заснет през 1915 г.","why":"Първият игрален филм е на Васил Гендов."},{"text":"С първия български звуков филм, заснет през 1933 г.","why":"Първият звуков филм също е на Гендов — „Бунтът на робите“."},{"text":"Със „Златната палма“ в Кан за „Женитба“","why":"„Женитба“ е на Слав Бакалов и Румен Петков — от следващото поколение."},{"text":"С основаването на българската анимационна школа","why":""}],"answer":3,"explain":"Динов прави „Юнак Марко“ — първия професионален български рисуван филм — и създава първото студио за анимационни филми у нас. Около него израстват аниматори като Доньо Донев, Стоян Дуков и Иван Андонов.","more":"Динов режисира и игрални филми — например „Иконостасът“ (1969), заедно с Христо Христов. Анимацията и игралното кино при него се захранват взаимно: и в двете мисли с образи, а не с думи."},{"id":"studio.hist.bg.c03","legacyId":"c10777g7","hall":"studio","domain":"hist","topic":"hist.bg","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","prompt":"Назови двама автори от българската анимация и по едно тяхно заглавие.","checklist":["Тодор Динов — „Юнак Марко“","Доньо Донев — „Тримата глупаци“","Или друг автор с вярно заглавие"],"model":"Тодор Динов („Юнак Марко“) и Доньо Донев („Тримата глупаци“). Провери и други имена в Справочника или с учителя си.","more":"Добави към списъка: Слав Бакалов и Румен Петков („Женитба“), Петков и поредицата за Чоко и Боко, както и Теодор Ушев — „Сляпата Вайша“, номинирана за „Оскар“."},{"id":"studio.lang.comp.c07","legacyId":"ck0ga64","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Героят е малък в долния ъгъл на кадъра, а всичко останало е празно небе. Какво внушава негативното пространство?","options":[{"text":"Самота и малкост пред света","why":""},{"text":"Сила и контрол над ситуацията","why":"Силата се внушава, когато героят заема кадъра или е в долен ракурс — не когато е малък в ъгъла."},{"text":"Близост и топлина към героя","why":"Близостта идва с по-близки планове; празното небе отдалечава зрителя от героя."},{"text":"Скорост и енергия на движението","why":"Празното пространство забавя окото; енергията идва от диагонали и движение в кадъра."}],"answer":0,"explain":"Празното пространство не е празно: то тежи над героя, изолира го и дава на зрителя време да почувства. Колкото по-голяма е празнотата около малката фигура, толкова по-силно е усещането.","more":"Опитай с телефона: снимай съученик на фона на голяма стена или небе — веднъж едър в центъра, веднъж малък в ъгъла. Сравни коя снимка разказва история."},{"id":"studio.lang.comp.c08","legacyId":"c416t7r","hall":"studio","domain":"lang","topic":"lang.comp","topic2":"board.check","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Story Artist Checklist съветва да избягваш симетрията. Кога тя все пак е силен избор?","options":[{"text":"Когато сцената е бърза и в кадъра трябва да има много движение","why":"Симетрията спира окото и внушава застой — обратното на бърза сцена."},{"text":"Когато искаш да внушиш ред, власт или нещо неестествено","why":""},{"text":"Когато героите спорят и искаш да покажеш кой печели","why":"Симетричният кадър показва двамата като равни; превъзходството се показва с асиметрия."},{"text":"Когато не си сигурен къде да поставиш героя","why":"Симетрия по навик прави кадъра скучен; тя е силна само като съзнателен избор."}],"answer":1,"explain":"Симетрията спира движението на окото: двете половини се уравновесяват и кадърът застива. Без причина това е скучно, но е силно, когато застиването е смисълът: трон, церемония, безкраен коридор.","more":"Уес Андерсън строи много от кадрите си симетрично — например в „Гранд хотел Будапеща“ — и така светът му изглежда подреден и леко нереален."},{"id":"studio.lang.comp.c09","legacyId":"c1ps46j5","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"С какво мрежата на златното сечение се различава от правилото на третините?","options":[{"text":"Линиите ѝ са по-близо до ръбовете: около 25% и 75%","why":"Обратното: съотношението 1 : 1,618 поставя линиите по-близо до центъра, не до ръбовете."},{"text":"Тя дели кадъра на 4 × 4 вместо на 3 × 3","why":"Мрежата пак е от две вертикални и две хоризонтални линии, само на други места."},{"text":"Линиите ѝ са по-близо до центъра: около 38% и 62%","why":""},{"text":"Тя важи за вертикалните линии, но не и за хоризонта","why":"Златното сечение се прилага и хоризонтално, и вертикално — както третините."}],"answer":2,"explain":"1 : 1,618 означава, че по-голямата част е около 61,8% от цялото, а по-малката — около 38,2%. Затова линиите падат по-навътре от третините (33% и 67%) и кадърът изглежда по-събран.","more":"Мрежата на златното сечение се нарича и phi grid — по гръцката буква φ (фи), с която се означава числото 1,618…"},{"id":"studio.lang.angle.c07","legacyId":"ca1ee0t","hall":"studio","domain":"lang","topic":"lang.angle","topic2":"board.persp","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо камерата на нивото на земята прави кадъра толкова динамичен?","options":[{"text":"Хоризонтът излиза от кадъра и перспективата изчезва","why":"Хоризонтът не изчезва — пада ниско, почти до земята, и хората се издигат над него."},{"text":"Линиите стават хоризонтални и кадърът се успокоява","why":"Обратното: ниската камера превръща линиите в диагонали, а хоризонталите успокояват кадъра."},{"text":"Героят се вижда отгоре и изглежда по-подвижен","why":"Камерата на земята гледа героя отдолу, не отгоре."},{"text":"Линиите на перспективата се превръщат в остри диагонали","why":""}],"answer":3,"explain":"Глебас: ниските ракурси са много динамични, защото създават много диагонали. Когато камерата е до пода, ръбовете на стени, маси и покриви се спускат към точката на изчезване под остър ъгъл, а окото усеща диагонала като движение.","more":"Засили ефекта с широкоъгълен обектив (Wide-angle lens) и предмет точно пред него — камък, колело, обувка. Перспективата се преувеличава още повече."},{"id":"studio.lang.pov.c06","legacyId":"c124yuef","hall":"studio","domain":"lang","topic":"lang.pov","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кадър от гледна точка (POV shot) обикновено се монтира между…","options":[{"text":"два установяващи плана на мястото","why":"Установяващите планове ориентират, но не показват чии са очите, през които гледаме."},{"text":"погледа на героя и неговата реакция","why":""},{"text":"два кадъра на предмета, който гледа","why":"Без кадър на героя не знаем кой гледа предмета."},{"text":"засечка през рамо и общ план","why":"Засечката и общият план не свързват погледа с реакцията, затова не знаем чии са очите."}],"answer":1,"explain":"Поглед → това, което вижда → реакция. Първият кадър казва чии са очите, а третият — какво значи видяното за героя. Без тази рамка кадърът от гледна точка е просто кадър на предмет.","more":"Тази тройка разчита на ефекта на Кулешов (Kuleshov effect): едно и също неутрално лице изглежда гладно, тъжно или влюбено според кадъра, монтиран до него."},{"id":"studio.lang.pov.c07","legacyId":"c1ri42yc","hall":"studio","domain":"lang","topic":"lang.pov","topic2":"story.irony","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Героят е в шок и не вярва на очите си. Искаш зрителят да го преживее заедно с него. Как използваш гледната точка?","options":[{"text":"Обективна камера: гледаме го отстрани в далечен план","why":"Отстрани зрителят наблюдава шока, но не го преживява."},{"text":"Кадър от гледна точка: виждаме ясно това, което вижда той","why":"Кадърът от гледна точка показва какво вижда, но ясният образ не предава, че не вярва на очите си."},{"text":"Субективна камера: образът и звукът се изкривяват като за него","why":""},{"text":"Засечка през рамо: гледаме над рамото му към събитието","why":"Над рамото сме до него, но образът остава обективен и не предава състоянието му."}],"answer":2,"explain":"Шокът е вътрешно състояние и се вижда само ако камерата изкриви самия образ и звук. Субективната камера предава преживяването — замайване, страх, объркване — а не само мястото, откъдето героят гледа.","more":"За шока често се използва и вертиго ефектът (Dolly zoom): в „Челюсти“ фонът зад шерифа Броуди сякаш се разтяга в мига, в който разбира, че акулата е нападнала."},{"id":"studio.edit.space.c08","legacyId":"csxe2ke","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Колата се движи отляво надясно. В следващия кадър искаш тя да се движи отдясно наляво, без зрителят да помисли, че се връща. Какво вмъкваш между двата кадъра?","options":[{"text":"Кадър на колата отстрани, но по-отблизо","why":"Страничният кадър пак показва посока надясно — обратът след него изглежда като връщане."},{"text":"Затъмнение, което разделя двата кадъра","why":"Затъмнението прекъсва сцената и внушава изминало време, а не продължение на пътя."},{"text":"Кадър, в който колата идва право към камерата","why":""},{"text":"Кадър отгоре, в който колата кара надясно","why":"И отгоре посоката е надясно; липсва кадър без посока, който да я неутрализира."}],"answer":2,"explain":"Когато колата идва право към камерата, тя не се движи нито наляво, нито надясно по екрана. Този кадър без посока разделя двата кадъра и следващата посока се приема като продължение на пътя, а не като връщане.","more":"Друг начин да смениш посоката е да покажеш самия завой. Ако колата завие пред очите на зрителя, новата посока е обяснена и кадър по оста не е нужен."},{"id":"studio.edit.cuts.c09","legacyId":"c1arm6w8","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Героят казва: „За нищо на света няма да скоча с парашут!“ — срязване — той крещи, падайки от самолета. Как се нарича този похват?","options":[{"text":"Прескачащ монтаж (Jump cut)","why":"Прескачащият монтаж реже в един и същ кадър; тук скачаме към съвсем друга ситуация."},{"text":"Графично съвпадение (Match cut)","why":"Графичното съвпадение свързва по форма; тук връзката е смисловото опровержение."},{"text":"Smash cut","why":""},{"text":"L-срязване (L-cut)","why":"При L-срязване звукът от предишния кадър продължава; тук ефектът идва от рязкото опровержение."}],"answer":2,"explain":"Срязването е внезапно и без никакъв преход, а следващият кадър опровергава току-що казаното. Контрастът между увереността и реалността ражда смях — същият рязък скок може да роди и шок.","more":"За по-силен ефект срежи веднага след последната дума и започни новия кадър в най-шумния му момент — без затъмнение и без звуков преход."},{"id":"studio.edit.cuts.c10","legacyId":"c5ybn9o","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Каква е разликата между insert shot и вмъкнат кадър (Cutaway)?","options":[{"text":"Insert е дълъг кадър, а cutaway — кратък като мигване","why":"Дължината не ги различава; различава ги дали кадърът е част от действието."},{"text":"Insert показва героя, а cutaway — предмета, който той гледа","why":"По-скоро обратното: insert често е предмет от действието, а cutaway може да е лице."},{"text":"Insert е детайл от самото действие, cutaway е нещо извън него","why":""},{"text":"Insert се снима на площадката, а cutaway идва от архив","why":"И двата обикновено се снимат на площадката; архивните кадри са друг случай."}],"answer":2,"explain":"Бележката в ръката на героя е insert — тя е част от това, което той прави в момента. Лицето на съседа, който гледа през прозореца, е cutaway — то отвежда погледа извън действието.","more":"В английските наръчници insert понякога се нарича и cut-in — „срязване навътре“ в същата сцена, за разлика от cutaway — „срязване навън“."},{"id":"studio.edit.time.c06","legacyId":"c11q492c","hall":"studio","domain":"edit","topic":"edit.time","topic2":"edit.sound","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо монтажната поредица (Montage) обикновено е под музика?","options":[{"text":"Кадрите са без звук, защото се снимат на различни места","why":"Кадрите може да имат звук; музиката се избира, за да ги свърже, а не защото звук липсва."},{"text":"Музиката свързва разнородните кадри в едно цяло","why":""},{"text":"Музиката е по-евтина от записа на реален звук","why":"Цената не е причината; музиката дава ритъм и емоция на сгъстеното време."},{"text":"Музиката забавя кадрите, за да се разтегне времето","why":"Монтажната поредица сгъстява времето, а музиката дава ритъм, не забавяне."}],"answer":1,"explain":"Кадрите в монтажната поредица са от различни места и дни и звукът им не се свързва. Непрекъснатата музика им дава общ ритъм и настроение, затова скоковете във времето не дразнят.","more":"В „В небето“ (2009) монтажна поредица само под музика, без нито една реплика, разказва за няколко минути целия съвместен живот на Карл и Ели."},{"id":"studio.edit.theory.c05","legacyId":"cc9wchy","hall":"studio","domain":"edit","topic":"edit.theory","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи метода на Айзенщайн с описанието.","pairs":[["Метричен монтаж","Кадрите се режат по точна дължина, независимо какво показват"],["Ритмичен монтаж","Срязването следва ритъма на движението в кадъра"],["Тонален монтаж","Кадрите се свързват по настроение — светлина, мъгла, вода"],["Интелектуален монтаж","Съпоставката на два кадъра ражда идея"]],"explain":"Методите вървят от простия към сложния: метричният гледа само дължината на кадъра, ритмичният — движението в него, тоналният — настроението му, а интелектуалният — идеята от съпоставката. Между тоналния и интелектуалния Айзенщайн поставя и обертонния.","more":"Айзенщайн описва тези методи в статията „Методи на монтажа“ (1929) и ги илюстрира със собствените си филми, например „Броненосецът Потьомкин“ и „Октомври“."},{"id":"studio.edit.theory.c06","legacyId":"c1qu9yue","hall":"studio","domain":"edit","topic":"edit.theory","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Монтажистка реже танцова сцена така, че всяко срязване пада на стъпка на танцьора. Кой метод по Айзенщайн е най-близо?","options":[{"text":"Ритмичен монтаж (Rhythmic montage)","why":""},{"text":"Метричен монтаж (Metric montage)","why":"Метричният реже по дължина на кадрите, като по часовник, независимо от стъпките."},{"text":"Тонален монтаж (Tonal montage)","why":"Тоналният следва емоционалния тон на кадрите — светлина, настроение, — а не движението."},{"text":"Обертонен монтаж (Overtonal montage)","why":"Обертонният съчетава всички методи; тук водещото е движението в кадъра."}],"answer":0,"explain":"Мястото на срязването се определя от самите кадри — от стъпките на танцьора, — а не от предварително зададена дължина. Метричният монтаж би рязал „по часовник“, независимо от стъпките.","more":"Съвет за монтаж: докато гледаш материала, слагай маркер на всяка стъпка или удар. После режи по маркерите — така срязванията ще паднат в ритъма на движението."},{"id":"studio.edit.theory.c07","legacyId":"c1eu60nl","hall":"studio","domain":"edit","topic":"edit.theory","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво показва експериментът на Кулешов с лицето на актьора Иван Мозжухин?","options":[{"text":"Мозжухин успява да изиграе три чувства с едно лице","why":"Лицето е едно и също във всички версии; „играта“ идва от монтажа."},{"text":"Зрителите не забелязват срязването между кадрите","why":"Експериментът не е за видимостта на срязването, а за смисъла, който се ражда между кадрите."},{"text":"Смисълът на лицето зависи от кадъра до него","why":""},{"text":"Крупният план е по-силен от общия план","why":"Размерът на плана не е темата; темата е съпоставката на два кадъра."}],"answer":2,"explain":"Кулешов монтира един и същ кадър с неутралното лице на Мозжухин след различни кадри — например чиния супа или ковчег. Зрителите хвалят как актьорът играе глад и скръб, а лицето е едно и също: смисълът се ражда от съпоставката.","more":"Оригиналните кадри не са запазени, а разказите за експеримента се различават в подробностите. Затова учени го повтарят и в наши дни, за да проверят доколко ефектът наистина действа."},{"id":"studio.cam.lens.c10","legacyId":"c1qjqr29","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"В един кадър искаш лицето на героя съвсем близо до обектива и стрелеца далеч в дъното — и двамата рязко. Какво използваш?","options":[{"text":"Прехвърляне на фокуса (Rack focus)","why":"Прехвърлянето мести рязкостта от единия към другия — не ги дава рязко едновременно."},{"text":"Макро обектив (Macro lens)","why":"Макро обективът може да фокусира съвсем отблизо, но тогава рязкостта е милиметри — далечният стрелец ще е напълно размит."},{"text":"Разделена диоптрична леща (Split diopter)","why":""},{"text":"Плитка дълбочина на рязкост (Shallow depth of field)","why":"Плитката рязкост прави рязък само един план — обратното на целта."}],"answer":2,"explain":"Разделената диоптрична леща (Split diopter) покрива само половината обектив и действа като лупа: през нея се фокусира отблизо, а през празната половина — далеч. Обикновеният дълбок фокус не стига, когато лицето е съвсем до обектива.","more":"Режисьорът Брайън Де Палма е известен с тази леща: в много негови филми лице в единия край на кадъра и далечно действие в другия са рязко едновременно."},{"id":"studio.cam.lens.c11","legacyId":"c1l7je2w","hall":"studio","domain":"cam","topic":"cam.lens","topic2":"board.persp","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"В перспектива с две точки слагаш точките на изчезване близо една до друга. Какво внушение се получава?","options":[{"text":"Като при телеобектив: сплескано и спокойно","why":"Обратното: раздалечените точки дават изглед като при телеобектив, а близките — като при широкоъгълен."},{"text":"Като при птичи поглед: гледаме отгоре надолу","why":"Птичият поглед иска трета точка надолу; две близки точки дават широкоъгълен изглед."},{"text":"Като при широкоъгълен обектив: разтеглено и динамично","why":""},{"text":"Като при нормален обектив: без изкривяване","why":"Близките точки изкривяват силно — неутрален изглед дават умерено раздалечени точки."}],"answer":2,"explain":"Глебас: колкото по-раздалечени са точките, толкова повече изгледът прилича на телеобектив; близките точки дават широкоъгълен изглед. Близките точки събират линиите рязко, както при широк обектив отблизо.","more":"Провери го в 3D програма, например Blender: кубче, заснето отблизо с камера 18 mm, има рязко събиращи се ръбове, а отдалеч със 135 mm, при същия размер в кадъра, ръбовете са почти успоредни."},{"id":"studio.cam.focus.c06","legacyId":"cb8foya","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Героят говори по телефона на преден план, а в дъното на стаята детето му се катери към отворения прозорец. Искаш зрителят да вижда и двамата едновременно. Какво избираш?","options":[{"text":"Дълбок фокус: рязко е и лицето, и детето","why":""},{"text":"Плитка рязкост: рязко е лицето на героя, фонът — не","why":"Детето в дъното ще е размито и опасността ще остане незабелязана."},{"text":"Прехвърляне на фокуса от героя към детето","why":"Прехвърлянето показва първо единия, после другия — не едновременно."},{"text":"Мек фокус, който омекотява целия кадър","why":"Мекият фокус омекотява всичко и отнема яснотата, която опасността изисква."}],"answer":0,"explain":"Дълбокият фокус позволява две действия на различни планове едновременно; зрителят вижда опасността, която героят не вижда. Постига се със затворена бленда (f/8–f/16), широк обектив и много светлина.","more":"Хичкок обяснява напрежението (Suspense) с бомба под масата: ако публиката я вижда, а героите не подозират, всеки миг спокоен разговор става мъчителен."},{"id":"studio.cam.move.c06","legacyId":"c1w2h1ad","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Героят разбира, че е останал съвсем сам в огромния град. Как го показваш с движение на камерата?","options":[{"text":"Рязка панорама към празната улица до него","why":"Рязката панорама е бърз преход; не показва колко е малък героят в целия град."},{"text":"Ръчна камера, която го следва плътно в гръб","why":"Плътното следване ни държи до героя и крие празното пространство около него."},{"text":"Отдалечаване, докато героят се смали сред улиците","why":""},{"text":"Обикаляне около него по дъга отблизо","why":"Дъгата подчертава значимостта на момента, но отблизо не показва самотата в града."}],"answer":2,"explain":"С всяка секунда героят заема по-малка част от кадъра, а празното пространство около него расте. Съотношението между малката фигура и огромния град се превръща в образ на самотата.","more":"Днес такъв кадър често се снима с дрон, който се отдалечава и издига едновременно. Преди полет в града провери правилата: над хора и улици летенето е ограничено."},{"id":"studio.cam.move.c07","legacyId":"cr6mosi","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"С какво проследяващият кадър (Tracking shot) се различава от панорамата?","options":[{"text":"При проследяването камерата се завърта, при панорамата — пътува","why":"Обратното: при панорамата камерата се завърта от едно място, а при проследяването пътува с героя."},{"text":"При проследяването камерата пътува, при панорамата — само се завърта","why":""},{"text":"Проследяването е с ръчна камера, а панорамата — от статив","why":"И двете може да се правят с различна техника; разликата е дали камерата се премества."},{"text":"Проследяването следи героя, а панорамата — пейзажа","why":"И панорамата може да следи герой; разликата е, че камерата не напуска мястото си."}],"answer":1,"explain":"При панорамата гледната точка остава на място и перспективата не се мени. При проследяването камерата пътува: близките предмети се разминават по-бързо от далечните (паралакс) и пространството се открива около героя.","more":"Филмът „1917“ (2019) на Сам Мендес е заснет и монтиран така, че да изглежда като почти непрекъснат проследяващ кадър след двамата войници."},{"id":"studio.cam.expo.c08","legacyId":"c16430fx","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Снимаш с 30 кадъра в секунда и ъгъл на затвора 180°. Колко време се експонира всеки кадър? Въведи знаменателя (1/…).","answer":60,"unit":"","explain":"Времето на експонация е (ъгъл ÷ 360°) × (1 ÷ кадровата честота). При 180° затворът е отворен половината от времето на кадъра: 1/30 ÷ 2 = 1/60 s.","more":"Пример от практиката: в страни с мрежа 50 Hz при 24 кадъра често се ползва ъгъл 172,8°. Той дава точно 1/50 s и пази от трептене на лампите."},{"id":"studio.cam.settings.c01","legacyId":"c1hxfrn3","hall":"studio","domain":"cam","topic":"cam.settings","level":11,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Стълб в хистограмата е „залепен“ за десния край. Какво означава това?","options":[{"text":"Част от кадъра е в пълна сянка и е без детайл","why":"Сенките без детайл се натрупват в левия край на хистограмата."},{"text":"Част от кадъра е прегоряла и е без детайл","why":""},{"text":"Цветовете в кадъра са прекалено наситени","why":"Хистограмата на яркостта показва светлото и тъмното, не наситеността."},{"text":"Кадърът е добре експониран, защото е светъл","why":"Светлият кадър е добър, докато не опре в края; залепеният стълб значи загубен детайл."}],"answer":1,"explain":"Десният край на хистограмата е най-голямата яркост, която камерата може да запише. Всичко по-светло се „отрязва“ на тази стойност и става еднакво бяло, без детайл.","more":"Прегоряло бяло не може да се върне при обработката, а тъмното често може да се изсветли. Затова при съмнение пази светлите места: намали експозицията, докато стълбът се отлепи от края."},{"id":"studio.cam.settings.c02","legacyId":"cx0b0if","hall":"studio","domain":"cam","topic":"cam.settings","level":11,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Зебрата на 100% показва ивици по бялата риза на героя. Какво правиш?","options":[{"text":"Махам зебрата, защото ивиците ще влязат в записа","why":"Зебрата не се записва; тя само предупреждава, че тези места ще прегорят."},{"text":"Отварям блендата, за да влезе повече светлина","why":"Повече светлина ще прегори ризата още повече."},{"text":"Намалявам експозицията, докато ивиците изчезнат","why":""},{"text":"Оставям така — ивиците показват добра експозиция","why":"Зебрата на 100% показва загубен детайл, а не добра експозиция."}],"answer":2,"explain":"При зебра на 100% ивиците бележат места на границата на прегаряне — там бялото губи гънките и текстурата на плата. Затваряш леко блендата или слагаш ND филтър, за да ги върнеш.","more":"Белите ризи са класически капан: експонираш ли за лицето, ризата прегаря, а пазиш ли ризата, лицето потъмнява. Затова костюмографите често избягват чисто бялото и избират леко сиво или кремаво."},{"id":"studio.cam.settings.c03","legacyId":"cmmfikd","hall":"studio","domain":"cam","topic":"cam.settings","topic2":"light.color","level":11,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Снимаш късометражен филм и после ще има цветова корекция. Кой профил избираш в камерата?","options":[{"text":"Плосък профил Log — блед, но с повече детайл","why":""},{"text":"Наситен профил Vivid — ярък още в камерата","why":"Наситеният профил „изпича“ цвета в записа и оставя малко място за корекция."},{"text":"Контрастен профил — плътно черно и бяло","why":"Високият контраст реже детайла в светлото и тъмното — точно онова, което колористът търси."},{"text":"Черно-бял профил — цветът се добавя после","why":"Цвят, който не е записан, не може да се добави после."}],"answer":0,"explain":"Log записва светлината по логаритмична крива: сгъстява целия диапазон от най-тъмното до най-светлото, вместо да го реже. Затова изглежда сив в камерата, но колористът има повече детайл в светлото и тъмното.","more":"Log има цена: при 8-битов запис в небето и по стените лесно се появяват ивици (banding), затова за него се предпочита 10-битов запис. Нужна е и точна експозиция."},{"id":"studio.cam.settings.c04","legacyId":"ctwzvu0","hall":"studio","domain":"cam","topic":"cam.settings","level":11,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy","fixes":["B026","B027"]},"kind":"card","format":"choice","prompt":"Кой инструмент в камерата оцветява най-рязките контури в кадъра?","options":[{"text":"False colour","why":"False colour оцветява кадъра според яркостта — инструмент за експозиция."},{"text":"Focus peaking","why":""},{"text":"Зебра (Zebra)","why":"Зебрата отбелязва с ивици местата, които ще прегорят."},{"text":"Вълнов монитор (Waveform monitor)","why":"Вълновият монитор показва яркостта по ширината на кадъра, а не рязкостта."}],"answer":1,"explain":"Камерата търси местата с най-силен контраст между съседни пиксели — там образът е на фокус — и ги оцветява. Така на малкия екран виждаш къде е рязкостта, докато въртиш пръстена за фокус.","more":"Цветът и силата на peaking се настройват: избери цвят, който го няма в кадъра — например червен в зелена гора. За прецизен фокус увеличи и образа на екрана (лупа)."},{"id":"studio.cam.settings.c05","legacyId":"c1a08qi0","hall":"studio","domain":"cam","topic":"cam.settings","topic2":"cam.expo","level":11,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"ND филтър с плътност 0,9 намалява светлината с колко степени (stops)?","answer":3,"unit":"степени","explain":"Плътността е логаритмична мярка: всяко 0,3 намалява светлината наполовина, тоест с една степен. 0,9 = 3 × 0,3 — три степени, или 2 × 2 × 2 = 8 пъти по-малко светлина.","more":"Плътностите се събират: ND 0,6 + ND 0,3 = 0,9, тоест 3 степени. Евтините силни ND филтри често дават лек цветен оттенък — провери баланса на бялото, след като ги сложиш."},{"id":"studio.cam.settings.c06","legacyId":"c1btj3b5","hall":"studio","domain":"cam","topic":"cam.settings","topic2":"anim.tech","level":11,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо анимационният проект се предава с един кодек (напр. ProRes) за монтажа, а с друг (напр. H.264) за YouTube?","options":[{"text":"За монтажа трябва качество, а за мрежата — малък файл","why":""},{"text":"YouTube не приема ProRes, затова трябва да се прекодира","why":"YouTube приема и ProRes, но файлът е огромен; H.264 се избира заради размера."},{"text":"H.264 пази повече детайл и е по-добър за монтажа","why":"Обратното: H.264 компресира силно и е по-тежък за монтаж, а ProRes пази качеството."},{"text":"ProRes пази звука, а H.264 — образа на проекта","why":"И двата кодека са за видео; разликата е в компресията, не в звука."}],"answer":0,"explain":"ProRes компресира леко и всеки кадър поотделно — пази качеството и монтажът върви гладко. H.264 обикновено пази цели само някои кадри, а за останалите — само промените, и дава малък файл за качване. ДОС по професията изисква да избираш кодек според устройството.","more":"Пази основното копие на проекта в ProRes и от него прави версиите за различните платформи. Ако прекодираш H.264 в H.264 няколко пъти, качеството пада всеки път."},{"id":"studio.cam.genres.c01","legacyId":"c17akno9","hall":"studio","domain":"cam","topic":"cam.genres","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи жанра със задачата.","pairs":[["Портрет","Да покаже характера на човека"],["Репортажна фотография","Да документира събитие без постановка"],["Натюрморт","Да подреди и освети предмети"],["Фотоистория","Да разкаже история в поредица от снимки"]],"explain":"Жанрът се определя от задачата, а не от предмета: един и същ човек може да е в портрет, в репортаж или във фотоистория. Решаващо е какво искаш да кажеш и дали намесата ти е позволена.","more":"Упражнение: снимай един учебен ден в три жанра — портрет на съученик, репортажен кадър от междучасието и натюрморт с предметите на чина му."},{"id":"studio.cam.genres.c02","legacyId":"cu76m9s","hall":"studio","domain":"cam","topic":"cam.genres","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кое е основното правило в репортажната фотография?","options":[{"text":"Снима се с дълъг обектив, за да не се пречи","why":"Обективът е въпрос на избор; правилото е да не се намесваш в събитието."},{"text":"Кадрирането се поправя после с изрязване и ретуш","why":"Ретушът, който променя съдържанието, разрушава доверието в репортажа."},{"text":"Не се постановява и не се променя съдържанието","why":""},{"text":"Героите позират, за да е снимката ясна","why":"Позирането е постановка — точно това репортажът не допуска."}],"answer":2,"explain":"Репортажната снимка е документ: зрителят вярва, че така се е случило. Разкритата постановка или манипулация поставя под съмнение и всички останали снимки на автора и на медията.","more":"Военният фотограф Робърт Капа съветва: ако снимките ти не са достатъчно добри, значи не си бил достатъчно близо. Репортерът не нагласява събитието — избира откъде и кога да го снима."},{"id":"studio.cam.genres.c03","legacyId":"chjooql","hall":"studio","domain":"cam","topic":"cam.genres","topic2":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Спортна фотография: бегач спринтира към теб. Кои настройки избираш?","options":[{"text":"Затвор 1/1000, следящ фокус и серийни снимки","why":""},{"text":"Затвор 1/1000, заключен фокус и единична снимка","why":"Заключеният фокус остава на първото разстояние, а бегачът се приближава."},{"text":"Затвор 1/60, следящ фокус и серийни снимки","why":"При 1/60 бързият бегач ще е размазан."},{"text":"Затвор 1/15, заключен фокус и статив","why":"Дългият затвор размазва движението, а заключеният фокус губи бегача."}],"answer":0,"explain":"Добър спринтьор тича с около 10 m/s: при 1/1000 s той се премества само с около 1 cm и излиза рязък. Разстоянието до него се сменя всеки миг, затова следящият фокус го преизчислява непрекъснато, а серията дава избор на най-добрата фаза.","more":"Професионалистите често фокусират предварително в точка, през която бегачът ще мине, например финалната линия, и снимат в мига, в който стигне до нея. Пробвай на училищния стадион."},{"id":"studio.cam.genres.c04","legacyId":"c15dxkij","hall":"studio","domain":"cam","topic":"cam.genres","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Снимаш портрет на възрастен майстор в работилницата му. Кое решение разказва най-много за него?","options":[{"text":"Среден план сред инструментите, със светлина от прозореца","why":""},{"text":"Крупен план на лицето на чист бял фон в студио","why":"Белият фон маха света му — виждаме човек, но не майстор."},{"text":"Далечен план на работилницата отвън, през витрината","why":"Отвън майсторът е малък и се губи; не виждаме лицето и работата му."},{"text":"Детайл на ръцете му, без лице и без работилница","why":"Ръцете казват нещо, но без лице и среда портретът губи човека."}],"answer":0,"explain":"Инструментите и работното място разказват за занаята и годините труд. Средният план пази и лицето, и средата, а светлината от прозореца е естествена за мястото. Това е портрет в среда (environmental portrait).","more":"Говори с човека, докато снимаш — изразът става по-естествен, отколкото при „усмихни се“. Помоли го да прави нещо обичайно, например да точи длето, и снимай между движенията."},{"id":"studio.cam.genres.c05","legacyId":"cs290de","hall":"studio","domain":"cam","topic":"cam.genres","topic2":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Архитектурен фотограф снима висока сграда отблизо, но иска вертикалите да останат успоредни. Какво използва?","options":[{"text":"Обектив с наклон и отместване, изместен нагоре","why":""},{"text":"Широкоъгълен обектив, наклонен силно нагоре","why":"Щом камерата се наклони нагоре, вертикалите се събират — точно това, което фотографът избягва."},{"text":"Рибешко око, поставено в средата на улицата","why":"Рибешкото око извива линиите още повече."},{"text":"Горен ракурс от покрива на сградата отсреща","why":"При наклон надолу вертикалите пак се събират, само в обратната посока."}],"answer":0,"explain":"Вертикалите остават успоредни, докато сензорът е успореден на фасадата. Отместването плъзга обектива нагоре спрямо сензора и „вдига“ кадъра към върха на сградата, без камерата да се накланя.","more":"Без такъв обектив снимай по-широко, без да накланяш камерата нагоре, и после изрежи празната долна част. Или изправи вертикалите в програма — с цената на част от кадъра."},{"id":"studio.light.3pt.c06","legacyId":"c2vvqco","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"По какво разпознаваш рембрантовото осветление?","options":[{"text":"Светъл триъгълник на сенчестата буза под окото","why":""},{"text":"Сянка като пеперуда точно под носа на героя","why":"Сянката пеперуда под носа е „холивудско“ осветление (Butterfly lighting) — светлината е отпред и отгоре."},{"text":"Светла ивица по ръба на лицето откъм гърба","why":"Светлата ивица по ръба е задна контурна светлина (Rim light)."},{"text":"Равномерно осветено лице почти без сенки","why":"Равномерното лице е плоско осветяване; рембрантовото има светла страна и сянка."}],"answer":0,"explain":"Рисуващата светлина е високо и встрани, затова сянката на носа се слива със сянката на бузата. Между тях остава само малък светъл триъгълник под окото.","more":"Упражнение: постави лампа високо и около 45° встрани от лицето на съученик. Нека той завърта бавно главата, докато под окото на сенчестата страна се появи светлият триъгълник."},{"id":"studio.light.3pt.c07","legacyId":"cc8ttk","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Портрет на уморен детектив в тъмен кабинет. Лицето му е обърнато леко встрани от камерата. Коя страна осветяваш?","options":[{"text":"Близката до камерата страна на лицето","why":"Така сянката отива настрани и лицето става по-широко и открито — за уморен детектив е твърде светло."},{"text":"Далечната от камерата страна на лицето","why":""},{"text":"И двете страни еднакво, за да няма сенки","why":"Без сенки лицето е плоско и губи драматизма."},{"text":"Фона зад него, а лицето остава в силует","why":"Силуетът крие лицето напълно — умората няма да се види."}],"answer":1,"explain":"Когато се освети далечната страна, сянката пада откъм камерата и лицето изглежда по-тясно, с обем и драматизъм — това е късото осветление (Short lighting). Широкото (Broad lighting) е по-открито — за комедия или реклама.","more":"В портретната фотография късото осветление се ползва и за да изглежда пълно лице по-тясно, а широкото — за да добави ширина на много тясно лице."},{"id":"studio.light.quality.c06","legacyId":"c74sq0u","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Малка стая, една лампа, нямаш дифузер, а искаш мека светлина за лицето. Какво правиш?","options":[{"text":"Насочвам лампата право в лицето отблизо","why":"Малкият директен източник дава твърди сенки, дори отблизо."},{"text":"Слагам топъл цветен гел пред лампата","why":"Гелът сменя цвета, а не мекотата на светлината."},{"text":"Отдалечавам лампата в другия край на стаята","why":"По-далечният източник е относително по-малък и светлината става по-твърда."},{"text":"Насочвам лампата към белия таван или стена","why":""}],"answer":3,"explain":"Меката светлина идва от голям източник. Когато лампата освети белия таван или стената, светлото петно става новият, много по-голям източник за лицето.","more":"Отразената светлина губи много сила: колкото по-далеч и по-тъмен е таванът, толкова по-слаба е тя. Затова при висок таван ти трябва по-мощна лампа."},{"id":"studio.light.quality.c07","legacyId":"c1djwonq","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Откъде идва понятието светлосянка (Chiaroscuro)?","options":[{"text":"От ранната фотография — „рисуване със светлина“","why":"„Рисуване със светлина“ е значението на думата фотография; светлосянката е по-стара — от живописта."},{"text":"От театъра на сенките — „игра на сенки“","why":"Театърът на сенките е друго изкуство; терминът е италиански, от живописта."},{"text":"От италианската живопис — „светло-тъмно“","why":""},{"text":"От немското кино — „експресивна светлина“","why":"Немското кино наследява светлосянката, но понятието идва от живописта — Караваджо, Рембранд."}],"answer":2,"explain":"Думата е сбор от chiaro („светло“) и scuro („тъмно“). Живописците моделират обема на фигурите със силен контраст, а киното наследява похвата през немския експресионизъм и ноара.","more":"Крайната форма, при която фигурите изплуват от почти черен фон, се нарича тенебризъм и е свързана с Караваджо. Разгледай негова картина и опитай да повториш светлината с една лампа."},{"id":"studio.light.color.c05","legacyId":"c17n4ogw","hall":"studio","domain":"light","topic":"light.color","level":10,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Много съвременни филми оцветяват сенките в синьо-зелено, а кожата — в оранжево (teal and orange). Защо?","options":[{"text":"Синьо-зеленото внушава нощ, а оранжевото — ден","why":"Сцената може да е по всяко време; целта е контрастът между кожата и фона."},{"text":"Допълващите цветове отделят лицата от фона","why":""},{"text":"Камерите записват най-точно тези два цвята","why":"Камерите записват всички цветове; изборът е художествен."},{"text":"Двата цвята са най-евтини за цветова корекция","why":"Цената на корекцията не зависи от цвета."}],"answer":1,"explain":"Синьо-зеленото и оранжевото са почти противоположни в цветния кръг, а кожата е естествено в топлата част. Затова лицата изпъкват срещу студения фон.","more":"Честа грешка е прекаленият ефект: кожата става оранжева като морков, а сенките — неестествено зелени. При корекцията пази кожата близо до естествения ѝ тон."},{"id":"studio.light.color.c06","legacyId":"c3wyhx","hall":"studio","domain":"light","topic":"light.color","level":10,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Сцена-спомен от щастливо детство, което героят вече не може да върне. Какво правиш с цвета при корекцията?","options":[{"text":"Топла, леко избледняла гама с по-ниска наситеност","why":""},{"text":"Студена синя гама с висок контраст и дълбоко черно","why":"Студеното и контрастното внушават тревога или дистанция, а не уют."},{"text":"Ярки наситени цветове с неонови акценти","why":"Неонът е нощен и модерен — не носи носталгия."},{"text":"Топла, но силно наситена гама с плътен контраст","why":"Топлото е вярно, но силната наситеност прави спомена ярък като настояще; избледняването дава дистанцията на времето."}],"answer":0,"explain":"Топлината носи уют и носталгия, а по-ниската наситеност — дистанцията на времето, като при избеляла стара снимка.","more":"Опитай в приложение за снимки: намали малко наситеността, леко изсветли най-тъмните места и добави топлина. Снимката веднага заприличва на стара фотография."},{"id":"studio.light.color.c07","legacyId":"csn62tq","hall":"studio","domain":"light","topic":"light.color","topic2":"prod.crew","level":10,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy","fixes":["B028"]},"kind":"card","format":"choice","prompt":"Кой отговаря за цвета на готовия филм в постпродукцията?","options":[{"text":"Главният осветител (Gaffer)","why":"Главният осветител отговаря за светлината на площадката, а не за цвета в постпродукцията."},{"text":"Колористът (Colourist)","why":""},{"text":"Монтажистът (Editor)","why":"Монтажистът подрежда кадрите; цветовата корекция е отделна професия."},{"text":"Художникът по костюмите (Costume designer)","why":"Художникът по костюмите избира цветовете на дрехите още преди снимките."}],"answer":1,"explain":"Колористът уеднаквява кадрите и създава цветовия стил заедно с режисьора и оператора-постановчика. Основната му работа започва след монтажа, когато редът на кадрите е окончателен.","more":"Ако снимаш в плосък профил (Log profile), картината излиза сива и бледа — нарочно, за да остане повече информация в светлото и тъмното за колориста."},{"id":"studio.light.loc.c06","legacyId":"cm0m8f8","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо при снимки на зелен екран актьорът не бива да носи зелени дрехи?","options":[{"text":"Зеленото изглежда сиво на камерата","why":"Камерата вижда зеленото отлично — точно затова софтуерът може да го изреже."},{"text":"Дрехите ще изчезнат заедно с фона","why":""},{"text":"Камерата фокусира по-трудно върху зелено","why":"Фокусът не зависи от цвета на дрехата."},{"text":"Зеленото се записва по-тъмно от другите цветове","why":"Зеленият канал е най-чистият в сензора — затова екраните са зелени."}],"answer":1,"explain":"Зеленият екран (Chroma key) изрязва всичко в определен цвят. Софтуерът не знае кое е фон и кое е дреха — всичко в този цвят става прозрачно.","more":"Внимавай и с отраженията: очила, бижута и лъскави повърхности отразяват зеленото и също могат да „изчезнат“. Дръж актьора на разстояние от екрана — поне около 2 m, — за да не пада зелен отблясък по раменете."},{"id":"studio.light.loc.c07","legacyId":"cwgq0jz","hall":"studio","domain":"light","topic":"light.loc","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"В класическите холивудски филми героите карат кола, а пейзажът зад тях е прожектиран на екран в студиото. Как се нарича техниката?","options":[{"text":"Зелен екран (Chroma key)","why":"Зеленият екран се изрязва в постпродукцията; тук фонът е прожектиран още на снимачната площадка."},{"text":"Американска нощ (Day for night)","why":"Американската нощ е трик с експозиция и цвят, не с прожекция."},{"text":"Рисуван фон (Matte painting)","why":"Рисуваният фон е неподвижна картина, съчетана с кадъра; тук пейзажът зад колата се движи, защото е прожектиран филм."},{"text":"Рир-проекция (Rear projection)","why":""}],"answer":3,"explain":"Прожекторът е зад полупрозрачния екран, затова актьорите не хвърлят сянка върху фона, а камерата заснема всичко наведнъж — още на площадката.","more":"Алфред Хичкок използва рир-проекция в много свои филми, особено за сцените в кола. Днес идеята се връща с LED стените на виртуалната продукция: фонът се показва около актьорите на живо."},{"id":"studio.light.flash.c01","legacyId":"cmvlpal","hall":"studio","domain":"light","topic":"light.flash","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Светкавица с водещо число 40 (ISO 100, метри). Снимаш на f/4. До какво разстояние експозицията е правилна?","answer":10,"unit":"m","explain":"Водещото число е разстояние × f-число, затова разстояние = водещо число ÷ f-число = 40 ÷ 4 = 10 m. По-далечен обект ще излезе тъмен.","more":"Водещото число е дадено при ISO 100. При ISO 400 (две степени по-високо) обхватът се удвоява: на f/4 светкавицата стига до 20 m."},{"id":"studio.light.flash.c02","legacyId":"cdy11qj","hall":"studio","domain":"light","topic":"light.flash","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"calc","prompt":"Светкавица с водещо число 32 (ISO 100, метри). Обектът е на 4 m. Каква бленда избираш? Въведи f-числото.","answer":8,"unit":"","explain":"От формулата водещо число = разстояние × f-число следва: f-число = 32 ÷ 4 = 8, тоест f/8.","more":"Ако обектът се отдалечи двойно — на 8 m, — блендата трябва да се отвори с две степени, до f/4: светлината отслабва с квадрата на разстоянието."},{"id":"studio.light.flash.c03","legacyId":"cudqd2b","hall":"studio","domain":"light","topic":"light.flash","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Портрет на плажа по обед: слънцето е зад героинята и лицето ѝ е тъмно. Какво правиш?","options":[{"text":"Затварям блендата чак до f/22","why":"По-малкият отвор затъмнява всичко — лицето става още по-тъмно."},{"text":"Вдигам ISO чак до 6400","why":"ISO изсветлява всичко — небето и пясъкът ще прегорят."},{"text":"Запълваща светкавица отпред","why":""},{"text":"Скъсявам затвора до 1/4000 s","why":"По-краткият затвор намалява цялата светлина — лицето потъмнява още."}],"answer":2,"explain":"Светкавицата изсветлява близкото лице, но почти не стига до далечното небе и пясъка — те зависят от затвора, блендата и ISO. Така изравняваш лицето с яркия фон, без да прегаряш небето.","more":"Нямаш светкавица? Бял отражател отпред върши същото: връща част от слънцето зад героинята обратно към лицето."},{"id":"studio.light.flash.c04","legacyId":"c1tdn0nd","hall":"studio","domain":"light","topic":"light.flash","topic2":"light.quality","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо светкавица, насочена право в лицето от апарата, дава „плоска“ снимка?","options":[{"text":"Светлината е твърде слаба и не стига до лицето","why":"Проблемът не е силата; дори силна, светлината от оста не дава сенки."},{"text":"Светлината идва от оста на обектива и не дава сенки","why":""},{"text":"Светлината е студена и прави кожата синкава","why":"Цветът се поправя с баланса на бялото; плоскостта идва от посоката."},{"text":"Светлината е твърде мека и изглажда формите","why":"Малката светкавица е твърда светлина; плоска е, защото сенките падат зад героя."}],"answer":1,"explain":"Обемът се вижда от сенките. Светлината от оста на обектива хвърля сенките точно зад героя, където камерата не ги вижда — затова насочи светкавицата към тавана или я отдалечи встрани от апарата.","more":"Евтин трик: прикрепи с ластик бяла картичка зад главата на светкавицата, насочена към тавана. Част от светлината отива напред и оставя светли отблясъци в очите."},{"id":"studio.light.flash.c05","legacyId":"cvm0gop","hall":"studio","domain":"light","topic":"light.flash","topic2":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Със светкавица и затвор 1/1000 част от кадъра излиза като черна ивица. Защо?","options":[{"text":"Затворът е по-кратък от синхронната скорост","why":""},{"text":"Светкавицата е твърде слаба за цялото поле","why":"Слабата светкавица дава тъмен кадър навсякъде, а не рязка черна ивица."},{"text":"Затворът е по-дълъг от синхронната скорост","why":"Обратното: при по-дълъг затвор двете завеси са напълно отворени и ивица няма."},{"text":"Обективът е по-широк от лъча на светкавицата","why":"Така потъмняват ъглите, а не ивица; ивицата е от завесата на затвора."}],"answer":0,"explain":"При затвор, по-кратък от синхронната скорост (обикновено около 1/200–1/250 s), втората завеса тръгва, преди първата да е открила целия кадър. Краткият импулс на светкавицата заварва само процеп и останалото остава тъмно.","more":"Затова много апарати сами не позволяват по-кратък затвор, когато светкавицата е включена. Режимът HSS (High-Speed Sync) заобикаля проблема с много бързи импулси, но светкавицата губи голяма част от мощността си."},{"id":"studio.board.check.c05","legacyId":"czrb7qa","hall":"studio","domain":"board","topic":"board.check","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"В панела ръбът на масата минава точно по брадичката на героя, а лампата сякаш расте от главата му. Какъв е проблемът?","options":[{"text":"Въздухът над главата е твърде много и героят потъва","why":"Проблемът не е в празното над главата, а в предметите, които се допират до героя."},{"text":"Контурите се допират и пространството става плоско","why":""},{"text":"Ракурсът е грешен и героят изглежда малък","why":"Ракурсът не е описан като проблем; проблем е допирът на контурите."},{"text":"Композицията е симетрична и затова е скучна","why":"Симетрията не е описана; лампата и масата се сливат с героя."}],"answer":1,"explain":"Глебас: лошите тангенти сплескват пространството, защото два плана на различна дълбочина се допират и окото ги чете като един. Премести предметите така, че контурите ясно да се застъпват или да са раздалечени.","more":"Класическият пример на Глебас: туристка получава снимките от почивката и открива, че от главата на детето ѝ „расте“ дърво. Преди да снимаш портрет, провери какво стои точно зад главата."},{"id":"studio.board.check.c06","legacyId":"cs2fs0l","hall":"studio","domain":"board","topic":"board.check","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Story Artist Checklist съветва: ако предишният кадър е горен ракурс, следващият да бъде…","options":[{"text":"долен ракурс, за да се смени формата","why":""},{"text":"отново горен ракурс, за да се пази ритъмът","why":"Два еднакви ракурса подред изглеждат еднообразно и могат да подскочат."},{"text":"профилен кадър, за да се успокои окото","why":"Профилът е най-плоският избор; съветът е да контрастираш формите."},{"text":"същият кадър, но в по-близък план","why":"По-близкият план от същия ъгъл внася малко разнообразие; силният контраст идва от смяна на ракурса."}],"answer":0,"explain":"Редуването на горен и долен ракурс дава различни форми и диагонали в поредните кадри, така че окото ясно усеща смяната. Това помага да избегнеш и прескачащ монтаж (Jump cut).","more":"В сцена между силен и слаб герой смяната има и смисъл: силния показваш отдолу, а слабия — отгоре, и зрителят усеща кой доминира, без нито дума."},{"id":"studio.board.check.c07","legacyId":"c1x9erh9","hall":"studio","domain":"board","topic":"board.check","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Героят бяга от чудовище, но в панелите двамата тичат отляво надясно в профил и сцената е плоска. Какво променяш?","options":[{"text":"Добавям още профилни кадри с по-бързо темпо","why":"Повече от същото остава плоско — само по-бързо."},{"text":"Обръщам бягането към камерата или от нея","why":""},{"text":"Правя кадъра симетричен с героя в центъра","why":"Симетрията спира движението, а сцената има нужда от дълбочина."},{"text":"Слагам хоризонта точно в центъра на кадъра","why":"Хоризонтът в центъра не добавя дълбочина; движението по оста към камерата я добавя."}],"answer":1,"explain":"Story Artist Checklist: движението към или от камерата засилва илюзията за дълбочина, защото размерът на героите се сменя. Чудовище, което расте в кадъра, е и по-страшно; профилът е най-лесен за рисуване, но най-скучен.","more":"В „Джурасик парк“ тиранозавърът гони джипа в дълбочина, а в един кадър се вижда в страничното огледало с надпис „Обектите в огледалото са по-близо, отколкото изглеждат“."},{"id":"studio.board.notation.c05","legacyId":"c19elpz1","hall":"studio","domain":"board","topic":"board.notation","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","prompt":"Как ще отбележиш на панел: камерата панорамира наляво, героят излиза от кадъра вдясно, а репликата се чува зад кадър?","checklist":["Стрелка за камерата с посока на панорамата","Стрелка за героя през ръба на кадъра","Бележка за звук зад кадър"],"checklistNeed":2,"model":"Панорамата — със стрелка за камерата по долния ръб или извън рамката, насочена наляво. Излизането — със стрелка за героя, която минава през десния ръб на кадъра. Репликата — с текста и бележка ЗК (O.S. или V.O.).","more":"Глебас: при панорама се рисуват началната и крайната рамка в пропорциите на кадъра, а стрелка между тях показва посоката. Така се вижда и какво открива камерата по пътя."},{"id":"studio.board.notation.c06","legacyId":"c1cdp8pm","hall":"studio","domain":"board","topic":"board.notation","topic2":"board.persp","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Как показваш в storyboard, че камерата се издига с кран над тълпата?","options":[{"text":"Начален и краен кадър; в крайния хоризонтът е над главите на хората","why":""},{"text":"Начален и краен кадър; хоризонтът пресича хората на същото място","why":"Ако хоризонтът пресича хората на същото място, камерата не е сменила височината си — издигането не се чете."},{"text":"Само краен кадър, а до него голяма стрелка нагоре","why":"Без началния кадър не се вижда откъде тръгва движението."},{"text":"Начален и краен кадър; в крайния хоризонтът е под краката на хората","why":"Хоризонтът е на височината на камерата: когато тя се издига, линията минава над хората, а не под тях."}],"answer":0,"explain":"Харт: когато камерата се качва, хоризонтът и точките на изчезване се качват с нея — затова в крайния кадър хората от тълпата вече са под линията на хоризонта и ги виждаме отгоре.","more":"Опитай с телефона: снимай улица от клек, изправен и от стол, без да накланяш телефона. Хоризонтът остава в средата на кадъра, а хората и колите все повече слизат под него."},{"id":"studio.board.persp.c01","legacyId":"c2yr53s","hall":"studio","domain":"board","topic":"board.persp","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Камерата гледа право по дълъг коридор. Каква перспектива рисуваш?","options":[{"text":"С две точки на изчезване","why":"Две точки има, когато гледаш ъгъл на сграда — тук камерата гледа право по коридора."},{"text":"С три точки на изчезване","why":"Трета точка трябва при поглед силно нагоре или надолу."},{"text":"С една точка на изчезване","why":""},{"text":"С обратна перспектива","why":"Обратната перспектива е в иконите — линиите се разширяват навътре; в кадър за коридор не се използва."}],"answer":2,"explain":"Когато камерата гледа по оста на пространството, стените, подът и таванът се отдалечават право от нея и линиите им се събират в обща точка на хоризонта. Стената в дъното остава успоредна на рамката.","more":"Стенли Кубрик е известен с кадри, в които всички линии бягат към точка точно в центъра — коридори, зали, пътища. Те дърпат окото право в дълбочината и внушават строг ред, а понякога и тревога."},{"id":"studio.board.persp.c02","legacyId":"c162ex0f","hall":"studio","domain":"board","topic":"board.persp","topic2":"lang.angle","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Искаш небостъргачът да изглежда огромен от долен ракурс. Какво добавяш към перспективата?","options":[{"text":"Трета точка ниско под земята — вертикалите се събират","why":"Точка под земята е за поглед надолу (горен ракурс); тук гледаме нагоре."},{"text":"Трета точка високо над сградата — вертикалите се събират","why":""},{"text":"Още една точка на хоризонта, до другите две","why":"Точките на хоризонта не събират вертикалите — нужна е трета точка извън хоризонта."},{"text":"Вертикалите остават успоредни, а хоризонтът се вдига","why":"При поглед нагоре вертикалите се събират; успоредните правят сградата обикновена."}],"answer":1,"explain":"При поглед нагоре и вертикалите се отдалечават от камерата — колкото по-високо, толкова по-далеч, — затова и те се събират към обща точка. Глебас: перспективата с три точки дава най-дълбокото пространство — като поглед нагоре по висока сграда или надолу от нея.","more":"Колкото по-близо до сградата е третата точка, толкова по-рязко се събират вертикалите и кадърът изглежда като заснет с широкоъгълен обектив. По-далечната трета точка дава по-спокоен поглед."},{"id":"studio.board.persp.c03","legacyId":"cfgnzz2","hall":"studio","domain":"board","topic":"board.persp","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Камерата гледа нагоре към героя (долен ракурс). Къде ще е линията на хоризонта в кадъра?","options":[{"text":"Високо в кадъра или над горния ръб","why":"Високо е при горен ракурс; при долен камерата гледа нагоре и хоризонтът слиза."},{"text":"Точно в средата на кадъра","why":"В средата е при нормален ъгъл, когато камерата гледа право напред."},{"text":"Диагонално през кадъра","why":"Наклон има при холандски ъгъл; ракурсът мести хоризонта нагоре или надолу."},{"text":"Ниско в кадъра или под долния ръб","why":""}],"answer":3,"explain":"Хоризонтът е на височината на очите на камерата. Когато тя се наклони нагоре, хоризонтът слиза надолу в кадъра — затова зад героя виждаме повече небе.","more":"Чистият фон от небе прави силуета на героя по-ясен и по-силен — още една причина долният ракурс да внушава мощ. Пробвай с телефона: снимай приятел от нивото на коленете му."},{"id":"studio.board.persp.c04","legacyId":"cx1ay4s","hall":"studio","domain":"board","topic":"board.persp","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"В панел с тълпа на площад всички хора са еднакво високи и стоят на една равнина, но хоризонтът пресича едни през коленете, а други над главата. Какво не е наред?","options":[{"text":"Хоризонтът трябва да минава през едно и също място на всички","why":""},{"text":"Близките хора трябва да са под хоризонта, далечните — над него","why":"Когато хората са еднакво високи и на една равнина, хоризонтът ги пресича на едно и също място."},{"text":"Трябва трета точка на изчезване, за да се оправи тълпата","why":"Третата точка е за силен поглед нагоре или надолу; тук грешката е в хоризонта."},{"text":"Далечните хора трябва да са по-високи, за да се виждат","why":"Далечните се смаляват, но хоризонтът пак минава през тях на същото място."}],"answer":0,"explain":"Глебас: хоризонтът пресича еднакво високите хора на една равнина на едно и също място на тялото, колкото и близо или далеч да са. Ако камерата е на височината на очите им, той минава през очите на всички.","more":"Бърза проверка: избери къде хоризонтът пресича първата фигура, например на коленете. Всяка следваща фигура строй така, че линията пак да минава през коленете ѝ — сменя се само мащабът."},{"id":"studio.board.persp.c05","legacyId":"cbwdbqp","hall":"studio","domain":"board","topic":"board.persp","topic2":"lang.comp","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Как въздушната перспектива помага в пейзажен панел?","options":[{"text":"Далечните планове са по-тъмни, по-наситени и по-резки","why":"Обратното: въздухът намалява контраста и наситеността на далечното."},{"text":"Далечните планове се рисуват със същия контраст","why":"Еднаквият контраст сплесква пейзажа — дълбочината изчезва."},{"text":"Далечните планове са по-светли, по-сиви и по-меки","why":""},{"text":"Близките планове се рисуват по-бледи от далечните","why":"Бледото и сивото отиват в далечината; близкото е най-контрастно."}],"answer":2,"explain":"Въздухът между нас и далечните предмети разсейва светлината: контрастът и наситеността намаляват, а цветовете клонят към синьо и сиво. Окото чете по-бледото като по-далечно.","more":"Леонардо да Винчи описва въздушната перспектива в бележките си за живописта. Виж фона на „Мона Лиза“: планините зад нея са синкави и размити, затова изглеждат далеч."},{"id":"studio.board.persp.c06","legacyId":"c9l4ef3","hall":"studio","domain":"board","topic":"board.persp","level":10,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво е принудителна перспектива (Forced perspective)?","options":[{"text":"Рисуваш перспективата с линийка и точни точки на изчезване","why":"Точната конструкция е обикновена перспектива; принудителната нарочно преувеличава."},{"text":"Преувеличаваш мащаба на близкото и далечното за дълбочина","why":""},{"text":"Накланяш хоризонта, за да изглежда кадърът динамичен","why":"Наклонът на хоризонта е холандски ъгъл, не принудителна перспектива."},{"text":"Рисуваш без точки на изчезване, по усещане","why":"Принудителната перспектива е съзнателен трик с мащаба, а не липса на конструкция."}],"answer":1,"explain":"Харт: преувеличаването на предметите на преден план увеличава дълбочината, защото окото съди за разстоянието по размера. Със същия трик на снимачната площадка актьори с еднакъв ръст изглеждат като великан и дребосък.","more":"Принудителна перспектива има и в Дисниленд: колкото по-нагоре, толкова по-малки са камъните и детайлите на замъка на Спящата красавица, затова той изглежда по-висок, отколкото е."},{"id":"studio.story.staging.c05","legacyId":"clp6kpf","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Двама герои спорят. В началото стоят далеч един от друг, а накрая единият сяда до другия. Какво разказва разстановката?","options":[{"text":"Отношенията минават от конфликт към помирение","why":""},{"text":"Актьорите се движат, за да не е статична сцената","why":"Движението в добрия мизансцен не е за разнообразие — то казва нещо за отношенията."},{"text":"Камерата скоро ще смени ракурса и размера на плана","why":"Разстановката може да мотивира смяна на плана, но смисълът е в отношенията."},{"text":"Единият герой печели спора и доминира над другия","why":"Доминирането се показва с височина и дистанция; сядането до другия е сближаване."}],"answer":0,"explain":"Разстоянието, височината и посоката на движение са езикът на разстановката; промяната в тях е промяна в отношенията. Затова режисьорът планира движенията да съвпаднат с обратите в разговора.","more":"Изиграйте сцената без звук и вижте дали отношенията се четат само от движенията. Ако се четат — разстановката работи; ако не — сцената разчита само на диалога."},{"id":"studio.story.structure.c06","legacyId":"ctha36y","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди точките на класическата структура в три акта.","sequence":["Подбудително събитие (Inciting incident)","Първа повратна точка","Средна точка (Midpoint)","Кулминация (Climax)","Развръзка (Resolution)"],"explain":"Подбудителното събитие отваря историята, първата повратна точка затваря първия акт, средната точка обръща втория, а кулминацията и развръзката затварят третия. Всяка точка е възможна само заради предишната.","more":"Много схеми добавят и втора повратна точка между средната точка и кулминацията — често най-тъмният момент, когато всичко изглежда изгубено. Тя отваря третия акт."},{"id":"studio.story.irony.c07","legacyId":"c127yvgt","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Рицар с отсечена ръка казва: „Само драскотина е!“ Какъв вид ирония е това?","options":[{"text":"Подценяване (Understatement)","why":""},{"text":"Сарказъм (Sarcasm)","why":"Сарказмът е хаплива ирония срещу някого; рицарят не подиграва никого."},{"text":"Драматична ирония (Dramatic irony)","why":"Драматичната ирония иска зрителят да знае нещо, което героят не знае."},{"text":"Поетична справедливост (Poetic justice)","why":"Поетичната справедливост наказва злото; тук има само смешно подценяване."}],"answer":0,"explain":"Подценяването казва много по-малко от истината и оставя зрителя сам да види разликата — колкото е по-голяма, толкова по-смешно. Сцената е от „Монти Пайтън и Свещеният граал“ (1975).","more":"Подценяването работи и в драмата: героят казва „Добре съм“, докато ръцете му треперят. Тогава иронията не разсмива, а показва колко много крие героят."},{"id":"studio.story.irony.c08","legacyId":"cw2m34q","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Зрителят знае, че Жулиета само спи, а Ромео вярва, че е мъртва, и изпива отровата. Какво е това?","options":[{"text":"Ситуационна ирония (Situational irony)","why":"Ситуационната е резултат, обратен на очакваното; тук ключът е, че зрителят знае повече от Ромео."},{"text":"Трагична ирония (Tragic irony)","why":""},{"text":"Космическа ирония (Cosmic irony)","why":"Космическата ирония е, когато съдбата се подиграва с човека; тук ключово е знанието на зрителя."},{"text":"Сарказъм (Sarcasm)","why":"Сарказмът е хаплива реплика, а не ситуация."}],"answer":1,"explain":"Зрителят знае истината, която би спасила Ромео, но не може да му я каже. Това безсилие прави сцената толкова болезнена: тук драматичната ирония не води към смях, а към гибел.","more":"Шекспир издава края още в пролога: зрителят знае, че влюбените ще загинат, преди да ги е видял. Така цялата пиеса се гледа с трагична ирония — знаем накъде вървят, а те не знаят."},{"id":"studio.story.irony.c09","legacyId":"car3cvj","hall":"studio","domain":"story","topic":"story.irony","topic2":"lang.pov","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"В края на филма се оказва, че разказвачът ни е лъгал и целият сюжет се преобръща. Каква е иронията?","options":[{"text":"Вербална ирония (Verbal irony)","why":"Вербалната е в една реплика; тук иронията е в целия разказ."},{"text":"Драматична ирония (Dramatic irony)","why":"При драматичната зрителят знае повече от героя; тук зрителят е бил подведен."},{"text":"Поетична справедливост (Poetic justice)","why":"Поетичната справедливост наказва злото; тук се преобръща разказът."},{"text":"Структурна ирония (Structural irony)","why":""}],"answer":3,"explain":"Иронията не е в една сцена, а в начина, по който е построен целият разказ. Финалният обрат кара зрителя да преосмисли всичко видяно, защото версията на разказвача се разминава с истината.","more":"Добрият обрат с ненадежден разказвач е честен: следите са в кадъра от самото начало. При второ гледане зрителят ги вижда — тук помага засаждането и изплащането (Setup and payoff)."},{"id":"studio.story.irony.c10","legacyId":"c1eby5rb","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Героиня казва на съученичка „Харесвам полата ти!“, а после пред приятелките си я нарича най-грозната пола на света. Ирония ли е първата реплика?","options":[{"text":"Да — вербална ирония, защото мисли обратното","why":"Вербалната ирония разчита слушателят да усети обратния смисъл; тук героинята го крие."},{"text":"Да — сарказъм, защото после ѝ се подиграва","why":"Сарказмът е явна подигравка в самата реплика; тук репликата звучи искрено."},{"text":"Да — драматична ирония, защото ние знаем истината","why":"Самата реплика е лъжа, която иска да бъде повярвана — затова не е ирония."},{"text":"Не — това е лъжа, защото тя иска да ѝ повярват","why":""}],"answer":3,"explain":"Вербалната ирония е открита игра: говорещият иска слушателят да усети обратния смисъл. Лъжата крие смисъла и иска да бъде повярвана. StudioBinder дава този пример от „Гадни момичета“ (Mean Girls).","more":"Ако героинята каже същото с подбелени очи и провлечено „Мно-о-ого ти отива“, репликата става вербална ирония. Често разликата е само в интонацията и мимиката на актьора."},{"id":"studio.story.irony.c11","legacyId":"c1bqc3e9","hall":"studio","domain":"story","topic":"story.irony","topic2":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Злодеят, който цял филм залага капани, накрая пада в собствения си капан. Какво е това?","options":[{"text":"Сократова ирония (Socratic irony)","why":"Сократовата ирония е престорено незнание, с което извеждаш събеседника до истината."},{"text":"Трагична ирония (Tragic irony)","why":"Трагичната води героя към гибел, докато зрителят знае повече; тук злото е наказано."},{"text":"Поетична справедливост (Poetic justice)","why":""},{"text":"Подценяване (Understatement)","why":"Подценяването е в думите — казваш по-малко от истината."}],"answer":2,"explain":"Поетичната справедливост не просто наказва злодея, а го наказва по начин, който отговаря на вината му — оръжието се обръща срещу създателя си. Така зрителят усеща, че светът на историята е справедлив.","more":"В „Цар Лъв“ Скар се опитва да прехвърли вината за злините си върху хиените, но те го чуват. Съюзниците, които е използвал, се обръщат срещу него."},{"id":"studio.story.figures.c01","legacyId":"c1at2b4b","hall":"studio","domain":"story","topic":"story.figures","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"В началото на филма героинята дълго гледа птица в клетка. Какво най-вероятно е това?","options":[{"text":"Визуална метафора за нейния затворен живот","why":""},{"text":"Синекдоха — една птица стои за много птици","why":"Синекдохата е част вместо цяло; тук птицата означава нещо друго — живота на героинята."},{"text":"Установяващ план, който показва стаята ѝ","why":"Установяващият план показва мястото, а дългият поглед към птицата носи смисъл."},{"text":"Случаен реквизит, добавен за атмосфера","why":"Когато образът получава повече внимание, отколкото сюжетът изисква, той не е случаен."}],"answer":0,"explain":"Визуалната метафора пренася смисъл от един образ към друг: затворената птица и героинята споделят една съдба. Дългият кадър е знак от режисьора, че образът носи повече от буквалното си значение.","more":"Ако по-късно героинята отвори клетката и пусне птицата, метафората се превръща в обещание: зрителят разбира, че и тя ще се освободи. Така метафората работи и като предзнаменование."},{"id":"studio.story.figures.c02","legacyId":"c1mv98ag","hall":"studio","domain":"story","topic":"story.figures","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Ако в първото действие на стената виси пушка, по-късно тя трябва да гръмне. Как се нарича принципът?","options":[{"text":"Поетична справедливост (Poetic justice)","why":"Поетичната справедливост наказва злото; принципът тук е, че подчертаният детайл трябва да се използва."},{"text":"Лайтмотив (Leitmotif)","why":"Лайтмотивът е повтарящ се мотив, свързан с герой или идея; тук е детайл, който по-късно „стреля“."},{"text":"Засаждане и изплащане (Setup and payoff)","why":""},{"text":"Ефект на Кулешов (Kuleshov effect)","why":"Ефектът на Кулешов е за смисъла от съседни кадри, а не за детайл, засаден по-рано."}],"answer":2,"explain":"Антон Чехов съветва: ако показваш пушка, тя трябва да стреля — иначе не я показвай. Подчертаният детайл е обещание към зрителя и ако не бъде изпълнено, вниманието му е похабено.","more":"Класически пример е „Завръщане в бъдещето“: в началото жена дава на Марти листовка за часовниковата кула, ударена от мълния. По-късно точно тази мълния връща Марти в неговото време."},{"id":"studio.story.figures.c03","legacyId":"c1h6fq25","hall":"studio","domain":"story","topic":"story.figures","topic2":"edit.sound","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Всеки път, когато акулата приближава в „Челюсти“, звучи един и същ мотив от две ноти. Как се нарича това?","options":[{"text":"Звуков контрапункт (Contrapuntal sound)","why":"Контрапунктът противоречи на образа, а мотивът в „Челюсти“ го подсилва."},{"text":"Диегетичен звук (Diegetic sound)","why":"Героите не чуват мотива — той е филмова музика, недиегетична."},{"text":"Лайтмотив (Leitmotif)","why":""},{"text":"Шумове (Foley)","why":"Шумовете са звуци от действия; тук е музикален мотив."}],"answer":2,"explain":"Повтаряният мотив се свързва в съзнанието на зрителя с акулата. След няколко повторения само музиката стига, за да почувстваме опасността, без да видим акулата.","more":"Музиката е на Джон Уилямс. Механичната акула често се разваляла по време на снимките, затова Спилбърг я показва рядко — и мотивът от две ноти я замества."},{"id":"studio.story.figures.c04","legacyId":"cay80k9","hall":"studio","domain":"story","topic":"story.figures","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Вместо цялата армия виждаме само ботушите на войниците, които маршируват в крак. Какъв е похватът?","options":[{"text":"Визуална метафора (Visual metaphor)","why":"Метафората заменя едно нещо с друго; тук частта (ботушите) стои вместо цялото (армията)."},{"text":"Предзнаменование (Foreshadowing)","why":"Предзнаменованието подсказва бъдещо събитие; тук похватът е част вместо цяло."},{"text":"Лайтмотив (Leitmotif)","why":"Лайтмотивът е повтарящ се мотив; тук е един образ, който представя цялото."},{"text":"Синекдоха (Synecdoche)","why":""}],"answer":3,"explain":"Подбраната част казва повече от цялото: без лица войниците стават безлични, а ритъмът на ботушите внушава механична, неумолима сила.","more":"Подобни кадри има в „Броненосецът „Потьомкин““ (1925) на Сергей Айзенщайн: в сцената на Одеското стълбище войниците често са показани само като редица ботуши и пушки, без лица."},{"id":"studio.story.figures.c05","legacyId":"c1k98thm","hall":"studio","domain":"story","topic":"story.figures","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","prompt":"Измисли детайл, който да „засадиш“ в началото на кратък филм и да „изплатиш“ в края.","checklist":["Детайлът е показан рано и ясно","В началото изглежда маловажен","В края променя или решава нещо"],"checklistNeed":2,"model":"Например: в началото героят не може да отвори заяждащото чекмедже и се ядосва. В края, в бързината, точно това чекмедже се отваря — вътре е ключът. Детайлът е показан ясно, но изглежда маловажен, и в края придобива смисъл.","more":"Провери засаждането с приятел: покажи му само началото и го попитай какво е запомнил. Ако не помни детайла, той е твърде скрит; ако веднага се досеща за края, е твърде явен."},{"id":"studio.anim.phases.c05","legacyId":"c1wq69pr","hall":"studio","domain":"anim","topic":"anim.phases","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди етапите на рисуваната сцена от първата скица до цвета.","sequence":["Ключова фаза (Key pose)","Breakdown","Pencil test","Изчистване (Clean-up)","Оцветяване"],"explain":"Първо позите и пътят между тях, после проверка на движението, едва накрая чистите линии и цветът — поправките са най-евтини в началото.","more":"Преди компютрите цветът се слагал на ръка: рисунките се пренасяли върху прозрачно фолио и се оцветявали откъм гърба. В Disney с това се занимавал цял отдел."},{"id":"studio.anim.phases.c06","legacyId":"cee2t20","hall":"studio","domain":"anim","topic":"anim.phases","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо аниматорът прави pencil test, преди да изчисти рисунките?","options":[{"text":"За да провери дали героят е в модел във всеки кадър","why":"Моделът се изправя при изчистването; pencil test проверява движението и timing-а."},{"text":"За да провери движението, докато поправките са евтини","why":""},{"text":"За да покаже на клиента как ще изглеждат цветовете","why":"На молив цвят няма — тестът е за движението."},{"text":"За да запише гласа на актьора върху движението","why":"Гласът се записва преди анимацията; тестът проверява движението по него."}],"answer":1,"explain":"Изчистването отнема много повече време от грубата рисунка. Ако движението не работи, по-добре е да се види още на грубите скици, когато поправката е бърза, а не след като всяка фаза е изчистена.","more":"В студиото на Disney стаята, в която се гледали и обсъждали тестовете на грубите рисунки, наричали sweatbox („потилня“): отначало в нея нямало климатик и аниматорите се потели, докато слушали критиките."},{"id":"studio.anim.phases.c07","legacyId":"c11cysgw","hall":"studio","domain":"anim","topic":"anim.phases","level":10,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кой етап превръща грубите скици в чисти линии точно по модела на героя?","options":[{"text":"Breakdown","why":"Breakdown определя пътя и характера на движението, а не чистотата на линията."},{"text":"Pencil test","why":"Pencil test проверява движението на грубите рисунки."},{"text":"Междинни фази (Inbetweens)","why":"Междинните фази попълват движението между ключовите; чистата линия идва при изчистването."},{"text":"Изчистване (Clean-up)","why":""}],"answer":3,"explain":"Грубата анимация търси движението, затова линиите са свободни, а пропорциите „плават“. При изчистването всяка фаза се прерисува по модела на героя с еднаква линия, така че той да не се мени от кадър на кадър.","more":"Честа грешка: при изчистването линията става твърда и движението губи живота си. Изчиствай, като гледаш грубата фаза под новия слой, и пусни теста отново, за да се увериш, че енергията е запазена."},{"id":"studio.anim.lipsync.c06","legacyId":"c1n0pqdy","hall":"studio","domain":"anim","topic":"anim.lipsync","level":11,"subjects":["rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо аниматорът слага мигане точно когато героят сменя мисълта си?","options":[{"text":"Мигането скрива грешка в синхрона на устните","why":"Мигането не е лепенка — то е актьорски избор."},{"text":"Мигането отбелязва новата мисъл и героят изглежда жив","why":""},{"text":"Хората мигат на точно определени интервали от време","why":"Хората мигат неравномерно; аниматорът поставя мигането там, където носи смисъл."},{"text":"Затворените очи спестяват няколко рисунки на погледа","why":"Мигането иска рисунки, а не ги спестява; смисълът му е в мисълта."}],"answer":1,"explain":"Мигането и движението на очите са прозорец към мисълта. Поставено при смяната ѝ, мигането работи като запетая между две идеи и показва, че героят обработва нещо, а не просто гледа.","more":"Монтажистът Уолтър Мърч пише в книгата си „In the Blink of an Eye“ (1992), че мигаме, за да разделим мислите си, затова добрият монтажен срез често пада там, където героят би мигнал."},{"id":"studio.anim.3d.c01","legacyId":"c1dgt9il","hall":"studio","domain":"anim","topic":"anim.3d","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Как най-бързо ще моделираш ваза с кръгло сечение?","options":[{"text":"Екструдираш кръг нагоре на няколко стъпки","why":"Може, но е по-бавно: всяка стъпка се мащабира на ръка, а ротацията дава гладка форма наведнъж."},{"text":"Изваждаш една сфера от друга","why":"Булевото изваждане дава кухина, но не и профила на вазата."},{"text":"Местиш точките на една равнина една по една","why":"Ръчното местене на точки е най-бавният начин за симетрична форма."},{"text":"Завърташ половин профил около оста","why":""}],"answer":3,"explain":"Вазата е ротационно тяло (Lathe): всяко хоризонтално сечение е кръг, а целият ѝ характер е в профила. Затова е достатъчен един профил — програмата строи цялата повърхност наведнъж, а промяната на профила веднага сменя цялата ваза.","more":"Lathe означава „струг“: профилът се върти около ос като дърво в струг. В 3ds Max модификаторът се казва Lathe, а в Blender същото прави модификаторът Screw — опитай с профила на шахматна пешка."},{"id":"studio.anim.3d.c02","legacyId":"cp81s4y","hall":"studio","domain":"anim","topic":"anim.3d","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Как правиш отвор за прозорец в 3D стена с помощта на друг обект?","options":[{"text":"Екструдираш стената навътре на мястото на прозореца","why":"Екструзията издърпва повърхността, но не изрязва отвор с формата на друг обект."},{"text":"Завърташ профила на рамката около вертикална ос","why":"Ротацията създава тяло от профил, а не отвор в стена."},{"text":"Разгъваш UV картата и изрязваш прозореца в нея","why":"UV картата е за текстурата; дупка в нея не прави отвор в модела."},{"text":"Изваждаш кутия от стената с булева операция","why":""}],"answer":3,"explain":"Кутията работи като резец: булевото изваждане маха от стената целия обем, който тя заема. Докато не приложиш операцията, можеш да местиш кутията и отворът се мести с нея.","more":"Името идва от Джордж Бул — английски математик от XIX век, създал алгебрата на логиката с „и“, „или“ и „не“. Сечението, обединението и изваждането са същите идеи, приложени към обеми."},{"id":"studio.anim.3d.c03","legacyId":"cpwrf5c","hall":"studio","domain":"anim","topic":"anim.3d","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо преди рисуването на текстура моделът се разгъва (UV unwrapping)?","options":[{"text":"За да стане моделът по-лек и с по-малко полигони","why":"Разгъването не намалява полигоните; то подготвя място за текстурата."},{"text":"За да има плоска карта, по която текстурата ляга без разтягане","why":""},{"text":"За да може моделът после да получи Rig и да се анимира","why":"Изграждането на Rig е отделен етап и не изисква UV карта."},{"text":"За да се изчисли правилно осветлението на сцената","why":"Осветлението се изчислява от геометрията и материалите, а не от UV разгъването."}],"answer":1,"explain":"Като при разгъването на картонена кутия: всяка част от повърхността получава място в плоското изображение. Така програмата знае кой пиксел от текстурата върху коя точка от модела да постави.","more":"U и V са просто имената на осите на плоската карта — X, Y и Z вече са заети от 3D пространството. Шевовете (seams) скривай там, където не се виждат: под мишниците, отвътре на ръкава, отдолу на предмета."},{"id":"studio.anim.3d.c04","legacyId":"c1iemp0p","hall":"studio","domain":"anim","topic":"anim.3d","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди етапите на 3D продукцията в класическия им ред.","sequence":["Моделиране","UV разгъване (UV unwrapping)","Текстури и материали","Rig","Анимация","Осветление","Рендиране (Rendering)"],"explain":"Първо формата, после повърхността, после контролерите и движението, накрая светлината и изчисляването на кадрите. Всеки етап стъпва на предишния: текстурата се рисува върху готовата UV карта, а анимацията се прави с готовия Rig.","more":"В голямо студио текстурите и Rig често се правят едновременно от различни хора, защото и двата зависят само от готовия модел. След рендирането обикновено идва compositing: отделните слоеве се събират в крайния кадър."},{"id":"studio.anim.3d.c05","legacyId":"cudh481","hall":"studio","domain":"anim","topic":"anim.3d","topic2":"anim.tech","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи вида 3D анимация с описанието.","pairs":[["Анимация с ключови кадри","Аниматорът задава позите, а компютърът изчислява междинните"],["Улавяне на движение (Motion capture)","Движението на актьор с маркери се пренася върху героя"],["Процедурна анимация (Procedural animation)","Правила и симулации движат плат, коса, частици, тълпи"]],"explain":"Ключовите кадри дават пълен контрол и стил, улавянето на движение — реализма на истински актьор, а процедурната анимация — мащаб: хиляди обекти без ръчна работа. ДОС по професията изисква да знаеш предимствата на трите вида.","more":"В големите продукции трите се смесват: Голъм във „Властелинът на пръстените“ е изигран от Анди Съркис с улавяне на движение, а аниматорите доработват лицето му ръчно с ключови кадри."},{"id":"studio.anim.3d.c06","legacyId":"conjqqr","hall":"studio","domain":"anim","topic":"anim.3d","level":11,"subjects":["anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кога ще избереш NURBS вместо полигонален модел?","options":[{"text":"За модел във видеоигра с възможно най-малко полигони","why":"Игрите използват полигони — NURBS се превръщат в полигони преди експорт."},{"text":"За груб скален терен с много остри неравности","why":"Грубите неравни форми се моделират по-лесно с полигони или скулптиране."},{"text":"За идеално гладки, точни повърхности — кола, продукт","why":""},{"text":"За герой, който ще се анимира с лицеви изражения","why":"Героите за анимация обикновено са полигонални — по-гъвкави са за деформация."}],"answer":2,"explain":"NURBS описват повърхността с математически криви и остават гладки при всяко увеличение — точност, нужна при производството на коли и уреди. Полигоните пък са по-гъвкави за деформиране на герои и по-леки за игри.","more":"В Maya можеш да моделираш с NURBS и после да превърнеш модела в полигони. Програмите за рендиране обикновено също разбиват гладката повърхност на много малки полигони, преди да я изчислят."},{"id":"studio.anim.fx.c01","legacyId":"caspi8x","hall":"studio","domain":"anim","topic":"anim.fx","level":11,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Как се движи пламъкът в рисуваната анимация?","options":[{"text":"Езиците се издигат и се откъсват нагоре в еднакъв ритъм","why":"Еднаквият ритъм прави огъня механичен — цикълът трябва да е неравен."},{"text":"Пламъкът се разширява във всички посоки като взрив","why":"Взривът се разширява; пламъкът се издига и изтънява нагоре."},{"text":"Пламъкът се люлее наляво-надясно, без да се откъсва","why":"Пламъкът не само се люлее — езиците му се откъсват и изчезват нагоре."},{"text":"Езиците се издигат, изтъняват и се откъсват нагоре неравно","why":""}],"answer":3,"explain":"Огънят е цикъл, но нерегулярен: ако всички езици се движат еднакво, пламъкът изглежда механичен. Причината е физична: горещият въздух е по-лек и тегли пламъка нагоре, а основата остава почти на място.","more":"Цикълът спестява работа: няколко рисунки, пуснати в повторение, горят през цялата сцена. Провери шева — последната рисунка трябва да води плавно към първата, иначе огънят „подскача“."},{"id":"studio.anim.fx.c02","legacyId":"cefgtau","hall":"studio","domain":"anim","topic":"anim.fx","level":11,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво става с дима, докато се издига?","options":[{"text":"Свива се, ускорява се и става по-плътен нагоре","why":"Димът се разсейва — обемът расте, а плътността намалява."},{"text":"Разширява се, забавя се и изтънява, докато изчезне","why":""},{"text":"Разширява се, но се ускорява и става по-тъмен","why":"Разширяването е вярно, но димът се забавя и изсветлява, докато се разсее."},{"text":"Остава с еднаква форма и скорост до самия край","why":"Еднаквата форма и скорост изглеждат изкуствено — димът се променя постоянно."}],"answer":1,"explain":"Това е разсейване (Dissipation): едно и също количество дим заема все повече въздух, затова обемът расте, а плътността пада. Димът изстива, губи силата, която го е издигала, и се забавя, докато се слее с въздуха.","more":"Референция за минута: снимай с телефона пара от чайник срещу тъмен фон на забавен каданс и я пусни кадър по кадър — ще видиш как едрите форми се разпадат на все по-малки."},{"id":"studio.anim.fx.c03","legacyId":"csm6hcp","hall":"studio","domain":"anim","topic":"anim.fx","topic2":"anim.principles","level":11,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Капка пада във вода. Кой принцип на анимацията е най-важен за пръските?","options":[{"text":"Подготвително движение: водата се свива, преди да пръсне","why":"Подготвителното движение е за действията на героите; пръските се подчиняват на гравитацията и летят по дъги."},{"text":"Сценичност: пръските насочват окото към центъра","why":"Сценичността е за ясното представяне на действието; тук важна е траекторията."},{"text":"Привлекателност: пръските трябва да са красиви","why":"Красотата идва от вярното движение — без дъги пръските изглеждат изкуствено."},{"text":"Дъги: всяка капка лети нагоре и пада по крива","why":""}],"answer":3,"explain":"Всичко, хвърлено нагоре, лети по парабола: капката се забавя към върха на дъгата и се ускорява надолу. Пръски, които летят по прави линии или с равна скорост, губят усещането за тежест.","more":"Пусни капка оцветена вода в чаша и я снимай с телефона на забавен каданс: след короната от центъра изскача стълбче вода, което понякога откъсва капка нагоре. Добави го и в анимацията си."},{"id":"studio.anim.fx.c04","legacyId":"c1yu0wyi","hall":"studio","domain":"anim","topic":"anim.fx","topic2":"anim.3d","level":11,"subjects":["anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Искаш 3D дъжд от хиляди капки. Какво използваш?","options":[{"text":"Система от частици (Particle system)","why":""},{"text":"Изрезкова анимация (Cut-out animation)","why":"Изрезковата анимация движи готови части на 2D герой, а не хиляди капки."},{"text":"Rotoscoping","why":"При rotoscoping се прерисува заснет материал кадър по кадър — непосилно за хиляди капки."},{"text":"Ръчни ключове за всяка капка (Keyframes)","why":"Никой не анимира хиляди капки поотделно; частиците се движат по правила."}],"answer":0,"explain":"Системата от частици работи с правила, а не с отделни ключове: задаваш откъде се раждат капките, колко са в секунда, колко бързо падат и колко живеят. Промениш ли едно число, целият дъжд се променя наведнъж.","more":"Дъждът става убедителен с вторичните ефекти: пръски при удара в земята, кръгове в локвите, по-тъмни мокри повърхности. Самите капки изглеждат като удължени черти, защото падат бързо."},{"id":"studio.prod.crew.c05","legacyId":"cz86bdk","hall":"studio","domain":"prod","topic":"prod.crew","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy","fixes":["B029"]},"kind":"card","format":"choice","prompt":"Кой подрежда заснетия материал, избира дублите и определя ритъма на филма?","options":[{"text":"Колористът (Colourist)","why":"Колористът работи върху цвета на вече монтирания филм."},{"text":"Монтажистът (Editor)","why":""},{"text":"Асистент-режисьорът (Assistant director)","why":"Асистент-режисьорът работи на снимачната площадка, а не в монтажа."},{"text":"Звукорежисьорът (Sound designer)","why":"Звукът се прави върху готовия монтаж; ритъма на кадрите определя монтажистът с режисьора."}],"answer":1,"explain":"Монтажът е последното пренаписване на филма: от едни и същи дубли могат да се сглобят сцени с различен ритъм и смисъл. Монтажистът решава заедно с режисьора, а бележките на script supervisor му казват кой дубъл е харесан.","more":"Телма Шунмейкър монтира филмите на Мартин Скорсезе от десетилетия и има три „Оскара“ за монтаж — пример колко дълго може да трае тандемът режисьор–монтажист."},{"id":"studio.prod.plan.c09","legacyId":"c6glm6j","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"В Day Out of Days до името на актьор в понеделник пише SW, а в петък — WF. Какво означава това?","options":[{"text":"Снима в понеделник и в петък, но не и между тях","why":"SW и WF отбелязват началото и края на работния период, а не отделни дни."},{"text":"Започва работа в понеделник и приключва в петък","why":""},{"text":"Почива в понеделник и в петък, а снима между тях","why":"Обратното: SW е първият, а WF — последният снимачен ден."},{"text":"Сменя ролята си в понеделник и я връща в петък","why":"Кодовете не са за ролята, а за снимачните дни на актьора."}],"answer":1,"explain":"SW (Start Work) отбелязва първия работен ден на актьора, а WF (Work Finish) — последния. От тези кодове продуцентът вижда колко дни ще плаща на всеки и в кои дни му трябва; по тях се правят договорите и бюджетът.","more":"Day Out of Days рядко се пише на ръка: програмите за планиране го генерират от stripboard. Щом преместиш лента в друг ден, кодовете на актьорите се променят сами."},{"id":"studio.prod.plan.c10","legacyId":"cwr4n5e","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво означава H (Hold) в Day Out of Days?","options":[{"text":"Не снима, но е задържан между снимачните дни и му се плаща","why":""},{"text":"Освободен е от филма и договорът му вече е приключил","why":"Освобождаването е краят на работата (WF); H е задържане между снимачни дни."},{"text":"Снима сцени, в които героят му е в главната роля","why":"Кодът не е за ролята, а за статуса на актьора в този ден."},{"text":"Снима нощна сцена и почива през следващия ден","why":"H не е свързан с часа на снимките — означава задържан, но не снима."}],"answer":0,"explain":"Актьорът е задържан, защото след паузата има още сцени и не може да поеме друга работа. Тези дни се плащат, затова асистент-режисьорът групира сцените му така, че задържанията да са малко.","more":"Ако паузата между снимачните дни на актьор е дълга, понякога е по-евтино той да бъде освободен и повикан отново (drop/pickup), вместо да бъде задържан."},{"id":"studio.prod.set.c06","legacyId":"czqsc3x","hall":"studio","domain":"prod","topic":"prod.set","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо актьорът трябва да спре точно на лентата на пода (Mark)?","options":[{"text":"Там са нагласени фокусът и светлината","why":""},{"text":"Там микрофонът на бума го чува най-ясно","why":"Бумът следва актьора; маркировката е заради фокуса и светлината."},{"text":"Там не се виждат кабелите на камерата","why":"Кабелите се скриват отделно; маркировката е за фокуса и светлината."},{"text":"Там партньорът му знае къде да гледа","why":"Погледите се репетират, но маркировката пази фокуса и светлината."}],"answer":0,"explain":"Фокусът и светлината се нагласяват на репетицията точно за тази позиция. Половин крачка встрани и лицето излиза от фокус или от светлината — и дубълът е загубен.","more":"Опитният актьор стига до марката, без да гледа надолу: на репетицията запомня крачките. Ако краката влизат в кадъра, марката се прави съвсем малка или се маха преди дубъла."},{"id":"studio.prod.set.c07","legacyId":"c1kd5b61","hall":"studio","domain":"prod","topic":"prod.set","topic2":"prod.sound","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"За какво служи репетицията с камера преди дубъла?","options":[{"text":"Актьорите учат текста наизуст за последен път","why":"Текстът се учи преди площадката; репетицията е за движение, камера и звук."},{"text":"Уточняват се движението, фокусът и нивата на звука","why":""},{"text":"Снимат се кадри зад кадър за рекламата на филма","why":"Кадрите зад кадър са странична задача; репетицията е за техниката и актьорите."},{"text":"Сменят се костюмите и гримът на актьорите","why":"Костюмите и гримът са готови преди репетицията."}],"answer":1,"explain":"На репетицията се проверява всичко, което ще се движи в дубъла: актьорите, камерата и микрофонът. Tomaric описва как тогава бум операторът намира позицията си, а тонрежисьорът нагласява нивата според гласовете на актьорите.","more":"На училищен филм направи поне една репетиция с включени камера и рекордер, после изгледай записа със слушалки. Повечето проблеми с фокуса и звука се виждат още тогава."},{"id":"studio.prod.sound.c01","legacyId":"cdyyp3","hall":"studio","domain":"prod","topic":"prod.sound","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кой микрофон е основният избор за диалог на снимачната площадка?","options":[{"text":"Петличен микрофон, скрит в дрехите на актьора","why":"Петличките са резервен вариант, когато бумът не може — дрехите шумолят."},{"text":"Насочен микрофон на бум над актьорите","why":""},{"text":"Вграденият микрофон на самата камера","why":"Камерата е далеч от актьорите и записва шума наоколо."},{"text":"Студиен микрофон на стойка пред актьорите","why":"Студийният микрофон на стойка ще се вижда в кадъра."}],"answer":1,"explain":"Tomaric: най-добрият начин за диалог е насочен микрофон на бум — изолира гласа и потиска околния шум; петличките са за случаите, когато няма друг начин. Бумът дава и естествено звучене, което отговаря на размера на кадъра.","more":"В малки стаи с ехо тонрежисьорите често предпочитат по-къс микрофон (хиперкардиоиден) пред дългия насочен, защото късият хваща по-малко отражения от стените."},{"id":"studio.prod.sound.c02","legacyId":"c4rb0vm","hall":"studio","domain":"prod","topic":"prod.sound","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Двама герои говорят в движеща се кола, а камерата отпред хваща цялото купе. Как записвате диалога?","options":[{"text":"С бум оператор на задната седалка с къс прът","why":"Камерата вижда задната седалка — бум операторът ще влезе в кадъра, а прътът ще пречи на актьорите."},{"text":"С вградения микрофон на камера, закрепена отвън","why":"Камерата отвън записва двигателя и вятъра, а не гласовете."},{"text":"Целият диалог се записва наново в студио после","why":"Постсинхронът е скъп и губи живия звук — първо се опитва запис на място."},{"text":"С петлични микрофони над сенниците пред актьорите","why":""}],"answer":3,"explain":"В тясното купе няма място за прът, а камерата вижда всичко зад актьорите. Tomaric предлага петлички над сенниците, свързани с отделен рекордер. Така микрофоните са близо до устата и гласът е по-силен от шума на пътя.","more":"За училищен филм е по-безопасно колата да не се движи: снимай я паркирана на тиха улица, а движението „изиграй“ с леко клатене и светлини, които минават през прозорците."},{"id":"studio.prod.sound.c03","legacyId":"carm61a","hall":"studio","domain":"prod","topic":"prod.sound","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кой е недостатъкът на петличния микрофон?","options":[{"text":"Дрехите шумолят, а шумовете около актьора се губят","why":""},{"text":"Записва гласа по-слабо от микрофона на камерата","why":"Петличката е близо до устата и записва гласа силно; проблемът е шумоленето."},{"text":"Вижда се в кадъра, колкото и добре да се крие","why":"Добре скрита, петличката не се вижда; проблемът е звуков."},{"text":"Работи с кабел и пречи на движението на актьора","why":"Има безжични петлички; недостатъкът е шумоленето на дрехите."}],"answer":0,"explain":"Петличката е притисната до тялото: хваща всяко търкане на плата и почти нищо от звуците наоколо — стъпки, докосване на предмети. Затова след петличките често трябват повече шумове (Foley) в постпродукцията.","more":"За да не шумоли, петличката се закрепва с лепенка така, че платът да не се движи по нея. Памучните дрехи шумолят по-малко от синтетичните — помисли за това още при избора на костюм."},{"id":"studio.prod.sound.c04","legacyId":"ck9tbfs","hall":"studio","domain":"prod","topic":"prod.sound","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Как бум операторът разбира колко ниско може да свали микрофона?","options":[{"text":"Държи микрофона колкото може по-високо, за да е сигурно","why":"Твърде високо записва стаята, а не гласа — целта е точно над кадъра."},{"text":"Пита актьорите докъде микрофонът им пречи да играят","why":"Актьорите не виждат кадъра; границата я знае операторът."},{"text":"Спуска микрофона, докато влезе в кадъра, и го вдига малко","why":""},{"text":"Гледа в сценария колко широк е планът на сцената","why":"Сценарият не казва размера на кадъра — питаш оператора или гледаш монитора."}],"answer":2,"explain":"Tomaric: така той научава горния ръб на кадъра и държи микрофона точно над него, насочен към говорещия. Колкото по-близо е микрофонът до устата, толкова по-силен е гласът спрямо шума и ехото на стаята.","more":"Внимавай и за сенки: бумът под лампа може да хвърли сянка върху стената или лицето, дори да е извън кадъра. Тогава бум операторът сменя ъгъла или застава от другата страна."},{"id":"studio.prod.sound.c05","legacyId":"cy0hjk0","hall":"studio","domain":"prod","topic":"prod.sound","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"При силните реплики звукът в записа „пращи“ и се изкривява. Какво се е случило?","options":[{"text":"Нивото е било над максимума и сигналът е претоварен","why":""},{"text":"Нивото е било твърде ниско и после шумът е усилен","why":"Ниското ниво дава шум, но не и пращене при силните реплики."},{"text":"Микрофонът е бил твърде далеч и е записал ехото","why":"Далечният микрофон дава кух звук и ехо, а не изкривяване."},{"text":"Липсва записан фон на помещението под репликите","why":"Липсата на фон дава дупки в тишината, а не пращене."}],"answer":0,"explain":"Записът има таван: щом сигналът го стигне, върховете на звуковата вълна се „отрязват“ и тази част от звука изчезва безвъзвратно. Това претоварване (Clipping) не се поправя после, затова нивата се нагласяват на репетицията с резерв.","more":"Много рекордери могат да записват паралелно втора, по-тиха резервна писта. Ако основната претовари при вик, монтажистът взима същия момент от резервната."},{"id":"studio.prod.sound.c06","legacyId":"c1oewz3k","hall":"studio","domain":"prod","topic":"prod.sound","topic2":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Намерихте идеалната къща за снимки, но тя е до магистрала. Защо това е проблем за бюджета?","options":[{"text":"Шумът ще наложи скъп постсинхрон на диалога","why":""},{"text":"Колите ще се виждат в кадъра на всеки план","why":"Кадърът може да се подреди без магистралата; шумът обаче се чува навсякъде."},{"text":"Трафикът ще пречи на екипа да паркира","why":"Паркирането е организационен въпрос; скъпото е презаписът на диалога."},{"text":"Шумът се маха лесно с филтър в монтажа","why":"Постоянният шум от трафика не се маха чисто — гласът се изкривява."}],"answer":0,"explain":"Постоянният шум от трафика е под всяка реплика и не може да се изчисти, без да пострада гласът. Tomaric описва точно такъв случай: красивата къща до магистралата излиза скъпо, защото диалогът трябва да се запише наново в студио — постсинхрон (ADR).","more":"На огледа затвори очи за минута и само слушай: магистрала, самолети, хладилник, климатик. Ела и в часа, в който ще снимате — шумът сутрин и вечер е различен."},{"id":"studio.hist.pioneer.c05","legacyId":"c1ppsnxq","hall":"studio","domain":"hist","topic":"hist.pioneer","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Коя е смятана за първата жена режисьор в историята на киното?","options":[{"text":"Аста Нилсен","why":"Аста Нилсен е датска звезда на нямото кино — актриса, а не режисьорка."},{"text":"Алис Ги","why":""},{"text":"Лоте Райнигер","why":"Лоте Райнигер е пионерка на анимацията, но започва по-късно — през 1910-те и 1920-те."},{"text":"Жермен Дюлак","why":"Жермен Дюлак режисира през 1910-те и 1920-те, след Алис Ги."}],"answer":1,"explain":"Алис Ги е секретарка на Леон Гомон и го убеждава да ѝ позволи да снима кратки сцени с измислена история. Така още в средата на 1890-те тя става режисьорка — години преди другите три да започнат в киното.","more":"В САЩ тя основава собствено студио, Solax, и окачва там табела „Бъди естествен“ (Be Natural) — съвет към актьорите. Документален филм със същото име (2018) връща забравеното ѝ име."},{"id":"studio.hist.pioneer.c06","legacyId":"c1vm2owb","hall":"studio","domain":"hist","topic":"hist.pioneer","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Какво означава „кино на атракциите“?","options":[{"text":"Ранните филми се прожектират в увеселителни паркове","why":"Филмите наистина се показват по панаири, но понятието е за това какво показват — зрелище, а не история."},{"text":"Ранните филми разказват дълги истории с паралелен монтаж","why":"Дългите истории с паралелен монтаж идват по-късно, с Грифит."},{"text":"Ранните филми са документални новини за събития","why":"Хрониките са част от програмата, но „атракция“ е всяко зрелище — трик, чудо, движение."},{"text":"Ранните филми показват зрелище, а не разказват история","why":""}],"answer":3,"explain":"Ранните филми често гледат право към публиката: фокусникът се покланя, влакът връхлита към камерата. Целта е удивлението в момента, а не разказът — той става водещ едва около 1906–1908 г.","more":"Терминът е на историка Том Гънинг (1986), който заема думата „атракция“ от Айзенщайн. Виж „Монтаж на атракционите (Montage of attractions)“ в темата „Монтажна теория“."},{"id":"studio.hist.pioneer.c07","legacyId":"cme9c0y","hall":"studio","domain":"hist","topic":"hist.pioneer","topic2":"hist.early","level":12,"subjects":["kino"],"sources":[],"review":{"status":"legacy","fixes":["P10"]},"kind":"card","format":"choice","prompt":"С какво братя Пате променят киното в началото на XX век?","options":[{"text":"Изобретяват първия звуков филм със записа на плоча","why":"Пате започват с продажба на фонографи, но звуковото кино идва чак в края на 1920-те."},{"text":"Правят първия анимационен филм в историята на киното","why":"Ранната анимация е свързана с Рейно, Блектън и Кол; „Фантасмагория“ (1908) на Кол е продукция на конкурента Gaumont."},{"text":"Превръщат го в световна индустрия под един покрив","why":""},{"text":"Основават студия в Холивуд преди американците","why":"Холивуд е създаден от американски компании; Пате доминират от Франция."}],"answer":2,"explain":"Пате контролират цялата верига: правят лента и камери, произвеждат филми, разпространяват ги и имат собствени кина. С клонове по целия свят преди Първата световна война те са най-голямата филмова компания.","more":"Пате създават и „Пате Журнал“ — кинопреглед с новини, прожектиран преди филмите. Десетилетия наред, преди телевизията, хората виждат световните събития първо в киното."},{"id":"studio.hist.bg.c04","legacyId":"c13uv1zp","hall":"studio","domain":"hist","topic":"hist.bg","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Кой е първият български звуков филм?","options":[{"text":"„Българан е галант“","why":"„Българан е галант“ (1915) е първият игрален филм — ням."},{"text":"„Бунтът на робите“","why":""},{"text":"„Под игото“","why":"Най-известната екранизация на „Под игото“ е от 1952 г. — почти двадесет години след първия звуков филм."},{"text":"„Юнак Марко“","why":"„Юнак Марко“ е анимационен филм на Тодор Динов от средата на 50-те — първият професионален български рисуван филм."}],"answer":1,"explain":"Премиерата е на 2 октомври 1933 г. С него българските зрители за пръв път чуват реч и музика от родно кино; Гендов е режисьор и сам играе Васил Левски.","more":"След натиск от турското посолство филмът е съкратен и спрян. Днес не е запазен — също като „Българан е галант“."},{"id":"studio.hist.bg.c05","legacyId":"c1ik9xb9","hall":"studio","domain":"hist","topic":"hist.bg","topic2":"hist.fest","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"С какво влиза в историята анимационният филм „Женитба“ на Слав Бакалов и Румен Петков?","options":[{"text":"Печели „Оскар“ за късометражен анимационен филм","why":"„Женитба“ печели в Кан, а не „Оскар“."},{"text":"Печели главната награда „Кристал“ на фестивала в Анси","why":"Анси е най-важният анимационен фестивал, но „Женитба“ печели „Златна палма“ в Кан."},{"text":"Печели „Златна палма“ за късометражен филм в Кан","why":""},{"text":"Става първият български пълнометражен анимационен филм","why":"„Женитба“ е късометражен филм."}],"answer":2,"explain":"Кан има отделен конкурс за късометражни филми със своя „Златна палма“. През 1985 г. тя отива при „Женитба“ — най-голямото признание за българската анимационна школа.","more":"По-късно Румен Петков работи в САЩ по сериали като „Лабораторията на Декстър“ и „Джони Браво“ и преподава в Калифорнийския институт за изкуства (CalArts)."},{"id":"studio.hist.bg.c06","legacyId":"cvpodp5","hall":"studio","domain":"hist","topic":"hist.bg","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Подреди българските заглавия по времето на създаването им.","sequence":["„Българан е галант“","„Бунтът на робите“","„Юнак Марко“","„Женитба“"],"explain":"1915 — първият игрален филм, още ням; 1933 — първият звуков филм; средата на 50-те — първият професионален рисуван филм; 1985 — „Златна палма“ в Кан за късометражна анимация.","more":"Направи времева линия на българското кино и анимация: за всяко десетилетие избери по едно заглавие и намери кадър от него. Така ще видиш как се сменят техниката и стилът."},{"id":"studio.hist.fest.c01","legacyId":"c376927","hall":"studio","domain":"hist","topic":"hist.fest","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи фестивала с главната му награда.","pairs":[["Кан","Златна палма"],["Венеция","Златен лъв"],["Берлинале","Златна мечка"],["Анси","Кристал"]],"explain":"Наградите носят символите на своите градове: палмата идва от герба на Кан, крилатият лъв е знакът на свети Марк — покровителя на Венеция, а мечката е символът на Берлин. „Кристал“ е главната награда на Анси.","more":"Освен главния конкурс фестивалите имат и паралелни програми — в Кан например „Особен поглед“ (Un Certain Regard) за по-смели авторски филми."},{"id":"studio.hist.fest.c02","legacyId":"cz07p58","hall":"studio","domain":"hist","topic":"hist.fest","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy","fixes":["P11"]},"kind":"card","format":"choice","prompt":"Кой фестивал е най-важен за анимационното кино?","options":[{"text":"Венеция (Venice)","why":"Венеция е най-старият фестивал, но за игрално кино."},{"text":"Сънданс (Sundance)","why":"Сънданс е за независимо кино, главно игрално и документално."},{"text":"Кан (Cannes)","why":"Кан е най-престижният за игрално кино; за анимация водещ е Анси."},{"text":"Анси (Annecy)","why":""}],"answer":3,"explain":"Анси е изцяло посветен на анимацията: в програмата има пълнометражни, късометражни, телевизионни и поръчкови филми, а до него работи пазарът MIFA, където студията търсят проекти и хора.","more":"В Анси има отделен конкурс за дипломни филми на студенти — хубава цел, когато след време направиш свой филм в университета."},{"id":"studio.hist.fest.c03","legacyId":"c8xlfc8","hall":"studio","domain":"hist","topic":"hist.fest","level":12,"subjects":["kino","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо „Оскар“ не е фестивал?","options":[{"text":"Провежда се в Европа, а фестивалите са в Америка","why":"„Оскарите“ са в Лос Анджелис, а фестивали има навсякъде по света."},{"text":"Това е церемония с награди, без фестивална програма","why":""},{"text":"Награждава американски филми, но не и чужди","why":"„Оскар“ има и категория за международен пълнометражен филм."},{"text":"Журито гледа филмите тайно, без публика","why":"Няма жури — гласуват членовете на академията."}],"answer":1,"explain":"Фестивалът събира на едно място прожекции, публика, конкурс и жури. При „Оскарите“ няма фестивална програма: членовете на академията гласуват за филми, които вече са излезли, а наградите се връчват на една вечер.","more":"Късометражен филм може да влезе в надпреварата и ако спечели награда на някой от фестивалите, които академията признава. Затова за много млади автори фестивалите са пътят и към „Оскар“."},{"id":"studio.anim.gags.c01","legacyId":"ccq94gl","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"match","prompt":"Свържи вида гаг с примера.","pairs":[["Визуален гаг","Героят минава през стената и оставя дупка с формата на тялото си"],["Гаг с предмет","Поръчаният по пощата магнит привлича върху Койота купчина метал"],["Сюрреалистичен гаг","Героят тича във въздуха над пропастта, докато не погледне надолу"],["Бърз гаг","Кратък удар, срязване към черно и веднага следващ опит"]],"explain":"Видовете често се застъпват — гагът с предмет е и визуален. Питай се откъде идва смехът: от образа, от предмета, от нарушената физика или от темпото.","more":"Упражнение: изгледай серия на „Том и Джери“ без звук и разпредели всеки гаг в една от четирите групи. Ще видиш кой вид преобладава и колко рядко е нужна дума."},{"id":"studio.anim.gags.c02","legacyId":"c1fnfk9t","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"order","prompt":"Героят забива пирон в стената. Подреди опитите така, че гагът да следва закона на трите.","sequence":["Удря си палеца с чука","Внимава повече, но пак си удря палеца, този път по-силно","Държи пирона с клещи и го забива точно, а стената се срутва цялата"],"explain":"Подготовка → ескалация → обрат. Вторият опит затвърждава модела („пак ще си удари палеца“), а третият го нарушава: всичко е направено правилно, но катастрофата идва отнякъде другаде.","more":"Структурата е по-стара от киното — три братя и три желания в приказките, троен ритъм във водевила. Нямото кино и аниматорите от Warner Bros. я превръщат в основен инструмент на визуалния гаг."},{"id":"studio.anim.gags.c03","legacyId":"czgy68o","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Койотът тича отвъд ръба на пропастта, спира във въздуха и пада едва когато погледне надолу. Кое „правило“ следва гагът?","options":[{"text":"Тялото пада едва когато осъзнае, че няма опора","why":""},{"text":"Тялото пада веднага, щом под краката му няма опора","why":"Това е истинската физика. В анимацията шегата е, че гравитацията „чака“."},{"text":"Тялото пада толкова по-бавно, колкото е по-тежко","why":"Обратното: тежките неща в анимацията падат рязко и силно — наковалнята е класика."},{"text":"Тялото пада, щом зрителят види пропастта","why":"Зрителят вижда пропастта отдавна; решаващо е, че героят разбира."}],"answer":0,"explain":"Анимационна физика (Cartoon physics): тяло, увиснало във въздуха, остава там, докато не осъзнае положението си — първото от „Законите на анимационното движение“ на Марк О’Донъл (1980). Гравитацията „чака“, защото шегата е в мига на осъзнаването.","more":"В игрите „coyote time“ е кратката пауза, в която героят още може да скочи, макар вече да е излязъл от ръба — кръстена на Койота. Така играта прощава закъснелия натиск на бутона."},{"id":"studio.anim.gags.c04","legacyId":"c1i93mev","hall":"studio","domain":"anim","topic":"anim.gags","topic2":"anim.timing","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Койотът вече стои във въздуха над пропастта. Как подреждаш падането, за да е най-смешно?","options":[{"text":"Пауза: поглежда надолу, после към зрителя и пада","why":""},{"text":"Пада веднага щом излезе от ръба, без никаква пауза","why":"Без пауза зрителят няма време да разбере положението и изненадата се губи."},{"text":"Пада бавно, на забавен каданс, през целия кадър","why":"Забавеният каданс разтяга падането, а смешното е рязката промяна след паузата."},{"text":"Стои неподвижен десет секунди и едва тогава пада","why":"Твърде дългото задържане убива ритъма: паузата трае колкото осъзнаването."}],"answer":0,"explain":"Смешното е в задържането (Hold) и в рязката промяна след него. Паузата дава време на зрителя да разбере положението, а погледът към камерата го прави съучастник. Решават кадрите, не физиката.","more":"В класическите филми с Койота падането рядко се вижда докрай: героят се смалява към дъното и след миг далеч долу се вдига малко облаче прах. Така ударът е смешен, без да е жесток."},{"id":"studio.anim.gags.c05","legacyId":"c1azgmpk","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Койотът поръчва по пощата продукти на ACME: магнит, ракета, катапулт. Какво е правилото на тези гагове с предмети?","options":[{"text":"Предметът накрая се обръща срещу собственика си","why":""},{"text":"Предметът се поврежда, преди да бъде използван","why":"Понякога предметът засича, но смешното идва, когато все пак проработи — срещу Койота."},{"text":"Предметът е по-малък, отколкото изглежда на снимката","why":"Размерът понякога е част от шегата, но не е правилото."},{"text":"Предметът работи, но Бързоходецът го открадва навреме","why":"Бързоходецът почти не пипа предметите — вредата идва от самия предмет."}],"answer":0,"explain":"Чък Джоунс записва правилата на поредицата в книгата си „Chuck Amuck“: нищо външно не вреди на Койота — само собствената му несръчност или провалът на продуктите на ACME. Затова в гага с предмет Койотът винаги сам си е виновен.","more":"Още две правила от списъка: гравитацията е най-големият враг на Койота, а провалите повече го унижават, отколкото го нараняват. Сценаристът Майкъл Малтийз обаче казва, че никога не е чувал за тях."},{"id":"studio.anim.gags.c06","legacyId":"c1tf9rnl","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Защо дете в Япония и дете в България се смеят на един и същ гаг от „Том и Джери“?","options":[{"text":"Смехът идва от образа и движението, а не от думите","why":""},{"text":"Филмите са дублирани на всички езици със същите шеги","why":"„Том и Джери“ почти няма диалог — няма какво да се дублира."},{"text":"Децата по целия свят имат еднакво чувство за хумор","why":"Хуморът зависи от културата; гагът минава границите, защото не опира до нея."},{"text":"Героите са животни и затова нямат култура и език","why":"Има анимации с животни, пълни с непреводими шеги. Важното е, че гагът не разчита на думи."}],"answer":0,"explain":"Гагът разчита на изразителни лица, на деформация на тялото — свиване и разтягане (Squash and Stretch) — и на точен Timing. Затова е универсален: смешката не зависи от превода.","more":"„Том и Джери“ е създаден от Уилям Хана и Джоузеф Барбера в студиото MGM. Поредицата печели седем награди „Оскар“ за анимационен късометражен филм."},{"id":"studio.anim.gags.c07","legacyId":"cwczbao","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"В студентски клип гагът с бананова кора се повтаря пет пъти по един и същ начин. Зрителите спират да се смеят след третия. Защо?","options":[{"text":"Кората трябва да е по-голяма при всяко следващо падане","why":"По-голям предмет е ескалация, но без обрат и тя омръзва."},{"text":"Падането трябва да е на забавен каданс, за да е смешно","why":"Забавеният каданс не носи изненада; смешното идва от нарушения модел."},{"text":"Пет повторения са твърде малко, за да се изгради ритъм","why":"Обратното: моделът се изгражда още на второто повторение."},{"text":"Моделът е ясен и повторенията без обрат не изненадват","why":""}],"answer":3,"explain":"Две повторения стигат, за да се изгради модел; третото трябва да го наруши. Четвърто и пето еднакво повторение стават скучни — освен ако самата скука не е шегата.","more":"Такава шега е гагът с греблата в „Семейство Симпсън“: героят настъпва гребло след гребло, смехът спира — и после се връща, защото упорството става абсурдно."},{"id":"studio.anim.gags.c08","legacyId":"cmhvvmm","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"diag","prompt":"Героят казва: „Само да не се подхлъзна на тази бананова кора!“ — и веднага се подхлъзва. Защо гагът не е смешен?","options":[{"text":"Липсва звуков ефект точно в момента на самото падане","why":"Звукът помага, но не спасява гаг, чиято развръзка е обявена предварително."},{"text":"Репликата предсказва развръзката и убива изненадата","why":""},{"text":"Падането е показано в общ план, а трябва да е в крупен","why":"Планът не е проблемът; проблемът е, че зрителят знае какво ще стане."},{"text":"Кората трябва да се появи по-късно в кадъра","why":"Моментът на появата не помага, щом героят вече е казал какво ще се случи."}],"answer":1,"explain":"Гагът живее от изненадата. Ако думите обявят развръзката, остава само потвърждение. Покажи кората, остави зрителя сам да се досети — и обърни очакването.","more":"Хичкок обяснява разликата с бомба под масата: ако зрителят я вижда, а героите не, кратката изненада (Surprise) се превръща в напрежение (Suspense). Добрият гаг може да използва и двете."},{"id":"studio.anim.gags.c09","legacyId":"c1fj5skb","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"scen","prompt":"Котката гони мишката до дупката в стената и два пъти се удря в стената. Кой трети опит е най-силният обрат?","options":[{"text":"Засилва се от другия край на стаята и се удря още по-силно","why":"Това е втора ескалация — същият модел, само по-болезнен. Зрителят го е предвидил."},{"text":"Пробива стената с бормашина и излиза в устата на куче","why":""},{"text":"Най-накрая хваща мишката, докато тя излиза от дупката","why":"Победата на котката разваля правилата на поредицата и не изненадва като шега."},{"text":"Обръща се към зрителя и казва, че вече ѝ е писнало","why":"Репликата заменя гага с думи и не нарушава модела."}],"answer":1,"explain":"Обратът пази очакването за провал, но го носи отнякъде, откъдето зрителят не гледа: котката решава проблема със стената — и попада в по-голям проблем.","more":"Схемата е честа в „Том и Джери“: Том преодолява препятствието, а наказанието идва от трети герой — например от булдога Спайк."},{"id":"studio.anim.gags.c10","legacyId":"c1yvair5","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Филмите с Койота и Бързоходеца почти нямат сюжет. Как са изградени?","options":[{"text":"Като една дълга гонитба в реално време, без срязвания","why":"Гонитбата е разбита на отделни опити, всеки със собствен край."},{"text":"Като верига от кратки гагове с удар и срязване","why":""},{"text":"Като три акта с подбудително събитие и кулминация","why":"Структурата не е класическата: всеки гаг е малък самостоятелен разказ."},{"text":"Като поредица от дълги диалози между двамата герои","why":"Бързоходецът казва само „бийп-бийп“, а Койотът „говори“ с табелки."}],"answer":1,"explain":"Това са бързи гагове (Blackout gags): опит, провал, срязване — и следващ опит. Темпото не спада, защото всеки гаг е кратък и завършен, а зрителят чака не сюжета, а следващата изненада.","more":"Името blackout идва от водевила: след ударната реплика светлините на сцената угасват веднага, за да завърши сценката на върха на смеха. В киното същото прави срязването или затъмнението (Fade)."},{"id":"studio.anim.gags.c11","legacyId":"c152tki4","hall":"studio","domain":"anim","topic":"anim.gags","topic2":"hist.silent","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"В „Стиймбоут Бил младши“ (1928) фасадата на къща пада върху героя, а той оцелява, защото стои точно там, където пада отвореният прозорец. Кой комик е в главната роля?","options":[{"text":"Чарли Чаплин","why":"Чаплин е Скитникът с бастуна; комедията му е по-сантиментална и рядко разчита на огромни механични гагове."},{"text":"Харолд Лойд","why":"Лойд е прочут с друг гаг на височина — виси от стрелките на часовник в „Safety Last!“ (1923)."},{"text":"Бъстър Кийтън","why":""},{"text":"Стан Лаурел","why":"Лаурел играе в дует с Оливър Харди; шегите им се раждат от отношенията между двамата."}],"answer":2,"explain":"Кийтън, „каменното лице“, изпълнява каскадите сам и показва гага в общ план, без срязване — така зрителят вярва, че опасността е истинска. Падащата фасада е един от най-известните гагове в историята на киното.","more":"Фасадата е истинска и тежи около два тона. Кийтън е правил по-малки варианти на същия гаг в късометражните „Back Stage“ (1919) и „One Week“ (1920)."},{"id":"studio.anim.gags.c12","legacyId":"c1cmjc33","hall":"studio","domain":"anim","topic":"anim.gags","topic2":"anim.principles","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"Героят се блъска в стена, сплесква се като палачинка и после изскача обратно във форма. Кой принцип на анимацията носи този гаг?","options":[{"text":"Свиване и разтягане","why":""},{"text":"Подготвително движение","why":"Подготвителното движение идва преди действието; тук смешното е деформацията при удара."},{"text":"Второстепенно действие","why":"Второстепенното действие подкрепя главното; тук самото тяло е шегата."},{"text":"Обемна рисунка","why":"Обемната рисунка гради формата в пространството, но не обяснява сплескването при удара."}],"answer":0,"explain":"Гаговете преувеличават свиването и разтягането (Squash and Stretch) до краен предел — тялото става палачинка или акордеон и после се връща. Важи правилото за обема: колкото се сплеска, толкова се разширява.","more":"Опитай: анимирай топка, която удря стена — веднъж реалистично и веднъж до „палачинка“. В комедията сплесканият герой често остава така за миг, преди да изскочи обратно: задържането (Hold) ни дава време да видим формата."},{"id":"studio.anim.gags.c13","legacyId":"c8rvkkf","hall":"studio","domain":"anim","topic":"anim.gags","topic2":"story.figures","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","prompt":"С какво законът на трите прилича на засаждането и изплащането (setup and payoff)?","options":[{"text":"И двете изискват точно три повторения на един детайл","why":"Засаденият детайл може да се появи само веднъж преди изплащането."},{"text":"И двете се използват само в комедията и анимацията","why":"Засаждането и изплащането работи във всеки жанр — и в трилъра, и в драмата."},{"text":"И двете заменят диалога с музика и звукови ефекти","why":"Нито едното не е свързано с музиката; и двете са структура на разказа."},{"text":"И двете градят очакване рано и го използват после","why":""}],"answer":3,"explain":"Подготовката и ескалацията „засаждат“ очакване, обратът го „изплаща“ — но наопаки: вместо очакваното идва изненада.","more":"Класически пример за засаждане и изплащане е „пушката на Чехов“: ако в първо действие на стената виси пушка, до края тя трябва да гръмне."},{"id":"studio.anim.gags.c14","legacyId":"ckcptt0","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"explain","prompt":"Обясни на съученик защо законът на трите работи. Дай свой пример, който не е от урока.","checklist":["Първият опит показва проблема и правилата","Вторият повтаря с по-голям залог и изгражда модел","Третият нарушава модела по неочакван начин","Повече еднакви повторения стават скучни","Собствен пример"],"checklistNeed":4,"model":"Мозъкът търси модели. Първият опит показва правилата, вторият ги потвърждава с по-голям залог и зрителят вече „знае“ какво ще стане. Третият път очакването се обръща — това е смехът. Ако повториш същото и четвърти, и пети път, моделът омръзва и смехът спира. Пример: героинята два пъти се опитва да прескочи локва и двата пъти джапа вътре. Третия път прескача успешно, усмихва се — и минаващ камион я облива.","more":"Нарисувай примера си като Storyboard от три кадъра и го покажи на приятел. Ако познае края, преди да види третия кадър, обратът е твърде предвидим."},{"id":"studio.anim.gags.c15","legacyId":"c54yi13","hall":"studio","domain":"anim","topic":"anim.gags","level":10,"subjects":["anim","rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","prompt":"Назови четирите основни вида гагове и дай по един пример за всеки.","checklist":["Визуален гаг — с пример","Гаг с предмет — с пример","Сюрреалистичен гаг — с пример","Бърз гаг — с пример"],"checklistNeed":3,"model":"Визуален гаг (Sight gag): героят минава през стената и оставя дупка с формата си. Гаг с предмет (Prop gag): продуктите на ACME се обръщат срещу Койота. Сюрреалистичен гаг (Surreal gag): тича във въздуха и пада, когато погледне надолу. Бърз гаг (Blackout gag): кратка шега, удар и срязване към черно.","more":"Повечето гагове съчетават няколко вида: наковалнята, която пада върху Койота, е гаг с предмет, а сплесканата му фигура след удара е визуален гаг."},{"id":"studio.lang.shots.c15","legacyId":"v-shots-a0","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-shots","prompt":"Колкото по-близък е планът, толкова по-силно…","options":[{"text":"зрителят усеща емоцията на героя","why":""},{"text":"зрителят разбира къде се намира героят","why":"Мястото се показва с широки планове; близкият план го изрязва."},{"text":"се чете движението на цялото тяло","why":"Цялото тяло се вижда в общ план; близкият план реже тялото."},{"text":"сцената изглежда епична и мащабна","why":"Мащабът идва от далечния план, в който човекът е малък в пространството."}],"answer":0,"explain":"Колкото по-голямо е лицето в кадъра, толкова по-малко друго остава за гледане и най-малкото трепване става видимо. Широките планове дават място, мащаб и контекст; изборът на плана е избор колко близо да е зрителят до героя.","more":"Чарли Чаплин казва: „Животът е трагедия, погледнат в крупен план, и комедия — в общ план.“ Отдалеч падането изглежда смешно, а отблизо се вижда болката."},{"id":"studio.lang.shots.c16","legacyId":"v-shots-a1","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-shots","prompt":"Каква е основната задача на детайла (Extreme close-up)?","options":[{"text":"Показва цялото лице, за да се види емоцията","why":"Цялото лице е крупен план; детайлът отива още по-близо — само очите, устните или предмет."},{"text":"Показва през очите на героя какво гледа той","why":"Това е кадър от гледна точка; детайлът може да е такъв, но задачата му е да изолира подробност."},{"text":"Установява мястото на действието преди сцената","why":"Мястото се установява с широк план; детайлът изрязва всичко около подробността."},{"text":"Изолира малка подробност и я прави главното събитие","why":""}],"answer":3,"explain":"Когато рамката изрязва всичко около подробността, зрителят няма избор къде да гледа. Затова и най-малкото — капка пот, треперещ пръст, дума в писмо — става важно.","more":"Детайлите често се снимат отделно, след основните кадри — понякога с ръцете на дубльор, защото лицето на актьора не се вижда."},{"id":"studio.lang.shots.c17","legacyId":"v-shots-b0","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-shots","prompt":"С какво се различават среден план (Medium shot) и близък план (Medium close-up)?","options":[{"text":"По обектива: средният е с широкоъгълен, близкият — с телеобектив","why":"Размерът на плана зависи от това докъде реже кадърът, а не от обектива — и двата се снимат с всякакъв обектив."},{"text":"По височината: средният е от нивото на очите, близкият — отдолу","why":"Височината на камерата е отделен избор; всеки план може да се снима от всяка височина."},{"text":"По мястото на рязане: средният реже на кръста, близкият — на гърдите","why":""},{"text":"По броя хора: средният побира двама, а близкият — един","why":"И двата плана може да са с един или с двама герои; различава ги линията на рязане."}],"answer":2,"explain":"Двата плана се различават само по линията на рязане, но тя сменя акцента: в средния план ръцете още говорят, а в близкия водещо става лицето. Колкото по-високо реже рамката, толкова повече внимание отива към очите.","more":"Запомни линиите на рязане по ризата: колан — среден план, джоб на гърдите — близък, яка — крупен."},{"id":"studio.lang.shots.c18","legacyId":"v-shots-b1","hall":"studio","domain":"lang","topic":"lang.shots","level":10,"subjects":["kino","oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-shots","prompt":"Избери три различни плана и за всеки опиши ситуация, в която той е най-добрият избор.","checklist":["Назован план и ситуация (1)","Назован план и ситуация (2)","Назован план и ситуация (3)","Обяснено защо точно този план"],"checklistNeed":3,"model":"Например: далечен план — героят е сам в пустинята и зрителят усеща самота и мащаб; среден план — двама спорят и жестикулират; крупен план — сълзата в момента на лошата новина.","more":"Направи го на практика: заснеми една и съща кратка случка — например някой отваря подарък — в три различни плана. Сравни кой план разказва най-добре изненадата."},{"id":"studio.lang.comp.c10","legacyId":"v-framing-a0","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-framing","prompt":"Камерата гледа покрай бедрото на прав герой към седналия му събеседник (Over-the-hip shot). Какво обикновено внушава този кадър?","options":[{"text":"Че двамата са равни и си вярват","why":"Равенство се показва с кадри от една височина; тук единият гледа другия отгоре."},{"text":"Че зрителят вижда през очите на седналия","why":"Камерата е зад правия герой, покрай бедрото му — не през очите на седналия."},{"text":"Че единият има власт над другия","why":""},{"text":"Че разговорът е случаен и маловажен","why":"Разликата във височината е режисьорски избор — разговорът не е неутрален."}],"answer":2,"explain":"Over-the-hip прилича на засечката през рамо, но камерата е на височината на бедрото. Правият герой се извисява в преден план, а седналият е по-ниско и гледа нагоре — разликата във височината става разлика във властта.","more":"Пробвай го в сцена на разпит или в кабинета на директора: седналият гледа нагоре, а ръката или коланът на правия запълват част от кадъра в преден план."},{"id":"studio.lang.comp.c11","legacyId":"v-framing-a1","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-framing","prompt":"Кога кадърът с двама герои (Two shot) е по-силен избор от редуването им в отделни кадри?","options":[{"text":"Когато реакцията на единия трябва да се види отблизо","why":"Реакцията отблизо иска отделен кадър на този герой; в общия кадър двамата делят вниманието."},{"text":"Когато отношението между тях трябва да се види наведнъж","why":""},{"text":"Когато сцената е бърза и иска много срязвания","why":"Много срязвания означава отделни кадри; кадърът с двамата е по-спокоен и по-дълъг."},{"text":"Когато искаш да изолираш всеки в неговия свят","why":"Изолацията се постига с отделни кадри — общият кадър ги свързва."}],"answer":1,"explain":"В един кадър зрителят вижда едновременно кой към кого е обърнат, кой е по-голям и кой по-близо. Отношенията се четат от самото разположение на героите, без монтажът да ги разделя.","more":"В кадъра с двама говори и разстоянието между тях: щом се приближат или отдалечат, отношенията им се променят без нито дума. Това е част от разстановката на актьорите (Blocking)."},{"id":"studio.edit.cuts.c11","legacyId":"v-framing-b0","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-framing","prompt":"За какво служи Insert shot — например кадър отблизо на ръка, която пише бележка?","options":[{"text":"Показва къде се развива действието и кой къде стои","why":"Мястото се установява с широк план; Insert shot изрязва детайл от действието."},{"text":"Показва как реагира на думите слушащият герой","why":"Това е кадър на реакцията; Insert shot показва предмет или детайл от самото действие."},{"text":"Показва героя в цял ръст сред обкръжението му","why":"Това е общ план; Insert shot е отблизо и показва само детайла."},{"text":"Насочва вниманието към важна за историята подробност","why":""}],"answer":3,"explain":"Камерата изключва всичко друго и оставя само детайла, затова зрителят няма как да го пропусне. Така режисьорът подчертава подробност, от която зависи историята — бележка, часовник, ключ.","more":"Пази непрекъснатостта: ако в общия план героят пише с дясната ръка и със синя химикалка, същото трябва да е и в Insert shot. В такива кадри разликите в ръката, ръкава или предмета се забелязват най-лесно."},{"id":"studio.lang.comp.c12","legacyId":"v-framing-b1","hall":"studio","domain":"lang","topic":"lang.comp","level":10,"subjects":["oper","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-framing","prompt":"Учител разговаря с ученик и ученикът се чувства малък. Опиши поне два избора на кадриране, които показват това.","checklist":["Кадър, който показва неравенство (over-the-hip, горен ракурс)","Различен размер на героите в кадъра","Място в кадъра: долу, в ъгъла, празно пространство"],"checklistNeed":2,"model":"Например: over-the-hip кадър покрай учителя към седналия ученик; учителят е по-голям и по-близо до камерата; ученикът е в долната част на кадъра с много празно пространство над него; горен ракурс към ученика.","more":"Помисли и за обрата: когато ученикът намери смелост, смени кадрирането — камерата слиза на нивото на очите и двамата стават равни по размер в кадъра."},{"id":"studio.lang.angle.c08","legacyId":"v-angles-a0","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-angles","prompt":"Каква е разликата между ъгъла на камерата и височината ѝ?","options":[{"text":"Ъгълът е колко широко вижда обективът, а височината — къде е камерата","why":"Колко широко вижда обективът е зрителен ъгъл; ъгълът на камерата е посоката, в която тя гледа."},{"text":"Ъгълът е наклонът на хоризонта, а височината — наклонът нагоре или надолу","why":"Наклонът на хоризонта е само един вид ъгъл (холандски), а наклонът нагоре или надолу също е ъгъл, не височина."},{"text":"Ъгълът и височината са едно и също, но за движеща се камера","why":"Това са два отделни избора: камерата може да е ниско и да гледа право или високо и да гледа надолу."},{"text":"Ъгълът е накъде гледа камерата, а височината — откъде гледа","why":""}],"answer":3,"explain":"Камерата може да е ниско и да гледа право напред или високо и да гледа надолу. Височината и ъгълът са два отделни избора, които заедно определят внушението.","more":"Пробвай с телефона: снимай един и същ човек от нивото на коленете — веднъж с право насочен обектив, веднъж наклонен нагоре. Ниската височина сама по себе си още не прави долен ракурс."},{"id":"studio.lang.angle.c09","legacyId":"v-angles-a1","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-angles","prompt":"Кадър от нивото на земята (Ground level shot) най-често…","options":[{"text":"показва героя неутрално, като равен на зрителя","why":"Неутрален е кадърът от нивото на очите; ниската камера изкривява мащаба."},{"text":"показва цялото място отгоре, като карта","why":"Като карта се вижда от птичи поглед — обратната крайност."},{"text":"прави предметите на пода големи и необичайни","why":""},{"text":"прави героя малък и уязвим пред мястото","why":"Героят става малък при горен ракурс; ниската камера го уголемява."}],"answer":2,"explain":"Предметите близо до обектива заемат голяма част от кадъра, а камерата на земята е съвсем до тях — стъпки, колела, капки. Рядко виждаме света от толкова ниско, затова гледната точка изглежда чужда: на дете, животно или предмет.","more":"Трик с телефона: обърни го наопаки и го облегни на нещо на пода. На повечето телефони обективът е близо до горния край, така ще слезе почти до земята."},{"id":"studio.lang.angle.c10","legacyId":"v-angles-b0","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-angles","prompt":"Въздушен кадър (Aerial shot), заснет с дрон или хеликоптер, най-често…","options":[{"text":"показва героя като силен и доминиращ","why":"От въздуха хората стават малки; силата се внушава с долен ракурс."},{"text":"предава объркването и страха на героя","why":"Объркването се предава със субективна камера или наклонен кадър, не с въздушен план."},{"text":"свързва два кадъра с обща форма в монтажа","why":"Това е графично съвпадение в монтажа; въздушният кадър служи за мащаб и ориентация."},{"text":"установява мащаба и географията на мястото","why":""}],"answer":3,"explain":"От голяма височина се виждат едновременно пътища, реки и сгради и как се свързват — затова зрителят веднага разбира къде е и колко голямо е мястото. Кадърът е за пространството, а не за героя.","more":"„Сиянието“ започва с въздушни кадри на малка кола по планински път. Още преди хотела зрителят усеща колко далеч от всичко ще бъдат героите."},{"id":"studio.lang.angle.c11","legacyId":"v-angles-b1","hall":"studio","domain":"lang","topic":"lang.angle","level":11,"subjects":["kino","oper","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-angles","prompt":"Героят е силен в началото на филма, а в края губи всичко. Как може ракурсът да разкаже тази промяна?","options":[{"text":"От горен ракурс в началото към долен в края","why":"Така героят расте — обратното на история за загуба."},{"text":"От птичи поглед в началото към долен ракурс в края","why":"Птичият поглед смалява героя в началото, а долният го издига в края — пак обратна посока."},{"text":"От долен ракурс в началото към горен в края","why":""},{"text":"С един и същ долен ракурс от началото до края","why":"Без смяна ракурсът не разказва промяна: героят изглежда силен и накрая."}],"answer":2,"explain":"Зрителят не брои ракурсите, но ги усеща: щом свикне да гледа героя отдолу, първият кадър отгоре го смалява и подсказва падението. Така ракурсът проследява пътя на героя през целия филм.","more":"В beat board или storyboard отбележи ракурса на героя във всяка ключова сцена. Така ще видиш дали камерата разказва пътя му, или ракурсите се сменят случайно."},{"id":"studio.cam.focus.c07","legacyId":"v-dof-a0","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-dof","prompt":"В „Гражданинът Кейн“ (1941) и предметите отпред, и героите в дъното са рязко. Как се нарича това?","options":[{"text":"Плитка рязкост (Shallow focus)","why":"При плитката рязкост е рязък само един план — обратното на кадрите в „Кейн“."},{"text":"Прехвърляне на фокуса (Rack focus)","why":"Прехвърлянето мести фокуса от план на план; тук всички планове са рязко едновременно."},{"text":"Дълбок фокус (Deep focus)","why":""},{"text":"Мек фокус (Soft focus)","why":"Мекият фокус омекотява целия кадър, а тук всичко е рязко."}],"answer":2,"explain":"При дълбокия фокус целият кадър е рязък. Режисьорът подрежда действието на няколко плана в дълбочина, а зрителят сам избира къде да гледа.","more":"Операторът Грег Толанд постига дълбокия фокус в „Гражданинът Кейн“ с широкоъгълни обективи, силно затворена бленда и много силна светлина."},{"id":"studio.cam.focus.c08","legacyId":"v-dof-a1","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-dof","prompt":"Какво позволява разделената диоптрична леща (Split diopter)?","options":[{"text":"Размиване на целия кадър за сънен ефект","why":"Сънният ефект е мек фокус; диоптричната леща прави два плана рязко, а не размити."},{"text":"Приближаване на образа, без да се мести камерата","why":"Приближаването без движение е трансфокация."},{"text":"Разделяне на кадъра на две сцени на различни места","why":"Това е разделен екран (split screen); диоптричната леща е в един кадър и на едно място."},{"text":"Рязко близо и рязко далеч в един и същ кадър","why":""}],"answer":3,"explain":"Разделената диоптрична леща (Split diopter) е половин леща пред обектива: едната половина на кадъра е фокусирана близо, другата — далеч. Между тях често личи размита граница.","more":"За да не се забелязва трикът, операторите скриват размитата граница по вертикален ръб в кадъра — рамка на врата, колона или стълб."},{"id":"studio.cam.focus.c09","legacyId":"v-dof-b0","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-dof","prompt":"Мекият фокус (Soft focus) най-често внушава…","options":[{"text":"мечтателност, спомен или романтика","why":""},{"text":"напрежение, заплаха и опасност","why":"Напрежението обикновено иска остър, твърд образ и контраст."},{"text":"документална достоверност и суровост","why":"Документалността се свързва с рязък, суров образ, а не с омекотени контури."},{"text":"скорост, хаос и енергия","why":"Скоростта и хаосът се предават с размазване от движение и бърз монтаж, а не с мек фокус."}],"answer":0,"explain":"Мекият фокус разлива светлите места в леко сияние и омекотява контурите и кожата. Светът губи твърдата си яснота и изглежда далечен, нереален и нежен.","more":"Холивудските оператори са опъвали тънка мрежа или коприна пред обектива при портретите на звездите. Опитай същото с парче найлонов чорапогащник пред камерата на телефона."},{"id":"studio.cam.focus.c10","legacyId":"v-dof-b1","hall":"studio","domain":"cam","topic":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-dof","prompt":"Обясни как фокусът може да разкаже история в един-единствен кадър, без монтаж. Дай пример.","checklist":["Прехвърляне на фокуса или дълбок фокус","Фокусът насочва вниманието към нова информация","Конкретна ситуация"],"checklistNeed":2,"model":"Например: героинята отпред говори по телефона и е на фокус, а в размития фон се появява някой. Фокусът се прехвърля към него (Rack focus) и зрителят разбира, че тя е в опасност. Дълбокият фокус (Deep focus) пък показва две действия на различни планове едновременно.","more":"Проверка за собствения ти кадър: изключи звука и гледай само кое е рязко във всеки момент. Ако по рязкостта личи кое е важно, фокусът разказва."},{"id":"studio.cam.move.c08","legacyId":"v-move-a0","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-move","prompt":"Бавното приближаване на камерата към лицето на героя (Push in) обикновено внушава…","options":[{"text":"че сцената приключва и започва нова","why":"Краят на сцената по-често се показва с отдалечаване или затъмнение."},{"text":"че в героя се случва нещо важно","why":""},{"text":"че героят губи значение в историята","why":"Обратното: приближаването засилва вниманието към героя."},{"text":"че героят е изолиран сред празното място","why":"Изолацията се показва с отдалечаване (Pull out) — обратното движение."}],"answer":1,"explain":"Кадърът постепенно отрязва околното пространство и лицето расте — зрителят буквално се приближава към мислите на героя. Отдалечаването (Pull out) прави обратното: изолира героя или разкрива какво има около него.","more":"Без релси: дръж телефона с двете ръце до гърдите, прибери лактите и пристъпвай бавно с плъзгаща стъпка от пета към пръсти. Плавността е по-важна от скоростта."},{"id":"studio.cam.move.c09","legacyId":"v-move-a1","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-move","prompt":"Камерата обикаля около героя по дъга (Arc shot). Какво най-често постига?","options":[{"text":"Установява мястото на действието","why":"Мястото се установява с широк план; дъгата е около героя, не е за ориентация."},{"text":"Показва света през очите на героя","why":"Камерата гледа към героя отвън — това не е неговата гледна точка."},{"text":"Кара героя да изглежда малък и слаб","why":"Дъгата издига героя, не го смалява; смаляване дават горен ракурс или отдалечаване."},{"text":"Моментът изглежда значим и драматичен","why":""}],"answer":3,"explain":"Докато камерата обикаля, фонът се върти зад героя, а той остава в центъра — като ос, около която се върти светът. Така кръговото движение издига момента; може да внуши също, че героите са хванати в собствения си кръг.","more":"В „Отмъстителите“ (2012) камерата обикаля около героите, когато за първи път застават заедно в битката за Ню Йорк — така екипът се „ражда“ пред очите ни."},{"id":"studio.cam.move.c10","legacyId":"v-move-b0","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-move","prompt":"Какво е рязка панорама (Whip pan)?","options":[{"text":"Толкова бързо завъртане, че образът се размазва","why":""},{"text":"Бавно завъртане на камерата около героя","why":"Бавното обикаляне около героя е кръгово движение (Arc shot)."},{"text":"Бързо приближаване с трансфокация към лицето","why":"Бързото приближаване с обектива е бърза трансфокация (crash zoom), а не панорама."},{"text":"Рязко спиране на движеща се камера","why":"Рязката панорама е бързо завъртане, а не спиране."}],"answer":0,"explain":"Камерата се завърта толкова бързо, че при обичайната скорост на затвора всеки кадър се размазва в хоризонтални ивици. В това размазване монтажистът може да скрие склейка към друго място или време.","more":"Упражнение: заснеми два кадъра на различни места, като завършиш първия и започнеш втория с рязка панорама в една и съща посока и с еднаква скорост. Склейката в средата на размазването ще е невидима."},{"id":"studio.cam.move.c11","legacyId":"v-move-b1","hall":"studio","domain":"cam","topic":"cam.move","level":11,"subjects":["oper","kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-move","prompt":"Избери сцена — реална или измислена — и опиши две движения на камерата, които ще използваш в нея. Защо точно тези?","checklist":["Назовани две движения","Какво внушава всяко","Връзка с емоцията на сцената"],"checklistNeed":2,"model":"Например: героинята получава писмо с лоша новина. Проследяващ кадър, докато тя върви към пощенската кутия (ежедневие, спокойствие), а когато чете — бавно приближаване (push in): светът около нея изчезва и остава само реакцията ѝ.","more":"Не забравяй и неподвижната камера: когато героят е в шок или всичко около него се движи, статичният кадър често говори по-силно от всяко движение."},{"id":"studio.cam.lens.c12","legacyId":"v-lens-a0","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-lens","prompt":"Как се нарича вариообектив, който остава на фокус, докато променяш фокусното разстояние?","options":[{"text":"Варифокален обектив (Varifocal lens)","why":"Варифокалният губи фокуса при всяка промяна на фокусното разстояние — точно обратното."},{"text":"Парфокален обектив (Parfocal lens)","why":""},{"text":"Фикс обектив (Prime lens)","why":"Фиксът има едно фокусно разстояние и не прави трансфокация."},{"text":"Анаморфен обектив (Anamorphic lens)","why":"Анаморфният е за широк формат; не е свързан с пазенето на фокуса."}],"answer":1,"explain":"Парфокалният обектив е конструиран така, че рязкостта не се измества, когато променяш фокусното разстояние. При варифокалния (Varifocal) обектив фокусът трябва да се поправя след всяка промяна.","more":"С парфокален обектив операторите фокусират на най-дългото фокусно разстояние, където грешката личи най-добре, и после отварят кадъра — рязкостта остава."},{"id":"studio.cam.lens.c13","legacyId":"v-lens-a1","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-lens","prompt":"Кой обектив ти трябва, за да снимаш око, мравка или капка в мащаб 1:1 — в естествената им големина върху сензора?","options":[{"text":"Макро обектив (Macro lens)","why":""},{"text":"Телеобектив (Telephoto lens)","why":"Телеобективът приближава далечни неща, но не фокусира толкова отблизо, че да даде мащаб 1:1."},{"text":"Рибешко око (Fisheye lens)","why":"Рибешкото око обхваща огромен ъгъл — малкият предмет ще е точица."},{"text":"Широкоъгълен обектив (Wide-angle lens)","why":"Широкоъгълният показва повече пространство, а не уголемява малкия предмет."}],"answer":0,"explain":"Мащаб 1:1 означава, че мравка с дължина 5 mm заема 5 mm и върху сензора. Обикновените обективи не могат да фокусират толкова отблизо; макро обективът е конструиран точно за това.","more":"При макро рязкостта е само милиметри. Затова фотографите затварят блендата или сливат няколко снимки с различен фокус в една (focus stacking)."},{"id":"studio.cam.lens.c14","legacyId":"v-lens-b0","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-lens","prompt":"Кой диапазон StudioBinder определя като стандартни обективи — с перспектива, близка до човешкото зрение (при пълен кадър)?","options":[{"text":"10–20 mm","why":"10–20 mm са свръхширокоъгълни обективи — силно разтягат пространството."},{"text":"35–55 mm","why":""},{"text":"85–200 mm","why":"85–200 mm са дългофокусни — приближават и сгъстяват."},{"text":"300–600 mm","why":"300–600 mm са супертелеобективи — за спорт и природа отдалеч."}],"answer":1,"explain":"В този диапазон съотношението между близките и далечните предмети изглежда така, както го виждаме с очите си — без разтягане и без сгъстяване. Под него StudioBinder поставя широкоъгълните, а над него — дългофокусните обективи.","more":"Нормалният обектив е близо до диагонала на сензора: при пълен кадър той е около 43 mm. Затова 50 mm е класическият „нормален“ обектив, а при по-малките сензори нормалният е по-къс."},{"id":"studio.cam.lens.c15","legacyId":"v-lens-b1","hall":"studio","domain":"cam","topic":"cam.lens","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-lens","prompt":"В „Социалната мрежа“ гребците на регатата изглеждат като играчки в макет. Кой обектив създава този ефект на миниатюра?","options":[{"text":"Макро обектив (Macro lens)","why":"Макро обективът снима малки предмети отблизо, а тук истински гребци изглеждат като малки предмети."},{"text":"Анаморфен обектив (Anamorphic lens)","why":"Анаморфният дава широк формат и овално bokeh, но не и ефект на макет."},{"text":"Широкоъгълен обектив (Wide-angle lens)","why":"Широкоъгълният дава дълбока рязкост, а ефектът на макет идва от тясна ивица рязкост."},{"text":"Обектив с наклон и отместване (Tilt-shift lens)","why":""}],"answer":3,"explain":"Наклонената оптика оставя рязка само тясна ивица от сцената. Такава плитка рязкост виждаме, когато снимаме малки предмети отблизо, затова мозъкът тълкува истинския пейзаж като макет.","more":"Ефектът се засилва, ако снимаш отвисоко, с наситени цветове и ускорено движение. Много телефони и програми имат филтър „миниатюра“, който го имитира с размиване горе и долу."},{"id":"studio.cam.format.c07","legacyId":"v-fps-a0","hall":"studio","domain":"cam","topic":"cam.format","level":10,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-fps","prompt":"Филм е заснет и пуснат с 60 кадъра в секунда. Как изглежда движението в сравнение с 24 кадъра в секунда?","options":[{"text":"По-бавно, като при забавен каданс на екрана","why":"Забавяне има, когато снимаш с 60 и пускаш с 24; тук снимаш и пускаш с 60."},{"text":"По-накъсано, с пропуски между фазите","why":"Повече кадри означава по-малко пропуски — движението е по-гладко."},{"text":"Същото като при 24 кадъра в секунда","why":"Окото усеща разликата: 60 кадъра изглеждат гладко, почти като видеоигра."},{"text":"По-гладко и „по-реално“, като на телевизия","why":""}],"answer":3,"explain":"При 60 кадъра между две фази минава 2,5 пъти по-малко време, отколкото при 24, затова скоковете в движението са по-малки, а размазването във всеки кадър — по-късо. Окото е свикнало с 24 кадъра в киното и възприема гладкото движение като „телевизионно“.","more":"„Хобит: Неочаквано пътешествие“ (2012) е заснет с 48 кадъра в секунда и част от зрителите намират образа за твърде „реален“, като на видео. Повечето филми и днес се снимат и прожектират с 24."},{"id":"studio.cam.format.c08","legacyId":"v-fps-a1","hall":"studio","domain":"cam","topic":"cam.format","level":10,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-fps","prompt":"Защо 24 кадъра в секунда стават стандарт на киното със звука в края на 20-те години?","options":[{"text":"Окото вижда точно 24 кадъра в секунда и не повече","why":"Окото няма „кадрова честота“ от 24; то усеща разлики и над 60 кадъра."},{"text":"Камерите от епохата не могат да снимат по-бързо","why":"Камерите могат и по-бързо; 24 е компромис между качество и цена на лентата."},{"text":"Достатъчно е за движение и звук, без да се хаби лента","why":""},{"text":"При 24 кадъра образът е по-светъл на екрана","why":"Яркостта на прожекцията не зависи от кадровата честота."}],"answer":2,"explain":"В нямото кино няма единна скорост — камерите се въртят на ръка. Звукът върху лентата изисква постоянна скорост, а 24 кадъра дават приемливо движение и качество на звуковата пътечка, без да се хаби излишна лента.","more":"Цифровото кино пази 24 кадъра по навик: точно това движение зрителите разпознават като „кино“. В монтажните програми ще срещнеш и 23,976 — вариант на 24, свързан с телевизията в САЩ."},{"id":"studio.cam.format.c09","legacyId":"v-fps-b0","hall":"studio","domain":"cam","topic":"cam.format","level":10,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-fps","prompt":"Снимаш със 120 кадъра в секунда и пускаш с 24. Какво получаваш?","options":[{"text":"Движението е 5 пъти по-бързо","why":"Обратното: повече заснети кадри, пуснати по-бавно, разтягат времето."},{"text":"Движението е 5 пъти по-бавно","why":""},{"text":"Нормална скорост, но по-гладко движение","why":"Нормална скорост ще има, ако пуснеш със 120; при 24 движението се забавя."},{"text":"Движението е 2 пъти по-бавно","why":"120 ÷ 24 = 5, а не 2."}],"answer":1,"explain":"Една реална секунда е разпределена в 120 кадъра, а при прожекция се показват само по 24 в секунда. Затова тези 120 кадъра траят 120 ÷ 24 = 5 секунди на екрана.","more":"Забавеният каданс е и разказвателен похват: разтяга кратък миг — удар, скок, падаща чаша — и го прави важен. Не прекалявай: ако всичко е забавено, нищо не изглежда специално."},{"id":"studio.cam.format.c10","legacyId":"v-fps-b1","hall":"studio","domain":"cam","topic":"cam.format","level":10,"subjects":["oper","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-fps","prompt":"Избери кадрова честота за три ситуации и обясни избора: игрален филм, спортно предаване, забавен каданс на капка вода.","checklist":["Филм — 24 кадъра в секунда","Спорт или телевизия — 50–60 кадъра","Забавен каданс: снимаш с висока, пускаш с нормална честота","Обяснение защо"],"checklistNeed":3,"model":"Игрален филм — 24 кадъра: познатото кинематографично движение с леко размазване. Спорт — 50 или 60 кадъра: гладко и ясно бързо движение. Капка вода — снимаш със 120 или повече кадъра и пускаш с 24 или 25, за да забавиш движението.","more":"Капката вода е толкова бърза, че и 120 кадъра често не стигат — за нея се ползват специални камери с хиляди кадри в секунда. При 1000 кадъра, пуснати с 25, една секунда трае 40 секунди на екрана."},{"id":"studio.edit.cuts.c12","legacyId":"v-trans-a0","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-trans","prompt":"Кой преход е запазена марка на „Междузвездни войни“ — новият кадър избутва стария с линия, която минава през екрана?","options":[{"text":"Wipe","why":""},{"text":"Преливане (Dissolve)","why":"При преливане двата образа се смесват за миг; линия, която минава през екрана, няма."},{"text":"Затъмнение (Fade)","why":"Затъмнението минава през черно; тук новият образ директно измества стария."},{"text":"Iris","why":"При Iris кадърът се затваря или отваря в кръг, а не с линия през екрана."}],"answer":0,"explain":"При wipe новият кадър „избърсва“ стария. Лукас го използва като поклон към старите приключенски сериали и към филмите на Куросава.","more":"Можеш да направиш естествен wipe без ефекти: нека човек или кола мине плътно пред камерата и закрие кадъра. В този миг срежи към новата сцена — най-добре и тя да започва с нещо, което се отдръпва от обектива."},{"id":"studio.edit.cuts.c13","legacyId":"v-trans-a1","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-trans","prompt":"Годар изрязва парчета от един непрекъснат кадър в „До последен дъх“ (À bout de souffle, 1960) и героите внезапно се оказват малко по-напред във времето. Какъв е преходът?","options":[{"text":"Прескачащ монтаж (Jump cut)","why":""},{"text":"Графично съвпадение (Match cut)","why":"Графичното съвпадение свързва различни неща по форма; тук е един и същ кадър с изрязани парчета."},{"text":"Преливане (Dissolve)","why":"Преливането смесва образите плавно; тук скокът е рязък и видим."},{"text":"Паралелен монтаж (Cross-cutting)","why":"Паралелният монтаж редува различни места; тук остават един кадър и едно място."}],"answer":0,"explain":"Прескачащият монтаж нарушава плавността нарочно; става подпис на Френската нова вълна, а днес — и на много видеа в YouTube.","more":"„До последен дъх“ е първият пълнометражен филм на Годар. Голяма част от него е снимана с ръчна камера по истинските улици на Париж — свободата на камерата отговаря на свободата на монтажа."},{"id":"studio.edit.cuts.c14","legacyId":"v-trans-b0","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-trans","prompt":"Кръг, който се свива около детайл и затваря кадъра (Iris), днес най-често…","options":[{"text":"е стандартният преход между темите в новините","why":"В новините се реже директно или с кратко преливане; кръгът там би изглеждал като шега."},{"text":"цитира нямото кино — носталгично или за смях","why":""},{"text":"показва, че следва спомен или сън на героя","why":"Спомен и сън обикновено се въвеждат с преливане; кръгът е знак за епохата на нямото кино."},{"text":"свързва два кадъра с обща кръгла форма","why":"Това е графично съвпадение; Iris е преход, който затваря кадъра в кръг."}],"answer":1,"explain":"Iris е бил обичаен преход в нямото кино, затова днес веднага напомня за онази епоха. Режисьорите го ползват като намигване към нея — в анимацията, в комедията и в пародиите.","more":"В нямото кино кръгът се прави още в камерата, по време на снимане: пред обектива има подвижна маска с кръгъл отвор, която операторът бавно затваря или отваря. Днес същото става с едно щракване в монтажната програма."},{"id":"studio.edit.cuts.c15","legacyId":"v-trans-b1","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-trans","prompt":"Кога ще избереш преливане (Dissolve) и кога обикновено срязване? Дай по един пример.","checklist":["Срязване — непрекъснато действие, без акцент","Преливане — минало време, връзка или спомен","Пример за всяко"],"checklistNeed":2,"model":"Срязването е невидимо и пази темпото — за действие и диалог, които продължават в същото време. Преливането смесва два кадъра и казва „мина време“ или „тези двете са свързани“ — например от лицето на героя към спомена му.","more":"Честа грешка: преливане между всеки два кадъра „за красота“. Така то губи значението си — пази го за моментите, в които наистина минава време или се свързват две мисли."},{"id":"studio.edit.time.c07","legacyId":"v-edit6-a0","hall":"studio","domain":"edit","topic":"edit.time","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-edit6","prompt":"Кратки кадри под музика показват как героят тренира седмици наред — всичко за една минута. Как се нарича това?","options":[{"text":"Паралелен монтаж (Cross-cutting)","why":"Паралелният монтаж редува различни линии на действие; тук е един процес, сгъстен във времето."},{"text":"Монтажна поредица (Montage)","why":""},{"text":"Прескачащ монтаж (Jump cut)","why":"Прескачащият монтаж реже вътре в един кадър; тук има много различни кадри от седмици."},{"text":"Реално време (Real time)","why":"Реалното време не съкращава нищо; тук седмици стават минута."}],"answer":1,"explain":"Всеки кратък кадър замества цял ден тренировки, а промяната от първия до последния кадър показва напредъка. Така седмиците стават минута, без да се губи усещането, че героят се е трудил.","more":"В „Мулан“ (1998) тренировъчната поредица върви под песента на капитана им и показва как неумелите новобранци постепенно стават войници."},{"id":"studio.edit.cuts.c16","legacyId":"v-edit6-a1","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-edit6","prompt":"Две или три действия, които се случват едновременно на различни места, се редуват в монтажа — любим похват на Кристофър Нолан. Как се нарича?","options":[{"text":"Монтажна поредица (Montage)","why":"Монтажната поредица сгъстява един процес; тук се редуват различни едновременни действия."},{"text":"Интелектуален монтаж (Intellectual montage)","why":"Интелектуалният монтаж съпоставя образи за метафора, а не следи едновременни действия."},{"text":"Кадър – контракадър (Shot/reverse shot)","why":"Кадър – контракадър редува събеседници в една сцена, а не различни места."},{"text":"Паралелен монтаж (Cross-cutting)","why":""}],"answer":3,"explain":"Паралелният монтаж редува линиите на действието; напрежението расте, защото зрителят чака те да се срещнат.","more":"В „Дънкерк“ (2017) Нолан редува три линии с различна продължителност — седмица на сушата, ден в морето и час във въздуха — и ги събира в края на филма."},{"id":"studio.edit.cuts.c17","legacyId":"v-edit6-b0","hall":"studio","domain":"edit","topic":"edit.cuts","level":11,"subjects":["kino","rej","anim"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-edit6","prompt":"Какво е кадър – контракадър (Shot/reverse shot)?","options":[{"text":"Редуване на кадри на двамата събеседници в диалог","why":""},{"text":"Кадър, в който камерата се връща назад по пътя си","why":"Това е движение на камерата; контракадърът е обратният кадър към събеседника."},{"text":"Редуване на две действия на различни места","why":"Това е паралелен монтаж; контракадърът е в една сцена, между двама души."},{"text":"Кадър, последван от същия кадър, пуснат обратно","why":"Пускането наобратно е ефект с времето; контракадърът е кадър към другия събеседник."}],"answer":0,"explain":"Така монтажистът избира във всеки момент кого да покаже — говорещия или реакцията на слушащия — и управлява вниманието на зрителя. Камерите остават от едната страна на оста (правилото 180°), за да се срещат погледите.","more":"Във „Властелинът на пръстените: Двете кули“ спорът между Смеагол и Голъм е монтиран като кадър – контракадър с един и същ герой: всяка „личност“ гледа в своя посока, сякаш са двама."},{"id":"studio.edit.time.c08","legacyId":"v-edit6-b1","hall":"studio","domain":"edit","topic":"edit.time","level":11,"subjects":["kino","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-edit6","prompt":"Героят чака важно обаждане. Опиши как ще монтираш сцената, за да расте напрежението. Използвай поне два похвата от видеото.","checklist":["Поне два назовани монтажни похвата","Темпото се ускорява — кадрите стават по-кратки","Връзка между похвата и напрежението"],"checklistNeed":2,"model":"Например: паралелен монтаж между героя, който гледа телефона, и човека, който се колебае дали да звънне; кадрите стават все по-кратки; вмъкнати кадри на часовника; накрая звънът се чува още върху предишния кадър (J-срязване).","more":"Не бързай да режеш накрая: задръж кадъра на мълчащия телефон малко по-дълго, отколкото е удобно. Зрителят очаква звъна и всяка излишна секунда засилва напрежението."},{"id":"studio.light.quality.c08","legacyId":"v-light-a0","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-light","prompt":"Какво е светлосянка (Chiaroscuro) в киното?","options":[{"text":"Мека светлина, която изглажда сенките по лицето","why":"Меката светлина изглажда, а светлосянката подчертава сенките."},{"text":"Цветна светлина с гелове в контрастни цветове","why":"Светлосянката е контраст между светло и тъмно, а не между цветове."},{"text":"Естествена светлина, която идва от прозореца","why":"Прозорецът може да е източникът, но светлосянката е в силния контраст, а не в произхода на светлината."},{"text":"Силен контраст между дълбоки сенки и ярки места","why":""}],"answer":3,"explain":"Светлосянката моделира обема чрез сблъсъка на светло и тъмно: важното е осветено, а останалото потъва в сянка. Идва от живописта (Караваджо, Рембранд), а в киното е типична за ноара и трилъра.","more":"Виж „Кръстникът“ (1972): операторът Гордън Уилис осветява Марлон Брандо отгоре и очите му често остават в сянка — героят изглежда загадъчен и опасен."},{"id":"studio.light.quality.c09","legacyId":"v-light-a1","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-light","prompt":"Кое от тези е практична лампа (Practical)?","options":[{"text":"Прожектор над декора, скрит извън кадъра","why":"Прожекторът е извън кадъра — практичната лампа е част от декора и се вижда."},{"text":"Нощна лампа на масата, която се вижда в кадъра","why":""},{"text":"Лампа с гел, която имитира светлина от прозорец","why":"Това е мотивирана светлина извън кадъра; практичната лампа е видима в сцената."},{"text":"Отражател до камерата, който връща светлина","why":"Отражателят е помощно средство извън кадъра, а не лампа от декора."}],"answer":1,"explain":"Практичната лампа (Practical) е част от декора и реално свети в кадъра — лампа, екран, свещ. Често тя „оправдава“ останалата, скрита светлина в сцената.","more":"Практичните лампи са и изразно средство: топла настолна лампа прави стаята уютна, а синкавият екран на телефон в тъмнината — самотна. Пробвай да осветиш лице само с екрана на телефона."},{"id":"studio.light.3pt.c08","legacyId":"v-light-b0","hall":"studio","domain":"light","topic":"light.3pt","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-light","prompt":"Героят е обърнат леко встрани от камерата. Осветяваш далечната от камерата страна на лицето (Short lighting). Какво получаваш?","options":[{"text":"По-широко и по-открито лице със сянка встрани","why":"Това дава широкото осветление (Broad lighting), когато осветиш близката страна."},{"text":"Сянка към камерата и по-тясно, драматично лице","why":""},{"text":"Плоско, равномерно лице почти без сенки","why":"Плоско става, когато светлината е откъм камерата; тук тя е встрани и оставя сянка."},{"text":"Силует — лицето е черно на светъл фон","why":"Силует има, когато светлината е зад героя; тук лицето е осветено от едната страна."}],"answer":1,"explain":"Светлината идва откъм далечната страна, затова обърнатата към камерата половина на лицето — по-голямата видима част — остава в сянка и лицето изглежда тясно и обемно. Обратното е широкото осветление (Broad lighting).","more":"Името подсказва правилото: когато лицето е завъртяно, далечната му половина се вижда по-тясна — „късата“ страна. Осветиш ли късата страна — късо осветление; широката — широко."},{"id":"studio.light.quality.c10","legacyId":"v-light-b1","hall":"studio","domain":"light","topic":"light.quality","level":11,"subjects":["oper","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-light","prompt":"Отблясък от обектива (Lens flare) в кадъра…","options":[{"text":"идва от мръсотия по лещата и е техническа грешка","why":"Мръсотията размива и замъглява; отблясъкът е от светлина, която се разсейва в лещите."},{"text":"идва от прекалено отворена бленда при нощни снимки","why":"Блендата влияе на формата на отблясъка, но причината е източник, насочен към обектива."},{"text":"идва от цифровия сензор и се добавя в монтажа","why":"Отблясъкът се ражда в стъклата на обектива; в монтажа може само да се имитира."},{"text":"идва от източник, насочен към камерата, и често е нарочен","why":""}],"answer":3,"explain":"Отблясъкът се ражда, когато силна светлина влезе в обектива и се отрази между стъклата му. Някога се смяташе за грешка, а режисьори като Джей Джей Ейбрамс го използват нарочно — за енергия и усещане за „истинска“ камера.","more":"Анаморфните обективи (Anamorphic lens) дават характерни дълги хоризонтални ивици отблясък. Затова игрите и анимацията често ги имитират, за да изглежда картината „като в киното“."},{"id":"studio.light.temp.c07","legacyId":"v-kelvin-a0","hall":"studio","domain":"light","topic":"light.temp","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-kelvin","prompt":"Колкото по-висока е цветната температура в келвини, толкова светлината е…","options":[{"text":"по-оранжева и топла","why":"Скалата е обратна на усещането: ниските стойности (свещ) са оранжеви, високите — сини."},{"text":"по-ярка и силна","why":"Цветната температура е за цвета, не за силата на светлината."},{"text":"по-синя и студена","why":""},{"text":"по-мека и разсеяна","why":"Мекотата зависи от размера на източника, не от келвините."}],"answer":2,"explain":"Скалата е обърната спрямо усещането: свещта (≈1500–1900 K) е оранжева, дневната светлина (≈5500–5600 K) е неутрална, а синьото небе е над 10 000 K.","more":"Пробвай с телефона: в много телефони ръчният (Pro) режим позволява баланс в келвини. Снимай един и същ кадър на 3200 K и на 5600 K и сравни двете снимки."},{"id":"studio.light.temp.c08","legacyId":"v-kelvin-a1","hall":"studio","domain":"light","topic":"light.temp","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy","fixes":["B030"]},"kind":"card","format":"choice","videoLock":"v-kelvin","prompt":"Какво прави гелът CTO, сложен пред лампа с дневна светлина?","options":[{"text":"Охлажда светлината към цвета на небето","why":"Охлажда синият гел CTB; CTO (Orange) затопля."},{"text":"Омекотява сенките, без да сменя цвета","why":"Мекотата идва от дифузер; гелът сменя цвета."},{"text":"Намалява яркостта, без да сменя цвета","why":"Това прави неутралният гел (ND); CTO сменя цвета към оранжево."},{"text":"Затопля светлината към цвета на жичка","why":""}],"answer":3,"explain":"CTO (Colour Temperature Orange) затопля светлината, а CTB (Colour Temperature Blue) я охлажда. Така различни източници се изравняват в един цвят.","more":"Гелът има степени — пълен, 1/2, 1/4 и 1/8 — за по-фина корекция. Пълният CTO приближава дневната светлина до тази на лампа с жичка."},{"id":"studio.light.temp.c09","legacyId":"v-kelvin-b0","hall":"studio","domain":"light","topic":"light.temp","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-kelvin","prompt":"Камерата е с баланс на бялото 3200 K. Коя светлина ще изглежда синкава и студена?","options":[{"text":"Лампата с жичка на масата (≈3200 K)","why":"При 3200 K лампата с жичка изглежда неутрално бяла."},{"text":"Пламъкът на свещта до леглото (≈1900 K)","why":"Свещта е по-ниска от баланса и изглежда оранжева, а не синя."},{"text":"Дневното небе през прозореца (≈5600 K)","why":""},{"text":"Уличната натриева лампа (≈2000 K)","why":"Натриевата лампа е по-ниска от баланса и изглежда оранжево-жълта."}],"answer":2,"explain":"Източник с по-висока температура от баланса на бялото изглежда син, а с по-ниска — оранжев. Затова при 3200 K прозорецът „посинява“.","more":"Така се прави и „лунна светлина“: при баланс 3200 K дневна лампа (≈5600 K) зад прозореца изглежда студена и синкава като луна, а лампите с жичка в стаята излизат естествено — бели или леко топли."},{"id":"studio.light.temp.c10","legacyId":"v-kelvin-b1","hall":"studio","domain":"light","topic":"light.temp","topic2":"light.color","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-kelvin","prompt":"Обясни как цветната температура може да подсили настроението на сцена. Дай два контрастни примера.","checklist":["Топла светлина: пример и внушение","Студена светлина: пример и внушение","Връзка с емоцията на сцената"],"checklistNeed":2,"model":"Топлата светлина (оранжева, жълта) внушава уют, носталгия, жега — StudioBinder дава за пример „О, братко, къде си?“. Студената (синя) внушава самота, нощ, спокойствие или меланхолия — например нощните сцени в „Лунна светлина“ (Moonlight).","more":"Упражнение: заснеми една и съща стая два пъти — веднъж само с топла настолна лампа, веднъж само със синкавата светлина от прозореца привечер. Опиши какво чувство носи всяка снимка."},{"id":"studio.cam.expo.c09","legacyId":"v-aperture-a0","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-aperture","prompt":"Кое f-число означава най-широко отворена бленда?","options":[{"text":"f/1,4","why":""},{"text":"f/4","why":"f/4 е по-затворена от f/1,4: колкото по-голямо е числото, толкова по-малък е отворът."},{"text":"f/8","why":"f/8 е средна бленда — по-малък отвор от f/1,4."},{"text":"f/16","why":"f/16 е най-затворената от изброените — малко светлина и дълбока рязкост."}],"answer":0,"explain":"Записът f/2 значи „фокусното разстояние, делено на 2“ — това е диаметърът на отвора. Затова колкото по-голямо е числото, толкова по-малък е отворът: f/16 пуска малко светлина и дава дълбока рязкост.","more":"Пример: при обектив 50 mm на f/2 отворът е широк 25 mm, а на f/16 — само около 3 mm. Затова при f/16 влиза 64 пъти по-малко светлина."},{"id":"studio.cam.expo.c10","legacyId":"v-aperture-a1","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-aperture","prompt":"За „Бари Линдън“ (1975) Кубрик снима сцени само на свещи. Какво му помага?","options":[{"text":"Скрити прожектори зад свещниците на масата","why":"Точно това Кубрик отказва: сцените са осветени само от свещите."},{"text":"Изключително светли обективи с бленда f/0,7","why":""},{"text":"Много дълъг затвор — по 1 секунда на кадър","why":"При 24 кадъра в секунда затворът не може да е по-дълъг от 1/24 s."},{"text":"Огледала, които насочват дневна светлина","why":"Сцените са нощни, на свещи — дневна светлина няма."}],"answer":1,"explain":"Обективите Zeiss с бленда f/0,7 събират достатъчно светлина от свещите. Цената е изключително плитка дълбочина на рязкост — актьорите почти не могат да мърдат, без да излязат от фокус.","more":"f/0,7 пуска 16 пъти повече светлина от f/2,8 — цели 4 степени. Тези обективи са разработени за лунната програма „Аполо“ на NASA; направени са само 10, а три от тях купува Кубрик."},{"id":"studio.cam.expo.c11","legacyId":"v-aperture-b0","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-aperture","prompt":"Отваряш блендата от f/8 на f/4. Какво се случва?","options":[{"text":"4 пъти повече светлина и по-плитка рязкост","why":""},{"text":"2 пъти повече светлина и по-плитка рязкост","why":"f/8 → f/5,6 → f/4 са две степени; всяка удвоява светлината, значи 4 пъти."},{"text":"4 пъти повече светлина и по-дълбока рязкост","why":"По-широкият отвор скъсява дълбочината на рязкост, а не я увеличава."},{"text":"2 пъти по-малко светлина и по-дълбока рязкост","why":"Отварянето пуска повече светлина: f/4 е по-широк отвор от f/8."}],"answer":0,"explain":"Светлината зависи от площта на отвора, а тя расте с квадрата на диаметъра. При f/4 диаметърът е два пъти по-голям, отколкото при f/8, значи площта е 2² = 4 пъти по-голяма — две степени. По-широкият отвор скъсява и дълбочината на рязкост.","more":"Ако искаш размития фон на f/4, но не и по-светъл кадър, компенсирай двете степени другаде: ISO 400 → 100 или ND филтър 0,6."},{"id":"studio.cam.expo.c12","legacyId":"v-aperture-b1","hall":"studio","domain":"cam","topic":"cam.expo","topic2":"cam.focus","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-aperture","prompt":"Обясни защо блендата е творческо, а не само техническо решение.","checklist":["По-малко f-число — повече светлина","Широка бленда — по-плитка дълбочина на рязкост","Пример за творчески избор: изолиране или цялото пространство"],"checklistNeed":2,"model":"Блендата определя не само колко светлина влиза, но и дълбочината на рязкост. Широка бленда (f/1,4–2,8) отделя героя от фона и насочва погледа; тясна (f/8–16) държи рязко цялото пространство — героя и средата му. Това е избор какво да види зрителят.","more":"Упражнение: в портретния режим на много телефони можеш да смениш симулираната бленда след снимката, например от f/1,4 до f/16. Сравни: при първата виждаш само човека, при втората — човека и мястото."},{"id":"studio.cam.expo.c13","legacyId":"v-shutter-a0","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-shutter","prompt":"Какво става с движещите се предмети, ако затворът е отворен по-дълго — например 1/25 s вместо 1/50 s?","options":[{"text":"Стават по-резки, защото влиза повече светлина","why":"Повече светлина не прави движението рязко — дългият затвор записва движението като следа."},{"text":"Изглеждат накъсани, всяка фаза поотделно","why":"Накъсано изглежда при много кратък затвор, например 1/1000."},{"text":"Размазват се повече по посоката на движението","why":""},{"text":"Изглеждат по-бавни, като на забавен каданс","why":"Скоростта на движението зависи от кадровата честота, не от затвора."}],"answer":2,"explain":"Докато затворът е отворен, предметът продължава да се движи и „рисува“ следа върху сензора. Колкото по-дълго е отворен, толкова по-дълга е следата; краткият затвор замразява всяка фаза.","more":"Във фотографията дългият затвор е художествен похват: на статив при 1 s или повече водопадът става като мъгла, а фаровете на колите — светли линии."},{"id":"studio.cam.expo.c14","legacyId":"v-shutter-a1","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-shutter","prompt":"Какво е ъгъл на затвора (Shutter angle)?","options":[{"text":"Ъгълът, под който е наклонена камерата към героя","why":"Наклонът на камерата е ракурс; ъгълът на затвора е за експозицията."},{"text":"Ъгълът на видимост на обектива в градуси","why":"Зрителният ъгъл зависи от фокусното разстояние, не от затвора."},{"text":"Посоката, в която се движи завесата на затвора","why":"Посоката на завесата няма значение за експозицията; важно е колко време е отворен затворът."},{"text":"Каква част от времето на кадъра затворът е отворен","why":""}],"answer":3,"explain":"Във филмовите камери затворът е въртящ се диск с изрязан сектор: лентата се експонира, докато отворът минава пред нея. При сектор 180° и 24 кадъра в секунда експонацията е 1/48 s — на практика 1/50 s.","more":"Ъгълът е удобен, защото не зависи от кадровата честота: 180° винаги дава познатото „кино“ размазване, а скоростта на затвора трябва да се пресмята наново при всяка смяна на кадрите в секунда."},{"id":"studio.cam.expo.c15","legacyId":"v-shutter-b0","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-shutter","prompt":"Искаш битката да изглежда нервна, накъсана и документална — всяка пръска пясък да е рязка. Какъв затвор избираш?","options":[{"text":"Широк ъгъл на затвора, например 360°","why":"Широкият ъгъл удължава експозицията и размазва — обратното на целта."},{"text":"Стандартният ъгъл на затвора — 180°","why":"180° дава естествено размазване; пясъкът няма да е рязък."},{"text":"Широк ъгъл и по-висока кадрова честота","why":"По-високата честота при нормално пускане забавя движението, а широкият ъгъл пак размазва."},{"text":"Тесен ъгъл на затвора, например 45°","why":""}],"answer":3,"explain":"При 45° всеки кадър се експонира само една осма от времето си — при 24 кадъра това е 1/192 s. Фазите излизат рязко, без следа, и движението подскача. Прочут пример е десантът в „Спасяването на редник Райън“.","more":"Тесният ъгъл „изяжда“ светлина: 45° е с две степени по-тъмно от 180°, затова трябва да отвориш блендата или да вдигнеш ISO. При 25 кадъра в секунда 45° отговаря на 1/200 s."},{"id":"studio.cam.expo.c16","legacyId":"v-shutter-b1","hall":"studio","domain":"cam","topic":"cam.expo","level":11,"subjects":["oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-shutter","prompt":"Защо при бързо панорамиране с много цифрови камери вертикалните линии изглеждат наклонени?","options":[{"text":"Широкоъгълният обектив изкривява вертикалите","why":"Изкривяването от обектива се вижда и при неподвижна камера; тук наклонът се появява само при бързо движение."},{"text":"Затворът е твърде кратък и замразява наклона","why":"Краткият затвор намалява размазването, а наклонът идва от поредното четене на редовете."},{"text":"Сензорът се чете ред по ред, а не наведнъж","why":""},{"text":"Кадровата честота е твърде ниска за панорама","why":"Ниската честота дава накъсване (judder), а не наклонени линии."}],"answer":2,"explain":"При rolling shutter горният ред се записва по-рано от долния. Докато сензорът стигне до долу, камерата вече се е завъртяла, затова вертикалите излизат наклонени. Global shutter записва целия кадър наведнъж.","more":"Пробвай с телефона: направи бърза панорама покрай стълбове или ограда и виж как вертикалите се накланят. При бавна панорама ефектът почти изчезва."},{"id":"studio.edit.space.c09","legacyId":"v-180-a0","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-180","prompt":"Режисьорът нарочно прескача оста точно когато отношенията между двама герои се обръщат. Какво постига?","options":[{"text":"Показва, че сцената е сън или спомен на героя","why":"Прескачането не е знак за сън; то смущава ориентацията в реалната сцена."},{"text":"Прави монтажа невидим, защото погледите се срещат","why":"Обратното: при прескачане погледите вече не се срещат и срязването се усеща."},{"text":"Смущението у зрителя подсилва драматичния обрат","why":""},{"text":"Спестява време, защото камерата не се мести","why":"Прескачането иска нова позиция на камерата; смисълът е драматургичен, не практичен."}],"answer":2,"explain":"Нарушеното правило се усеща като смущение; когато съвпадне с емоционален обрат, смущението носи смисъл. StudioBinder показва такива примери от „Реквием за една мечта“ и „25-ият час“.","more":"Кубрик прави подобно нещо в „Сиянието“: в разговора в банята камерата прескача оста и у зрителя расте усещане за объркване и тревога."},{"id":"studio.edit.space.c10","legacyId":"v-180-a1","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-180","prompt":"Какво е неутрален кадър (Neutral shot) спрямо линията на действието?","options":[{"text":"Кадър от нивото на очите, без долен или горен ракурс","why":"Това е нормален ъгъл по височина; неутралният кадър е за посоката спрямо оста."},{"text":"Кадър без герои, който разделя двете страни на оста","why":"Кадър без герои може да е вмъкнат кадър, но не е неутрален: неутралният показва героя без посока наляво или надясно."},{"text":"Кадър по самата ос — героят идва право към камерата","why":""},{"text":"Кадър под 90° спрямо оста, точно отстрани на героите","why":"Отстрани посоката е най-ясна; неутрален е кадърът по оста, в който посока няма."}],"answer":2,"explain":"Посоката на екрана се определя спрямо оста. Кадър, сниман точно по нея, показва героя фронтално или в гръб и не дава посока — затова след него можеш да минеш от другата страна, без зрителят да се обърка.","more":"Снимай неутрален кадър като застраховка: на площадката вземи и един кадър, в който героят идва право към камерата. В монтажа той ще ти позволи да смениш посоката, ако се наложи."},{"id":"studio.edit.space.c11","legacyId":"v-180-b0","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-180","prompt":"Как вмъкнат кадър (Cutaway) помага да прескочиш оста?","options":[{"text":"Поставя камерата точно на оста, така че посока няма","why":"Това прави неутралният кадър; вмъкнатият показва нещо извън оста."},{"text":"Удължава сцената, така че зрителят забравя посоките","why":"Не дължината помага, а прекъсването на прякото сравнение между двата кадъра."},{"text":"Прекъсва сравнението на посоките и зрителят приема новата","why":""},{"text":"Обръща образа огледално, за да съвпаднат посоките","why":"Вмъкнатият кадър не обръща образа; огледалното обръщане е монтажна корекция с други рискове."}],"answer":2,"explain":"Ориентацията на зрителя се крепи на прякото сравнение между два съседни кадъра. Кадър на нещо извън оста — часовник, прозорец, наблюдател — разкъсва тази верига и следващата позиция се възприема като нова отправна точка.","more":"Най-добре работи вмъкнат кадър със собствен смисъл — например реакция на трети герой. Празен кадър, сложен само „за пълнеж“, се усеща като кръпка."},{"id":"studio.edit.space.c12","legacyId":"v-180-b1","hall":"studio","domain":"edit","topic":"edit.space","level":11,"subjects":["kino","rej","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-180","prompt":"Обясни правилото 180° с думи или рисунка: къде е линията, къде стои камерата и какво се обърква, ако я прескочиш.","checklist":["Линията минава през героите или по посоката на движение","Камерите са от едната страна","Посоките на погледите остават постоянни","Последствие от прескачането: объркване"],"checklistNeed":3,"model":"Линията минава през двамата герои или по посоката на движение. Всички камери стоят от едната страна — в полукръг от 180°. Тогава А винаги гледа надясно, а Б наляво, и погледите им се срещат. Ако камерата прескочи линията, героите сменят местата си на екрана и зрителят губи ориентация.","more":"Правилото 180° е една от опорите на невидимия монтаж (Continuity editing) — класическия стил, в който зрителят следи историята и нито за миг не се чуди къде се намира."},{"id":"studio.edit.sound.c07","legacyId":"v-sound-a0","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-sound","prompt":"Чуваме вътрешния монолог на героя, но устните му не мърдат. Според StudioBinder какъв е този звук?","options":[{"text":"Недиегетичен, защото никой около героя не го чува","why":"StudioBinder го смята за диегетичен: мислите принадлежат на героя, който е в света на историята."},{"text":"Недиегетичен, защото е записан отделно в студио","why":"Къде е записан звукът, не решава дали е диегетичен — решава източникът в историята."},{"text":"Диегетичен, защото идва от съзнанието на героя","why":""},{"text":"Шумов ефект, защото е добавен след снимките","why":"Шумовете са звуци от действия — стъпки, врати; вътрешният монолог е глас."}],"answer":2,"explain":"Мислите принадлежат на героя, който живее в света на историята, затова StudioBinder смята вътрешния монолог за диегетичен звук, макар да го чува само той. Разказвач отвън, който не е част от историята, е недиегетичен.","more":"Вътрешният глас обикновено се записва в студио, близо до микрофона и без ехото на стаята. Затова звучи по-интимно от другите реплики и зрителят веднага разбира, че чува мисли."},{"id":"studio.edit.sound.c08","legacyId":"v-sound-a1","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-sound","prompt":"В „Казабланка“ пианистът Сам свири в заведението и героите го слушат. Каква е музиката?","options":[{"text":"Недиегетична, защото е написана за филма","why":"Дали е написана за филма, не решава нищо; решава дали героите я чуват."},{"text":"Недиегетична, защото е записана в студио","why":"Мястото на записа не определя категорията; източникът — пианото — е в сцената."},{"text":"Диегетична, защото пианото е в самата сцена","why":""},{"text":"Контрапунктна, защото противоречи на сцената","why":"Музиката не противоречи на сцената; тя е част от нея."}],"answer":2,"explain":"Музиката има източник в сцената — пианото, — а героите я чуват и реагират на нея. Затова е диегетична, независимо че е подбрана и записана специално за филма.","more":"Песента „As Time Goes By“, която Илса моли Сам да изсвири, става и лайтмотив: композиторът Макс Стайнер вплита мелодията ѝ в оркестровата музика зад кадър."},{"id":"studio.edit.sound.c09","legacyId":"v-sound-b0","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-sound","prompt":"Кой от тези звуци е недиегетичен?","options":[{"text":"Шумът на самолета, който гони героя","why":"Самолетът е в сцената и героят го чува — звукът е диегетичен."},{"text":"Оркестровата музика, която засилва страха","why":""},{"text":"Песента от радиото в колата на героя","why":"Радиото е източник в света на героя — песента е диегетична."},{"text":"Вътрешният монолог, който чуваме в главата му","why":"Мислите принадлежат на героя в историята, затова StudioBinder ги брои за диегетични."}],"answer":1,"explain":"Оркестър няма никъде в сцената и героят не може да чуе музиката — тя е само за зрителя. Недиегетичният звук идва „отвън“ на историята: филмова музика, разказвач, който не е герой, звуков акцент при изненада.","more":"В нямото кино музиката звучи на живо в салона — пианист или оркестър свири, докато тече филмът. Тя е недиегетична, макар да е в една зала със зрителите."},{"id":"studio.edit.sound.c10","legacyId":"v-sound-b1","hall":"studio","domain":"edit","topic":"edit.sound","level":11,"subjects":["kino","anim","rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-sound","prompt":"Измисли кратка сцена, в която преходът от диегетичен към недиегетичен звук (или обратно) казва нещо за героя.","checklist":["Ясен източник на диегетичния звук","Моментът на прехода","Какво казва преходът за героя"],"checklistNeed":2,"model":"Например: героинята слага слушалките в шумния автобус. Музиката от слушалките (диегетична) става силна и чиста, шумът изчезва — звукът става субективен, почти като филмова музика. Когато някой я дръпне за ръката, музиката рязко спира и шумът се връща.","more":"Опитай с телефона: запиши шума в автобуса и отделно песента, която слушаш. В монтажа заглуши шума, когато героинята слага слушалките, и го върни рязко, когато я прекъснат — контрастът казва повече от реплика."},{"id":"studio.story.staging.c06","legacyId":"v-mise-a0","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-mise","prompt":"Кое от тези НЕ е част от мизансцена?","options":[{"text":"Декорът и реквизитът в кадъра","why":"Декорът и реквизитът са в кадъра — те са мизансцен."},{"text":"Музиката, добавена в монтажа","why":""},{"text":"Разположението и движението на актьорите","why":"Разстановката на актьорите е сърцевината на мизансцена."},{"text":"Осветлението на снимачната площадка","why":"Светлината пред камерата е част от мизансцена."}],"answer":1,"explain":"Мизансценът е всичко пред камерата: декор, реквизит, костюми, грим, светлина, актьори и тяхното движение. Музиката и монтажът идват след снимките.","more":"Изключение е музиката, която героите чуват в кадъра — радио или улични музиканти. Тогава източникът ѝ е част от мизансцена, а самата музика е диегетичен звук (Diegetic sound)."},{"id":"studio.story.staging.c07","legacyId":"v-mise-a1","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-mise","prompt":"Какво е разстановка на актьорите (Blocking)?","options":[{"text":"Подреждането на кадрите в монтажа един след друг","why":"Подреждането в монтажа е монтажен план; разстановката е пред камерата."},{"text":"Забраната да се снима на дадена локация без разрешение","why":"Английското „blocking“ тук не значи блокиране, а разстановка на актьорите."},{"text":"Разположението и движението на актьорите спрямо камерата","why":""},{"text":"Разпределението на реквизита по декора преди снимки","why":"Реквизитът е част от мизансцена, но разстановката е за актьорите и движението им."}],"answer":2,"explain":"Разстановката определя кой къде стои, кога и накъде се движи. Така отношенията между героите се виждат, а не само се чуват.","more":"На площадката разстановката се репетира, преди да се нагласи светлината, а местата, където актьорът спира, се отбелязват с лепенки на пода — позиция на актьора (Mark)."},{"id":"studio.story.staging.c08","legacyId":"v-mise-b0","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-mise","prompt":"Един герой заема много по-голяма част от кадъра, по-близо е до камерата и е по-високо от останалите. Какво казва мизансценът?","options":[{"text":"Той доминира и има власт в сцената","why":""},{"text":"Той е най-уязвимият и скоро ще загуби","why":"Уязвимостта се показва с малък размер, ниско положение и дистанция — обратното."},{"text":"Той е най-далеч от събитията в сцената","why":"Той е най-близо до камерата — значи е в центъра на събитията."},{"text":"Той е наблюдател, а не участник","why":"Големият и високо поставен герой е център на сцената, а не страничен наблюдател."}],"answer":0,"explain":"Размерът в кадъра, височината и мястото спрямо другите са знаци за власт, които зрителят чете, без да ги осъзнава.","more":"Можеш да обърнеш властта в средата на сцената: подчиненият става, а шефът сяда. Ако смяната в разстановката съвпадне с точката на опора (Fulcrum), обратът се вижда, без да се казва."},{"id":"studio.story.staging.c09","legacyId":"v-mise-b1","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-mise","prompt":"Опиши стаята на герой така, че зрителят да разбере характера му, без никой да каже дума. Назови поне три елемента на мизансцена.","checklist":["Декор или реквизит, който разказва","Светлина или цвят","Разположение или поведение на героя","Връзка с характера"],"checklistNeed":3,"model":"Например: тъмна стая с плътни завеси, книги, подредени по цвят, една-единствена чаша на масата, спрял часовник — самотен и педантичен човек, заседнал в миналото. Светлината идва само от една настолна лампа.","more":"Във филма „УОЛ-И“ на Pixar роботът почти не говори, но подредените по рафтовете находки в дома му разказват, че е любопитен, грижовен и самотен."},{"id":"studio.story.staging.c10","legacyId":"v-staging-a0","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-staging","prompt":"Спилбърг често снима цяла сцена в един кадър без срязване: актьорите и камерата се движат така, че плановете се сменят сами. Как се нарича такъв кадър?","options":[{"text":"Монтажна поредица (Montage)","why":"Монтажната поредица е от много кратки кадри; тук е един кадър."},{"text":"Прескачащ монтаж (Jump cut)","why":"Прескачащият монтаж е срязване, а тук няма нито едно."},{"text":"Засечка през рамо (Over-the-shoulder shot)","why":"Засечката е отделен кадър в диалог; тук цялата сцена е в един кадър."},{"text":"Дълъг кадър (Long take)","why":""}],"answer":3,"explain":"В т.нар. Spielberg oner един кадър съдържа общ, среден и крупен план, защото актьорите се приближават и отдалечават, а камерата ги следва.","more":"Дългите кадри на Спилбърг често минават незабелязано: поставени са толкова естествено, че зрителят не усеща липсата на монтаж. Пробвай с телефона разговор на двама, в който те сами идват към камерата."},{"id":"studio.story.staging.c11","legacyId":"v-staging-a1","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-staging","prompt":"Какво е разполагане в дълбочина (Staging in depth)?","options":[{"text":"Всички актьори стоят в една линия успоредно на камерата","why":"Една линия е плитка постановка — обратното на дълбочината."},{"text":"Сцената се снима отгоре, за да се вижда дълбочината","why":"Разполагането в дълбочина е за разстоянието от камерата, а не за височината ѝ."},{"text":"Героят е в центъра на кадъра, а фонът е силно размит","why":"Размитият фон е плитка рязкост; разполагането в дълбочина използва и заден план."},{"text":"Героите и действията са на различни разстояния от камерата","why":""}],"answer":3,"explain":"Дълбочината позволява две действия в един кадър — единият герой отпред, другият отзад — без монтаж. Зрителят сам избира накъде да гледа, а режисьорът насочва окото с движение, светлина и фокус.","more":"Класически пример е „Гражданинът Кейн“ (1941) на Орсън Уелс: майката подписва документи на преден план, а през прозореца в дъното малкият Кейн играе в снега, без да знае, че съдбата му се решава."},{"id":"studio.story.staging.c12","legacyId":"v-staging-b0","hall":"studio","domain":"story","topic":"story.staging","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-staging","prompt":"Каква е голямата полза от сцена в един непрекъснат кадър?","options":[{"text":"По-евтино и по-бързо е за снимане от монтажа","why":"Дългият кадър иска много репетиции, а една грешка разваля целия дубъл — често е по-труден."},{"text":"Напрежението не се прекъсва и зрителят е „вътре“","why":""},{"text":"Грешките на актьорите се скриват по-лесно","why":"Обратното: без срязване всяка грешка остава в кадъра."},{"text":"Мястото на действието може да се смени мигновено","why":"Мигновена смяна на мястото дава монтажът; дългият кадър пази непрекъснатостта."}],"answer":1,"explain":"Без срязване екранното време тече като реалното и зрителят няма „почивка“ — преживява сцената заедно с героите. Затова дългият кадър се пази за моменти, в които непрекъснатостта е смисълът.","more":"Хичкок снима „Въжето“ (1948) в кадри до около 10 минути — колкото побира тогавашната ролка филм. Част от срязванията са скрити: камерата минава плътно до гърба на актьор и кадърът потъмнява."},{"id":"studio.story.staging.c13","legacyId":"v-staging-b1","hall":"studio","domain":"story","topic":"story.staging","topic2":"lang.comp","level":11,"subjects":["rej"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-staging","prompt":"Майка чака сина си, който се прибира късно. Опиши как ще поставиш сцената в един кадър: кой къде е и как се движи камерата.","checklist":["Разполагане в дълбочина","Движението на актьорите сменя плана","Движение на камерата — или неподвижна камера с причина","Разстановката показва отношенията"],"checklistNeed":3,"model":"Например: майката седи на преден план в полумрака, а вратата е в дъното — действието е разположено в дълбочина. Синът влиза отзад, малък в кадъра; докато тя говори, той се приближава и застава в близък план до нея. Камерата бавно се доближава — без срязване планът се сменя от общ към близък.","more":"Използвай вратата в дъното като рамка в рамката (Frame within a frame): когато синът се появи в нея, той е затворен в собствена рамка — още преди да е казал дума."},{"id":"studio.story.irony.c12","legacyId":"v-suspense-a0","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-suspense","prompt":"Защо залогът (Stakes) е задължителен за напрежението?","options":[{"text":"Залогът определя колко дълго може да трае сцената","why":"Залогът не мери време; той дава причина да ни е грижа."},{"text":"Залогът подсказва на зрителя как ще свърши сцената","why":"Залогът казва какво може да се загуби, а не как ще свърши — иначе напрежението изчезва."},{"text":"Без грижа за загубата чакането е скучно, а не тревожно","why":""},{"text":"Без залог героите нямат за какво да си говорят","why":"Залогът е за зрителя и за героя, а не за количеството диалог."}],"answer":2,"explain":"Напрежение = знание + грижа. Зрителят трябва да знае какво предстои и да го е грижа за героя и за това, което може да загуби.","more":"Сценаристът Блейк Снайдър нарича това „Спаси котката“ (Save the Cat): още в началото героят прави нещо добро, за да ни стане близък. Ако героят ни е безразличен, и най-голямата заплаха не тревожи."},{"id":"studio.story.irony.c13","legacyId":"v-suspense-a1","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-suspense","prompt":"Началото на „Докосване до злото“ (Touch of Evil, 1958) на Орсън Уелс е класически пример за напрежение. Какво вижда зрителят?","options":[{"text":"Как слагат бомба в кола, която после дълго пътува","why":""},{"text":"Как героите дълго спорят дали в колата има бомба","why":"Героите не знаят за бомбата — точно в това е напрежението."},{"text":"Как колата избухва още в първите секунди на филма","why":"Експлозията идва накрая; напрежението е в дългото чакане преди нея."},{"text":"Как полицаи преследват колата през целия град","why":"Няма преследване; колата просто пътува, а зрителят знае за бомбата."}],"answer":0,"explain":"Зрителят вижда как някой нагласява часовников механизъм и слага бомбата в багажника. После дългият непрекъснат кадър следва колата, а ние чакаме взрива — хичкоковата „бомба под масата“ в действие.","more":"Кадърът трае над три минути без нито едно срязване: камерата е на кран и минава над улиците заедно с колата. Това е един от най-известните дълги кадри (Long take) в историята на киното."},{"id":"studio.story.irony.c14","legacyId":"v-suspense-b0","hall":"studio","domain":"story","topic":"story.irony","topic2":"edit.time","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-suspense","prompt":"Зрителят знае, че зад вратата се крие някой. Героинята посяга към дръжката. Как удължаваш напрежението?","options":[{"text":"Режеш веднага към следващата сцена на друго място","why":"Срязването към друго място прекъсва чакането — напрежението изтича."},{"text":"Показваш всичко в един бърз далечен план","why":"Бързият далечен план съкращава момента, вместо да го разтегне."},{"text":"Разтягаш момента с кадри на ръката, вратата и лицето","why":""},{"text":"Разкриваш веднага кой се крие зад вратата","why":"Щом разкриеш тайната, напрежението свършва."}],"answer":2,"explain":"Напрежението живее в чакането. Когато покажеш действието на части и от няколко ъгъла, екранното време става по-дълго от реалното — това е разтягане на времето (Elaboration).","more":"Честа грешка е да разтягаш с кадри, които не носят нищо ново. Всеки кадър трябва да добавя информация — трепереща ръка, сянка под вратата, звук отвътре. Иначе зрителят се отегчава, вместо да се тревожи."},{"id":"studio.story.irony.c15","legacyId":"v-suspense-b1","hall":"studio","domain":"story","topic":"story.irony","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-suspense","prompt":"Превърни изненадата в напрежение: „Героят отваря хладилника и вътре има змия.“ Какво ще покажеш на зрителя по-рано?","checklist":["Зрителят научава за опасността преди героя","Героят има причина да отиде към опасността","Моментът преди развръзката е разтегнат"],"checklistNeed":2,"model":"По-рано показвам как змията се вмъква в хладилника (или как някой я слага там). После — героя, който е гладен и тръгва към кухнята. Зрителят знае, героят — не. Разтягам: героят се бави, прави сандвич, посяга към дръжката…","more":"Редувай кадри на змията в хладилника и на гладния герой в кухнята — паралелен монтаж (Cross-cutting). Всяко срязване към змията напомня на зрителя какво предстои."},{"id":"studio.story.structure.c07","legacyId":"v-3act-a0","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-3act","prompt":"Какво е подбудително събитие (Inciting incident)?","options":[{"text":"Моментът, в който героят сам решава да приеме пътя","why":"Решението идва след подбудата — това е първата повратна точка."},{"text":"Най-напрегнатата сцена точно преди края на филма","why":"Това е кулминацията, а подбудата е в началото."},{"text":"Обратът в средата, след който нищо не е същото","why":"Това е средната точка; подбудителното събитие е много по-рано."},{"text":"Събитието, което изважда героя от обичайния му живот","why":""}],"answer":3,"explain":"Подбудителното събитие нарушава равновесието: пристига писмото, изчезва детето, появява се непознатият. Без него историята не започва, а героят обикновено не го избира — то му се случва.","more":"В разбора на StudioBinder за „Джурасик парк“ подбудителното събитие е, когато Джон Хамънд убеждава учените Алан Грант и Ели Сатлър да посетят парка му."},{"id":"studio.story.structure.c08","legacyId":"v-3act-a1","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-3act","prompt":"Какво е средна точка (Midpoint) в структурата?","options":[{"text":"Голям обрат около средата, след който нищо не е същото","why":""},{"text":"Точно 45-ата минута, независимо какво се случва","why":"Средната точка е драматургичен обрат, а не минута на часовника."},{"text":"Началото на третия акт, когато героят се връща","why":"Третият акт започва след втората повратна точка, много след средата."},{"text":"Сцената, в която всички герои се събират заедно","why":"Броят на героите няма значение; важен е обратът."}],"answer":0,"explain":"В средата на филма нещо се обръща: героят научава истината, губи или печели нещо важно. В разбора на StudioBinder за „Джурасик парк“ това е появата на тиранозавъра, който излиза през оградата.","more":"Добрата средна точка често превръща героя от реагиращ в действащ: до нея той бяга от проблема, след нея тръгва срещу него. Ако вторият ти акт „провисва“, търси липсващата средна точка."},{"id":"studio.story.structure.c09","legacyId":"v-3act-b0","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-3act","prompt":"Героинята решава да тръгне на пътешествието и затваря вратата след себе си. Къде в структурата сме?","options":[{"text":"В края на първия акт — първата повратна точка","why":""},{"text":"В подбудителното събитие в началото на филма","why":"Подбудата я вади от обичайния живот; тук тя вече сама решава да тръгне."},{"text":"В средната точка, по средата на втория акт","why":"Средната точка е по-късно — обрат вътре в новия свят."},{"text":"В кулминацията, точно преди развръзката","why":"Кулминацията е в третия акт; тук пътешествието едва започва."}],"answer":0,"explain":"Първата повратна точка приключва експозицията: героят приема предизвикателството и навлиза в новия свят на втория акт. Подбудата му се случва, а тук той сам избира.","more":"Повратната точка не винаги е решение. В разбора на StudioBinder за „Джурасик парк“ това е мигът, в който Алан и Ели виждат първите динозаври — оттук няма връщане."},{"id":"studio.story.structure.c10","legacyId":"v-3act-b1","hall":"studio","domain":"story","topic":"story.structure","level":11,"subjects":["rej","kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-3act","prompt":"Разкажи сюжета на любим анимационен филм по схемата: подбудително събитие → първа повратна точка → средна точка → кулминация → развръзка. По едно изречение за всяка точка.","checklist":["Подбудително събитие","Първа повратна точка","Средна точка","Кулминация","Развръзка"],"checklistNeed":4,"model":"Модел: 1) Подбудително събитие — нещо изважда героя от обичайния живот. 2) Първа повратна точка — героят решава да действа и влиза в новия свят. 3) Средна точка — голям обрат, след който няма връщане. 4) Кулминация — най-големият сблъсък, героят рискува всичко. 5) Развръзка — новото равновесие: как се е променил героят.","more":"В класическата схема първият акт заема около една четвърт от филма, вторият — около половината, а третият — последната четвърт. Засечи минутите на всяка точка в любимия си филм и провери колко се доближава."},{"id":"studio.prod.plan.c11","legacyId":"v-preprod-a0","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-preprod","prompt":"Защо разбивката на сценария (Script breakdown) се прави толкова рано?","options":[{"text":"От нея излизат списъците, по които се правят бюджетът и графикът","why":""},{"text":"От нея се вижда дали сценарият е с правилна дължина","why":"Дължината се преценява по броя страници; разбивката отбелязва всичко нужно за всяка сцена."},{"text":"От нея продуцентът разбира кои актьори да избере","why":"Разбивката показва кои роли има в коя сцена, но изборът на актьори е кастинг."},{"text":"От нея се пише синопсисът за кандидатстване по фестивали","why":"Синопсисът се пише по-рано и за други цели; разбивката е работен документ."}],"answer":0,"explain":"Разбивката отбелязва всеки елемент на всяка сцена: актьори, реквизит, костюми, локации, ефекти. От нея всеки отдел знае какво да подготви, а продуцентът — колко ще струва филмът и колко дни ще трябват.","more":"При разбивка всеки вид елемент се подчертава с различен цвят — по най-разпространената схема персонажите са в червено, а реквизитът в лилаво. Опитай с една страница от училищния си сценарий и цветни маркери."},{"id":"studio.prod.periods.c05","legacyId":"v-preprod-a1","hall":"studio","domain":"prod","topic":"prod.periods","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-preprod","prompt":"Кои документи показват КАК ще изглежда всеки кадър, преди да е заснет?","options":[{"text":"Повиквателната за снимачния ден","why":"Повиквателната казва кой, кога и къде идва за снимачния ден — не как изглежда кадърът."},{"text":"Storyboard и списъкът на кадрите","why":""},{"text":"Разбивката на сценария по елементи","why":"Разбивката изброява какво е нужно за всяка сцена, но не рисува кадрите."},{"text":"Снимачният план по дни","why":"Снимачният план подрежда сцените по дни, а не описва кадрите."}],"answer":1,"explain":"Рисунките в storyboard и таблицата на списъка на кадрите (Shot list) превръщат сценария в конкретни кадри: размер на плана, ракурс, движение. По тях операторът и асистент-режисьорът знаят какво ще снимат и колко време ще им отнеме.","more":"Ако не рисуваш, снимай кадрите с телефона на самата локация, със съученици на мястото на актьорите. Така проверяваш ракурсите още преди снимачния ден."},{"id":"studio.prod.plan.c12","legacyId":"v-preprod-b0","hall":"studio","domain":"prod","topic":"prod.plan","level":11,"subjects":["kino","oper"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"choice","videoLock":"v-preprod","prompt":"Защо огледите на локации (Location scouting) се правят заедно с оператора и тонрежисьора?","options":[{"text":"За да изберат костюмите според цветовете на мястото","why":"Костюмите се съгласуват с художника; операторът и звукът проверяват светлината и шума."},{"text":"За да проверят светлината, шума и мястото за техниката","why":""},{"text":"За да пренапишат диалога според акустиката на мястото","why":"Диалогът не се пренаписва по акустиката; звукът проверява дали шумът ще позволи запис."},{"text":"За да снимат рекламни кадри за социалните мрежи","why":"Огледът е работен — за техническите решения на снимките."}],"answer":1,"explain":"Всеки отдел търси различни проблеми: операторът — откъде и кога идва слънцето и къде ще стоят камерата и лампите, тонрежисьорът — шума, продуцентът — разрешенията и паркирането. Проблем, открит на огледа, не струва снимачен ден.","more":"На огледа провери и практичните неща: къде са контактите, има ли тоалетна, къде ще стои техниката. Приложенията за пътя на слънцето показват къде ще е то в часа на снимките."},{"id":"studio.prod.periods.c06","legacyId":"v-preprod-b1","hall":"studio","domain":"prod","topic":"prod.periods","level":11,"subjects":["kino"],"sources":[],"review":{"status":"legacy"},"kind":"card","format":"recall","videoLock":"v-preprod","prompt":"Ти си продуцент на 3-минутен училищен филм. Изброи стъпките на подготвителния период в реда, в който ще ги направиш.","checklist":["Разбивка на сценария","Бюджет и график","Екип и актьори","Локации и разрешения","Storyboard или shot list","Проба на техниката"],"checklistNeed":4,"model":"Примерен ред: сценарий и разбивка → бюджет и график → екип и разпределение на ролите → огледи на локации и разрешения → storyboard и shot list → костюми, реквизит, декор → проба на камерата и звука → снимачен план и повиквателни.","more":"Планирай назад от датата на снимките: до кога трябват разрешенията, костюмите и пробата на техниката. Записани в обратен ред, задачите веднага показват какво вече закъснява."}]`);export{e as default};
